	private final java.util.Deque<String> recentRolls = new java.util.ArrayDeque<>();
	private Activity rolled;
	/** The category a roll is restricted to, or null for anything. */
	private Activity.Category rollCategory;
	private final java.util.Random random = new java.util.Random();

	private final JCheckBox tickManipulationCheckbox;
	/**
	 * Whether an item goal counts what the player already owns. Sits in the item
	 * block rather than with the global tick-manipulation preference because it
	 * is part of asking the question, not a standing preference.
	 */
	private final JCheckBox countOwnedCheckbox;
	/** Wrapped lines, links and the other small pieces every screen is built from. */
	private final PanelKit kit;
	/** The plan to a goal: its steps, the choices made in it, and what to bring. */
	private final PlanView plan;

	public NowWhatPanel(NowWhatConfig config, List<Activity> allActivities,
		List<ItemSource> allItemSources, Function<Goal, Path> pathResolver)
	{
		this(config, allActivities, allItemSources, pathResolver, null, null);
	}

	public NowWhatPanel(NowWhatConfig config, List<Activity> allActivities,
		List<ItemSource> allItemSources, Function<Goal, Path> pathResolver,
		PluginManager pluginManager)
	{
		this(config, allActivities, allItemSources, pathResolver, pluginManager, null);
	}

	public NowWhatPanel(NowWhatConfig config, List<Activity> allActivities,
		List<ItemSource> allItemSources, Function<Goal, Path> pathResolver,
		PluginManager pluginManager, ItemManager itemManager)
	{
		super(false);
		this.pathResolver = pathResolver;
		this.kit = new PanelKit(pluginManager);
		this.plan = new PlanView(kit, itemManager, pathResolver, activitiesById, itemSourcesById,
			this::sinkFooter);
		this.allActivities = allActivities;
		for (Activity activity : allActivities)
		{
			activitiesById.put(activity.getId(), activity);
		}
		for (ItemSource source : allItemSources)
		{
			itemSourcesById.put(source.getId(), source);
		}

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		content = new ContentPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		column(startContainer);
		column(chooseContainer);
		column(randomContainer);
		buildStartScreen();
		content.add(startContainer);
		content.add(chooseContainer);
		content.add(randomContainer);

		// --- Goal: an existing activity (quest/diary/pvm/etc) ---
		stack(chooseContainer, sectionHeader("Plan a path to\u2026"));

		// The way back, and the roll.
		//
		// This screen had neither: once you picked "Plan a path" the opening
		// fork was gone for the rest of the session, and with it the only route
		// to a random suggestion - which is the half of the panel meant for the
		// player who has no goal in mind. Small, and in one row, because it is a
		// way out of this screen rather than part of the form.
		stack(chooseContainer, kit.linkRow(java.util.Arrays.asList(
			kit.actionLink("\u2190 Back", () -> setMode(Mode.START)),
			kit.actionLink("Surprise me", () ->
			{
				setMode(Mode.RANDOM);
				roll();
			}))));

		tickManipulationCheckbox = new JCheckBox("Use tick-manipulation methods");
		tickManipulationCheckbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tickManipulationCheckbox.setForeground(SUBTLE);
		tickManipulationCheckbox.setFont(SMALL_FONT);
		tickManipulationCheckbox.setSelected(config.allowTickManipulation());
		tickManipulationCheckbox.setFocusPainted(false);
		tickManipulationCheckbox.setToolTipText(
			"<html>On: shows tick-manipulation methods (falls back to normal methods only where none are recorded).<br>"
				+ "Off: shows only normal methods, never tick-manipulation.<br>"
				+ "Either way you see one intensity, not both mixed together.</html>");
		stack(chooseContainer, tickManipulationCheckbox);

		// Quests are deliberately absent. 168 of the 256 activities are quests,
		// so they drowned every boss, diary and minigame in the dropdown - and
		// picking one as a goal is a question Quest Helper answers better than a
		// path ever could. They get their own section below instead. Quests that
		// are *prerequisites* on a path are unaffected: naming those, in order,
		// is still this plugin's job.
		List<Activity> sortedActivities = allActivities.stream()
			.filter(a -> a.getCategory() != Activity.Category.QUEST)
			.sorted(Comparator.comparing(Activity::getName))
			.collect(Collectors.toList());
		activityCombo = new JComboBox<>(sortedActivities.toArray(new Activity[0]));
		activityCombo.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean isSelected, boolean cellHasFocus)
			{
				super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
				setText(value == null ? "" : ((Activity) value).getName());
				return this;
			}
		});
		constrainInput(activityCombo);
		stack(chooseContainer, goalBlock("Activity", activityCombo, null, "Plan path", e ->
		{
			Activity selected = (Activity) activityCombo.getSelectedItem();
			if (selected != null)
			{
				showPlan(pathResolver.apply(Goal.activity(selected.getId(), selected.getName(),
					tickManipulationCheckbox.isSelected())));
			}
		}));

		// --- Goal: a skill level ---
		skillCombo = new JComboBox<>(SKILLS);
		// The values stay SHOUTED because that is how RuneLite's Skill enum names
		// them and what PlayerState is keyed on; only the label is title-cased.
		skillCombo.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean selected, boolean focused)
			{
				super.getListCellRendererComponent(list, value, index, selected, focused);
				if (value instanceof String)
				{
					setText(titleCase((String) value));
				}
				return this;
			}
		});
		constrainInput(skillCombo);
		skillLevelSpinner = new JSpinner(new SpinnerNumberModel(99, 2, 99, 1));
		constrainSpinner(skillLevelSpinner);
		stack(chooseContainer, goalBlock("Skill level", skillCombo, skillLevelSpinner, "Plan path", e ->
			showPlan(pathResolver.apply(Goal.skillLevel((String) skillCombo.getSelectedItem(),
				(Integer) skillLevelSpinner.getValue(), tickManipulationCheckbox.isSelected())))));

		// --- Goal: an item ---
		// Typed at, not scrolled through. A bare free-text field was worse than
		// useless when this was tried before, because anything absent from
		// item-sources.json came back as "no source data" and the only way to
		// get an answer was to already know what was in there. A search over
		// what is known keeps the typing and loses the guessing - and unlike a
		// dropdown it gets better as the database grows rather than worse.
		List<ItemSource> sortedItems = allItemSources.stream()
			.sorted(Comparator.comparing(ItemSource::getDisplayName))
			.collect(Collectors.toList());
		itemPicker = new SearchPicker<>(sortedItems, ItemSource::getDisplayName,
			"Search for an item", "Type to search, or pick from the list");
		itemQuantitySpinner = new JSpinner(new SpinnerNumberModel(1, 1, 10000, 1));
		constrainSpinner(itemQuantitySpinner);
		countOwnedCheckbox = new JCheckBox("Count what I already own");
		countOwnedCheckbox.setBackground(ColorScheme.DARK_GRAY_COLOR);
		countOwnedCheckbox.setForeground(SUBTLE);
		countOwnedCheckbox.setFont(SMALL_FONT);
		countOwnedCheckbox.setSelected(true);
		countOwnedCheckbox.setFocusPainted(false);
		countOwnedCheckbox.setToolTipText("On: plans only what is missing from your bank, "
			+ "inventory and gear. Off: plans the full route as if you had none, which is what "
			+ "you want when you already own one and are after another.");
		itemPicker.setTrailing(itemQuantitySpinner);
		stack(chooseContainer, goalBlock("Item", itemPicker, countOwnedCheckbox,
			"Plan path", e ->
			{
				ItemSource selected = itemPicker.getSelected();
				if (selected == null)
				{
					itemPicker.promptForChoice();
					return;
				}
				showPlan(pathResolver.apply(Goal.itemQuantity(selected.getId(),
					(Integer) itemQuantitySpinner.getValue(), selected.getDisplayName(),
					tickManipulationCheckbox.isSelected(), countOwnedCheckbox.isSelected())));
			}));

		// --- Goal: a floor under every skill ---
		// "I want 80+ in everything" is a question the panel could not be asked.
		// Answering it one skill at a time means working out which are short and
		// in what order by hand, which is the part a plan is for.
		baseStatsSpinner = new JSpinner(new SpinnerNumberModel(70, 2, 99, 1));
		constrainSpinner(baseStatsSpinner);
		stack(chooseContainer, goalBlock("Base stats", goalCaption("Every skill at least"),
			baseStatsSpinner, "Plan path", e ->
				showPlan(pathResolver.apply(Goal.baseStats(
					(Integer) baseStatsSpinner.getValue(),
					tickManipulationCheckbox.isSelected())))));

		// --- Goal: a total level ---
		// The lower bound is 33, which is every skill at 1 and Hitpoints at 10;
		// the upper is every skill at 99. Outside that the number means nothing.
		totalLevelSpinner = new JSpinner(new SpinnerNumberModel(1500, 33, 2376, 1));
		// Plain digits. The default editor groups by locale, so 1500 renders as
		// "1.500" for anyone in Europe - which reads as one and a half, not
		// fifteen hundred.
		totalLevelSpinner.setEditor(new JSpinner.NumberEditor(totalLevelSpinner, "0"));
		constrainSpinner(totalLevelSpinner);
		stack(chooseContainer, goalBlock("Total level", goalCaption("Reach a total of"),
			totalLevelSpinner, "Plan path", e ->
				showPlan(pathResolver.apply(Goal.totalLevel(
					(Integer) totalLevelSpinner.getValue(),
					tickManipulationCheckbox.isSelected())))));

		// Sits with the other goal pickers, not under the plan: it is one of the
		// things you choose between when deciding what to do next.
		stack(chooseContainer, questsSection());

		plan.setOnClose(this::closePlan);
		content.add(plan.container());

		// --- Suggestions ---
		// "Available now" was a list of cards whose only action was to open the
		// wiki - the one thing this panel is trying to stop players needing to
		// do - so the space goes to the plan instead. The container survives
		// because the logged-out placeholder still renders into it.
		availableNowContainer.setLayout(new BoxLayout(availableNowContainer, BoxLayout.Y_AXIS));
		availableNowContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		availableNowContainer.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(availableNowContainer);

		almostThereHeader = sectionHeader("Almost there");
		stack(content, almostThereHeader);
		almostBackRow = kit.linkRow(java.util.Collections.singletonList(
			kit.actionLink("\u2190 Back", () -> setMode(Mode.START))));
		stack(content, almostBackRow);
		almostThereContainer.setLayout(new BoxLayout(almostThereContainer, BoxLayout.Y_AXIS));
		almostThereContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		almostThereContainer.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(almostThereContainer);
		setMode(Mode.START);

		// A measured gap, so the credit sits at the foot of the sidebar instead
		// of following whatever is on screen. On a fresh login there is almost
		// nothing above it, and the licence text arriving directly under
		// "Almost there" reads as the answer to the question the player just
		// asked. See sinkFooter for why this is measured rather than glued.
		footerSpacer.setOpaque(false);
		footerSpacer.setAlignmentX(Component.LEFT_ALIGNMENT);
		footerSpacer.setPreferredSize(new Dimension(1, 0));
		footerSpacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, 0));
		content.add(footerSpacer);
		stack(content, attributionBlock());

		scrollPane = new JScrollPane(content);
		kit.scrollPane = scrollPane;
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		// The ContentPanel below tracks the viewport width, so there is never
		// anything to scroll to horizontally.
		scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		scrollPane.getViewport().addComponentListener(new java.awt.event.ComponentAdapter()
		{
			@Override
			public void componentResized(java.awt.event.ComponentEvent resized)
			{
				sinkFooter();
			}
		});
		add(scrollPane, BorderLayout.CENTER);

		showPlaceholder();
	}

	/**
	 * Inputs report a preferred width based on their widest content - a long
	 * activity name or a 23-entry skill list will ask for far more than the
	 * 225px the sidebar has. Pin them to the panel width instead.
	 */
	private static void constrainInput(javax.swing.JComponent input)
	{
		int h = input.getPreferredSize().height;
		input.setPreferredSize(new Dimension(CONTENT_WIDTH, h));
		input.setMinimumSize(new Dimension(40, h));
		input.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
	}

	/**
	 * Pins a spinner to the width its own digits need.
	 * <p>
	 * This was a flat 56px, which fits two digits and an arrow box and clips the
	 * last digit off a total level of 2000. The editor is told how many columns
	 * the model's maximum actually takes, and the width then comes from the
	 * spinner rather than from a guess about fonts and arrow widths.
	 */
	private static void constrainSpinner(JSpinner spinner)
	{
		if (spinner.getEditor() instanceof JSpinner.DefaultEditor
			&& spinner.getModel() instanceof SpinnerNumberModel)
		{
			Comparable<?> max = ((SpinnerNumberModel) spinner.getModel()).getMaximum();
			int digits = max instanceof Number
				? String.valueOf(((Number) max).longValue()).length()
				: 2;
			((JSpinner.DefaultEditor) spinner.getEditor()).getTextField()
				.setColumns(Math.max(2, digits));
		}
		Dimension want = spinner.getPreferredSize();
		Dimension size = new Dimension(Math.max(56, want.width), want.height);
		spinner.setPreferredSize(size);
		spinner.setMinimumSize(size);
		spinner.setMaximumSize(size);
	}

	/**
	 * One goal row: a caption, the input (optionally with a small trailing
	 * spinner), and a full-width action button underneath.
	 */
	private JPanel goalBlock(String caption, Component input, JSpinner trailing, String buttonText,
		java.awt.event.ActionListener action)
	{
		return goalBlock(caption, input, trailing, null, buttonText, action);
	}

	/**
	 * The left half of a goal row that has no list to pick from - just a
	 * sentence and the number that finishes it. "Every skill at least [80]"
	 * reads as one thing, where a bare spinner under a heading reads as a
	 * setting.
	 */
	private JLabel goalCaption(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(DETAIL);
		label.setFont(SMALL_FONT);
		return label;
	}

	/**
	 * A goal block built round a {@link SearchPicker} instead of a dropdown.
	 * <p>
	 * Separate from the dropdown version because the picker owns its own height:
	 * it is a field with a results list that appears and disappears underneath,
	 * so pinning the input row to one line - which is right for a combo box -
	 * would clip the matches away.
	 */
	private JPanel goalBlock(String caption, SearchPicker<?> picker, Component extra,
		String buttonText, java.awt.event.ActionListener action)
	{
		// Its height is asked for every layout, never fixed. stack() caps a
		// block at the height it has when the panel is built, and this one is
		// built with the matches closed - so typing opened a list inside a block
		// that could not grow, and the list came out 6px tall: the field took
		// the text, and nothing showed underneath to say what it had found.
		JPanel block = new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setBackground(ColorScheme.DARK_GRAY_COLOR);
		block.setBorder(new EmptyBorder(6, 0, 2, 0));

		stack(block, kit.microLabel(caption, SUBTLE, 0));
		stack(block, picker);
		if (extra != null)
		{
			stack(block, extra);
		}

		JButton button = new JButton(buttonText);
		button.setFocusPainted(false);
		button.addActionListener(action);
		stack(block, button);

		block.setAlignmentX(Component.LEFT_ALIGNMENT);
		return block;
	}

	/** As above, with one extra control between the inputs and the button. */
	private JPanel goalBlock(String caption, Component input, JSpinner trailing, Component extra,
		String buttonText, java.awt.event.ActionListener action)
	{
		JPanel block = new JPanel();
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setBackground(ColorScheme.DARK_GRAY_COLOR);
		block.setBorder(new EmptyBorder(6, 0, 2, 0));

		stack(block, kit.microLabel(caption, SUBTLE, 0));

		JPanel inputRow = new JPanel(new BorderLayout(4, 0));
		inputRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		inputRow.add(input, BorderLayout.CENTER);
		if (trailing != null)
		{
			inputRow.add(trailing, BorderLayout.EAST);
		}
		// Tall enough for everything on the row, not just the thing in the
		// middle of it. Two of these rows have a plain caption in the centre and
		// the spinner beside it; a caption is some 15px tall, so taking the
		// height from the centre alone squeezed the spinner and cut the tops and
		// bottoms off its digits.
		int rowHeight = input.getPreferredSize().height;
		if (trailing != null)
		{
			rowHeight = Math.max(rowHeight, trailing.getPreferredSize().height);
		}
		inputRow.setPreferredSize(new Dimension(CONTENT_WIDTH, rowHeight));
		stack(block, inputRow);

		if (extra != null)
		{
			stack(block, extra);
		}

		JButton button = new JButton(buttonText);
		button.setFocusPainted(false);
		button.addActionListener(action);
		stack(block, button);

		block.setAlignmentX(Component.LEFT_ALIGNMENT);
		block.setMaximumSize(new Dimension(Integer.MAX_VALUE, block.getPreferredSize().height));
		return block;
	}

	/**
	 * Visible credit for where every figure in this panel came from.
	 * <p>
	 * None of this content is ours: the xp rates, requirements, drop rates and
	 * quest chains are facts read off the Old School RuneScape Wiki, which
	 * publishes under CC BY-NC-SA 3.0 and asks for attribution. The wiki link
	 * on each individual step is not a substitute for saying so once, plainly,
	 * where the player can see it - and the game itself is Jagex's, which a
	 * third-party tool should state rather than leave ambiguous.
	 */
	private JPanel attributionBlock()
	{
		JPanel block = new JPanel();
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setBackground(ColorScheme.DARK_GRAY_COLOR);
		block.setAlignmentX(Component.LEFT_ALIGNMENT);
		block.setBorder(new EmptyBorder(16, 0, 4, 0));

		// A rule above it, for the same reason the steps have one: it marks this
		// off as the edge of the panel rather than one more thing to read.
		block.add(kit.hairline());
		block.add(Box.createVerticalStrut(8));

		// One line. The credit the licence asks for is the wiki's name and
		// the licence's, and both are here; the rest is on the hover, because
		// three paragraphs of it under a two-choice screen read as content.
		JLabel credit = kit.actionLink("Data: OSRS Wiki \u2197", () -> PanelKit.openUrl(WIKI_URL));
		credit.setToolTipText("<html>Data from the Old School RuneScape Wiki, used under "
			+ "CC BY-NC-SA 3.0.<br>This plugin owns none of it.<br>Not affiliated with or endorsed "
			+ "by Jagex. RuneScape and Old School<br>RuneScape are trademarks of Jagex Ltd.</html>");
		JLabel licence = kit.actionLink("CC BY-NC-SA 3.0 \u2197", () -> PanelKit.openUrl(LICENCE_URL));
		licence.setToolTipText(LICENCE_URL);
		block.add(kit.linkRow(java.util.Arrays.asList(credit, licence)));

		return block;
	}

	/**
	 * Plans a path to a suggested activity, as if it had been picked from the
	 * Activity dropdown - which it also is, so the controls agree with the
	 * result on screen rather than the plan appearing to come from nowhere.
	 */
	void planFor(Activity activity)
	{
		activityCombo.setSelectedItem(activity);
		showPlan(pathResolver.apply(Goal.activity(activity.getId(), activity.getName(),
			tickManipulationCheckbox.isSelected())));
	}

	/** HUNTER -> Hunter. Display only; the underlying value is untouched. */
	private static String titleCase(String skill)
	{
		if (skill == null || skill.isEmpty())
		{
			return skill;
		}
		return skill.substring(0, 1).toUpperCase(java.util.Locale.ROOT)
			+ skill.substring(1).toLowerCase(java.util.Locale.ROOT);
	}

	/**
	 * Quests get a signpost rather than a picker.
	 * <p>
	 * Listing 168 quests to choose a goal from would be rebuilding the front
	 * page of a plugin that already does it better - Quest Helper lists what you
	 * can start, with its requirements, and then walks you through it. What this
	 * panel keeps is the part Quest Helper doesn't do: when a quest stands
	 * between you and something you asked for, it is named in the plan, in order.
	 */
	private JPanel questsSection()
	{
		JPanel block = new JPanel();
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setBackground(ColorScheme.DARK_GRAY_COLOR);
		block.setAlignmentX(Component.LEFT_ALIGNMENT);
		block.setBorder(new EmptyBorder(4, 0, 8, 0));

		block.add(kit.microLabel("Quests", SUBTLE, 0));

		JLabel body = kit.resultLine("Pick a quest in Quest Helper \u2014 it lists every one you "
			+ "can start and walks you through it. Quests needed for a goal here still "
			+ "show up in its plan.", DETAIL, 0);
		body.setFont(SMALL_FONT);
		body.setBorder(new EmptyBorder(3, 0, 0, 0));
		block.add(body);

		JLabel pointer = kit.helperPointer(PanelKit.QUEST_HELPER, "quest-helper",
			"is installed and ready.", "the quest list and walkthroughs", 0);
		block.add(pointer);

		block.setMaximumSize(new Dimension(Integer.MAX_VALUE, block.getPreferredSize().height));
		return block;
	}

	/** A vertical, left-aligned, transparent strip - the shape every screen uses. */
	private void column(JPanel panel)
	{
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	/**
	 * The two ways in, as two offers rather than a menu bar: naming what each
	 * one is for is the whole point, since the second one only makes sense once
	 * you have read it.
	 */
	private void buildStartScreen()
	{
		stack(startContainer, sectionHeader("What now?"));
		stack(startContainer, startOption("Plan a path",
			"A boss, a skill level, an item - and everything it takes to get there.",
			() -> setMode(Mode.CHOOSE)));
		stack(startContainer, startOption("Surprise me",
			"One thing you can already do, picked at random. For when nothing in "
				+ "particular is calling.",
			() ->
			{
				setMode(Mode.RANDOM);
				roll();
			}));
		stack(startContainer, startOption("Almost there",
			"What you are a few levels or a quest away from being able to do.",
			() -> setMode(Mode.ALMOST)));
	}

	private JPanel startOption(String title, String blurb, Runnable action)
	{
		// The two things to do on the opening screen are the clearest case of
		// all for a box: nothing else is on screen to tell them apart from the
		// sentence sitting under each of them.
		JPanel block = kit.optionCard(false);
		int outer = kit.cardInset;
		kit.cardInset = CARD_INSET;
		try
		{
			JLabel heading = kit.resultLine(title + " \u2192", ACCENT, 0);
			heading.setFont(STEP_TITLE_FONT);
			kit.makeClickable(heading, action);
			stack(block, heading);

			JLabel detail = kit.resultLine(blurb, DETAIL, 0);
			detail.setFont(SMALL_FONT);
			stack(block, detail);
		}
		finally
		{
			kit.cardInset = outer;
		}

		block.setMaximumSize(new Dimension(Integer.MAX_VALUE, block.getPreferredSize().height));
		return block;
	}

	/**
	 * Grows or shrinks the gap above the attribution so it ends up at the bottom
	 * of the sidebar.
	 * <p>
	 * Measured rather than glued: a Scrollable that tracks the viewport height
	 * hangs this panel (see ContentPanel), and glue inside a scroll pane gets no
	 * leftover height to take because the view is sized to its own preferred
	 * height. So the gap is worked out here - viewport height minus what the
	 * content comes to without it - and left at zero whenever the content is
	 * already taller than the viewport, which is the usual case once a plan is
	 * on screen. Changes under 4px are ignored: the one thing worse than a
	 * footer in the wrong place is a layout that keeps relaying itself.
	 */
	private void sinkFooter()
	{
		if (scrollPane == null || content == null)
		{
			return;
		}
		int spacer = footerSpacer.getPreferredSize().height;
		int withoutSpacer = content.getPreferredSize().height - spacer;
		int want = Math.max(0, scrollPane.getViewport().getHeight() - withoutSpacer);
		if (Math.abs(want - spacer) < 4)
		{
			return;
		}
		footerSpacer.setPreferredSize(new Dimension(1, want));
		footerSpacer.setMaximumSize(new Dimension(Integer.MAX_VALUE, want));
		footerSpacer.setMinimumSize(new Dimension(1, want));
		content.revalidate();
	}

	/** Shows one screen and clears whatever the last one left on the page. */
	private void setMode(Mode next)
	{
		mode = next;
		planOpen = false;
		// A plan belongs to the question that produced it.
		plan.clearPath();
		if (next != Mode.RANDOM)
		{
			randomContainer.removeAll();
		}
		showScreen();
	}

	/**
	 * Puts a plan on screen by itself; its own Back link closes it. Whatever screen
	 * asked for it is hidden, not cleared, so going back finds the pickers as
	 * they were left and a rolled suggestion still rolled.
	 */
	private void showPlan(Path path)
	{
		planOpen = true;
		showScreen();
		plan.renderPath(path);
	}

	private void closePlan()
	{
		planOpen = false;
		plan.clearPath();
		showScreen();
	}

	/** Makes what is visible agree with the mode and with whether a plan is open. */
	private void showScreen()
	{
		startContainer.setVisible(!planOpen && mode == Mode.START);
		chooseContainer.setVisible(!planOpen && mode == Mode.CHOOSE);
		randomContainer.setVisible(!planOpen && mode == Mode.RANDOM);
		plan.container().setVisible(planOpen);
		availableNowContainer.setVisible(!planOpen);
		// A screen of its own, reached from the opening one. Sitting under
		// every other screen it made each of them a long page, and the opening
		// screen - two choices - the longest of all.
		boolean almost = !planOpen && mode == Mode.ALMOST;
		almostThereHeader.setVisible(almost);
		almostBackRow.setVisible(almost);
		almostThereContainer.setVisible(almost);
		revalidate();
		repaint();
		SwingUtilities.invokeLater(this::sinkFooter);
	}

	/**
	 * Picks one thing to do, from what the player can actually do right now.
	 * <p>
	 * Weighted by the activity's own priority rather than drawn flat: two thirds
	 * of the bundled activities are quests, so a flat draw would answer "do a
	 * quest" two times in three and the feature would feel broken. Weighting
	 * keeps the long tail reachable while the notable content comes up more
	 * often, and the category filter is there for when the player does have a
	 * mood in mind.
	 */
	private void roll()
	{
		List<Activity> pool = new ArrayList<>();
		// Logged out there is no player state to filter by, so the whole
		// catalogue is the pool and the panel says so rather than sitting empty.
		for (Activity activity : availableNow.isEmpty() ? allActivities : availableNow)
		{
			if (rollCategory != null && activity.getCategory() != rollCategory)
			{
				continue;
			}
			if (!recentRolls.contains(activity.getId()))
			{
				pool.add(activity);
			}
		}
		if (pool.isEmpty())
		{
			// Everything left is something we just offered: start the memory over
			// rather than refusing to roll.
			recentRolls.clear();
			for (Activity activity : availableNow.isEmpty() ? allActivities : availableNow)
			{
				if (rollCategory == null || activity.getCategory() == rollCategory)
				{
					pool.add(activity);
				}
			}
		}

		rolled = weightedPick(pool);
		if (rolled != null)
		{
			recentRolls.addLast(rolled.getId());
			while (recentRolls.size() > 6)
			{
				recentRolls.removeFirst();
			}
		}
		renderRoll();
	}

	private Activity weightedPick(List<Activity> pool)
	{
		if (pool.isEmpty())
		{
			return null;
		}
		int total = 0;
		for (Activity activity : pool)
		{
			total += Math.max(1, activity.getPriority());
		}
		int target = random.nextInt(total);
		for (Activity activity : pool)
		{
			target -= Math.max(1, activity.getPriority());
			if (target < 0)
			{
				return activity;
			}
		}
		return pool.get(pool.size() - 1);
	}

	private void renderRoll()
	{
		randomContainer.removeAll();
		stack(randomContainer, sectionHeader("Something to do"));
		stack(randomContainer, categoryRow());

		if (rolled == null)
		{
			stack(randomContainer, kit.resultLine("Nothing to pick from in that category.", SUBTLE, 0));
		}
		else
		{
			stack(randomContainer, kit.hairline());
			String kind = rolled.getCategory() == null
				? "Activity"
				: rolled.getCategory().name().toLowerCase(java.util.Locale.ROOT).replace('_', ' ');
			stack(randomContainer, kit.microLabel(kind, SUBTLE, 11));

			JLabel name = kit.resultLine(rolled.getName(), PRIMARY, 0);
			name.setFont(STEP_TITLE_FONT);
			stack(randomContainer, name);

			if (rolled.getDescription() != null && !rolled.getDescription().isEmpty())
			{
				JLabel description = kit.resultLine(rolled.getDescription(), DETAIL, 0);
				description.setFont(SMALL_FONT);
				stack(randomContainer, description);
			}

			if (availableNow.isEmpty())
			{
				stack(randomContainer, kit.resultLine("! Rolled from everything \u2014 log in so this "
					+ "can pick something you can actually do now.", Color.ORANGE, 0));
			}

			final Activity picked = rolled;
			stack(randomContainer, kit.linkRow(java.util.Arrays.asList(
				kit.actionLink("Plan it \u2192", () -> planFor(picked)),
				kit.actionLink("Roll again", this::roll))));
		}

		stack(randomContainer, kit.linkRow(java.util.Collections.singletonList(
			kit.actionLink("\u2190 Back", () -> setMode(Mode.START)))));
		randomContainer.revalidate();
		randomContainer.repaint();
	}

	/**
	 * The mood filter. Not a dropdown: at six entries a row of words is fewer
	 * clicks than opening a combo, and it shows what the choices are.
	 * <p>
	 * Three to a line, because a link row lays its children out horizontally and
	 * never wraps: six of them walked straight off the right edge of a 190px
	 * sidebar, leaving "Anything" and two letters of "Quests" on screen.
	 */
	private JPanel categoryRow()
	{
		List<JLabel> top = new ArrayList<>();
		top.add(categoryChip("Anything", null));
		top.add(categoryChip("Quests", Activity.Category.QUEST));
		top.add(categoryChip("Bosses", Activity.Category.PVM));

		List<JLabel> bottom = new ArrayList<>();
		bottom.add(categoryChip("Diaries", Activity.Category.DIARY));
		bottom.add(categoryChip("Minigames", Activity.Category.MINIGAME));
		bottom.add(categoryChip("Skilling", Activity.Category.SKILLING));

		JPanel rows = new JPanel();
		column(rows);
		rows.add(kit.linkRow(top));
		rows.add(kit.linkRow(bottom));
		rows.setMaximumSize(new Dimension(Integer.MAX_VALUE, rows.getPreferredSize().height));
		return rows;
	}

	/**
	 * A plain label, not a {@link #resultLine}: those wrap text inside a table
	 * of the full content width, so a row of them is a row of 190px-wide blocks
	 * and only the first one is on screen.
	 */
	private JLabel categoryChip(String text, Activity.Category category)
	{
		boolean on = rollCategory == category;
		JLabel chip = new JLabel(text);
		chip.setForeground(on ? ACCENT : QUIET_LINK);
		chip.setFont(SMALL_FONT);
		if (!on)
		{
			kit.makeClickable(chip, () ->
			{
				rollCategory = category;
				roll();
			});
		}
		return chip;
	}

	private JLabel sectionHeader(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(PRIMARY);
		label.setFont(HEADER_FONT);
		label.setBorder(new EmptyBorder(12, 0, 4, 0));
		return label;
	}

	/**
	 * The logged-out state, in this panel's own typography rather than
	 * RuneLite's PluginErrorPanel.
	 * <p>
	 * PluginErrorPanel puts its description in an HTML label with no wrap width,
	 * so it asked for 253px inside a 225px sidebar. Horizontal scrolling is off
	 * here, so nothing scrolls to reach it - the tail of the sentence is simply
	 * cut off at the viewport edge, on the one screen a new user sees first.
	 * Text wrapped by this panel has a width by construction, and
	 * PanelWidthTest is the guard that keeps it that way.
	 */
	private void showPlaceholder()
	{
		stack(availableNowContainer, sectionHeader("Now What"));
		stack(availableNowContainer, kit.resultLine(
			"Log in to see suggestions based on your progress.", SUBTLE, 0));
	}

	/** Lets gear be drawn as a worn-equipment loadout, which needs the game thread for slots. */
	public void setClientThread(ClientThread clientThread)
	{
		plan.setClientThread(clientThread);
	}

	/**
	 * The player's current levels, pushed in by NowWhatPlugin on the Swing
	 * thread after each refresh.
	 * <p>
	 * A plan is rendered once and then sat there while the player went and did
	 * it, so a step stayed on screen after it was finished and the list only
	 * ever got longer to scroll through. The rendered plan is rebuilt when, and
	 * only when, this changes which steps count as finished - it is called on
	 * every refresh, and rebuilding the panel each time would make it flicker
	 * for no reason.
	 */
	public void setProgress(Map<String, Integer> currentLevels)
	{
		plan.setProgress(currentLevels, java.util.Collections.emptySet());
	}

	/**
	 * @param finishedActivities the name of every quest, diary tier and other
	 *                           activity with a done state that the player has
	 *                           reached
	 */
	public void setProgress(Map<String, Integer> currentLevels, Set<String> finishedActivities)
	{
		plan.setProgress(currentLevels, finishedActivities);
	}

	public void update(List<Activity> almostAvailable)
	{
		update(java.util.Collections.emptyList(), almostAvailable);
	}

	/**
	 * @param availableNowList what the player can do right now, which is also
	 *                         the pool a roll draws from
	 */
	public void update(List<Activity> availableNowList, List<Activity> almostAvailable)
	{
		update(availableNowList, almostAvailable, java.util.Collections.emptyMap());
	}

	/**
	 * @param missingById per activity id, the line saying what is still in the
	 *                    way ("Needs 91 Slayer, you have 87"). A suggestion
	 *                    that only named a category and a boss left the player
	 *                    to work out for themselves why it was "almost".
	 */
	public void update(List<Activity> availableNowList, List<Activity> almostAvailable,
		Map<String, String> missingById)
	{
		this.availableNow = availableNowList;
		if (mode == Mode.RANDOM && rolled == null)
		{
			// The panel can open before the first refresh arrives; once it does,
			// a roll that had nothing to draw from gets its answer.
			roll();
		}
		availableNowContainer.removeAll();
		almostThereContainer.removeAll();

		if (almostAvailable.isEmpty())
		{
			stack(almostThereContainer, kit.resultLine("Nothing close enough to list yet.", SUBTLE, 0));
		}
		else
		{
			for (Activity activity : almostAvailable)
			{
				stack(almostThereContainer, new ActivityCard(activity, missingById.get(activity.getId()),
					kit.wrapWidth(14), this::planFor));
			}
		}

		availableNowContainer.revalidate();
		availableNowContainer.repaint();
		almostThereContainer.revalidate();
		almostThereContainer.repaint();
	}
}

package com.nowwhat;

import com.google.inject.Provides;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.CombatAchievementTracker;
import com.nowwhat.data.DiaryTracker;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.ItemTracker;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.engine.SuggestionEngine;
import com.nowwhat.model.Goal;
import com.nowwhat.model.Path;
import com.nowwhat.model.PlayerState;
import java.awt.image.BufferedImage;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import com.nowwhat.model.Activity;

@Slf4j
@PluginDescriptor(
	name = "Now What",
	description = "Suggests what to do next based on your skills, quests, diaries and Combat Achievements",
	tags = {"todo", "goals", "quests", "diaries", "combat achievements", "pvm", "advisor", "planner"}
)
public class NowWhatPlugin extends Plugin
{
	// Refresh isn't event-driven off every relevant varbit change (there are
	// too many to subscribe to individually and reliably); instead we
	// recompute on a timer. The two things a player watches for - a level-up
	// and a change in what they are carrying - do not wait for it: each asks
	// for a refresh on the next tick.
	private static final int REFRESH_INTERVAL_TICKS = 50; // ~30 seconds

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private NowWhatConfig config;

	@Inject
	private ActivityDatabase activityDatabase;

	@Inject
	private DiaryTracker diaryTracker;

	@Inject
	private TrainingMethodDatabase trainingMethodDatabase;

	@Inject
	private ItemSourceDatabase itemSourceDatabase;

	@Inject
	private ItemTracker itemTracker;

	// Only ever asked whether Quest Helper is installed and on, so the panel can
	// say the right thing when a path needs quests. No API of theirs is touched.
	@Inject
	private net.runelite.client.plugins.PluginManager pluginManager;

	/**
	 * RuneLite's item index and icon source, handed to the panel so a boss's
	 * "what to bring" list can show the gear as pictures rather than only as
	 * nine item names in a row.
	 */
	@Inject
	private net.runelite.client.game.ItemManager itemManager;

	private final SuggestionEngine suggestionEngine = new SuggestionEngine();
	private final CombatAchievementTracker combatAchievementTracker = new CombatAchievementTracker();
	private PrerequisiteResolver prerequisiteResolver;
	private PathPlanner pathPlanner;

	private NowWhatPanel panel;
	private NavigationButton navButton;
	private int ticksSinceRefresh = 0;
	/** The real level last seen per skill, to tell a level-up from an xp drop. */
	private final Map<Skill, Integer> lastLevels = new HashMap<>();

	// Snapshot from the most recent refresh, read by the panel's "check
	// requirements" lookup so that lookups don't need to hop back onto the
	// client thread on every click - a few seconds of staleness is fine here.
	private volatile PlayerState latestState = new PlayerState();

	@Provides
	NowWhatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NowWhatConfig.class);
	}

	@Override
	protected void startUp()
	{
		activityDatabase.load();
		// The activities go in too: a method that is really an activity takes that
		// activity's kit, so the skill path pictures the same gear the
		// suggestion list does.
		trainingMethodDatabase.load(activityDatabase.getAllActivities());
		itemSourceDatabase.load();
		itemTracker.load();
		prerequisiteResolver = new PrerequisiteResolver(activityDatabase.getAllActivities());
		pathPlanner = new PathPlanner(activityDatabase.getAllActivities(), prerequisiteResolver,
			trainingMethodDatabase, itemSourceDatabase);

		panel = new NowWhatPanel(config, activityDatabase.getAllActivities(),
			itemSourceDatabase.getAllSources(), this::resolvePath, pluginManager, itemManager);
		// Gear is drawn in the shape of the worn-equipment tab, and which slot an
		// item goes in can only be asked on the game thread.
		panel.setClientThread(clientThread);
		// Lets the panel open another plugin's sidebar panel when it points at
		// one - the toolbar is the only thing that can.

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/nowwhat/icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Now What")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			refresh();
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			ticksSinceRefresh = REFRESH_INTERVAL_TICKS; // force refresh next tick
		}
	}

	/**
	 * Equipment and inventory stream in continuously; the bank arrives only
	 * when the player opens it. Either way a change is worth a refresh, since
	 * what you own feeds straight into what the planner tells you to go get.
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (itemTracker.onContainerChanged(event.getContainerId(), event.getItemContainer()))
		{
			ticksSinceRefresh = REFRESH_INTERVAL_TICKS; // refresh on the next tick
		}
	}

	/**
	 * A level-up is what finishes a training step, and it used to sit on screen
	 * as unfinished until the timer came round, up to half a minute later. Only
	 * the level matters: an xp drop arrives every few ticks while training and
	 * changes nothing the panel shows.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer before = lastLevels.put(event.getSkill(), event.getLevel());
		if (before != null && before != event.getLevel())
		{
			ticksSinceRefresh = REFRESH_INTERVAL_TICKS; // refresh on the next tick
		}
	}

	/** Another account has logged in: what was known about the last one's items goes. */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		lastLevels.clear();
		itemTracker.load();
		ticksSinceRefresh = REFRESH_INTERVAL_TICKS;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		ticksSinceRefresh++;
		if (ticksSinceRefresh >= REFRESH_INTERVAL_TICKS)
		{
			ticksSinceRefresh = 0;
			refresh();
		}
	}

	/**
	 * Rebuilds PlayerState from the live client (must run on the client
	 * thread) then hands it to the suggestion engine off-thread and pushes
	 * results to the Swing panel.
	 */
	private void refresh()
	{
		clientThread.invoke(() ->
		{
			PlayerState state = buildPlayerState();
			latestState = state;

			SwingUtilities.invokeLater(() ->
			{
				Set<Activity.Category> hidden = hiddenCategories();
				// Before the suggestions, because this can rebuild a rendered
				// plan and the update below repaints around it.
				Set<String> finished = new java.util.HashSet<>();
				for (Activity activity : activityDatabase.getAllActivities())
				{
					if (com.nowwhat.engine.RequirementEvaluator.isAlreadyDone(activity, state))
					{
						finished.add(activity.getName());
					}
				}
				panel.setProgress(state.getSkillLevels(), finished);
				boolean hideWilderness = !config.showWilderness();
				List<Activity> almost = suggestionEngine.getAlmostAvailable(
					activityDatabase.getAllActivities(), state, hidden, hideWilderness);
				Map<String, String> missing = new HashMap<>();
				for (Activity activity : almost)
				{
					missing.put(activity.getId(), suggestionEngine.whatIsMissing(activity, state));
				}
				panel.update(
					suggestionEngine.getAvailableNow(activityDatabase.getAllActivities(), state, hidden,
						hideWilderness),
					almost, missing
				);
			});
		});
	}

	/**
	 * The categories the player has switched off in settings.
	 * <p>
	 * Only the four categories with a switch can appear here. MINIGAME,
	 * SKILLING, COMBAT_ACHIEVEMENT and CLUE_SCROLL have no setting of their
	 * own, so they are never hidden - adding a switch is what would change
	 * that, not adding a category.
	 */
	private Set<Activity.Category> hiddenCategories()
	{
		Set<Activity.Category> hidden = EnumSet.noneOf(Activity.Category.class);
		if (!config.showQuests())
		{
			hidden.add(Activity.Category.QUEST);
		}
		if (!config.showDiaries())
		{
			hidden.add(Activity.Category.DIARY);
		}
		if (!config.showPvm())
		{
			hidden.add(Activity.Category.PVM);
		}
		if (!config.showCollectionLog())
		{
			hidden.add(Activity.Category.COLLECTION_LOG);
		}
		return hidden;
	}

	private PlayerState buildPlayerState()
	{
		PlayerState state = new PlayerState();

		for (Skill skill : Skill.values())
		{
			// Skill.OVERALL is deprecated but still returned by values(); compare by
			// name so this keeps working if it is eventually dropped from the enum.
			if ("OVERALL".equals(skill.name()))
			{
				continue;
			}
			state.setSkillLevel(skill.name(), client.getRealSkillLevel(skill));
			// The xp too, not just the level: a total level plan compares the
			// cost of the next level in one skill against the next level in
			// another, and "level 62" is anywhere from the start of the bracket
			// to one xp short of the end of it.
			state.setSkillXp(skill.name(), client.getSkillExperience(skill));
		}

		for (Quest quest : Quest.values())
		{
			if (quest.getState(client) == net.runelite.api.QuestState.FINISHED)
			{
				state.addCompletedQuest(quest.getName());
			}
		}

		// The Quest enum doesn't expose each quest's reward QP, so an earlier
		// version gave up and left this at 0 - which silently made every
		// QUEST_POINTS requirement permanently unmet. The game already tracks the
		// running total in a varp; just read it.
		state.setQuestPoints(client.getVarpValue(VarPlayerID.QP));

		if (client.getLocalPlayer() != null)
		{
			state.setCombatLevel(client.getLocalPlayer().getCombatLevel());
		}

		diaryTracker.readInto(client, state);
		combatAchievementTracker.readInto(client, state);
		// Read here as well as on change. The change events for what is carried
		// and worn can arrive before the account they belong to is known, and
		// are then dropped with the last account's items; the client still has
		// both, so asking it is always right.
		itemTracker.load();
		itemTracker.onContainerChanged(InventoryID.INV, client.getItemContainer(InventoryID.INV));
		itemTracker.onContainerChanged(InventoryID.WORN, client.getItemContainer(InventoryID.WORN));
		itemTracker.writeInto(state);

		// PvM boss KC and collection log slot data intentionally left as
		// integration points - see README. For boss KC specifically: prefer
		// reading VarPlayerID.TOTAL_<BOSS>_KILLS-style varps directly (this is
		// how Goal Planner does it - no chat parsing or network calls needed)
		// once the per-boss varp ids are mapped; chat-message parsing is a
		// fallback only for bosses without a known varp.

		return state;
	}

	/**
	 * Called from the panel (EDT) when the user sets a skill/item/activity
	 * goal and asks for a path. Uses the cached snapshot from the last
	 * refresh rather than touching the client thread synchronously from a
	 * UI click.
	 */
	private Path resolvePath(Goal goal)
	{
		return pathPlanner.plan(goal, latestState);
	}
}

package com.nowwhat;

import static com.nowwhat.PanelStyle.*;

import com.nowwhat.data.PluginLookup;
import com.nowwhat.model.PathStep;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * The small pieces every screen in the sidebar is built from: a line of text
 * wrapped to the sidebar's real width, a caption, a rule, a link, a pointer to
 * another plugin.
 * <p>
 * One object rather than loose helpers because wrapping depends on two things
 * that change while the panel is alive - how wide the viewport is, and whether
 * the text is going inside an option box.
 */
@Slf4j
class PanelKit
{
	/** The plugin that actually walks you through a quest, as its Plugin Hub descriptor names it. */
	static final String QUEST_HELPER = "Quest Helper";
	static final String PLUGIN_HUB_URL = "https://runelite.net/plugin-hub/";

	/** Used only to ask whether a named helper plugin is present; null outside a real client. */
	private final PluginManager pluginManager;
	/** Whose viewport text is wrapped to. Null until the panel has built it. */
	JScrollPane scrollPane;

	PanelKit(PluginManager pluginManager)
	{
		this.pluginManager = pluginManager;
	}

	/**
	 * An empty option box: filled, edged, padded, and spaced off the one above.
	 * A chosen option is edged in green instead, so the decision is visible from
	 * the shape of the panel rather than only from the tick in its title.
	 */
	JPanel optionCard(boolean selected)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(OPTION_BG);
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(6, 0, 0, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(selected ? CHOSEN : OPTION_EDGE, 1),
				new EmptyBorder(7, 9, 8, 9))));
		return card;
	}

	/** A 1px rule between steps - the whole separation budget of this layout. */
	JPanel hairline()
	{
		JPanel rule = new JPanel();
		rule.setBackground(HAIRLINE);
		rule.setAlignmentX(Component.LEFT_ALIGNMENT);
		rule.setPreferredSize(new Dimension(10, 1));
		rule.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		rule.setBorder(null);
		return rule;
	}

	/** Uppercase, tracked, dim: the "STEP 3 - 1.3M XP" line above a step. */
	JLabel microLabel(String text, Color color, int topPad)
	{
		return microLabel(text, color, topPad, 0);
	}

	JLabel microLabel(String text, Color color, int topPad, int indent)
	{
		JLabel label = resultLine(text.toUpperCase(java.util.Locale.ROOT), color, indent);
		label.setFont(MICRO_FONT);
		label.setBorder(new EmptyBorder(topPad, indent, 1, 0));
		return label;
	}

	/**
	 * Puts links side by side instead of stacking them. Four stacked grey links
	 * under every step was most of what made the plan look like a wall.
	 */
	JPanel linkRow(List<JLabel> links)
	{
		return linkRow(links, 0);
	}

	JPanel linkRow(List<JLabel> links, int indent)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		// Transparent rather than painted: inside an option box the box's fill
		// has to show through, and everywhere else the parent is the panel
		// background this used to paint by hand.
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(new EmptyBorder(5, indent, 0, 0));
		for (int i = 0; i < links.size(); i++)
		{
			if (i > 0)
			{
				JLabel gap = new JLabel("   ");
				gap.setFont(SMALL_FONT);
				row.add(gap);
			}
			JLabel link = links.get(i);
			link.setBorder(null);
			link.setAlignmentY(Component.CENTER_ALIGNMENT);
			row.add(link);
		}
		row.add(javax.swing.Box.createHorizontalGlue());
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** A bare clickable label, for a link row. */
	JLabel actionLink(String text, Runnable onClick)
	{
		JLabel label = new JLabel(text);
		label.setForeground(QUIET_LINK);
		label.setFont(SMALL_FONT);
		makeClickable(label, onClick);
		return label;
	}

	/** Hand cursor plus a hover tint, so a clickable line looks clickable. */
	void makeClickable(JLabel label, Runnable onClick)
	{
		Color resting = label.getForeground();
		label.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.run();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setForeground(ColorScheme.BRAND_ORANGE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setForeground(resting);
			}
		});
	}

	JLabel wikiLink(String url, int indent)
	{
		JLabel link = resultLine("Wiki \u2197", QUIET_LINK, indent);
		link.setFont(SMALL_FONT);
		link.setToolTipText(url);
		link.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				openUrl(url);
			}
		});
		return link;
	}

	static void openUrl(String url)
	{
		try
		{
			LinkBrowser.browse(url);
		}
		catch (Exception ex)
		{
			log.warn("Failed to open wiki url", ex);
		}
	}

	/**
	 * A line of wrapped text. The HTML width is what makes the label wrap
	 * instead of stretching the panel; the indent is applied as a border so it
	 * doesn't eat into the wrap width.
	 */
	JLabel resultLine(String text, Color color, int indent)
	{
		JLabel label = new JLabel(wrapped(escape(text), wrapWidth(indent)));
		label.setForeground(color);
		label.setFont(BODY_FONT);
		label.setBorder(new EmptyBorder(1, indent, 1, 0));
		label.setToolTipText(text);
		return label;
	}

	/**
	 * Wrap width for a line of text, measured from the live viewport rather
	 * than computed from panel constants - border, scrollbar and look-and-feel
	 * insets all eat into the real width, and guessing at them is what left
	 * text clipped off the right edge.
	 */
	/**
	 * How much of the width the current option box is eating, while one is being
	 * filled. Text wraps to a width this panel works out itself (Swing will not
	 * wrap a label otherwise), so a box drawn around it has to be subtracted or
	 * every line inside one runs under its right edge.
	 */
	int cardInset;

	int wrapWidth(int indent)
	{
		int available = scrollPane == null ? 0 : scrollPane.getViewport().getWidth();
		if (available <= 40)
		{
			available = TEXT_WIDTH;
		}
		else if (!scrollPane.getVerticalScrollBar().isVisible())
		{
			// Adding content is about to make the scrollbar appear and take
			// this width away again.
			available -= PluginPanel.SCROLLBAR_WIDTH;
		}
		return Math.max(60, available - indent - cardInset - 8);
	}

	String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * One line about Quest Helper, worded for what the player actually has
	 * installed - telling someone to "install Quest Helper" when it is already
	 * running in the same sidebar is the kind of thing that makes a plugin feel
	 * like it isn't paying attention.
	 */
	JLabel questHelperPointer(PathStep.Type type, int count)
	{
		boolean diary = type == PathStep.Type.DO_DIARY;
		return helperPointer(QUEST_HELPER,
			"has " + (diary ? "the task list for " : "the walkthrough for ")
				+ (count == 1 ? (diary ? "this diary" : "this quest") : "each") + ".",
			"step-by-step help", 10);
	}

	/**
	 * One line about another plugin, worded for what the player actually has
	 * installed - telling someone to install a plugin that is already running in
	 * the same sidebar is the kind of thing that makes a plugin feel like it
	 * isn't paying attention.
	 */
	JLabel helperPointer(String pluginName, String does, String offer, int indent)
	{
		return helperPointer(pluginName, null, does, offer, indent);
	}

	JLabel helperPointer(String pluginName, String hubId, String does, String offer,
		int indent)
	{
		Plugin helper = findPlugin(pluginName);
		if (helper != null && pluginManager.isPluginEnabled(helper))
		{
			// Installed and running: name it and what it does. Opening its panel
			// for the player would mean reaching into RuneLite's sidebar, which
			// has no public way in.
			JLabel line = resultLine(pluginName + " " + does, SUBTLE, indent);
			line.setFont(SMALL_FONT);
			return line;
		}

		if (helper != null)
		{
			// Installed but switched off. Said rather than done: switching on
			// someone else's plugin is the player's call, made in RuneLite's own
			// plugin list.
			JLabel line = resultLine(pluginName + " is installed but switched off. Turn it "
				+ "on in RuneLite's plugin list for " + offer + ".", SUBTLE, indent);
			line.setFont(SMALL_FONT);
			return line;
		}

		JLabel line = resultLine("Install " + pluginName + " from the Plugin Hub for "
			+ offer + " \u2197", QUIET_LINK, indent);
		line.setFont(SMALL_FONT);
		String url = hubId == null ? PLUGIN_HUB_URL : PLUGIN_HUB_URL + "show/" + hubId;
		line.setToolTipText(url);
		makeClickable(line, () -> openUrl(url));
		return line;
	}

	/**
	 * Looks a plugin up by the name in its PluginDescriptor. Name-based on
	 * purpose: it keeps this a one-way, read-only nod at another plugin with no
	 * compile-time dependency on it, so Now What still builds and runs whether
	 * or not Quest Helper is installed.
	 *
	 * @see PluginLookup for the matching itself, and for the bug that put it in
	 * its own tested class
	 */
	Plugin findPlugin(String descriptorName)
	{
		if (pluginManager == null)
		{
			return null;
		}
		List<Plugin> plugins = new ArrayList<>(pluginManager.getPlugins());
		List<String> names = new ArrayList<>(plugins.size());
		List<String> classNames = new ArrayList<>(plugins.size());
		for (Plugin plugin : plugins)
		{
			PluginDescriptor descriptor = plugin.getClass().getAnnotation(PluginDescriptor.class);
			names.add(descriptor == null ? null : descriptor.name());
			classNames.add(plugin.getClass().getName());
		}
		int at = PluginLookup.match(descriptorName, names, classNames);
		return at < 0 ? null : plugins.get(at);
	}
}

package com.nowwhat;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar's colours, fonts and widths, and the two layout helpers every
 * part of it leans on. Kept in one place so the panel, the gear view and the
 * suggestion rows cannot drift apart in how they look.
 */
final class PanelStyle
{
	private PanelStyle()
	{
	}

	// The sidebar is a fixed 225px wide and never gets wider, so every piece of
	// text has to be told what width to wrap at - Swing will happily report a
	// 600px preferred width for a long label and drag the whole panel sideways.
	static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH - (2 * PluginPanel.BORDER_OFFSET);
	// Fallback only, for the first render before the viewport has a real width.
	static final int TEXT_WIDTH = CONTENT_WIDTH - PluginPanel.SCROLLBAR_WIDTH;

	static final Color SUBTLE = new Color(0xAD, 0xA6, 0x9C);
	// Detail text sits under every option, so it is the most-read text in the
	// panel and was the least legible: 0x808080 pixel-font on a dark background.
	static final Color DETAIL = new Color(0xC6, 0xC0, 0xB5);
	static final Color CHOSEN = new Color(0x86, 0xC9, 0x8A);
	/**
	 * Text, instead of pure white. White at 13px against this grey is the glare
	 * the panel was accused of being flat by - a warm off-white carries the same
	 * weight without the hard edge, and leaves somewhere above the body text for
	 * the eye to go.
	 */
	static final Color PRIMARY = new Color(0xF1, 0xED, 0xE6);
	/**
	 * Links and the "show N others" controls. Kept above the note grey rather
	 * than below it: a control that reads fainter than the prose around it looks
	 * disabled.
	 */
	static final Color QUIET_LINK = new Color(0xB9, 0xB2, 0xA8);
	/**
	 * Softer than Color.CYAN, which was the loudest thing in the panel and sat
	 * above the content rather than beside it.
	 */
	static final Color ACCENT = new Color(0x8F, 0xD3, 0xE0);
	/** Caution, for the Wilderness tag. Amber over red: it survives colourblindness. */
	static final Color WARN = new Color(0xE3, 0xA8, 0x55);
	static final Color HAIRLINE = new Color(0x35, 0x33, 0x31);
	/**
	 * The things you can click sit in a box of their own.
	 * <p>
	 * Everything in this panel used to be the same flat column of text, and the
	 * only thing marking a method you could pick out from the sentence
	 * describing it was a 12px indent. A fill one step off the background and a
	 * 1px edge is enough to say "this is a thing, and it is one of several"
	 * without the panel turning into a stack of widgets.
	 */
	static final Color OPTION_BG = new Color(0x2F, 0x2D, 0x2B);
	static final Color OPTION_EDGE = new Color(0x3D, 0x3A, 0x37);
	/** Card padding (9px each side) plus its two 1px edges. */
	static final int CARD_INSET = 20;

	// RuneLite's bundled RuneScape font is a pixel face designed for the game
	// viewport; at sidebar size, for paragraphs rather than labels, it smears.
	// So it is used where it is at home - the things you navigate by: the
	// goal, each step, each method - and the platform UI sans carries
	// everything you read. Titles were a serif for a while, which next to the
	// client's own buttons and dropdowns made three faces in one sidebar and
	// looked like it belonged to a different program.
	static final String[] UI_FAMILIES = {"Segoe UI", "Noto Sans", "DejaVu Sans",
		Font.SANS_SERIF};
	/** Windows ships this as its own family; elsewhere bold stands in for it. */
	static final String[] UI_MEDIUM_FAMILIES = {"Segoe UI Semibold", "Noto Sans Medium",
		"DejaVu Sans"};

	static final Font BODY_FONT = installed(UI_FAMILIES, Font.PLAIN, 12);
	static final Font BODY_BOLD = BODY_FONT.deriveFont(Font.BOLD);
	/**
	 * The smallest prose in the panel. 12px, not 11: a line of 11px sans at this
	 * grey is the one thing in the sidebar that genuinely is hard to read, and
	 * the pixel saved by shrinking it buys nothing.
	 */
	static final Font SMALL_FONT = installed(UI_FAMILIES, Font.PLAIN, 12);
	/** A step title, a method name, a section heading: the game's own face, at its native 16px. */
	static final Font STEP_TITLE_FONT = FontManager.getRunescapeBoldFont();
	static final Font OPTION_FONT = FontManager.getRunescapeFont();
	static final Font HEADER_FONT = FontManager.getRunescapeBoldFont();
	/**
	 * The little uppercase label over each step. Letter-spacing is what stops
	 * all-caps at 10px reading as a smudge - and the extra weight is what stops
	 * it reading as a smudge in grey, which tracking alone could not fix.
	 */
	static final Font MICRO_FONT = microFont();

	private static Font microFont()
	{
		Map<java.awt.font.TextAttribute, Object> attrs = new HashMap<>();
		attrs.put(java.awt.font.TextAttribute.TRACKING, 0.1);
		Font base = installed(UI_MEDIUM_FAMILIES, Font.PLAIN, 10);
		if (base.getFamily().equals(Font.SANS_SERIF) || base.getFamily().equals("DejaVu Sans"))
		{
			base = base.deriveFont(Font.BOLD);
		}
		return base.deriveFont(attrs);
	}

	/**
	 * The first of these families the machine actually has, so a face can be
	 * named without the panel falling back to a logical font on a box that has
	 * something better.
	 * <p>
	 * Java silently substitutes for an unknown family rather than failing, and
	 * the substitute is Dialog - which is how a panel ends up looking the same
	 * everywhere regardless of what it asked for.
	 */
	static Font installed(String[] families, int style, int size)
	{
		Set<String> available = availableFamilies();
		for (String family : families)
		{
			if (available.contains(family.toLowerCase(java.util.Locale.ROOT)))
			{
				return new Font(family, style, size);
			}
		}
		return new Font(families[families.length - 1], style, size);
	}

	private static Set<String> installedFamilies;

	private static Set<String> availableFamilies()
	{
		if (installedFamilies == null)
		{
			installedFamilies = new HashSet<>();
			try
			{
				for (String family : java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment()
					.getAvailableFontFamilyNames())
				{
					installedFamilies.add(family.toLowerCase(java.util.Locale.ROOT));
				}
			}
			catch (Throwable headlessOrNoFonts)
			{
				// Nothing to do but take the logical fonts.
			}
		}
		return installedFamilies;
	}

	/**
	 * Adds a component to the vertical stack, pinned to the left and capped so
	 * BoxLayout can stretch it horizontally but never vertically. Without the
	 * maximum-size cap, BoxLayout hands leftover height to whichever component
	 * will take it and the layout goes to pieces.
	 */
	static void stack(JPanel parent, Component child)
	{
		if (child instanceof javax.swing.JComponent)
		{
			javax.swing.JComponent c = (javax.swing.JComponent) child;
			c.setAlignmentX(Component.LEFT_ALIGNMENT);
			c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		}
		parent.add(child);
	}

	/**
	 * Wraps text at an exact pixel width.
	 *
	 * <p>This uses a one-cell table rather than the more obvious
	 * {@code <body style='width:Npx'>}: Swing's CSS support treats that width
	 * as advisory and still reports a preferred width ~45px larger, so the
	 * label overflows the sidebar and the tail of every line gets clipped. A
	 * table width is honoured exactly.
	 */
	static String wrapped(String escapedText, int width)
	{
		return "<html><table cellpadding=0 cellspacing=0 border=0 width='" + width + "'>"
			+ "<tr><td>" + escapedText + "</td></tr></table></html>";
	}
}

package com.nowwhat;

import static com.nowwhat.PanelStyle.*;

import com.nowwhat.engine.XpTable;
import com.nowwhat.model.Activity;
import com.nowwhat.model.Goal;
import com.nowwhat.model.ItemSource;
import com.nowwhat.model.Path;
import com.nowwhat.model.PathStep;
import com.nowwhat.model.TrainingMethod;
import java.awt.Color;
import java.awt.Component;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/**
 * The plan to a goal as the sidebar shows it: the steps in order, which
 * method the player picked for each, what is already behind them, how to do
 * the thing at the end and what to take to it.
 * <p>
 * Split out of the panel, which keeps the goal pickers and the opening
 * screens. Everything a plan remembers between redraws lives here.
 */
class PlanView
{
	private final JPanel pathResultContainer = new JPanel();
	/**
	 * The player's real levels, for telling which plan steps are behind them.
	 * Empty when logged out, which means nothing is finished - the honest answer
	 * when the panel has nothing to go on.
	 */
	private Map<String, Integer> levels = java.util.Collections.emptyMap();
	/** Names of the quests, diary tiers and the like that the game reports as complete. */
	private Set<String> doneActivities = java.util.Collections.emptySet();
	/**
	 * Whether finished steps are listed or folded away. Folded by default: a
	 * base-stats plan over thirteen skills is long enough that scrolling past
	 * the part you have already done to reach the part you are on is the main
	 * thing wrong with it.
	 */
	private boolean showFinishedSteps;
	/**
	 * Option titles the player has picked, so a step with a choice can collapse
	 * to the one they chose instead of listing five every time.
	 * <p>
	 * Keyed by option title rather than by step, deliberately: pick "Hunter
	 * rumours" once and every later bracket that still offers it stays
	 * collapsed to it, while the bracket where it stops being available
	 * re-opens the choice on its own - which is exactly the point at which a
	 * player wants to be asked again.
	 */
	private final Set<String> chosenOptions = new HashSet<>();
	/**
	 * Step titles whose full option list is currently open. Steps start closed
	 * showing their top-rated option, because a plan that lists five methods for
	 * each of a dozen brackets is unreadable before it is informative - the
	 * alternatives are one click away and the count is always visible, so
	 * nothing is hidden, just folded.
	 */
	private final Set<String> expandedSteps = new HashSet<>();
	/** Last rendered path, so choosing an option can re-render without re-planning. */
	private Path lastPath;
	/**
	 * Option bodies already spelled out in the render currently being built,
	 * keyed on their exact text.
	 * <p>
	 * A method that spans a wide range is an option in every segment inside it
	 * - Runecraft's quest route covers four, Farming's tree runs cover three -
	 * and repeating its note, its quest list and its Quest Helper pointer under
	 * each one rebuilds the wall of text the collapsing exists to prevent.
	 * <p>
	 * Keying on the body text rather than on the method is what makes this safe:
	 * a method with an xp/hr rate carries a per-segment time estimate in its
	 * detail line ("~4.1 hrs at 130k xp/hr"), so its text differs between
	 * segments and it is never suppressed. Only genuinely identical bodies -
	 * which in practice means the rate-less, passive methods - collapse.
	 */
	private final Set<String> optionBodiesShown = new HashSet<>();

	private final PanelKit kit;
	/** Everything that turns written gear and supply lines into pictures. */
	private final GearView gear;
	private final Function<Goal, Path> pathResolver;
	/** Activities by id, so a finished plan can look up what to wear and bring. */
	private final Map<String, Activity> activitiesById;
	private final Map<String, ItemSource> itemSourcesById;
	/** Asks the panel to re-seat its footer once a plan has changed the page's height. */
	private final Runnable sinkFooter;

	PlanView(PanelKit kit, ItemManager itemManager, Function<Goal, Path> pathResolver,
		Map<String, Activity> activitiesById, Map<String, ItemSource> itemSourcesById,
		Runnable sinkFooter)
	{
		this.kit = kit;
		this.pathResolver = pathResolver;
		this.activitiesById = activitiesById;
		this.itemSourcesById = itemSourcesById;
		this.sinkFooter = sinkFooter;
		pathResultContainer.setLayout(new BoxLayout(pathResultContainer, BoxLayout.Y_AXIS));
		pathResultContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pathResultContainer.setAlignmentX(Component.LEFT_ALIGNMENT);
		this.gear = new GearView(itemManager, pathResultContainer, kit::resultLine, () ->
		{
			if (lastPath != null)
			{
				// Not scrolled to the top: the player did not ask for this redraw.
				renderPath(lastPath, false);
			}
		});
	}

	/** What the plan's Back link does. The panel replaces this to bring its own screens back. */
	private Runnable onClose = this::clearPath;

	void setOnClose(Runnable onClose)
	{
		this.onClose = onClose;
	}

	/** The column the plan is drawn into, for the panel to place. */
	JPanel container()
	{
		return pathResultContainer;
	}

	/** Lets gear be drawn as a worn-equipment loadout, which needs the game thread for slots. */
	void setClientThread(ClientThread clientThread)
	{
		gear.setClientThread(clientThread);
	}

	/**
	 * Renders a Path (from any of the three goal types) as an ordered,
	 * numbered list of concrete steps, plus any warnings the planner hit.
	 */
	void renderPath(Path path)
	{
		renderPath(path, true);
	}

	private void renderPath(Path path, boolean scrollToTop)
	{
		lastPath = path;
		optionBodiesShown.clear();
		pathResultContainer.removeAll();

		JLabel titleLabel = kit.resultLine(path.getGoal().getLabel(), ACCENT, 0);
		titleLabel.setFont(STEP_TITLE_FONT);
		titleLabel.setBorder(new EmptyBorder(10, 0, 0, 0));
		stack(pathResultContainer, titleLabel);

		// The way out. A plan has the sidebar to itself, so this is the only
		// route back to the pickers and the suggestions.
		stack(pathResultContainer, kit.linkRow(java.util.Collections.singletonList(
			kit.actionLink("\u2190 Back", () -> onClose.run()))));

		if (path.isAlreadyComplete())
		{
			stack(pathResultContainer, kit.resultLine("Already done.", ColorScheme.PROGRESS_COMPLETE_COLOR, 0));

			// An item goal can be "already done" purely because one is sitting in
			// the bank, which is a dead end for the player who wants a second one
			// - or whose bank this plugin has read wrong. Offer the route anyway
			// rather than making them inflate the quantity until a plan appears.
			Goal goal = path.getGoal();
			if (goal.getType() == Goal.Type.ITEM_QUANTITY && goal.isCountOwned())
			{
				stack(pathResultContainer, kit.linkRow(java.util.Collections.singletonList(
					kit.actionLink("Plan it anyway, as if I had none",
						() -> renderPath(pathResolver.apply(goal.ignoringWhatIsOwned()))))));
			}
		}
		else if (path.isRequirementsAlreadyMet())
		{
			stack(pathResultContainer, kit.resultLine("You already meet every requirement, so you can "
				+ "start this now.", ColorScheme.PROGRESS_COMPLETE_COLOR, 0));
			// Meeting the requirements answers "can I", not "what do I do". For
			// a birdhouse or herb run the how is the whole answer, and it lives
			// in the description; without this the plan stopped at the line
			// above. A quest or diary's description is a one-word label, and
			// Quest Helper below says the rest.
			String howTo = howTo(targetActivity(path));
			if (howTo != null)
			{
				renderHowTo(howTo);
			}
			Activity target = preparationFor(path);
			if (target != null)
			{
				renderPreparation(target, borrowedFrom(path, target));
			}
			else
			{
				// The one branch that had nothing to hand off to.
				//
				// A quest or a diary you already qualify for is exactly when
				// Quest Helper is most useful, and this is the branch every
				// rolled suggestion lands in - the roll only offers things whose
				// requirements are already met. So "Surprise me" would answer
				// "Lumbridge & Draynor Hard Diary", and then the only thing on
				// offer was a wiki link, with the plugin that has the whole task
				// list sitting in the same sidebar unmentioned.
				for (PathStep step : path.getSteps())
				{
					if (step.isTarget() && isHandedOff(step))
					{
						stack(pathResultContainer, kit.questHelperPointer(step.getType(), 1));
						break;
					}
				}

				for (PathStep step : path.getSteps())
				{
					for (PathStep.Option option : step.getAlternatives())
					{
						if (option.getWikiUrl() != null)
						{
							stack(pathResultContainer, kit.wikiLink(option.getWikiUrl(), 0));
						}
					}
				}
			}
		}
		else if (path.getSteps().isEmpty() && path.getWarnings().isEmpty())
		{
			stack(pathResultContainer, kit.resultLine("Nothing to plan \u2014 should be achievable right now.", PRIMARY, 0));
		}
		else
		{
			int i = 1;
			List<PathStep> steps = path.getSteps();

			if (onlyRecommendedInTheWay(path))
			{
				// The suggestion list holds a fight back until the recommended
				// stats are met; the plan has to say the same thing it does,
				// without pretending the game is what stops the player.
				stack(pathResultContainer, kit.resultLine("You meet every requirement, so nothing stops "
					+ "you going now. The steps below only close the gap to the stats the wiki "
					+ "recommends.", ColorScheme.PROGRESS_COMPLETE_COLOR, 0));
			}

			// Steps the player is already past come out of the list, so what is
			// left is what there is left to do. They are a link away, not gone:
			// a plan that quietly drops things is a plan you cannot check.
			int done = finishedCount(path);
			if (done > 0)
			{
				stack(pathResultContainer, doneLink(
					showFinishedSteps
						? "Hide the " + done + " finished"
						: done + " step" + (done == 1 ? "" : "s") + " done already "
							+ "\u2014 show " + (done == 1 ? "it" : "them")));
				if (!showFinishedSteps)
				{
					List<PathStep> left = new ArrayList<>();
					for (PathStep step : steps)
					{
						if (!isFinished(step))
						{
							left.add(step);
						}
					}
					steps = left;
				}
			}
			if (steps.isEmpty() && done > 0 && !showFinishedSteps)
			{
				stack(pathResultContainer, kit.resultLine("Every step in this plan is behind you "
					+ "\u2014 plan it again to see what is next.",
					ColorScheme.PROGRESS_COMPLETE_COLOR, 0));
			}
			for (int at = 0; at < steps.size(); at++)
			{
				PathStep step = steps.get(at);

				// A run of prerequisite quests (or diary tiers) collapses into one
				// listed block: naming them and their order is this plugin's job,
				// walking you through them is Quest Helper's. The goal itself is
				// excluded - it's the destination, not something needed first.
				if (isHandedOff(step) && !step.isTarget())
				{
					int end = at;
					while (end + 1 < steps.size()
						&& steps.get(end + 1).getType() == step.getType()
						&& !steps.get(end + 1).isTarget())
					{
						end++;
					}
					renderHandoffBlock(i, steps.subList(at, end + 1));
					at = end;
					i++;
					continue;
				}

				// Consecutive brackets that resolve to the same method are one
				// stretch of play, not several steps. Thieving 76-99 breaks into
				// eight brackets because the Knights of Ardougne rate ramps and
				// other methods come and go around it - but a player blackjacking
				// thugs is doing one thing for all 23 levels, and reading the same
				// method name under eight headings says otherwise. The brackets are
				// still there, one link away.
				int runEnd = sameMethodRunEnd(steps, at);
				if (runEnd > at)
				{
					List<PathStep> run = steps.subList(at, runEnd + 1);
					String runKey = runKey(run);
					if (expandedSteps.contains(runKey))
					{
						for (PathStep bracket : run)
						{
							renderStep(i, bracket);
							i++;
						}
						stack(pathResultContainer, runLink(runKey, "\u2190 Back to one step ("
							+ run.get(0).getLevelFrom() + " \u2192 "
							+ run.get(run.size() - 1).getLevelTo() + ")"));
					}
					else
					{
						renderMergedRun(i, run, runKey);
						i++;
					}
					at = runEnd;
					continue;
				}

				renderStep(i, step);
				i++;
			}

			// What you actually do there, whether or not anything was in the
			// way. It used to show only once every requirement was met, so the
			// player who most needed telling got a list of levels and no word on
			// what the levels were for.
			String howTo = howTo(targetActivity(path));
			if (howTo != null)
			{
				renderHowTo(howTo);
			}

			// The last step of a plan is the content itself; what to take to it
			// is the next thing the player needs and the reason they'd otherwise
			// open the wiki.
			Activity target = preparationFor(path);
			if (target != null)
			{
				renderPreparation(target, borrowedFrom(path, target));
			}

		}

		for (String warning : path.getWarnings())
		{
			stack(pathResultContainer, kit.resultLine("! " + warning, Color.ORANGE, 0));
		}

		pathResultContainer.revalidate();
		pathResultContainer.repaint();

		// Results render below three goal blocks, so on a short sidebar they can
		// land off-screen; bring them into view rather than leaving the user to
		// wonder whether the click did anything.
		SwingUtilities.invokeLater(() ->
		{
			sinkFooter.run();
			if (!scrollToTop)
			{
				return;
			}
			int visible = Math.min(pathResultContainer.getHeight(), kit.scrollPane.getViewport().getHeight());
			pathResultContainer.scrollRectToVisible(new Rectangle(0, 0, 1, visible));
		});
	}

	/** True when the plan has steps on the way to its goal and every one is only recommended. */
	private static boolean onlyRecommendedInTheWay(Path path)
	{
		boolean any = false;
		for (PathStep step : path.getSteps())
		{
			if (step.isTarget())
			{
				continue;
			}
			if (!step.isRecommended())
			{
				return false;
			}
			any = true;
		}
		return any;
	}

	/** The activity a path is aimed at, or null for skill and item goals. */
	private Activity targetActivity(Path path)
	{
		String id = path.getGoal().getActivityId();
		return id == null ? null : activitiesById.get(id);
	}

	/** The activity's own description, when it says more than what kind of thing it is. */
	static String howTo(Activity activity)
	{
		if (activity == null || activity.getHowTo() == null)
		{
			return null;
		}
		Activity.Category category = activity.getCategory();
		if (category == Activity.Category.QUEST || category == Activity.Category.DIARY)
		{
			return null;
		}
		String text = activity.getHowTo().trim();
		return text.isEmpty() ? null : text;
	}

	/**
	 * The how-to text, laid out: a gap before each paragraph, a short line
	 * ending in a colon as a heading, and "* " lines as an indented list under
	 * it, in the same dash-and-indent style as the inventory below.
	 */
	/** The list marker the inventory uses, as a number so the source stays ASCII. */
	private static final String EN_DASH = String.valueOf((char) 0x2013);

	private void renderHowTo(String text)
	{
		for (String raw : text.split("\n"))
		{
			String line = raw.trim();
			if (line.isEmpty())
			{
				continue;
			}
			JLabel label;
			if (line.startsWith("* "))
			{
				label = kit.resultLine(EN_DASH + " " + line.substring(2).trim(), DETAIL, 12);
				label.setFont(SMALL_FONT);
			}
			else if (line.endsWith(":") && line.length() <= 60)
			{
				label = kit.resultLine(line.substring(0, line.length() - 1), PRIMARY, 0);
				label.setBorder(new EmptyBorder(8, 0, 1, 0));
			}
			else
			{
				// A paragraph of five sentences is a wall in a column this
				// narrow, so prose is broken into a couple of sentences at a time.
				for (String chunk : paragraphs(line))
				{
					JLabel paragraph = kit.resultLine(chunk, DETAIL, 0);
					paragraph.setBorder(new EmptyBorder(6, 0, 1, 0));
					stack(pathResultContainer, paragraph);
				}
				continue;
			}
			stack(pathResultContainer, label);
		}
	}

	/** Sentences regrouped into paragraphs of about two, never splitting one. */
	static List<String> paragraphs(String prose)
	{
		List<String> out = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		for (String sentence : prose.split("(?<=[.!?])\\s+(?=[A-Z])"))
		{
			if (current.length() > 0 && current.length() + sentence.length() > PARAGRAPH_CHARS)
			{
				out.add(current.toString());
				current.setLength(0);
			}
			if (current.length() > 0)
			{
				current.append(' ');
			}
			current.append(sentence);
		}
		if (current.length() > 0)
		{
			out.add(current.toString());
		}
		return out;
	}

	/** Roughly two sentences, or four or five lines at sidebar width. */
	private static final int PARAGRAPH_CHARS = 170;

	/**
	 * The activity whose gear answers this plan, which is not always the thing
	 * the plan was asked for.
	 * <p>
	 * "Ancestral robe top" is a plan that ends in Chambers of Xeric and "Pet
	 * snakeling" is a plan that ends in Zulrah, and in both cases the player's
	 * next question is the one Chambers of Xeric and Zulrah already answer. The
	 * panel used to hand that answer over only when the goal happened to be the
	 * fight itself, so asking for the drop told you where to go and then stopped
	 * - exactly where picking the boss off the Activity list keeps going.
	 */
	private Activity preparationFor(Path path)
	{
		Activity own = targetActivity(path);
		if (own != null)
		{
			return own.hasPreparation() ? own : null;
		}

		ItemSource source = itemSourcesById.get(path.getGoal().getItemId());
		if (source == null)
		{
			return null;
		}
		// A crafted item has no fight of its own, but its pieces do. An abyssal
		// bludgeon is three Sire drops and a venator bow is Muspah shards, and
		// the plan for either is a trip to that boss - so its gear is what the
		// player needs. Only when every piece comes from the same boss, though:
		// a godsword's hilt and blade shards are four different fights, and
		// picking one boss's gear would answer a quarter of the question.
		Set<String> fights = new LinkedHashSet<>();
		fightsBehind(source, fights, new HashSet<>());
		if (fights.size() != 1)
		{
			return null;
		}
		Activity fight = activitiesById.get(fights.iterator().next());
		return fight != null && fight.hasPreparation() ? fight : null;
	}

	/** Every boss page an item or its recipe's pieces come from. */
	private void fightsBehind(ItemSource source, Set<String> fights, Set<String> visiting)
	{
		if (!visiting.add(source.getId()))
		{
			return;
		}
		if (source.getPreparationFrom() != null)
		{
			fights.add(source.getPreparationFrom());
		}
		for (ItemSource.Ingredient ingredient : source.getIngredients())
		{
			ItemSource part = itemSourcesById.get(ingredient.getItemId());
			if (part != null)
			{
				fightsBehind(part, fights, visiting);
			}
		}
	}

	/**
	 * Whose gear this is, when it is not the goal's own - the name to put in the
	 * heading. Null when the player asked for the fight itself and no heading
	 * beyond "What to bring" is needed.
	 */
	private String borrowedFrom(Path path, Activity preparation)
	{
		if (preparation.getId().equals(path.getGoal().getActivityId()))
		{
			// An activity that borrowed its own gear from another one already
			// knows whose it is.
			return preparation.getPreparationSource();
		}
		return preparation.getName();
	}

	/**
	 * What to wear, what to bring, and who helps once you're there.
	 * <p>
	 * Items are joined into a paragraph per kit rather than listed one slot per
	 * line: eleven slots across four kits is forty-odd lines in a 225px column,
	 * which is a wall, and the player is reading this to fill an inventory, not
	 * to audit a slot table.
	 */
	private void renderPreparation(Activity activity, String borrowedFrom)
	{
		stack(pathResultContainer, kit.hairline());
		// Named when the gear is someone else's: asking for a pet snakeling and
		// being handed a blowpipe and anti-venom only makes sense once the panel
		// has said the word "Zulrah" out loud.
		String whose = borrowedFrom == null
			? "What to bring"
			: "What to bring to " + borrowedFrom;
		stack(pathResultContainer, kit.microLabel(whose, SUBTLE, 11));

		for (List<Activity.GearSetup> family : GearView.setupFamilies(activity.getSetups()).values())
		{
			if (family.size() > 1)
			{
				String first = family.get(0).getName().trim();
				if (gear.renderSetupFamily(first.substring(0, first.indexOf(" (")), family))
				{
					continue;
				}
			}
			for (Activity.GearSetup setup : family)
			{
				gear.renderSetup(setup);
			}
		}

		if (!activity.getSupplies().isEmpty())
		{
			JLabel label = kit.resultLine("Inventory", PRIMARY, 0);
			label.setBorder(new EmptyBorder(6, 0, 0, 0));
			stack(pathResultContainer, label);
			GearView.Pictured supplies = gear.iconsFor(activity.getSupplies());
			gear.stackIcons(pathResultContainer, supplies);
			for (String supply : supplies.getInWords())
			{
				JLabel line = kit.resultLine("\u2013 " + supply, DETAIL, 12);
				line.setFont(SMALL_FONT);
				stack(pathResultContainer, line);
			}
		}

		if (activity.getHelperPlugin() != null)
		{
			stack(pathResultContainer, kit.helperPointer(activity.getHelperPlugin(),
				activity.getHelperPluginId(), "will help you through the fight itself.",
				"in-fight help", 10));
		}

		if (activity.getStrategyUrl() != null)
		{
			JLabel link = kit.resultLine("Full strategy on the wiki \u2197",
				QUIET_LINK, 10);
			link.setFont(SMALL_FONT);
			link.setToolTipText(activity.getStrategyUrl());
			kit.makeClickable(link, () -> PanelKit.openUrl(activity.getStrategyUrl()));
			stack(pathResultContainer, link);
		}
	}

	/** Quests and diary tiers are both Quest Helper's territory, not ours. */
	private static boolean isHandedOff(PathStep step)
	{
		return step.getType() == PathStep.Type.DO_QUEST
			|| step.getType() == PathStep.Type.DO_DIARY;
	}

	/**
	 * Renders the quests or diary tiers a path needs as a plain numbered list -
	 * name, order, and a wiki link on each - followed by a pointer to Quest
	 * Helper.
	 * <p>
	 * Deliberately shallow. Quest Helper is a large, mature plugin that walks
	 * players through quests, diaries, miniquests and combat tasks properly, and
	 * a second, worse walkthrough helps nobody. What this plugin knows that
	 * Quest Helper doesn't is *which* of them a particular goal requires and in
	 * what order - and that is the part that otherwise costs a player a long
	 * session of reading wiki pages.
	 */
	private void renderHandoffBlock(int number, List<PathStep> items)
	{
		boolean diaries = items.get(0).getType() == PathStep.Type.DO_DIARY;
		String noun = diaries
			? (items.size() == 1 ? "diary tier" : "diary tiers")
			: (items.size() == 1 ? "quest" : "quests");
		stack(pathResultContainer, kit.hairline());
		stack(pathResultContainer, kit.microLabel("Step " + number + " \u00b7 "
			+ (diaries ? "Diaries" : "Quests"), SUBTLE, 11));
		JLabel header = kit.resultLine(items.size() + " " + noun + " needed first", PRIMARY, 0);
		header.setFont(STEP_TITLE_FONT);
		stack(pathResultContainer, header);

		for (PathStep item : items)
		{
			JLabel line = kit.resultLine("\u2022 " + item.getTitle(), PRIMARY, 6);
			if (item.getWikiUrl() != null)
			{
				line.setToolTipText(item.getWikiUrl());
				kit.makeClickable(line, () -> PanelKit.openUrl(item.getWikiUrl()));
			}
			stack(pathResultContainer, line);
		}

		stack(pathResultContainer, kit.questHelperPointer(items.get(0).getType(), items.size()));
	}

	/** One step on its own: caption, title, and its option or option list. */
	private void renderStep(int number, PathStep step)
	{
		stack(pathResultContainer, kit.hairline());
		stack(pathResultContainer, kit.microLabel(stepCaption(number, step), SUBTLE, 11));
		JLabel stepTitle = kit.resultLine(step.getTitle(), PRIMARY, 0);
		stepTitle.setFont(STEP_TITLE_FONT);
		stack(pathResultContainer, stepTitle);

		if (!step.hasChoice())
		{
			renderOption(step, step.getAlternatives().get(0), false);
			// Reaching a quest or diary you asked for is exactly where
			// Quest Helper takes over.
			if (isHandedOff(step))
			{
				stack(pathResultContainer, kit.questHelperPointer(step.getType(), 1));
			}
		}
		else if (expandedSteps.contains(step.getTitle()))
		{
			JLabel hint = kit.resultLine("Click one to keep just that method:", SUBTLE, 10);
			hint.setFont(SMALL_FONT);
			stack(pathResultContainer, hint);

			PathStep.Option picked = chosenFrom(step);
			for (PathStep.Option option : step.getAlternatives())
			{
				renderOption(step, option, option == picked);
			}
			stack(pathResultContainer, toggleLink(step, "Collapse", null));
		}
		else
		{
			PathStep.Option picked = chosenFrom(step);
			PathStep.Option shown = picked != null ? picked : step.getAlternatives().get(0);
			renderOption(step, shown, picked != null);

			// Undecided steps also show the quest route, if there is one.
			// Training is the plugin's own path and stays the headline,
			// but a bracket a player can quest straight past shouldn't
			// have that fact folded away behind "show 1 other" - that
			// would be deciding for them in the other direction. Once
			// they have actually picked something, their choice stands
			// alone.
			int shownCount = 1;
			if (picked == null)
			{
				for (PathStep.Option other : step.getAlternatives())
				{
					if (other != shown && !other.getQuests().isEmpty())
					{
						renderOption(step, other, false);
						shownCount++;
					}
				}
			}

			int others = step.getAlternatives().size() - shownCount;
			if (picked != null)
			{
				stack(pathResultContainer, toggleLink(step, "Change method",
					others + (others == 1 ? " other" : " others")));
			}
			else if (others > 0)
			{
				stack(pathResultContainer, toggleLink(step, "Show " + others
					+ " other method" + (others == 1 ? "" : "s"), null));
			}
		}
	}

	/**
	 * The last index of the run of level brackets starting at `at` that all show
	 * the same method, or `at` itself when the next bracket differs.
	 * <p>
	 * Which method a bracket shows depends on what the player has chosen, so this
	 * cannot be settled in the planner - it is recomputed on every redraw. A
	 * bracket whose option list is open is never swept into a run: its choice is
	 * on screen and merging would hide it mid-decision.
	 */
	private int sameMethodRunEnd(List<PathStep> steps, int at)
	{
		PathStep first = steps.get(at);
		PathStep.Option shown = displayed(first);
		if (shown == null || !mergeable(first))
		{
			return at;
		}

		int end = at;
		while (end + 1 < steps.size())
		{
			PathStep next = steps.get(end + 1);
			if (!mergeable(next)
				|| next.isRecommended() != first.isRecommended()
				|| !next.getSkill().equals(first.getSkill())
				|| next.getLevelFrom() != steps.get(end).getLevelTo())
			{
				break;
			}
			PathStep.Option nextShown = displayed(next);
			if (nextShown == null || !nextShown.getTitle().equals(shown.getTitle()))
			{
				break;
			}
			end++;
		}
		return end;
	}

	private boolean mergeable(PathStep step)
	{
		return step.getType() == PathStep.Type.TRAIN_SKILL
			&& step.hasLevels()
			&& !expandedSteps.contains(step.getTitle());
	}

	/** The option a collapsed step shows: the chosen one, else the top-rated one. */
	private PathStep.Option displayed(PathStep step)
	{
		PathStep.Option picked = chosenFrom(step);
		if (picked != null)
		{
			return picked;
		}
		return step.getAlternatives().isEmpty() ? null : step.getAlternatives().get(0);
	}

	/** This run's identity in the expanded set - its range plus its method. */
	private String runKey(List<PathStep> run)
	{
		PathStep first = run.get(0);
		PathStep last = run.get(run.size() - 1);
		PathStep.Option shown = displayed(first);
		return "run:" + first.getSkill() + ":" + first.getLevelFrom() + "-" + last.getLevelTo()
			+ ":" + (shown == null ? "" : shown.getTitle());
	}

	private PathStep.Option matching(PathStep step, String title)
	{
		for (PathStep.Option option : step.getAlternatives())
		{
			if (option.getTitle().equals(title))
			{
				return option;
			}
		}
		return null;
	}

	/**
	 * A run of brackets as one step: the whole range in the title, the summed xp
	 * in the caption, one estimate covering the lot.
	 * <p>
	 * The estimate is summed bracket by bracket rather than divided once, because
	 * the same method is often recorded as several rows with a rising rate -
	 * Knights of Ardougne goes 141k at 75 to 240k at 95 - and dividing the total
	 * xp by any one of those rates would be wrong for most of the range. The rate
	 * is then shown as the span it actually covers.
	 */

	/**
	 * One method's whole showing across a merged run of brackets: the levels it
	 * actually covers, the xp it would carry over them, and its rate as the span
	 * it really spans rather than any single bracket's figure.
	 * <p>
	 * Pulled out because the headline and the alternatives need exactly the same
	 * arithmetic. It used to exist only for the headline, which is why the other
	 * ways to train a skill were only visible by expanding the brackets - and a
	 * method recorded in eight brackets then printed eight near-identical cards
	 * for the player to read past. Pyramid Plunder opening at 91 is not a
	 * footnote to Thieving; it is the answer for a third of the range.
	 */
	private static final class Across
	{
		private PathStep.Option option;
		private int from = Integer.MAX_VALUE;
		private int to = 0;
		private long xp;
		private int rateLow = Integer.MAX_VALUE;

		private boolean found()
		{
			return option != null;
		}
	}

	private Across mergeAcross(List<PathStep> run, String title)
	{
		Across across = new Across();
		PathStep.Option template = null;
		String detail = null;
		double hours = 0;
		boolean timed = true;
		int rateHigh = 0;

		for (PathStep bracket : run)
		{
			PathStep.Option here = matching(bracket, title);
			if (here == null)
			{
				continue;
			}
			if (template == null)
			{
				template = here;
			}
			across.from = Math.min(across.from, bracket.getLevelFrom());
			across.to = Math.max(across.to, bracket.getLevelTo());
			across.xp += bracket.getXpCost();
			if (detail == null && here.getDetail() != null && !here.getDetail().isEmpty())
			{
				// A bracketed method carries its note on its first bracket only,
				// so a run starting part-way up it would otherwise show no note
				// at all - the one place the note is most wanted.
				detail = here.getDetail();
			}
			Integer rate = here.getXpPerHour();
			if (rate == null || rate <= 0)
			{
				// A rate-less bracket (a quest route) would make any total a lie
				// about part of the range, so no estimate is shown at all.
				timed = false;
				continue;
			}
			across.rateLow = Math.min(across.rateLow, rate);
			rateHigh = Math.max(rateHigh, rate);
			hours += bracket.getXpCost() / (double) rate;
		}

		// Shopping lists add up over the run. Taking the first bracket's would
		// understate a merged range by however many brackets followed it, which
		// is the one way a count like this can be worse than no count at all.
		Map<String, Long> totals = new LinkedHashMap<>();
		for (PathStep bracket : run)
		{
			PathStep.Option here = matching(bracket, title);
			if (here == null)
			{
				continue;
			}
			for (PathStep.Option.Needed line : here.getNeeded())
			{
				totals.merge(line.getItem(), line.getQuantity(), Long::sum);
			}
		}
		List<PathStep.Option.Needed> needed = new ArrayList<>();
		for (Map.Entry<String, Long> entry : totals.entrySet())
		{
			needed.add(new PathStep.Option.Needed(entry.getKey(), entry.getValue()));
		}

		if (template == null)
		{
			return across;
		}

		String meta = null;
		if (timed && hours > 0)
		{
			meta = "~" + XpTable.formatHours(hours) + " \u00b7 "
				+ (across.rateLow == rateHigh
					? XpTable.formatXp(across.rateLow) + " xp/hr"
					: XpTable.formatXp(across.rateLow) + "\u2013" + XpTable.formatXp(rateHigh)
						+ " xp/hr");
		}
		across.option = new PathStep.Option(template.getTitle(), detail, meta,
			template.getWikiUrl(), template.getQuests(), template.isPvpRisk(),
			template.isTickManipulation(), template.getXpPerHour(), template.getGear(),
			template.getSupplies())
			.withAttention(template.getAttention())
			.withNeeded(needed);
		return across;
	}

	private void renderMergedRun(int number, List<PathStep> run, String runKey)
	{
		PathStep first = run.get(0);
		PathStep last = run.get(run.size() - 1);
		PathStep.Option shown = displayed(first);
		boolean picked = chosenFrom(first) != null;

		long totalXp = 0;
		Set<String> allTitles = new LinkedHashSet<>();
		for (PathStep bracket : run)
		{
			totalXp += bracket.getXpCost();
			for (PathStep.Option option : bracket.getAlternatives())
			{
				allTitles.add(option.getTitle());
			}
		}

		String title = capitalize(first.getSkill()) + " " + first.getLevelFrom()
			+ " \u2192 " + last.getLevelTo();
		PathStep.Option merged = mergeAcross(run, shown.getTitle()).option;
		// Single-option by construction, so renderOption leaves the name
		// unclickable: choosing happens in the brackets, which are one link away.
		PathStep mergedStep = new PathStep(PathStep.Type.TRAIN_SKILL, title,
			java.util.Collections.singletonList(merged))
			.withXpCost(totalXp)
			.withLevels(first.getSkill(), first.getLevelFrom(), last.getLevelTo());
		if (first.isRecommended())
		{
			mergedStep.asRecommended();
		}

		stack(pathResultContainer, kit.hairline());
		stack(pathResultContainer, kit.microLabel(stepCaption(number, mergedStep), SUBTLE, 11));
		JLabel stepTitle = kit.resultLine(title, PRIMARY, 0);
		stepTitle.setFont(STEP_TITLE_FONT);
		stack(pathResultContainer, stepTitle);
		renderOption(mergedStep, merged, picked);

		// A quest route that skips part of this range stays visible even merged.
		// Folding it away behind a link would be the same mistake as sorting it to
		// the top, in the other direction: the player is told to train, with the
		// shortcut off screen.
		Set<String> questsAlreadyShown = new HashSet<>();
		if (!picked)
		{
			Set<String> questsShown = questsAlreadyShown;
			for (PathStep bracket : run)
			{
				for (PathStep.Option option : bracket.getAlternatives())
				{
					if (option.getQuests().isEmpty()
						|| option.getTitle().equals(shown.getTitle())
						|| !questsShown.add(option.getTitle()))
					{
						continue;
					}

					int from = first.getLevelTo();
					int to = first.getLevelFrom();
					for (PathStep other : run)
					{
						if (matching(other, option.getTitle()) != null)
						{
							from = Math.min(from, other.getLevelFrom());
							to = Math.max(to, other.getLevelTo());
						}
					}
					if (from > first.getLevelFrom() || to < last.getLevelTo())
					{
						stack(pathResultContainer, kit.microLabel("Shortcut \u00b7 covers "
							+ from + " \u2192 " + to, SUBTLE, 6, 12));
					}
					renderOption(bracket, option, false);
				}
			}
		}

		// The other ways to train this range, each once, merged the same way the
		// headline is - and deliberately NOT behind the bracket expansion. Those
		// are two different questions ("what else could I do?" and "where does
		// the rate change?"), and one link answering both meant the second
		// buried the first: Thieving 65-84 printed five near-identical
		// blackjacking cards, with Rogues' Castle and Pyramid Plunder somewhere
		// underneath them.
		List<Across> alternatives = new ArrayList<>();
		if (!picked)
		{
			for (String other : allTitles)
			{
				if (other.equals(shown.getTitle()) || questsAlreadyShown.contains(other))
				{
					continue;
				}
				Across across = mergeAcross(run, other);
				if (across.found())
				{
					alternatives.add(across);
				}
			}
			// Fastest first, by the rate at the bottom of each one's range: the
			// same figure, and the same order, the planner ranks a single
			// bracket's options by.
			alternatives.sort((a, b) -> b.rateLow != a.rateLow
				? Integer.compare(b.rateLow, a.rateLow)
				: a.option.getTitle().compareTo(b.option.getTitle()));
		}

		String altKey = runKey + "|alts";
		if (!alternatives.isEmpty())
		{
			if (expandedSteps.contains(altKey))
			{
				// A multi-option step, so each title stays clickable: picking one
				// of these is the same act as picking it inside a bracket.
				List<PathStep.Option> options = new ArrayList<>();
				for (Across across : alternatives)
				{
					options.add(across.option);
				}
				PathStep altStep = new PathStep(PathStep.Type.TRAIN_SKILL, title, options)
					.withLevels(first.getSkill(), first.getLevelFrom(), last.getLevelTo());
				JLabel hint = kit.resultLine("Click one to keep just that method:", SUBTLE, 10);
				hint.setFont(SMALL_FONT);
				stack(pathResultContainer, hint);
				for (Across across : alternatives)
				{
					// Only where it does not cover the whole run. "Covers 91 to
					// 99" is the fact worth a line; repeating the step's own
					// levels under every option would not be.
					if (across.from > first.getLevelFrom() || across.to < last.getLevelTo())
					{
						stack(pathResultContainer, kit.microLabel("Covers " + across.from
							+ " \u2192 " + across.to, SUBTLE, 6, 12));
					}
					renderOption(altStep, across.option, false);
				}
				stack(pathResultContainer, runLink(altKey, "Hide other methods"));
			}
			else
			{
				int others = alternatives.size();
				stack(pathResultContainer, runLink(altKey, "Show " + others + " other way"
					+ (others == 1 ? "" : "s") + " to train this"));
			}
		}

		stack(pathResultContainer, runLink(runKey, picked
			? "Change method (" + run.size() + " level brackets)"
			: "Show " + run.size() + " level brackets"));
	}

	/** Opens or closes a merged run of level brackets. */
	/**
	 * Folds the steps the player is already past away, or brings them back.
	 * <p>
	 * Its own state rather than an entry in {@code expandedSteps}: that set is
	 * keyed by step, and this is one switch for the whole plan.
	 */
	private JLabel doneLink(String text)
	{
		JLabel link = kit.resultLine(text, QUIET_LINK, 10);
		link.setFont(SMALL_FONT);
		kit.makeClickable(link, () ->
		{
			showFinishedSteps = !showFinishedSteps;
			renderPath(lastPath);
		});
		return link;
	}

	private JLabel runLink(String runKey, String text)
	{
		JLabel link = kit.resultLine(text, QUIET_LINK, 10);
		link.setFont(SMALL_FONT);
		kit.makeClickable(link, () ->
		{
			if (!expandedSteps.remove(runKey))
			{
				expandedSteps.add(runKey);
			}
			renderPath(lastPath);
		});
		return link;
	}

	private String capitalize(String text)
	{
		if (text == null || text.isEmpty())
		{
			return text == null ? "" : text;
		}
		return text.substring(0, 1).toUpperCase(java.util.Locale.ROOT)
			+ text.substring(1).toLowerCase(java.util.Locale.ROOT);
	}

	/**
	 * The option this step is collapsed to, or null while the choice is still
	 * open. Only collapses on an unambiguous match - if two of a step's options
	 * were somehow both chosen, showing the list again beats picking for them.
	 */
	private PathStep.Option chosenFrom(PathStep step)
	{
		PathStep.Option found = null;
		for (PathStep.Option option : step.getAlternatives())
		{
			if (chosenOptions.contains(option.getTitle()))
			{
				if (found != null)
				{
					return null;
				}
				found = option;
			}
		}
		return found;
	}

	/**
	 * One option: its title, its detail line and its wiki link. When the step
	 * still has an open choice the title is clickable, and clicking it collapses
	 * the step to that option.
	 */
	private void renderOption(PathStep step, PathStep.Option option, boolean selected)
	{
		JPanel card = kit.optionCard(selected);
		int outer = kit.cardInset;
		kit.cardInset = CARD_INSET;
		try
		{
			fillOption(card, step, option, selected);
		}
		finally
		{
			kit.cardInset = outer;
		}

		// A repeat whose every line was suppressed as already-said would
		// otherwise leave an empty box behind.
		if (card.getComponentCount() > 0)
		{
			stack(pathResultContainer, card);
		}
	}

	/** The contents of one option box. */
	private void fillOption(JPanel card, PathStep step, PathStep.Option option, boolean selected)
	{
		// A single-option step mirrors its own title into that option, so
		// printing both just says the same thing twice.
		if (!option.getTitle().equals(step.getTitle()))
		{
			String bullet = selected ? "\u2714 " : "";
			JLabel title = kit.resultLine(bullet + option.getTitle(), selected ? CHOSEN : PRIMARY, 0);
			title.setFont(OPTION_FONT);
			if (step.hasChoice() && !selected)
			{
				kit.makeClickable(title, () -> choose(step, option));
			}
			stack(card, title);
		}

		boolean questRoute = !option.getQuests().isEmpty();
		// The time estimate is deliberately NOT part of this key. It differs for
		// every segment a method spans, so counting it would mean the prose was
		// never a repeat and the same three-line note printed under all nine
		// Knights of Ardougne brackets.
		String body = String.join("", option.getTitle(), String.valueOf(option.getDetail()),
			String.valueOf(option.getQuests()));
		boolean alreadySaid = !optionBodiesShown.add(body);

		// Tags and the estimate always render. A Wilderness warning is not
		// something to suppress as a duplicate, and the estimate is the one part
		// that genuinely changed since the last time this method appeared.
		if (option.isPvpRisk())
		{
			stack(card, kit.microLabel("Wilderness \u00b7 PvP risk", WARN, 3, 0));
		}
		if (option.isTickManipulation())
		{
			stack(card, kit.microLabel("Tick manipulation", SUBTLE, 3, 0));
		}
		// The attention cost, where it has been judged. Deliberately not amber:
		// amber is reserved for "you can lose what you brought". A method being
		// hard work is a trade-off to weigh, not a warning.
		if (option.getAttention() == TrainingMethod.Attention.DEMANDING)
		{
			stack(card, kit.microLabel("Constant input", SUBTLE, 3, 0));
		}
		else if (option.getAttention() == TrainingMethod.Attention.AFK)
		{
			stack(card, kit.microLabel("Nearly AFK", SUBTLE, 3, 0));
		}
		if (option.getMeta() != null && !option.getMeta().isEmpty())
		{
			stack(card, kit.microLabel(option.getMeta(), SUBTLE, 3, 0));
		}

		if (alreadySaid)
		{
			// Said in full once already. A quest route is worth pointing back to;
			// for an ordinary method the estimate above is the news.
			if (questRoute)
			{
				JLabel repeat = kit.resultLine("The same quests as above \u2014 they cover this "
					+ "range too.", DETAIL, 0);
				repeat.setFont(SMALL_FONT);
				stack(card, repeat);
			}
			return;
		}

		if (option.getDetail() != null && !option.getDetail().isEmpty())
		{
			JLabel detail = kit.resultLine(option.getDetail(), DETAIL, 0);
			detail.setFont(SMALL_FONT);
			stack(card, detail);
		}

		// What to take, in the box with the method that needs it. The same
		// pictures a boss setup gets: "Maniacal monkeys" answers where to go and
		// leaves the player in the bank wondering what to bring, which is the
		// question they were going to the wiki for.
		renderKit(card, "Wear", option.getGear(), true);
		renderKit(card, "Bring", option.getSupplies(), false);
		renderNeeded(card, option.getNeeded());

		// Name the quests, then let Quest Helper take the player through each
		// one and its own requirements; they come back here afterwards to pick
		// the path up.
		if (questRoute)
		{
			for (String quest : option.getQuests())
			{
				stack(card, kit.resultLine("\u2022 " + quest, PRIMARY, 0));
			}
			stack(card,
				kit.questHelperPointer(PathStep.Type.DO_QUEST, option.getQuests().size()));
		}

		if (option.getWikiUrl() != null)
		{
			stack(card, kit.linkRow(java.util.Collections.singletonList(
				kit.actionLink("Wiki \u2197", () -> PanelKit.openUrl(option.getWikiUrl()))), 0));
		}
	}

	/**
	 * What this range will use up, as pictures with the counts under them.
	 * <p>
	 * The same row the gear gets, because it is the same question one step
	 * later: the plan says 16 hours at a gilded altar, and the player's next
	 * move is to work out how many dragon bones that is and go and buy them.
	 * Doing that division in the panel is the difference between a plan you can
	 * read and a plan you can act on - and it was being done on the wiki, in
	 * another tab, with the numbers copied across by hand.
	 */
	private void renderNeeded(JPanel card, List<PathStep.Option.Needed> needed)
	{
		if (needed.isEmpty())
		{
			return;
		}

		stack(card, kit.microLabel("Buy", SUBTLE, 6, 12));
		GearView.Pictured pictured = new GearView.Pictured();
		for (PathStep.Option.Needed line : needed)
		{
			Integer id = gear.firstItemFor(line.getItem());
			if (id == null || pictured.names.size() >= GearView.MAX_ICONS)
			{
				// No sprite for it: the count is the point, so it goes back to
				// words rather than being dropped.
				pictured.inWords.add(exact(line.getQuantity()) + " "
					+ line.getItem().toLowerCase(java.util.Locale.ROOT));
				continue;
			}
			pictured.names.putIfAbsent(id, line.getItem());
			pictured.counts.put(id, exact(line.getQuantity()));
		}
		gear.stackIcons(card, pictured);
		for (String words : pictured.getInWords())
		{
			JLabel line = kit.resultLine(words, DETAIL, 0);
			line.setFont(SMALL_FONT);
			stack(card, line);
		}
	}

	/**
	 * A count in full, with thousands separators - never abbreviated.
	 * <p>
	 * Everywhere else in the panel an xp figure is rounded to "12.3M", because
	 * nobody needs the digits of an xp total. A shopping list is the opposite:
	 * "23k superior dragon bones" is not a number you can take to the Grand
	 * Exchange, and rounding it is how the player ends up two bones short at
	 * level 98.
	 */
	private static String exact(long quantity)
	{
		return String.format(java.util.Locale.ROOT, "%,d", quantity);
	}

	/** One labelled row of gear or supplies inside an option box. */
	private void renderKit(JPanel card, String label, List<String> items, boolean worn)
	{
		if (items.isEmpty())
		{
			return;
		}
		stack(card, kit.microLabel(label, SUBTLE, 6, 0));
		GearView.Pictured pictured;
		if (worn)
		{
			pictured = gear.stackGear(card, items);
		}
		else
		{
			pictured = gear.iconsFor(items);
			gear.stackIcons(card, pictured);
		}
		for (String remaining : pictured.getInWords())
		{
			JLabel line = kit.resultLine(remaining, DETAIL, 0);
			line.setFont(SMALL_FONT);
			stack(card, line);
		}
	}

	/** Records a choice for this step and redraws the plan around it. */
	private void choose(PathStep step, PathStep.Option option)
	{
		// Drop any sibling first, so a step never has two chosen options.
		for (PathStep.Option other : step.getAlternatives())
		{
			chosenOptions.remove(other.getTitle());
		}
		chosenOptions.add(option.getTitle());
		expandedSteps.remove(step.getTitle());
		// Picking a method re-forms the runs around it, so no run stays expanded
		// under a key that described the old arrangement.
		expandedSteps.removeIf(key -> key.startsWith("run:"));
		renderPath(lastPath);
	}

	/** Opens or closes a step's full option list. */
	private JLabel toggleLink(PathStep step, String text, String suffix)
	{
		JLabel link = kit.resultLine(text + (suffix == null ? "" : " (" + suffix + ")"),
			QUIET_LINK, 10);
		link.setFont(SMALL_FONT);
		kit.makeClickable(link, () ->
		{
			if (!expandedSteps.remove(step.getTitle()))
			{
				expandedSteps.add(step.getTitle());
			}
			renderPath(lastPath);
		});
		return link;
	}

	private String prefixFor(PathStep.Type type)
	{
		switch (type)
		{
			case TRAIN_SKILL:
				return "[Train] ";
			case ACQUIRE_ITEM:
				return "[Get] ";
			case KILL_BOSS:
				return "[Drop] ";
			case DO_ACTIVITY:
				return "[Do] ";
			case DO_QUEST:
				return "[Quest] ";
			case DO_DIARY:
				return "[Diary] ";
			default:
				return "";
		}
	}

	/**
	 * The uppercase line above a step: its number, plus the one fact worth
	 * putting there - what the step costs in xp, or what kind of thing it is.
	 */
	private String stepCaption(int number, PathStep step)
	{
		String caption = "Step " + number;
		if (step.getXpCost() > 0)
		{
			caption = caption + " \u00b7 " + XpTable.formatXp(step.getXpCost()) + " xp";
		}
		else
		{
			String kind = prefixFor(step.getType()).replace("[", "").replace("]", "").trim();
			caption = kind.isEmpty() ? caption : caption + " \u00b7 " + kind;
		}
		// Reached only while finished steps are being shown, since otherwise
		// they are not in the list to caption. Without it they read as work
		// still to do, which is the opposite of why they were unfolded.
		if (step.isRecommended())
		{
			// Nothing in the game insists on this one, and a step that looks
			// like the rest reads as one more thing in the way.
			caption = caption + " \u00b7 recommended";
		}
		return isFinished(step) ? caption + " \u00b7 done" : caption;
	}

	/** Drops the rendered plan and puts the goal pickers back in view. */
	void clearPath()
	{
		lastPath = null;
		optionBodiesShown.clear();
		pathResultContainer.removeAll();
		pathResultContainer.revalidate();
		pathResultContainer.repaint();
		SwingUtilities.invokeLater(() ->
			kit.scrollPane.getViewport().setViewPosition(new java.awt.Point(0, 0)));
	}

	/**
	 * @param finishedActivities the name of every quest, diary tier and other
	 *                           activity with a done state that the player has
	 *                           reached. A plan is not planned again while it is
	 *                           open, so without this a quest finished since
	 *                           stayed listed as still to do.
	 */
	void setProgress(Map<String, Integer> currentLevels, Set<String> finishedActivities)
	{
		int before = lastPath == null ? 0 : finishedCount(lastPath);
		Map<String, Integer> levelsBefore = levels;
		levels = currentLevels == null
			? java.util.Collections.emptyMap()
			: new java.util.HashMap<>(currentLevels);
		doneActivities = finishedActivities == null
			? java.util.Collections.emptySet()
			: new java.util.HashSet<>(finishedActivities);
		if (lastPath != null && !levelsBefore.isEmpty() && !levels.isEmpty()
			&& !levels.equals(levelsBefore))
		{
			// A level went up while the plan was open. Folding finished steps
			// away is not enough here: a step from 75 to 77 is not finished at
			// 76, but its xp, its hours and its shopping list are all wrong.
			// So the plan is made again from where the player now stands, with
			// the methods they picked kept, and without moving the view.
			renderPath(keepingFinished(lastPath, pathResolver.apply(lastPath.getGoal())), false);
		}
		else if (lastPath != null && finishedCount(lastPath) != before)
		{
			// Not scrolled to the top: this re-render was not asked for, and
			// yanking the view while the player is mid-read is worse than the
			// stale step it is fixing.
			renderPath(lastPath, false);
		}
	}

	/**
	 * Whether the player is already past this step.
	 * <p>
	 * Skill training is judged by level, and a quest or diary tier on the way
	 * by whether the game says it is complete. A purchase or a boss kill has
	 * nothing to compare, and guessing would hide a step that still needs doing
	 * - so those are never folded away. Nor is the goal itself: a plan whose
	 * destination vanished from it would read as a plan to nowhere.
	 */
	private boolean isFinished(PathStep step)
	{
		if ((step.getType() == PathStep.Type.DO_QUEST || step.getType() == PathStep.Type.DO_DIARY
			|| step.getType() == PathStep.Type.DO_ACTIVITY) && !step.isTarget())
		{
			return doneActivities.contains(step.getTitle());
		}
		if (step.getType() != PathStep.Type.TRAIN_SKILL || step.getSkill() == null
			|| step.getLevelTo() <= 0 || levels.isEmpty())
		{
			return false;
		}
		Integer at = levels.get(step.getSkill().toUpperCase(Locale.ROOT));
		return at != null && at >= step.getLevelTo();
	}

	/**
	 * The new plan with the old one's finished steps put back at the front.
	 * <p>
	 * A plan made again starts from where the player stands, so everything
	 * already behind them is simply absent from it - and the steps they
	 * finished while watching would vanish instead of folding away as done.
	 */
	private Path keepingFinished(Path old, Path fresh)
	{
		if (fresh == null || fresh.isAlreadyComplete())
		{
			return fresh;
		}
		List<PathStep> steps = new ArrayList<>();
		for (PathStep step : old.getSteps())
		{
			if (isFinished(step))
			{
				steps.add(step);
			}
		}
		if (steps.isEmpty())
		{
			return fresh;
		}
		steps.addAll(fresh.getSteps());
		return new Path(fresh.getGoal(), false, steps, fresh.getWarnings(),
			fresh.isRequirementsAlreadyMet());
	}

	private int finishedCount(Path path)
	{
		int done = 0;
		for (PathStep step : path.getSteps())
		{
			if (isFinished(step))
			{
				done++;
			}
		}
		return done;
	}
}

package com.nowwhat;

import com.nowwhat.data.NameSearch;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Function;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.DefaultListModel;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;

/**
 * A type-to-filter picker: a text field, and the matches underneath it.
 * <p>
 * It replaces a {@link javax.swing.JComboBox} for the goal lists, which were
 * already awkward and would only get worse. A dropdown of 35 items is a scroll;
 * a dropdown of 300 is unusable, and the content database is supposed to keep
 * growing. A search box is the one control that improves as the list does.
 * <p>
 * The results list is only on screen while it is wanted - when the field has
 * focus, or when nothing has been picked yet. A sidebar is 240px wide and shares
 * its height with three other goal blocks, so a permanently open six-row list
 * would cost more than it gives. Picking something closes it and leaves the name
 * in the field, so the control reads as "this is your choice" at rest and as a
 * search while you are using it.
 * <p>
 * Keyboard: up and down move through the matches, Enter takes the highlighted
 * one, Escape puts the field back to what is already chosen. That matters more
 * here than in most pickers, because the player is typing anyway.
 *
 * @param <T> the kind of thing being picked
 */
public class SearchPicker<T> extends JPanel
{
	/** Enough to show the answer and a couple of near misses without eating the panel. */
	private static final int VISIBLE_ROWS = 6;
	/** Beyond this the list is noise; refine the query instead of scrolling. */
	private static final int MAX_RESULTS = 40;

	/**
	 * The field, with the placeholder painted into it whenever it is empty.
	 * <p>
	 * Swing has no placeholder, and the obvious substitute - putting the hint in
	 * as real text and clearing it on focus - makes the hint a value: it plans
	 * for "Search for an item" if you never touch the box. Painting it is the
	 * honest version, because the document stays empty.
	 */
	private final JTextField field = new JTextField()
	{
		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			if (placeholder == null || !getText().isEmpty())
			{
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				g2.setFont(getFont());
				Insets insets = getInsets();
				FontMetrics metrics = g2.getFontMetrics();
				int y = insets.top + metrics.getAscent()
					+ Math.max(0, (getHeight() - insets.top - insets.bottom
						- metrics.getHeight()) / 2);
				g2.drawString(placeholder, insets.left + 1, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	};
	private final DefaultListModel<T> model = new DefaultListModel<>();
	private final JList<T> results = new JList<>(model);
	private final JScrollPane scroller = new JScrollPane(results);
	private final JLabel empty;
	private final JPanel fieldRow;

	private final List<T> all;
	private final Function<T, String> name;

	/** Painted in the field while it is empty; see {@link #field}. */
	private String placeholder;

	private T selected;
	/** Guards the document listener while the field is being set programmatically. */
	private boolean updating;

	/**
	 * @param placeholder short text painted in the empty field, which is the
	 * only thing telling a player this is a box they can type in - it sits
	 * beside two real dropdowns and would otherwise look like a third
	 * @param hint the longer explanation, as a tooltip
	 */
	SearchPicker(List<T> all, Function<T, String> name, String placeholder, String hint)
	{
		this.all = all;
		this.name = name;
		this.placeholder = placeholder;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(Component.LEFT_ALIGNMENT);

		field.setToolTipText(hint);
		field.setAlignmentX(Component.LEFT_ALIGNMENT);

		results.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		results.setVisibleRowCount(VISIBLE_ROWS);
		results.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		results.setBorder(new EmptyBorder(0, 0, 0, 0));
		results.setCellRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index,
				boolean isSelected, boolean focused)
			{
				super.getListCellRendererComponent(list, value, index, isSelected, focused);
				setText(value == null ? "" : label(value));
				return this;
			}

			@SuppressWarnings("unchecked")
			private String label(Object value)
			{
				String text = name.apply((T) value);
				return text == null ? "" : text;
			}
		});
		scroller.setAlignmentX(Component.LEFT_ALIGNMENT);
		scroller.setBorder(new EmptyBorder(2, 0, 0, 0));
		// A long name is clipped with an ellipsis, never scrolled to. The list is
		// six rows at most and a row is about 18px, so a horizontal scrollbar
		// appearing along the bottom takes most of a row's height with it - which
		// shows up as a result row sliced in half rather than as a scrollbar.
		scroller.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroller.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);

		empty = new JLabel("Nothing matches that");
		empty.setAlignmentX(Component.LEFT_ALIGNMENT);
		empty.setBorder(new EmptyBorder(3, 2, 1, 0));
		empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		empty.setFont(field.getFont().deriveFont(field.getFont().getSize2D() - 1f));
		empty.setVisible(false);

		fieldRow = new JPanel(new BorderLayout(4, 0));
		fieldRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		fieldRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		fieldRow.add(field, BorderLayout.CENTER);
		add(fieldRow);
		add(empty);
		add(scroller);

		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				typed();
			}
		});

		field.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_DOWN:
						move(1);
						e.consume();
						break;
					case KeyEvent.VK_UP:
						move(-1);
						e.consume();
						break;
					case KeyEvent.VK_ENTER:
						take();
						e.consume();
						break;
					case KeyEvent.VK_ESCAPE:
						showChosen();
						e.consume();
						break;
					default:
						break;
				}
			}
		});

		// Clicking into the field starts a new search rather than editing the
		// name already in it. Without this, a field reading "Fire cape" and a
		// player typing "drag" produces "Fire capedrag" and no matches - which
		// reads as the search being broken.
		field.addFocusListener(new java.awt.event.FocusAdapter()
		{
			@Override
			public void focusGained(java.awt.event.FocusEvent e)
			{
				field.selectAll();
				filter("");
				setListVisible(true);
			}
		});

		results.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				int index = results.locationToIndex(e.getPoint());
				if (index >= 0)
				{
					results.setSelectedIndex(index);
					take();
				}
			}
		});

		// Nothing is chosen to start with, so the field is empty and the
		// placeholder shows. The dropdown this replaced had to open on
		// something; a search box opening on an arbitrary item would be both a
		// choice the player did not make and the reason the box looks like a
		// dropdown. The empty field is what makes it read as a search.
		filter("");
		showChosen();
	}

	/**
	 * Puts a control beside the field - the quantity spinner, in practice. It
	 * belongs on the field's own row rather than above the results, so the row
	 * still reads as one input.
	 */
	void setTrailing(Component trailing)
	{
		fieldRow.add(trailing, BorderLayout.EAST);
		fieldRow.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			field.getPreferredSize().height));
		resize();
	}

	/**
	 * Puts the cursor in the search box with the matches open.
	 * <p>
	 * What "Plan path" does when nothing has been chosen yet. Doing nothing at
	 * all reads as a broken button, and a complaint under it would be telling
	 * the player off for not knowing the box was a box - this just shows them
	 * where to type.
	 */
	void promptForChoice()
	{
		field.requestFocusInWindow();
		filter("");
		setListVisible(true);
	}

	/** The current choice, or null if nothing has been picked yet. */
	public T getSelected()
	{
		return selected;
	}

	/**
	 * Everything this picker can offer, in the order it was given them.
	 * <p>
	 * Public for the diagnostic harnesses, which render the panel with no game
	 * client and need to choose a goal by id - the job they used to do by
	 * walking a {@code JComboBox}'s model.
	 */
	public List<T> getEntries()
	{
		return java.util.Collections.unmodifiableList(all);
	}

	/** Chooses {@code value} as though the player had clicked it. */
	public void select(T value)
	{
		selected = value;
		showChosen();
	}

	private void typed()
	{
		if (updating)
		{
			return;
		}
		filter(field.getText());
		// Typing is a search, so the matches come back into view even if the
		// player had collapsed them by picking something.
		setListVisible(true);
	}

	private void filter(String query)
	{
		// No cap while nothing is typed: that is the whole list being browsed,
		// and truncating it would hide entries a dropdown would have shown.
		boolean searching = query != null && !query.trim().isEmpty();
		List<T> hits = NameSearch.rank(query, all, name, searching ? MAX_RESULTS : 0);
		model.clear();
		for (T hit : hits)
		{
			model.addElement(hit);
		}
		if (!model.isEmpty())
		{
			results.setSelectedIndex(0);
			results.ensureIndexIsVisible(0);
		}
		empty.setVisible(model.isEmpty());
		scroller.setVisible(!model.isEmpty());
		resize();
	}

	private void move(int by)
	{
		if (model.isEmpty())
		{
			return;
		}
		setListVisible(true);
		int next = Math.max(0, Math.min(model.size() - 1, results.getSelectedIndex() + by));
		results.setSelectedIndex(next);
		results.ensureIndexIsVisible(next);
	}

	/** Commits the highlighted match and collapses the list. */
	private void take()
	{
		T value = results.getSelectedValue();
		if (value == null)
		{
			return;
		}
		selected = value;
		showChosen();
	}

	/**
	 * Back to the resting state: the chosen name in the field, the matches out
	 * of the way. Also what Escape does, so a half-typed query is never left
	 * looking like a selection.
	 */
	private void showChosen()
	{
		updating = true;
		try
		{
			field.setText(selected == null ? "" : text(selected));
			field.setCaretPosition(field.getText().length());
		}
		finally
		{
			updating = false;
		}
		empty.setVisible(false);
		setListVisible(false);
	}

	/**
	 * How tall one row of results actually is, asked of the renderer that draws
	 * it.
	 * <p>
	 * This used to be guessed at as the field's height minus 4, and the guess
	 * was short: the list was then capped below the height of its own rows, so
	 * the first match showed with its text sliced in half across the bottom
	 * edge. A renderer knows its own height; nothing else does.
	 */
	private int rowHeight()
	{
		if (!model.isEmpty())
		{
			Component sample = results.getCellRenderer().getListCellRendererComponent(
				results, model.get(0), 0, false, false);
			int measured = sample.getPreferredSize().height;
			if (measured > 0)
			{
				return measured;
			}
		}
		FontMetrics metrics = results.getFontMetrics(results.getFont());
		return Math.max(16, metrics.getHeight() + 2);
	}

	/** The scroll pane's own borders and insets, which eat into the rows. */
	private int chrome()
	{
		Insets scrollerInsets = scroller.getInsets();
		Insets viewportInsets = scroller.getViewport().getInsets();
		return scrollerInsets.top + scrollerInsets.bottom
			+ viewportInsets.top + viewportInsets.bottom + 2;
	}

	private String text(T value)
	{
		String label = name.apply(value);
		return label == null ? "" : label;
	}

	private void setListVisible(boolean visible)
	{
		scroller.setVisible(visible && !model.isEmpty());
		resize();
	}

	private void resize()
	{
		// BoxLayout honours the maximum, and a scroll pane's is unbounded, so
		// without this the list stretches to fill whatever height is going.
		int rows = Math.min(VISIBLE_ROWS, Math.max(1, model.size()));
		int rowHeight = rowHeight();
		int height = rows * rowHeight + chrome();
		scroller.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		scroller.setPreferredSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
		revalidate();
		repaint();
	}
}

package com.nowwhat.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.nowwhat.model.Activity;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the bundled activities.json (the ruleset: activities + their
 * requirements) into memory. This is the file the community would maintain
 * and expand over time as OSRS adds content - the plugin code itself
 * shouldn't need to change when new diary tiers, quests, or bosses ship.
 */
@Slf4j
@Singleton
public class ActivityDatabase
{
	private static final String RESOURCE_PATH = "/com/nowwhat/activities.json";

	private final Gson gson;
	private List<Activity> activities = Collections.emptyList();

	@Inject
	public ActivityDatabase(Gson gson)
	{
		this.gson = gson;
	}

	public void load()
	{
		try (InputStream is = ActivityDatabase.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (is == null)
			{
				log.error("Could not find bundled activities.json at {}", RESOURCE_PATH);
				return;
			}
			try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				Type listType = new TypeToken<List<Activity>>()
				{
				}.getType();
				activities = gson.fromJson(reader, listType);
				resolvePreparation(activities);
				log.info("Loaded {} activities from bundled database", activities.size());
			}
		}
		catch (IOException e)
		{
			log.error("Failed to load activities.json", e);
		}
	}

	/**
	 * Hands every entry that borrows its preparation the gear of the activity it
	 * borrows from.
	 * <p>
	 * Done at load rather than at render time so the rest of the code never has
	 * to know an activity's gear might live somewhere else, and so a reference
	 * that no longer resolves is noticed in the log on startup instead of being
	 * a blank space in the panel.
	 */
	static void resolvePreparation(List<Activity> activities)
	{
		if (activities == null)
		{
			return;
		}
		Map<String, Activity> byId = new HashMap<>();
		for (Activity activity : activities)
		{
			byId.put(activity.getId(), activity);
		}
		for (Activity activity : activities)
		{
			String from = activity.getPreparationFrom();
			if (from == null)
			{
				continue;
			}
			Activity source = byId.get(from);
			if (source == null || !source.hasPreparation())
			{
				log.warn("{} borrows its preparation from {}, which has none", activity.getId(), from);
				continue;
			}
			activity.inheritPreparation(source);
		}
	}

	public List<Activity> getAllActivities()
	{
		return activities;
	}
}

package com.nowwhat.data;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads Combat Achievement tier completion out of varbits.
 *
 * <p>Unlike the collection log, this needs no interface scraping and no
 * snapshotting: the game keeps one varbit per tier and the client has them
 * for the whole session, so tier completion is simply readable whenever the
 * player is logged in.
 *
 * <p>The tier varbits are progress counters rather than plain flags - 0 is
 * not started, 1 is in progress, 2 is complete - which is the same shape as
 * the Karamja diary varbits. If a completed tier ever fails to register, that
 * threshold is the first thing to check with the Var Inspector in developer
 * mode.
 *
 * <p>Keys written here are {@code CA_<TIER>}, matching both the activity ids
 * in activities.json and the values a {@code COMBAT_ACHIEVEMENT_TIER}
 * requirement uses, so "have I done this tier" and "does this need that tier"
 * agree on one spelling.
 */
public class CombatAchievementTracker
{
	private static final int COMPLETE = 2;

	private static final String[] TIERS = {
		"EASY", "MEDIUM", "HARD", "ELITE", "MASTER", "GRANDMASTER"
	};

	private static final int[] TIER_VARBITS = {
		VarbitID.CA_TIER_STATUS_EASY,
		VarbitID.CA_TIER_STATUS_MEDIUM,
		VarbitID.CA_TIER_STATUS_HARD,
		VarbitID.CA_TIER_STATUS_ELITE,
		VarbitID.CA_TIER_STATUS_MASTER,
		VarbitID.CA_TIER_STATUS_GRANDMASTER,
	};

	/**
	 * Populates completed Combat Achievement tiers on the state accumulator.
	 * Call once per refresh cycle from the plugin, on the client thread.
	 */
	public void readInto(Client client, com.nowwhat.model.PlayerState state)
	{
		for (int i = 0; i < TIERS.length; i++)
		{
			if (client.getVarbitValue(TIER_VARBITS[i]) >= COMPLETE)
			{
				state.addCompletedCombatAchievementTier("CA_" + TIERS[i]);
			}
		}

		// The running total every tier threshold is measured against. Read
		// alongside the tier flags so "how far am I from Master" can be
		// answered with a number rather than a wiki link. If the panel ever
		// shows a total that disagrees with the in-game interface, check
		// this varbit in the Var Inspector first.
		state.setCombatAchievementPoints(client.getVarbitValue(VarbitID.CA_POINTS));
	}
}

package com.nowwhat.data;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads Achievement Diary completion out of varbits.
 *
 * <p>An earlier version of this class assumed each region packed all four
 * tiers into one varbit as a bitmask, and shipped with every id set to -1 -
 * which meant the loop skipped every region and diary completion was never
 * actually read. RuneLite exposes a separate varbit per region per tier
 * ({@link VarbitID#ARDOUGNE_DIARY_EASY_COMPLETE} and friends), so there is no bitmask
 * and no placeholder ids: the real values are used directly.
 *
 * <p>Karamja is the exception. Its easy/medium/hard varbits are progress
 * counters (0 = not started, 1 = started, 2 = complete) rather than the plain
 * 0/1 flags every other region uses, so they need a different comparison.
 * Karamja elite is a normal flag. If a diary tier ever reports as incomplete
 * when it isn't, this quirk is the first thing to check with the Var
 * Inspector in developer mode.
 */
public class DiaryTracker
{
	/** Region name (as used in activity ids and requirement values) -> per-tier varbit ids. */
	private static final Map<String, int[]> REGION_VARBITS = new LinkedHashMap<>();

	/** Regions whose varbits count progress instead of flagging completion. */
	private static final String KARAMJA = "KARAMJA";

	private static final int EASY = 0;
	private static final int MEDIUM = 1;
	private static final int HARD = 2;
	private static final int ELITE = 3;

	private static final String[] TIER_NAMES = {"EASY", "MEDIUM", "HARD", "ELITE"};

	static
	{
		REGION_VARBITS.put("ARDOUGNE", new int[]{
			VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
			VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("DESERT", new int[]{
			VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
			VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("FALADOR", new int[]{
			VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
			VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("FREMENNIK", new int[]{
			VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
			VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("KANDARIN", new int[]{
			VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE});
		// Karamja's first three tiers predate the standard naming and are still
		// called ATJUN_* (the island's internal name) rather than KARAMJA_DIARY_*;
		// only the elite tier, added later, follows the usual pattern.
		REGION_VARBITS.put(KARAMJA, new int[]{
			VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE,
			VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("KOUREND", new int[]{
			VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
			VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("LUMBRIDGE", new int[]{
			VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("MORYTANIA", new int[]{
			VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
			VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("VARROCK", new int[]{
			VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
			VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("WESTERN", new int[]{
			VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
			VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE});
		REGION_VARBITS.put("WILDERNESS", new int[]{
			VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
			VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE});
	}

	/**
	 * Populates completedDiaryTiers on the given state accumulator.
	 * Call once per refresh cycle from the plugin, on the client thread.
	 */
	public void readInto(Client client, com.nowwhat.model.PlayerState state)
	{
		for (Map.Entry<String, int[]> entry : REGION_VARBITS.entrySet())
		{
			String region = entry.getKey();
			int[] tiers = entry.getValue();

			for (int tier = EASY; tier <= ELITE; tier++)
			{
				if (isComplete(client.getVarbitValue(tiers[tier]), region, tier))
				{
					state.addCompletedDiaryTier(region + "_" + TIER_NAMES[tier]);
				}
			}
		}
	}

	private static boolean isComplete(int value, String region, int tier)
	{
		if (KARAMJA.equals(region) && tier != ELITE)
		{
			// Progress counter, not a flag: 1 means started, not finished.
			return value >= 2;
		}
		return value > 0;
	}
}

package com.nowwhat.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Names and ids for the items the bundled gear and supply lines mention, for
 * the ones RuneLite's own search cannot find.
 * <p>
 * This exists because {@code ItemManager.search} only covers <b>tradeable</b>
 * items: it walks the Grand Exchange price map, so nothing untradeable is in
 * it. Half the gear a boss guide names is untradeable - void, barrows gloves,
 * an infernal cape, a slayer helmet - and a charged weapon is the sharpest
 * case of all, because the charged scythe of vitur cannot be traded and only
 * "Scythe of vitur (uncharged)" appears in the price list. A player looking at
 * a best-in-slot setup with no scythe in it reasonably concludes the pictures
 * are broken.
 * <p>
 * The table is a resource, {@code item-names.txt}, generated from RuneLite's
 * {@code ItemID} constants by {@code ./gradlew itemnames}. It used to be read
 * from those constants at runtime by reflection, which Plugin Hub plugins may
 * not use; it holds only the items the bundled text resolves to, and
 * {@code ItemNamesTableTest} fails when the text and the table drift apart.
 * Constant names are not display names - they have lost apostrophes, hyphens
 * and brackets - so this stays the <em>fallback</em>: a real display name from
 * RuneLite's index is always preferred when there is one.
 */
@Slf4j
public final class ItemNameIndex
{
	static final String RESOURCE = "/com/nowwhat/item-names.txt";
	/** A typographic apostrophe, written as a number so the source stays ASCII. */
	private static final String CURLY_APOSTROPHE = String.valueOf((char) 0x2019);

	private static List<ItemTextParser.Candidate> index;
	/**
	 * Flattened names of the items the plugin itself knows as goals - the rows
	 * marked "known" in the table. When a phrase fits several items equally
	 * ("Bandos" for legs: tassets or chaps), the known one is what a guide
	 * means.
	 */
	private static Set<String> known = Collections.emptySet();

	private ItemNameIndex()
	{
	}

	/**
	 * Every item in the table whose name contains {@code term}, compared without
	 * the punctuation these names cannot carry.
	 */
	public static List<ItemTextParser.Candidate> search(String term)
	{
		List<ItemTextParser.Candidate> hits = new ArrayList<>();
		if (term == null || term.trim().isEmpty())
		{
			return hits;
		}
		String needle = flatten(term);
		for (ItemTextParser.Candidate candidate : index())
		{
			if (flatten(candidate.getName()).contains(needle))
			{
				hits.add(candidate);
			}
		}
		return hits;
	}

	/** The whole table, for the test that keeps it in step with the bundled text. */
	/** The table's third column for an item the plugin knows as a goal. */
	static final String KNOWN = "known";

	/** @see #known */
	public static Set<String> known()
	{
		index();
		return known;
	}

	static List<ItemTextParser.Candidate> all()
	{
		return Collections.unmodifiableList(index());
	}

	/** Apostrophes and hyphens are absent from constant names; ignore them on both sides. */
	public static String flatten(String text)
	{
		return text.toLowerCase(Locale.ROOT)
			.replace("'", "")
			.replace(CURLY_APOSTROPHE, "")
			.replace("-", "")
			.replace("+", "");
	}

	private static synchronized List<ItemTextParser.Candidate> index()
	{
		if (index == null)
		{
			index = load();
		}
		return index;
	}

	/** One item per line, "id TAB name". A missing or broken table leaves the fallback empty. */
	private static List<ItemTextParser.Candidate> load()
	{
		List<ItemTextParser.Candidate> loaded = new ArrayList<>();
		Set<String> knownNames = new HashSet<>();
		try (InputStream in = ItemNameIndex.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Item name table {} is missing", RESOURCE);
				return loaded;
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				String[] columns = line.split("\t");
				if (columns.length < 2 || columns[0].isEmpty())
				{
					continue;
				}
				loaded.add(new ItemTextParser.Candidate(columns[1], Integer.parseInt(columns[0])));
				if (columns.length > 2 && KNOWN.equals(columns[2]))
				{
					knownNames.add(flatten(columns[1]));
				}
			}
		}
		catch (IOException | NumberFormatException broken)
		{
			log.warn("Could not read the item name table", broken);
			loaded.clear();
			knownNames.clear();
		}
		known = Collections.unmodifiableSet(knownNames);
		return loaded;
	}
}

package com.nowwhat.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.nowwhat.model.ItemSource;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class ItemSourceDatabase
{
	private static final String RESOURCE_PATH = "/com/nowwhat/item-sources.json";

	private final Gson gson;
	private final Map<String, ItemSource> sourcesById = new HashMap<>();

	@Inject
	public ItemSourceDatabase(Gson gson)
	{
		this.gson = gson;
	}

	/** Direct in-memory construction - used by tests so they don't depend on the real bundled item-sources.json. */
	public static ItemSourceDatabase of(List<ItemSource> sources)
	{
		ItemSourceDatabase db = new ItemSourceDatabase(null);
		for (ItemSource source : sources)
		{
			db.sourcesById.put(source.getId().toUpperCase(), source);
		}
		return db;
	}

	public void load()
	{
		try (InputStream is = ItemSourceDatabase.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (is == null)
			{
				log.error("Could not find bundled item-sources.json at {}", RESOURCE_PATH);
				return;
			}
			try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				Type listType = new TypeToken<List<ItemSource>>()
				{
				}.getType();
				List<ItemSource> all = gson.fromJson(reader, listType);
				for (ItemSource source : all)
				{
					sourcesById.put(source.getId().toUpperCase(), source);
				}
				log.info("Loaded {} item sources", sourcesById.size());
			}
		}
		catch (IOException e)
		{
			log.error("Failed to load item-sources.json", e);
		}
	}

	/** Null if this item has no bundled source data - the planner reports that as unresolved rather than guessing. */
	public ItemSource getSource(String itemId)
	{
		if (itemId == null)
		{
			return null;
		}
		return sourcesById.get(normalizeId(itemId));
	}

	/**
	 * Ids in the data file are SCREAMING_SNAKE_CASE, but people type item
	 * names ("Twisted bow", "twisted-bow"). Normalise rather than make the
	 * exact id the price of getting an answer.
	 */
	public static String normalizeId(String raw)
	{
		return raw.trim().toUpperCase().replaceAll("[^A-Z0-9]+", "_").replaceAll("^_|_$", "");
	}

	public java.util.List<ItemSource> getAllSources()
	{
		return new java.util.ArrayList<>(sourcesById.values());
	}
}

package com.nowwhat.data;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Turns the free-text gear and supply lines in activities.json into item names
 * concrete enough to look up and show as a picture.
 * <p>
 * The lines were written to be read, not parsed: "Neck: rancour, torture, blood
 * fury", "Head/body/legs: Masori (f), Masori, Armadyl", "8-10 prayer potions
 * (4)". That is the right way round - the words are what a player actually
 * needs - so this reads them rather than asking the data to become a list of
 * item ids. Two things make it tractable:
 * <ul>
 *   <li>the lines name their slot often enough to disambiguate shorthand.
 *       "occult" is only an amulet because the line says "Neck:", and without
 *       that context a bare "crystal" could be a key, a pickaxe or a halberd -
 *       so a one-word option with no slot named resolves to nothing at all
 *       rather than to a guess;</li>
 *   <li>a slot prefix naming several slots ("Head/body/legs") means the option
 *       is a set, and expands into one lookup per slot.</li>
 * </ul>
 * Everything here is deliberately pure: it takes text and returns phrases and
 * ids, with no RuneLite types in sight, so the guessing can be unit-tested
 * instead of eyeballed in a running client.
 */
public final class ItemTextParser
{
	/** Separators between alternatives in one line, longest first so " or " wins over ",". */
	private static final String[] SEPARATORS = {" such as ", " then ", " with ", " or ", " and ",
		" plus ", ", ", ",", " / "};

	/**
	 * Words that start an explanation rather than another item: "4+ cooked
	 * karambwan <b>for</b> combo eating", "Any Bandos item <b>to</b> stop the
	 * bodyguards". Everything from there on is advice, and feeding it to a
	 * search only buys a wrong picture.
	 */
	private static final String[] PROSE_TAILS = {" for ", " to ", " if ", " when ", " unless ",
		" depending ", " must ", " that ", " which "};

	/** Dropped from the front of a phrase: quantities and determiners, never item words. */
	private static final Set<String> LEADING_NOISE = new LinkedHashSet<>(Arrays.asList(
		"a", "an", "any", "some", "the", "x", "best", "your", "about", "around",
		// Quantities again, spelled out: "Several super restores", "8 doses of
		// Saradomin brew". Stripped one word at a time, so "doses of" goes too.
		"several", "plenty", "lots", "extra", "spare", "more", "bring", "dose",
		"doses", "of", "or", "and"));

	/**
	 * The words that identify an item as belonging to a slot. Used only to pin
	 * down a one-word option: "ultor" plus "Ring:" is the Ultor ring, while
	 * "ultor" on its own is not safely anything.
	 */
	private static final Map<String, List<String>> SLOT_NOUNS = new LinkedHashMap<>();

	static
	{
		SLOT_NOUNS.put("head", Arrays.asList("helm", "helmet", "hat", "mask", "hood", "coif",
			"faceguard", "faceguard", "crown"));
		SLOT_NOUNS.put("helm", SLOT_NOUNS.get("head"));
		SLOT_NOUNS.put("body", Arrays.asList("body", "platebody", "chestplate", "top", "robetop",
			"hauberk", "torso", "robe", "chainbody", "chest", "leathertop", "brassard", "chestguard"));
		SLOT_NOUNS.put("chest", SLOT_NOUNS.get("body"));
		SLOT_NOUNS.put("legs", Arrays.asList("legs", "platelegs", "chaps", "skirt", "plateskirt",
			"robeskirt", "bottom", "tassets", "robe", "chainskirt", "leatherskirt", "cuisse", "legguards"));
		SLOT_NOUNS.put("neck", Arrays.asList("necklace", "amulet"));
		SLOT_NOUNS.put("amulet", SLOT_NOUNS.get("neck"));
		SLOT_NOUNS.put("cape", Arrays.asList("cape", "cloak", "quiver", "assembler", "accumulator"));
		SLOT_NOUNS.put("back", SLOT_NOUNS.get("cape"));
		SLOT_NOUNS.put("shield", Arrays.asList("shield", "ward", "defender", "buckler", "book",
			"tome", "kiteshield"));
		SLOT_NOUNS.put("offhand", SLOT_NOUNS.get("shield"));
		SLOT_NOUNS.put("hands", Arrays.asList("gloves", "vambraces", "gauntlets", "bracelet",
			"bracers", "gloves"));
		SLOT_NOUNS.put("gloves", SLOT_NOUNS.get("hands"));
		// "treads" too: "Boots: Avernic treads (max), primordial boots" names the
		// best boots in the game without the word "boots" anywhere in them.
		SLOT_NOUNS.put("boots", Arrays.asList("boots", "shoes", "treads"));
		SLOT_NOUNS.put("feet", SLOT_NOUNS.get("boots"));
		SLOT_NOUNS.put("ring", Collections.singletonList("ring"));
		SLOT_NOUNS.put("ammo", Arrays.asList("arrow", "arrows", "bolts", "darts", "javelins",
			"knives"));
		SLOT_NOUNS.put("ammunition", SLOT_NOUNS.get("ammo"));
		// A weapon slot has no noun of its own - there is nothing all weapons are
		// called - so it is registered with none. That still gets the prefix out
		// of the way, which is the other half of the job: without it, "Weapon:
		// twisted bow plus toxic blowpipe" asks for an item called "weapon:
		// twisted bow" and finds nothing.
		SLOT_NOUNS.put("weapon", Collections.emptyList());
		SLOT_NOUNS.put("mainhand", Collections.emptyList());
		SLOT_NOUNS.put("2h", Collections.emptyList());
	}

	/** Kinds of thing a list can share: "nature, fire, dust and law runes". */
	private static final Set<String> SHARED_NOUNS = new LinkedHashSet<>(Arrays.asList(
		"runes", "rune", "arrows", "bolts", "darts", "javelins", "potions", "seeds", "logs",
		"bars", "ores", "planks", "hides", "bones", "saplings"));

	/** Every slot noun, for telling which belong to one slot only. */
	private static final Set<String> ALL_SLOT_NOUNS = new LinkedHashSet<>();

	static
	{
		SLOT_NOUNS.values().forEach(ALL_SLOT_NOUNS::addAll);
	}

	/**
	 * Names for "any one of these", pictured by one of them. Guides write "god
	 * cape" and "blessed coif" because every god's version does the same job,
	 * and no item is called that, so the box stayed empty. The Saradomin one
	 * stands in for the picture; the line keeps its words (see
	 * {@link #namesAStandIn}), so "any god" is still said.
	 */
	private static final Map<String, String> STAND_INS = new LinkedHashMap<>();

	static
	{
		STAND_INS.put("imbued god cape", "imbued saradomin cape");
		STAND_INS.put("god cape", "saradomin cape");
		STAND_INS.put("blessed coif", "saradomin coif");
		STAND_INS.put("blessed d'hide coif", "saradomin coif");
		STAND_INS.put("blessed body", "saradomin d'hide body");
		STAND_INS.put("blessed d'hide body", "saradomin d'hide body");
		STAND_INS.put("blessed chaps", "saradomin chaps");
		STAND_INS.put("blessed d'hide chaps", "saradomin chaps");
		STAND_INS.put("blessed boots", "saradomin d'hide boots");
		STAND_INS.put("blessed d'hide boots", "saradomin d'hide boots");
	}

	/** Whether a line names one of the "any of these" items, so its words have to stay. */
	public static boolean namesAStandIn(String entry)
	{
		if (entry == null)
		{
			return false;
		}
		String lower = entry.toLowerCase(Locale.ROOT);
		for (String name : STAND_INS.keySet())
		{
			if (lower.contains(name))
			{
				return true;
			}
		}
		return false;
	}

	/** Names that are a different thing wearing the same name, and never what a guide means. */
	private static final String[] JUNK = {"placeholder", "(broken)", "(deadman", "(last man",
		"(lms)", "(bh)", "(beta)"};

	/**
	 * The same object, unloaded. Taken only when nothing better matches.
	 * <p>
	 * These used to be rejected outright, which quietly lost whole weapons: a
	 * charged scythe of vitur cannot be traded, so the only scythe in an index
	 * built from Grand Exchange prices is "Scythe of vitur (uncharged)". The
	 * picture is the same weapon either way.
	 */
	private static final String[] UNLOADED = {"(uncharged)", "(empty)", "(u)", "(unf)"};

	private ItemTextParser()
	{
	}

	/** One thing to look up: the words of an option, plus the slot words that pin it down. */
	public static final class Phrase
	{
		private final String text;
		private final List<String> words;
		private final List<String> slotNouns;
		private final String quantity;

		Phrase(String text, List<String> words, List<String> slotNouns, String quantity)
		{
			this.text = text;
			this.words = words;
			this.slotNouns = slotNouns;
			this.quantity = quantity;
		}

		public String getText()
		{
			return text;
		}

		public List<String> getWords()
		{
			return words;
		}

		/** Empty when the line named no slot - in which case a one-word phrase is dropped. */
		public List<String> getSlotNouns()
		{
			return slotNouns;
		}

		/**
		 * How many the line asked for - "8-10", "4+", "12-14" - or null where it
		 * said no number.
		 * <p>
		 * Stripped out of the words before looking the item up, because no item is
		 * called "8-10 prayer potions", but kept, because a picture of a prayer
		 * potion that does not say "8-10" has quietly dropped the part the player
		 * most needed.
		 */
		public String getQuantity()
		{
			return quantity;
		}

		@Override
		public String toString()
		{
			return text + (slotNouns.isEmpty() ? "" : " " + slotNouns);
		}
	}

	/** A possible item: whatever an item index offered for a phrase. */
	public static final class Candidate
	{
		private final String name;
		private final int id;

		public Candidate(String name, int id)
		{
			this.name = name;
			this.id = id;
		}

		public String getName()
		{
			return name;
		}

		public int getId()
		{
			return id;
		}
	}

	/**
	 * The lookups one written line asks for, in the order they were written.
	 * <p>
	 * A line naming several slots is a set, so it expands: "Head/body/legs:
	 * Masori (f), Masori, Armadyl" becomes nine phrases, which is nine pictures
	 * of three real kits rather than one arbitrarily chosen helmet.
	 */
	public static List<Phrase> phrases(String entry)
	{
		List<Phrase> phrases = new ArrayList<>();
		if (entry == null || entry.trim().isEmpty())
		{
			return phrases;
		}

		String text = entry.trim();
		List<String> slots = new ArrayList<>();

		// "Neck: occult then fury" - the part before the colon names the slot(s),
		// never the item. A colon anywhere else in the line is left alone.
		int colon = text.indexOf(':');
		if (colon > 0 && colon < 24)
		{
			String prefix = text.substring(0, colon).toLowerCase(Locale.ROOT);
			for (String part : prefix.split("[/ ]+"))
			{
				if (SLOT_NOUNS.containsKey(part))
				{
					slots.add(part);
				}
			}
			if (!slots.isEmpty())
			{
				text = text.substring(colon + 1).trim();
			}
		}

		text = itemPart(text);

		// "Bandos chestplate and tassets" is one kit written once: the pieces after
		// the first are named by their own word alone, and only the first option
		// says which set they belong to. Without carrying that word across, every
		// line of this shape loses all but its first piece.
		// A set's name carries across the pieces written after it, but not past
		// an "or": "Bandos chestplate and tassets" is one kit, "Super attack,
		// strength and defence" three super potions, while "Oathplate helm,
		// chest and legs or Torva" is two kits and Torva is not an oathplate
		// piece. Every wrong carry the loadout audit found crossed an "or".
		for (String group : text.split("(?i) or "))
		{
			addPhrases(group, slots, phrases);
		}
		return phrases;
	}

	private static void addPhrases(String text, List<String> slots, List<Phrase> phrases)
	{
		String setWord = null;
		List<String> options = split(text);
		List<Cleaned> cleanedOptions = new ArrayList<>();
		for (String option : options)
		{
			cleanedOptions.add(words(option));
		}

		for (int i = 0; i < options.size(); i++)
		{
			String option = options.get(i);
			Cleaned cleaned = cleanedOptions.get(i);
			List<String> words = cleaned.getWords();
			if (words.isEmpty())
			{
				continue;
			}
			if (words.size() > 1 && setWord == null)
			{
				setWord = words.get(0);
			}
			else if (words.size() == 1 && setWord != null && slots.isEmpty())
			{
				words = Arrays.asList(setWord, words.get(0));
				option = setWord + " " + option;
			}
			// The other way round, a list that shares its last word: "nature,
			// fire, dust and law runes" is four kinds of rune.
			else if (words.size() == 1 && slots.isEmpty())
			{
				String shared = sharedLastWord(cleanedOptions, i);
				if (shared != null)
				{
					words = Arrays.asList(words.get(0), shared);
					option = option + " " + shared;
				}
			}
			String standIn = STAND_INS.get(String.join(" ", words));
			if (standIn != null)
			{
				words = Arrays.asList(standIn.split(" "));
			}
			if (slots.isEmpty())
			{
				phrases.add(new Phrase(option, words, Collections.emptyList(),
					cleaned.getQuantity()));
				continue;
			}
			for (String slot : slots)
			{
				phrases.add(new Phrase(option, words, SLOT_NOUNS.get(slot),
					cleaned.getQuantity()));
			}
		}
	}

	/**
	 * The last word of the next longer option, when only single words stand
	 * between: in "death, chaos, soul and air runes", "runes" for "chaos". Null
	 * when a longer option comes in between or there is none.
	 */
	private static String sharedLastWord(List<Cleaned> options, int from)
	{
		for (int j = from + 1; j < options.size(); j++)
		{
			List<String> later = options.get(j).getWords();
			if (later.size() > 2)
			{
				return null;
			}
			if (later.size() == 2)
			{
				// Only a word that names a kind of thing: "manta rays" must not
				// turn "anglerfish, sharks or manta rays" into "anglerfish rays".
				return SHARED_NOUNS.contains(later.get(1)) ? later.get(1) : null;
			}
		}
		return null;
	}

	/**
	 * The part of a line that names items: everything before a trailing
	 * explanation. "Hespori seed - no seed, no fight" is one item and a warning.
	 */
	static String itemPart(String text)
	{
		String part = text.trim();
		for (String dash : new String[]{" - ", " \u2014 ", " \u2013 "})
		{
			int at = part.indexOf(dash);
			if (at > 0)
			{
				part = part.substring(0, at).trim();
			}
		}
		for (String tail : PROSE_TAILS)
		{
			int at = part.toLowerCase(Locale.ROOT).indexOf(tail);
			if (at > 0)
			{
				part = part.substring(0, at).trim();
			}
		}
		return part;
	}

	/**
	 * Whether a line says anything beyond naming items - a condition, a reason, a
	 * caveat.
	 * <p>
	 * This is what decides whether pictures can stand in for the words. Icons can
	 * replace "twisted bow or toxic blowpipe" completely; they cannot replace
	 * "Extended anti-venom+ (4) - not optional here", where the sentence is the
	 * point and the item is only where it starts.
	 */
	public static boolean hasExplanation(String entry)
	{
		if (entry == null)
		{
			return false;
		}
		return itemPart(entry).length() < entry.trim().length();
	}

	/**
	 * What a line says after it has finished naming items, without the dash
	 * that introduced it: "not optional here". Null when it only names items.
	 */
	public static String explanation(String entry)
	{
		if (!hasExplanation(entry))
		{
			return null;
		}
		String rest = entry.trim().substring(itemPart(entry).length()).trim();
		int from = 0;
		while (from < rest.length() && "-,:;\u2013\u2014 ".indexOf(rest.charAt(from)) >= 0)
		{
			from++;
		}
		rest = rest.substring(from).trim();
		return rest.isEmpty() ? null : rest;
	}

	private static List<String> split(String text)
	{
		List<String> parts = new ArrayList<>();
		parts.add(text);
		for (String separator : SEPARATORS)
		{
			List<String> next = new ArrayList<>();
			for (String part : parts)
			{
				for (String piece : part.split(java.util.regex.Pattern.quote(separator)))
				{
					if (!piece.trim().isEmpty())
					{
						next.add(piece.trim());
					}
				}
			}
			parts = next;
		}
		return parts;
	}

	/** An option's words, lowercased, with leading quantities and determiners dropped. */
	/** An option's words and the count in front of them, separated. */
	static final class Cleaned
	{
		private final List<String> words = new ArrayList<>();
		private String quantity;

		List<String> getWords()
		{
			return words;
		}

		String getQuantity()
		{
			return quantity;
		}
	}

	/**
	 * An option's words, lowercased, with leading quantities and determiners
	 * dropped - and the quantity handed back rather than thrown away.
	 */
	static Cleaned words(String option)
	{
		Cleaned cleanedOption = new Cleaned();
		for (String word : option.toLowerCase(Locale.ROOT).split("[\\s]+"))
		{
			String cleaned = word.replace("\"", "").trim();
			if (cleaned.isEmpty())
			{
				continue;
			}
			if (cleanedOption.words.isEmpty())
			{
				if (cleaned.matches("[0-9]+[-+x][0-9]*") || cleaned.matches("[0-9]+"))
				{
					cleanedOption.quantity = cleanedOption.quantity == null
						? word.trim()
						: cleanedOption.quantity;
					continue;
				}
				if (LEADING_NOISE.contains(cleaned))
				{
					continue;
				}
			}
			cleanedOption.words.add(cleaned);
		}
		return cleanedOption;
	}

	/**
	 * What to ask an item index for, so that it offers the right candidates.
	 * <p>
	 * The longest word, since that is the most distinctive one, minus a trailing
	 * plural: the guides write "prayer potions" where the item is "Prayer
	 * potion(4)", and searching for the plural finds nothing at all.
	 */
	public static String searchTerm(Phrase phrase)
	{
		String longest = "";
		for (String word : phrase.getWords())
		{
			String cleaned = trimPunctuation(word);
			if (cleaned.length() > longest.length())
			{
				longest = cleaned;
			}
		}
		if (longest.length() >= 5 && longest.endsWith("s"))
		{
			longest = longest.substring(0, longest.length() - 1);
		}
		return longest;
	}

	/**
	 * The one item a phrase means, or null when the phrase does not pin an item
	 * down well enough to show a picture of it.
	 * <p>
	 * Every word of the phrase has to appear in the item's name, so "Masori body"
	 * cannot land on Masori chaps. A one-word phrase additionally has to be
	 * carrying a slot, and the slot's noun has to appear too - this is what keeps
	 * "crystal" under "Boots:" off a crystal key. Where several items still
	 * qualify the shortest name wins, since the longer ones are variants
	 * ("Masori body" over "Masori body (f)").
	 * <p>
	 * Before length, though, a name that has the very words the line was
	 * written with beats one that only matched through a slot's other nouns.
	 * "Shield" stands for the whole off-hand slot, so "dragonfire shield" also
	 * matches "Dragonfire ward", and the ward's shorter name used to win; the
	 * same went for "robe bottom" landing on the robe top, since "robe" is in
	 * both the body and the legs lists.
	 */
	public static Integer pick(Phrase phrase, List<Candidate> candidates)
	{
		return pick(phrase, candidates, ItemNameIndex.known());
	}

	/**
	 * As above, with the names that win a tie said outright - for building the
	 * table those names are read from, before it exists.
	 */
	public static Integer pick(Phrase phrase, List<Candidate> candidates, Set<String> known)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return null;
		}
		// A one-word option normally needs a slot to pin it to an item. The
		// exception is a word that is the whole name of something - "Facemask",
		// "Antipoison", "Sharks" - where there is nothing left to disambiguate.
		// "crystal" still resolves to nothing, because no item is called that.
		boolean nameInFull = phrase.getWords().size() < 2 && phrase.getSlotNouns().isEmpty();
		// Known items only settle a shorthand the slot narrows ("Bandos" for
		// legs). A line that names its item outright already said which one, and
		// "fire staff" must not become the known "fire element staff crown".
		if (phrase.getSlotNouns().isEmpty())
		{
			known = Collections.emptySet();
		}

		Candidate best = null;
		Candidate bestWritten = null;
		Candidate unloaded = null;
		for (Candidate candidate : candidates)
		{
			String lower = candidate.getName().toLowerCase(Locale.ROOT);
			if (contains(lower, JUNK))
			{
				continue;
			}

			List<String> nameWords = Arrays.asList(lower.split("[\\s]+"));
			if (!containsAll(nameWords, phrase.getWords()))
			{
				continue;
			}
			if (nameInFull && nameWords.size() > 1)
			{
				continue;
			}
			if (!phrase.getSlotNouns().isEmpty() && !containsAny(nameWords, phrase.getSlotNouns()))
			{
				continue;
			}
			// A word only another slot uses rules the item out: "ancestral" for
			// legs found "ancestral robe top", because "robe" is a legs word too.
			// "top" is not, so the top is the body's and the legs get the bottom.
			if (!phrase.getSlotNouns().isEmpty() && belongsElsewhere(nameWords, phrase.getSlotNouns()))
			{
				continue;
			}
			if (contains(lower, UNLOADED))
			{
				if (unloaded == null || beats(candidate, unloaded, known))
				{
					unloaded = candidate;
				}
				continue;
			}
			if (best == null || beats(candidate, best, known))
			{
				best = candidate;
			}
			if (containsAllExactly(nameWords, phrase.getWords())
				&& (bestWritten == null || beats(candidate, bestWritten, known)))
			{
				bestWritten = candidate;
			}
		}
		if (bestWritten != null)
		{
			best = bestWritten;
		}
		if (best == null)
		{
			best = unloaded;
		}
		return best == null ? null : best.getId();
	}

	private static boolean contains(String name, String[] markers)
	{
		for (String marker : markers)
		{
			if (name.contains(marker))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Which of two equally valid matches to show. The shorter name is the plainer
	 * item, so it wins; between names of the same length the bigger dose does,
	 * because a guide that says "prayer potions" without a number means full
	 * ones, and a 1-dose icon would be quietly wrong.
	 */
	/** Whether a name carries a slot word that this slot does not share. */
	private static boolean belongsElsewhere(List<String> nameWords, List<String> slotNouns)
	{
		for (String word : nameWords)
		{
			if (ALL_SLOT_NOUNS.contains(word) && !slotNouns.contains(word))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean beats(Candidate candidate, Candidate best, Set<String> known)
	{
		// An item the plugin knows as a goal beats one it does not. Shortest
		// name used to settle "Bandos" for legs, and "bandos chaps" is shorter
		// than "bandos tassets".
		boolean candidateKnown = known.contains(ItemNameIndex.flatten(candidate.getName()));
		boolean bestKnown = known.contains(ItemNameIndex.flatten(best.getName()));
		if (candidateKnown != bestKnown)
		{
			return candidateKnown;
		}
		int length = candidate.getName().length() - best.getName().length();
		if (length != 0)
		{
			return length < 0;
		}
		int dose = dose(candidate.getName()) - dose(best.getName());
		if (dose != 0)
		{
			return dose > 0;
		}
		return candidate.getId() < best.getId();
	}

	/** The dose in a name like "Prayer potion(4)", or 0 where there is none. */
	private static int dose(String name)
	{
		String trimmed = name.trim();
		if (trimmed.length() < 3 || !trimmed.endsWith(")"))
		{
			return 0;
		}
		char digit = trimmed.charAt(trimmed.length() - 2);
		return trimmed.charAt(trimmed.length() - 3) == '(' && Character.isDigit(digit)
			? digit - '0'
			: 0;
	}

	private static boolean containsAll(List<String> nameWords, List<String> needed)
	{
		for (String word : needed)
		{
			if (!containsWord(nameWords, word, true))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Does this name belong to the slot the line named?
	 * <p>
	 * Strict, with no synonym groups: the slot nouns <em>are</em> the groups, so
	 * widening them here would make every group match every other through the
	 * words they share - "robe" sits in both the body list and the legs list -
	 * and "Head/body/legs: Masori (f)" would answer every one of its three slots
	 * with the same piece.
	 */
	private static boolean containsAny(List<String> nameWords, List<String> options)
	{
		for (String word : options)
		{
			if (containsWord(nameWords, word, false))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Word match, tolerating a plural on either side and trailing punctuation.
	 * The guides say "prayer potions (4)" where the item is "Prayer potion(4)",
	 * and refusing that pairing would cost most of the supply icons.
	 */
	private static boolean containsWord(List<String> nameWords, String word, boolean synonyms)
	{
		String needle = trimPunctuation(word);
		if (needle.isEmpty())
		{
			return true;
		}
		for (String name : nameWords)
		{
			String candidate = trimPunctuation(name);
			if (samish(candidate, needle))
			{
				return true;
			}
			// "potion(4)" is one word in an item name but two ideas; match either.
			int bracket = candidate.indexOf('(');
			if (bracket > 0 && (samish(candidate.substring(0, bracket), needle)
				|| samish(candidate.substring(bracket), needle)))
			{
				return true;
			}
			if (synonyms && sameSlotWord(candidate, needle))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether two words are the same piece of armour under different names.
	 * <p>
	 * The guides say "Torag's body and legs" where the items are "Torag's
	 * platebody" and "Torag's platelegs". Matching those needs the slot groups
	 * that are already written down for disambiguating one-word options - and
	 * using them this way keeps the guarantee that matters, because a body word
	 * and a legs word are never in the same group: "Masori body" still cannot
	 * land on Masori chaps.
	 */
	private static boolean sameSlotWord(String a, String b)
	{
		if (a.equals(b))
		{
			return true;
		}
		for (List<String> group : SLOT_NOUNS.values())
		{
			boolean hasA = false;
			boolean hasB = false;
			for (String word : group)
			{
				hasA = hasA || samish(word, a);
				hasB = hasB || samish(word, b);
			}
			if (hasA && hasB)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Equal, give or take a plural and an apostrophe on either side. Item names
	 * and the guides disagree about apostrophes often enough to matter: a line
	 * reading "Avas accumulator" should still find "Ava's accumulator".
	 */
	private static boolean samish(String a, String b)
	{
		// Hyphens too: the guides write "anti-dragon shield", the game "antidragon".
		a = a.replace("'", "").replace("\u2019", "").replace("-", "");
		b = b.replace("'", "").replace("\u2019", "").replace("-", "");
		return a.equals(b) || a.equals(b + "s") || b.equals(a + "s")
			|| a.equals(b + "es") || b.equals(a + "es");
	}

	/** As {@link #containsAll}, but each word has to be there itself, not through its slot's other nouns. */
	private static boolean containsAllExactly(List<String> nameWords, List<String> needed)
	{
		for (String word : needed)
		{
			if (!containsWord(nameWords, word, false))
			{
				return false;
			}
		}
		return true;
	}

	private static String trimPunctuation(String word)
	{
		return word.replaceAll("^[^a-z0-9('\u2019+]+", "").replaceAll("[^a-z0-9)'\u2019+]+$", "");
	}
}

package com.nowwhat.data;

import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

/**
 * Tracks what the player actually owns: worn equipment, inventory, and bank.
 *
 * <p>This is what lets the planner answer "do you already have this" instead
 * of assuming you own nothing, and it is also the only way to know what gear
 * someone is working with - which matters because a training rate or a boss
 * recommendation is meaningless if the player can't equip the kit it assumes.
 *
 * <p>Three containers, with genuinely different availability, and the
 * difference is worth understanding rather than papering over:
 *
 * <ul>
 *   <li><b>Equipment and inventory</b> are pushed by the client continuously
 *       while logged in. These are always current.</li>
 *   <li><b>The bank</b> is only sent to the client when the player opens it.
 *       Until then there is nothing to read - not a RuneLite limitation, the
 *       data simply isn't client-side. So the bank is a <em>snapshot</em>
 *       from the last time it was opened, persisted to config so it survives
 *       logout instead of resetting to "you own nothing" every login - one
 *       snapshot per account, so two accounts never see each other's bank.</li>
 * </ul>
 *
 * <p>Because of that, {@link #hasBankSnapshot()} exists: a plan built with no
 * bank data should say so rather than quietly claiming the player needs to
 * acquire things they may already have stacked in their bank.
 */
@Slf4j
@Singleton
public class ItemTracker
{
	private static final String CONFIG_GROUP = "nowwhat";
	private static final String BANK_KEY = "bankSnapshot";

	private final ConfigManager configManager;

	private final Map<Integer, Integer> bank = new HashMap<>();
	private final Map<Integer, Integer> inventory = new HashMap<>();
	private final Map<Integer, Integer> equipment = new HashMap<>();

	/** The account the bank in memory belongs to, or null before anyone has logged in. */
	private String loadedFor;

	@Inject
	public ItemTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * Restores the bank snapshot of whoever is logged in. Safe to call as often
	 * as you like: it only does anything when the account has changed.
	 * <p>
	 * The snapshot is kept per account. It used to be one setting for the whole
	 * client, so a second account was planned against the first one's bank and
	 * told it already owned things it had never seen. Inventory and gear are
	 * dropped on a change too; the plugin reads those from the client again on
	 * its next refresh.
	 */
	public void load()
	{
		String account = configManager.getRSProfileKey();
		if (account == null || account.equals(loadedFor))
		{
			return;
		}
		loadedFor = account;
		bank.clear();
		inventory.clear();
		equipment.clear();

		String raw = configManager.getRSProfileConfiguration(CONFIG_GROUP, BANK_KEY);
		if (raw == null || raw.isEmpty())
		{
			// A snapshot saved before they were kept per account. It belongs to
			// whoever opened a bank last, which for nearly everyone is the one
			// account they play; handed to the first account that logs in and
			// then removed, so it can never reach a second one.
			raw = configManager.getConfiguration(CONFIG_GROUP, BANK_KEY);
			if (raw != null)
			{
				configManager.unsetConfiguration(CONFIG_GROUP, BANK_KEY);
				if (!raw.isEmpty())
				{
					configManager.setRSProfileConfiguration(CONFIG_GROUP, BANK_KEY, raw);
				}
			}
		}
		if (raw == null || raw.isEmpty())
		{
			return;
		}

		try
		{
			for (String pair : raw.split(","))
			{
				int split = pair.indexOf(':');
				if (split > 0)
				{
					bank.put(Integer.parseInt(pair.substring(0, split)),
						Integer.parseInt(pair.substring(split + 1)));
				}
			}
			log.debug("Restored bank snapshot of {} distinct items", bank.size());
		}
		catch (NumberFormatException e)
		{
			// A corrupt snapshot is not worth failing over; drop it and let the
			// next bank visit rebuild it.
			log.warn("Discarding unreadable bank snapshot", e);
			bank.clear();
		}
	}

	/**
	 * Feeds one container update in. Returns true if this was a container we
	 * care about, so the caller can decide whether to trigger a refresh.
	 */
	public boolean onContainerChanged(int containerId, ItemContainer container)
	{
		switch (containerId)
		{
			case InventoryID.BANK:
				snapshot(container, bank);
				persistBank();
				return true;
			case InventoryID.INV:
				snapshot(container, inventory);
				return true;
			case InventoryID.WORN:
				snapshot(container, equipment);
				return true;
			default:
				return false;
		}
	}

	private static void snapshot(ItemContainer container, Map<Integer, Integer> into)
	{
		into.clear();
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				into.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}

	private void persistBank()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Integer> e : bank.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.getKey()).append(':').append(e.getValue());
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, BANK_KEY, sb.toString());
	}

	/** Copies everything owned into the state accumulator. */
	public void writeInto(com.nowwhat.model.PlayerState state)
	{
		Map<Integer, Integer> total = new HashMap<>(bank);
		inventory.forEach((id, qty) -> total.merge(id, qty, Integer::sum));
		equipment.forEach((id, qty) -> total.merge(id, qty, Integer::sum));

		state.setOwnedItems(total);
		state.setEquippedItems(new LinkedHashSet<>(equipment.keySet()));
		state.setBankSnapshotAvailable(hasBankSnapshot());
	}

	public boolean hasBankSnapshot()
	{
		return !bank.isEmpty();
	}

	public Set<Integer> getEquippedItemIds()
	{
		return new LinkedHashSet<>(equipment.keySet());
	}
}

package com.nowwhat.data;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Function;

/**
 * Ranked name matching for the goal pickers.
 * <p>
 * A dropdown is the wrong control once a list stops being short: it cannot be
 * typed at, it has no idea what you meant, and it gets worse with every entry
 * added - which is the opposite of what a content database should do as it
 * grows. A search box gets better.
 * <p>
 * The ranking is deliberately plain, because a player typing "drag cl" has a
 * precise item in mind and wants it first, not a cleverer guess:
 * <ul>
 *   <li>every whitespace-separated term must appear somewhere in the name, so
 *       "drag cl" finds "Dragon claws" and "bandos tas" finds "Bandos
 *       tassets";</li>
 *   <li>a name the query prefixes outright comes first, then one where a word
 *       starts with the first term, then the rest;</li>
 *   <li>within a rank, shorter names first - "Dragon boots" before "Dragon
 *       hunter lance" for "dragon" - then alphabetically, so the order is
 *       stable rather than dependent on file order.</li>
 * </ul>
 * Punctuation is ignored on both sides for the same reason {@link ItemNameIndex}
 * ignores it: nobody types the apostrophe in "Seers' ring", and several of these
 * names have lost theirs already.
 */
public final class NameSearch
{
	private NameSearch()
	{
	}

	/**
	 * The entries matching {@code query}, best first.
	 *
	 * @param query  what the player typed; blank returns the entries unranked
	 *               and in their given order, so an untouched search box shows
	 *               the whole list exactly as a dropdown would have
	 * @param limit  at most this many results, or 0 for all of them
	 */
	public static <T> List<T> rank(String query, List<T> entries, Function<T, String> name,
		int limit)
	{
		List<String> terms = terms(query);
		if (terms.isEmpty())
		{
			// Nothing typed yet, so this is the whole list being browsed rather
			// than a search being ranked. It keeps the order it was given -
			// alphabetical, for the pickers - because the length tie-break below
			// would otherwise open the box on whichever name happens to be
			// shortest, which looks like a bug and is no use to anyone.
			List<T> everything = new ArrayList<>();
			for (T entry : entries)
			{
				if (limit > 0 && everything.size() >= limit)
				{
					break;
				}
				if (name.apply(entry) != null)
				{
					everything.add(entry);
				}
			}
			return everything;
		}

		List<Ranked<T>> hits = new ArrayList<>();
		for (T entry : entries)
		{
			String label = name.apply(entry);
			if (label == null)
			{
				continue;
			}
			int rank = rank(terms, flatten(label));
			if (rank >= 0)
			{
				hits.add(new Ranked<>(entry, label, rank));
			}
		}

		hits.sort(Comparator.<Ranked<T>>comparingInt(h -> h.rank)
			.thenComparingInt(h -> h.label.length())
			.thenComparing(h -> h.label, String.CASE_INSENSITIVE_ORDER));

		List<T> out = new ArrayList<>();
		for (Ranked<T> hit : hits)
		{
			if (limit > 0 && out.size() >= limit)
			{
				break;
			}
			out.add(hit.entry);
		}
		return out;
	}

	/**
	 * @return 0 for a prefix of the whole name, 1 for a word start, 2 for a
	 *     match anywhere, or -1 for no match at all
	 */
	private static int rank(List<String> terms, String flattened)
	{
		for (String term : terms)
		{
			if (!flattened.contains(term))
			{
				return -1;
			}
		}

		String first = terms.get(0);
		if (flattened.startsWith(first))
		{
			return 0;
		}
		// A word start, which is what makes "claws" rank above a name that
		// merely contains the letters mid-word.
		for (int i = 1; i < flattened.length(); i++)
		{
			if (flattened.charAt(i - 1) == ' ' && flattened.startsWith(first, i))
			{
				return 1;
			}
		}
		return 2;
	}

	private static List<String> terms(String query)
	{
		List<String> terms = new ArrayList<>();
		if (query == null)
		{
			return terms;
		}
		for (String raw : flatten(query).split(" "))
		{
			if (!raw.isEmpty())
			{
				terms.add(raw);
			}
		}
		return terms;
	}

	/** Lowercased, with the punctuation nobody types removed and runs of space collapsed. */
	private static String flatten(String text)
	{
		StringBuilder out = new StringBuilder(text.length());
		String lower = text.toLowerCase(Locale.ROOT);
		for (int i = 0; i < lower.length(); i++)
		{
			char c = lower.charAt(i);
			if (c == '\'' || c == '\u2019' || c == '-' || c == '+' || c == '('
				|| c == ')' || c == '.' || c == ',')
			{
				continue;
			}
			if (Character.isWhitespace(c) || c == '_' || c == '/')
			{
				if (out.length() > 0 && out.charAt(out.length() - 1) != ' ')
				{
					out.append(' ');
				}
				continue;
			}
			out.append(c);
		}
		return out.toString().trim();
	}

	private static final class Ranked<T>
	{
		private final T entry;
		private final String label;
		private final int rank;

		private Ranked(T entry, String label, int rank)
		{
			this.entry = entry;
			this.label = label;
			this.rank = rank;
		}
	}
}

package com.nowwhat.data;

import java.util.List;
import java.util.Locale;

/**
 * Finds another RuneLite plugin by the name in its {@code PluginDescriptor},
 * without compiling against it.
 * <p>
 * Name-based on purpose: Now What points at Quest Helper and at boss helpers
 * rather than reimplementing them, and that pointer has to work the same
 * whether or not the other plugin is installed. A build dependency would make
 * this plugin fail to load without them.
 * <p>
 * The matching lives here, apart from RuneLite's types, because it is the part
 * that can be wrong in a way nobody notices. It already was: the class-name
 * fallback used to test for a hardcoded {@code com.questhelper} package, so
 * <em>every</em> lookup answered "yes, installed" on the strength of Quest
 * Helper being there - asking whether Zulrah Helper was installed said yes. It
 * was caught by chance, in conversation. Now it is a pure function over two
 * lists of strings, and there are tests.
 */
public final class PluginLookup
{
	private PluginLookup()
	{
	}

	/**
	 * The index of the plugin that answers to {@code descriptorName}, or -1.
	 *
	 * @param descriptorName  the name as its PluginDescriptor spells it, e.g. "Quest Helper"
	 * @param descriptorNames every installed plugin's descriptor name, null where it has none
	 * @param classNames      the same plugins' fully qualified class names, same order
	 */
	public static int match(String descriptorName, List<String> descriptorNames,
		List<String> classNames)
	{
		if (descriptorName == null || descriptorNames == null || classNames == null)
		{
			return -1;
		}

		// An exact descriptor match wins, and is checked across every plugin
		// before the loose fallback gets a look in - otherwise a fuzzy hit on
		// whichever plugin happens to be iterated first beats the real match
		// further down the list.
		for (int i = 0; i < descriptorNames.size(); i++)
		{
			if (descriptorName.equals(descriptorNames.get(i)))
			{
				return i;
			}
		}

		// Plugins get forked and renamed, and a fork still does the job, so fall
		// back to the class name. The needle must be derived from the name being
		// searched for and nothing else.
		String needle = descriptorName.replace(" ", "").toLowerCase(Locale.ROOT);
		if (needle.isEmpty())
		{
			return -1;
		}
		for (int i = 0; i < classNames.size() && i < descriptorNames.size(); i++)
		{
			String className = classNames.get(i);
			if (className != null && className.toLowerCase(Locale.ROOT).contains(needle))
			{
				return i;
			}
		}
		return -1;
	}
}

package com.nowwhat.data;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.nowwhat.model.TrainingMethod;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class TrainingMethodDatabase
{
	private static final String RESOURCE_PATH = "/com/nowwhat/methods.json";

	private final Gson gson;
	private final Map<String, List<TrainingMethod>> methodsBySkill = new HashMap<>();

	@Inject
	public TrainingMethodDatabase(Gson gson)
	{
		this.gson = gson;
	}

	/** Direct in-memory construction - used by tests so they don't depend on the real bundled methods.json. */
	public static TrainingMethodDatabase of(List<TrainingMethod> methods)
	{
		TrainingMethodDatabase db = new TrainingMethodDatabase(null);
		for (TrainingMethod method : methods)
		{
			db.methodsBySkill.computeIfAbsent(method.getSkill().toUpperCase(), k -> new ArrayList<>()).add(method);
		}
		for (List<TrainingMethod> perSkill : db.methodsBySkill.values())
		{
			perSkill.sort(Comparator.comparingInt(TrainingMethod::getMinLevel));
			shareNotesAcrossBrackets(perSkill);
		}
		return db;
	}

	/**
	 * Loads the bundled methods and resolves every method that borrows its kit
	 * from an activity.
	 * <p>
	 * The activities are a parameter rather than a second call the caller has to
	 * remember, because forgetting it is invisible: the plan still renders, the
	 * gear is simply absent, and that was exactly the bug - Wintertodt on the
	 * Firemaking path named the minigame and said nothing about warm clothing.
	 * Six places build this database (the plugin and five diagnostic harnesses)
	 * and one signature keeps all six honest.
	 */
	public void load(List<com.nowwhat.model.Activity> activities)
	{
		try (InputStream is = TrainingMethodDatabase.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (is == null)
			{
				log.error("Could not find bundled methods.json at {}", RESOURCE_PATH);
				return;
			}
			try (InputStreamReader reader = new InputStreamReader(is, StandardCharsets.UTF_8))
			{
				Type listType = new TypeToken<List<TrainingMethod>>()
				{
				}.getType();
				List<TrainingMethod> all = gson.fromJson(reader, listType);
				for (TrainingMethod method : all)
				{
					methodsBySkill
						.computeIfAbsent(method.getSkill().toUpperCase(), k -> new ArrayList<>())
						.add(method);
				}
				// Sorted ascending by minLevel so the planner can walk them in order.
				for (List<TrainingMethod> methods : methodsBySkill.values())
				{
					methods.sort(Comparator.comparingInt(TrainingMethod::getMinLevel));
					shareNotesAcrossBrackets(methods);
				}
				linkActivityKit(activities);
				log.info("Loaded {} training methods across {} skills", all.size(), methodsBySkill.size());
			}
		}
		catch (IOException e)
		{
			log.error("Failed to load methods.json", e);
		}
	}

	/**
	 * Gives every bracket of a method the note recorded on its lowest bracket.
	 * <p>
	 * The data file states a note once per method rather than once per bracket -
	 * see tools/README.md - which keeps it from being restated nine times down a
	 * single skill. The cost is that a plan starting part-way up a method begins
	 * above the row holding the note. Copying it down here puts it back within
	 * reach of every plan; the panel's repeat check is what stops it appearing
	 * more than once on screen.
	 *
	 * @param methods one skill's methods, sorted ascending by minLevel
	 */
	private static void shareNotesAcrossBrackets(List<TrainingMethod> methods)
	{
		Map<String, String> firstNote = new HashMap<>();
		for (TrainingMethod method : methods)
		{
			String key = method.getName().toLowerCase(java.util.Locale.ROOT);
			if (method.getNotes() != null && !method.getNotes().isEmpty())
			{
				firstNote.putIfAbsent(key, method.getNotes());
			}
		}
		Map<String, TrainingMethod.Attention> firstAttention = new HashMap<>();
		for (TrainingMethod method : methods)
		{
			if (method.getAttention() != null)
			{
				firstAttention.putIfAbsent(method.getName().toLowerCase(java.util.Locale.ROOT),
					method.getAttention());
			}
		}
		Map<String, List<String>> firstGear = new HashMap<>();
		Map<String, List<String>> firstSupplies = new HashMap<>();
		for (TrainingMethod method : methods)
		{
			String key = method.getName().toLowerCase(java.util.Locale.ROOT);
			if (!method.getGear().isEmpty())
			{
				firstGear.putIfAbsent(key, method.getGear());
			}
			if (!method.getSupplies().isEmpty())
			{
				firstSupplies.putIfAbsent(key, method.getSupplies());
			}
		}
		for (TrainingMethod method : methods)
		{
			String key = method.getName().toLowerCase(java.util.Locale.ROOT);
			method.inheritNotes(firstNote.get(key));
			method.inheritPreparation(firstGear.get(key), firstSupplies.get(key));
			method.inheritAttention(firstAttention.get(key));
		}
	}

	/**
	 * Fills in the kit of every method that names an activity to borrow it from,
	 * then re-shares it down that method's level brackets.
	 * <p>
	 * The activities are a different file with its own database, and this is the
	 * one point where the two meet. A method that already carries its own gear
	 * keeps it: the borrow is a default, not an override.
	 * <p>
	 * A setup's name is dropped on the way in. The activity view has room to
	 * head three kits "Ranged (budget)", "Magic (best in slot)"; a training
	 * option inside a plan is a 240px card that has already spent two lines on
	 * the rate and the note, so it gets one row of pictures. Where an activity
	 * offers several kits they are concatenated in written order, the first
	 * being the one the data recommends.
	 */
	private void linkActivityKit(List<com.nowwhat.model.Activity> activities)
	{
		Map<String, com.nowwhat.model.Activity> byId = new HashMap<>();
		for (com.nowwhat.model.Activity activity : activities)
		{
			byId.put(activity.getId(), activity);
		}

		for (List<TrainingMethod> perSkill : methodsBySkill.values())
		{
			for (TrainingMethod method : perSkill)
			{
				if (method.getActivity() == null)
				{
					continue;
				}
				com.nowwhat.model.Activity source = byId.get(method.getActivity());
				if (source == null)
				{
					log.warn("Method '{}' borrows kit from unknown activity '{}'",
						method.getName(), method.getActivity());
					continue;
				}
				List<String> gear = new ArrayList<>();
				for (com.nowwhat.model.Activity.GearSetup setup : source.getSetups())
				{
					gear.addAll(setup.getItems());
				}
				method.inheritPreparation(gear, source.getSupplies());
			}
			shareNotesAcrossBrackets(perSkill);
		}
	}

	/** Every bundled method, in no particular order. For diagnostics over the whole file. */
	public List<TrainingMethod> getAllMethods()
	{
		List<TrainingMethod> all = new java.util.ArrayList<>();
		for (List<TrainingMethod> perSkill : methodsBySkill.values())
		{
			all.addAll(perSkill);
		}
		return all;
	}

	/** Methods for a skill, sorted ascending by minLevel. Empty list if the skill has no bundled data. */
	public List<TrainingMethod> getMethodsFor(String skill)
	{
		return methodsBySkill.getOrDefault(skill.toUpperCase(), Collections.emptyList());
	}
}

package com.nowwhat.engine;

import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.model.Activity;
import com.nowwhat.model.CombatAchievementTier;
import com.nowwhat.model.Goal;
import com.nowwhat.model.ItemSource;
import com.nowwhat.model.Path;
import com.nowwhat.model.PathStep;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.PrerequisiteChain;
import com.nowwhat.model.Requirement;
import com.nowwhat.model.TrainingMethod;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Turns a Goal into an ordered Path of concrete actions - the piece
 * neither Goal Planner nor QuestPath provide (see README). Delegates to:
 * <ul>
 *   <li>{@link SkillPathPlanner} for SKILL_LEVEL goals and for expanding any
 *       SKILL_LEVEL requirement found along an activity's prerequisite chain</li>
 *   <li>{@link PrerequisiteResolver} for ACTIVITY goals (quests/diaries/etc)</li>
 *   <li>recursive item-source resolution for ITEM_QUANTITY goals, including
 *       crafting recipes that bottom out in other items</li>
 * </ul>
 */
public class PathPlanner
{
	private final PrerequisiteResolver prerequisiteResolver;
	private final TrainingMethodDatabase trainingMethodDatabase;
	private final ItemSourceDatabase itemSourceDatabase;
	private final SkillPathPlanner skillPathPlanner = new SkillPathPlanner();
	private final Map<String, Activity> activitiesById;

	public PathPlanner(List<Activity> allActivities, PrerequisiteResolver prerequisiteResolver,
		TrainingMethodDatabase trainingMethodDatabase, ItemSourceDatabase itemSourceDatabase)
	{
		this.prerequisiteResolver = prerequisiteResolver;
		this.trainingMethodDatabase = trainingMethodDatabase;
		this.itemSourceDatabase = itemSourceDatabase;
		this.activitiesById = new java.util.HashMap<>();
		for (Activity a : allActivities)
		{
			activitiesById.put(a.getId(), a);
		}
	}

	public Path plan(Goal goal, PlayerState state)
	{
		List<PathStep> steps = new ArrayList<>();
		List<String> warnings = new ArrayList<>();
		boolean alreadyComplete;
		boolean requirementsAlreadyMet = false;

		switch (goal.getType())
		{
			case SKILL_LEVEL:
			{
				int current = state.getSkillLevel(goal.getSkillName());
				alreadyComplete = current >= goal.getTargetLevel();
				if (!alreadyComplete)
				{
					steps.addAll(skillPathPlanner.plan(goal.getSkillName(), current, goal.getTargetLevel(),
						trainingMethodDatabase.getMethodsFor(goal.getSkillName()),
						goal.isAllowTickManipulation(), warnings));
				}
				break;
			}
			case ITEM_QUANTITY:
			{
				// Plan for what's still missing, not the full target: asking for 3
				// of something you already have 2 of is a one-item job. Unless the
				// player said not to count what they own - someone who wants the
				// route to an item they already have one of gets told "already
				// done" otherwise, and the goal becomes unaskable.
				ItemSource owned = itemSourceDatabase.getSource(goal.getItemId());
				int have = goal.isCountOwned() && owned != null && owned.getGameItemId() != null
					? state.getOwnedCount(owned.getGameItemId())
					: 0;
				int remaining = goal.getTargetQuantity() - have;

				alreadyComplete = remaining <= 0;
				if (alreadyComplete)
				{
					// Say what made it complete. "Already done" on its own looks
					// like the plugin has no route, when what it means is that the
					// item is already sitting in the bank.
					warnings.add("You already have " + have
						+ ", counting your bank, inventory and gear.");
				}
				if (!alreadyComplete)
				{
					Set<String> visiting = new LinkedHashSet<>();
					// Null when the player asked for the route as if they owned
					// nothing: then no ingredient is counted as owned either.
					Map<Integer, Integer> spent = goal.isCountOwned() ? new java.util.HashMap<>() : null;
					planItem(goal.getItemId(), remaining, state, steps, warnings, visiting,
						goal.isAllowTickManipulation(), spent);
					dropRepeatedPrerequisites(steps);

					if (!state.isBankSnapshotAvailable())
					{
						// Say so rather than quietly telling someone to go buy
						// something that's already sitting in their bank.
						warnings.add("Bank contents unknown \u2014 open your bank once so this "
							+ "can account for what you already have.");
					}
					else if (have > 0)
					{
						warnings.add("You already have " + have + " \u2014 planning for the remaining "
							+ remaining + ".");
					}
				}
				break;
			}
			case ACTIVITY:
			{
				Activity target = activitiesById.get(goal.getActivityId());
				if (target == null)
				{
					warnings.add("Unknown activity id: " + goal.getActivityId());
					return new Path(goal, false, steps, warnings);
				}
				PrerequisiteChain chain = prerequisiteResolver.resolve(target, state);
				alreadyComplete = chain.isAlreadyUnlocked();
				if (!alreadyComplete)
				{
					// Levels before the quests that ask for them. Listed the other
					// way round, the plan opened with a block of quests the player
					// could not start and only then said what to train for them.
					for (Requirement req : chain.getStandaloneRequirements())
					{
						expandStandaloneRequirement(req, state, steps, warnings, goal.isAllowTickManipulation());
					}
					for (Activity prereq : chain.getRequiredActivitiesInOrder())
					{
						steps.add(new PathStep(stepTypeFor(prereq.getCategory()), prereq.getName(),
							prereq.getCategory() + (prereq.getDescription() != null ? " \u2014 " + prereq.getDescription() : ""),
							prereq.getWikiUrl()));
					}
					warnings.addAll(chain.getUnresolvedReferences());
					planRecommended(target, chain.getStandaloneRequirements(), state, steps, warnings,
						goal.isAllowTickManipulation());
					// A Combat Achievement tier is a points total, not a set of
					// requirements, so "you meet every requirement" was true and
					// useless: the combat level was the only thing it checked.
					// What stands between the player and the tier is the points,
					// so the points become the step.
					CombatAchievementTier tier = CombatAchievementTier.fromKey(target.getId());
					if (tier != null)
					{
						steps.add(combatAchievementPointsStep(tier, state.getCombatAchievementPoints()));
					}
					// Nothing was produced by the chain walk, so every requirement is
					// already satisfied - the activity just isn't the kind of thing
					// that gets marked "done" (a boss, a minigame, an unlock).
					requirementsAlreadyMet = steps.isEmpty() && warnings.isEmpty();
					steps.add(new PathStep(stepTypeFor(target.getCategory()), target.getName(),
						"Target: " + target.getCategory(), target.getWikiUrl(), true));
				}
				break;
			}
			case BASE_STATS:
			{
				List<Shortfall> shortfalls = new ArrayList<>();
				for (String skill : PLANNABLE_SKILLS)
				{
					int current = state.getSkillLevel(skill);
					if (current < goal.getTargetLevel())
					{
						shortfalls.add(new Shortfall(skill, current, goal.getTargetLevel(),
							XpTable.xpBetween(current, goal.getTargetLevel())));
					}
				}
				// Hitpoints is never planned - there is no going and training it -
				// but "every skill" names it, so it cannot be passed over in
				// silence either. With it left out altogether, an account with 60
				// Hitpoints asking for 70 in everything was told "already done".
				int hitpoints = state.getSkillLevel("HITPOINTS");
				boolean hitpointsShort = hitpoints < goal.getTargetLevel();
				alreadyComplete = shortfalls.isEmpty() && !hitpointsShort;
				if (hitpointsShort)
				{
					warnings.add("Hitpoints is " + hitpoints + ", below " + goal.getTargetLevel()
						+ ". There is no step for it: it rises on its own as you train "
						+ "the combat skills.");
				}
				if (!shortfalls.isEmpty())
				{
					// Cheapest first. The player asked for a floor, not an order,
					// so the order is ours to choose - and the one that gets the
					// most skills over the line soonest is the one that keeps the
					// list visibly shrinking.
					shortfalls.sort(Comparator.comparingLong(sf -> sf.xp));
					long total = 0;
					for (Shortfall sf : shortfalls)
					{
						total += sf.xp;
					}
					warnings.add(shortfalls.size() + " skill"
						+ (shortfalls.size() == 1 ? " is" : "s are") + " below "
						+ goal.getTargetLevel() + ", "
						+ XpTable.formatXp(total) + " xp in all \u2014 cheapest first.");
					for (Shortfall sf : shortfalls)
					{
						steps.addAll(skillPathPlanner.plan(sf.skill, sf.from, sf.to,
							trainingMethodDatabase.getMethodsFor(sf.skill),
							goal.isAllowTickManipulation(), warnings));
					}
				}
				break;
			}
			case TOTAL_LEVEL:
			{
				// Every skill counts towards the total, but only a skill we can
				// describe how to train is a candidate to take levels from.
				// Sailing is the case that proved it: its early levels are the
				// cheapest in the game, so the greedy took all twelve from it
				// and produced a plan with no steps in it at all.
				Map<String, Integer> levels = new LinkedHashMap<>();
				List<String> untrainable = new ArrayList<>();
				int current = 0;
				// Levels the plan cannot add to: they count as they stand.
				int fixed = state.getSkillLevel("HITPOINTS");
				for (String skill : PLANNABLE_SKILLS)
				{
					int level = state.getSkillLevel(skill);
					current += level;
					if (hasTrainingData(skill))
					{
						levels.put(skill, level);
					}
					else
					{
						untrainable.add(capitalize(skill));
						fixed += level;
					}
				}
				// Hitpoints counts towards the total but cannot be chosen: it
				// rises out of combat xp on its own. Counting it and then
				// planning it would be telling the player to go and train
				// something there is no way to go and train.
				current += state.getSkillLevel("HITPOINTS");

				int needed = goal.getTargetLevel() - current;
				alreadyComplete = needed <= 0;
				if (alreadyComplete)
				{
					warnings.add("Your total level is already " + current + ".");
					break;
				}

				if (!untrainable.isEmpty())
				{
					warnings.add("No training data for " + String.join(", ", untrainable)
						+ ", so no levels were planned there \u2014 they still count "
						+ "towards your total.");
				}

				// What the plan itself can reach: 99 in everything it can train,
				// and the rest where it stands. Counting Hitpoints as 99 and the
				// skills with no data as nothing made this fire late or not at all.
				int ceiling = levels.size() * 99 + fixed;
				if (goal.getTargetLevel() > ceiling)
				{
					warnings.add("The skills this can plan top out at a total of " + ceiling
						+ " with the rest where they are now, so " + goal.getTargetLevel()
						+ " is out of this plan's reach.");
				}

				// Take the cheapest next level, over and over. Each skill's
				// levels get dearer as it climbs, so repeatedly taking the
				// cheapest available one is also the cheapest set of that many
				// levels overall - there is no arrangement that beats it.
				Map<String, Integer> targets = new LinkedHashMap<>(levels);
				int taken = 0;
				while (taken < needed)
				{
					String best = null;
					long bestCost = Long.MAX_VALUE;
					for (Map.Entry<String, Integer> entry : targets.entrySet())
					{
						int at = entry.getValue();
						if (at >= 99)
						{
							continue;
						}
						long cost = XpTable.xpForLevel(at + 1) - Math.max(
							XpTable.xpForLevel(at), state.getSkillXp(entry.getKey()));
						if (cost < bestCost)
						{
							bestCost = cost;
							best = entry.getKey();
						}
					}
					if (best == null)
					{
						warnings.add("Every skill with training data is already 99 \u2014 "
							+ (needed - taken) + " level"
							+ (needed - taken == 1 ? "" : "s") + " short of "
							+ goal.getTargetLevel() + ".");
						break;
					}
					targets.put(best, targets.get(best) + 1);
					taken++;
				}

				List<Shortfall> picked = new ArrayList<>();
				for (Map.Entry<String, Integer> entry : targets.entrySet())
				{
					int from = levels.get(entry.getKey());
					if (entry.getValue() > from)
					{
						picked.add(new Shortfall(entry.getKey(), from, entry.getValue(),
							XpTable.xpBetween(from, entry.getValue())));
					}
				}
				picked.sort(Comparator.comparingLong(sf -> sf.xp));

				long total = 0;
				for (Shortfall sf : picked)
				{
					total += sf.xp;
				}
				warnings.add(taken + " level" + (taken == 1 ? "" : "s")
					+ " from " + current + " to " + (current + taken) + ", "
					+ XpTable.formatXp(total) + " xp in all \u2014 the cheapest "
					+ "next level each time.");

				for (Shortfall sf : picked)
				{
					steps.addAll(skillPathPlanner.plan(sf.skill, sf.from, sf.to,
						trainingMethodDatabase.getMethodsFor(sf.skill),
						goal.isAllowTickManipulation(), warnings));
				}
				break;
			}
			default:
				warnings.add("Unsupported goal type: " + goal.getType());
				alreadyComplete = false;
		}

		return new Path(goal, alreadyComplete, steps, warnings, requirementsAlreadyMet);
	}

	/**
	 * The skills a plan can actually send someone to train.
	 * <p>
	 * Hitpoints is absent on purpose. It counts towards a total level and it is
	 * in the game's skill list, but there is no such thing as going and
	 * training it - it rises out of combat xp, which is why its one entry in
	 * methods.json has no rate and says so. A total level plan that said
	 * "Hitpoints 70 to 73" would be telling the player to do something that
	 * cannot be done.
	 * <p>
	 * Sailing is present. There is no Sailing data yet, so asking for it
	 * produces SkillPathPlanner's "no training method data" warning - which is
	 * the honest answer to "get every skill to 80", and better than quietly
	 * leaving a skill out of a goal that said "every".
	 */
	private static final List<String> PLANNABLE_SKILLS = java.util.Collections.unmodifiableList(
		java.util.Arrays.asList(
			"ATTACK", "DEFENCE", "STRENGTH", "RANGED", "PRAYER", "MAGIC",
			"COOKING", "WOODCUTTING", "FLETCHING", "FISHING", "FIREMAKING", "CRAFTING",
			"SMITHING", "MINING", "HERBLORE", "AGILITY", "THIEVING", "SLAYER", "FARMING",
			"RUNECRAFT", "HUNTER", "CONSTRUCTION", "SAILING"));

	/**
	 * Whether methods.json has anything at all to say about training this.
	 * <p>
	 * Deliberately "any method", not "any method with an xp/hr". Slayer and
	 * Farming are recorded without rates on purpose - Slayer comes a task at a
	 * time and Farming a run at a time, and an hourly figure would be a
	 * fiction - but "do Slayer tasks" is still a real answer to "where do I get
	 * a level". Requiring a rate excluded both of them from total level plans,
	 * which is a worse answer than one without a time estimate on it.
	 */
	private boolean hasTrainingData(String skill)
	{
		return !trainingMethodDatabase.getMethodsFor(skill).isEmpty();
	}

	private static String capitalize(String skill)
	{
		return skill.charAt(0) + skill.substring(1).toLowerCase(java.util.Locale.ROOT);
	}

	/** One skill that is short of where a goal needs it, and what closing that costs. */
	private static final class Shortfall
	{
		private final String skill;
		private final int from;
		private final int to;
		private final long xp;

		private Shortfall(String skill, int from, int to, long xp)
		{
			this.skill = skill;
			this.from = from;
			this.to = to;
			this.xp = xp;
		}
	}

	/**
	 * A SKILL_LEVEL requirement gets expanded into real training steps via
	 * SkillPathPlanner. Everything else (BOSS_KC, QUEST_POINTS, COMBAT_LEVEL,
	 * COMBAT_ACHIEVEMENT_TIER) has no further data-driven expansion in this
	 * scaffold, so it's surfaced as an INFO step using the same description
	 * logic the panel already had, plus the requirement's own `hint` field
	 * if one was authored for it.
	 */
	/**
	 * Quests and diary tiers get their own step types because the panel hands
	 * both off to Quest Helper rather than describing how to do them; everything
	 * else is a plain activity.
	 */
	private static PathStep.Type stepTypeFor(Activity.Category category)
	{
		switch (category)
		{
			case QUEST:
				return PathStep.Type.DO_QUEST;
			case DIARY:
				return PathStep.Type.DO_DIARY;
			default:
				return PathStep.Type.DO_ACTIVITY;
		}
	}

	/**
	 * The stats the wiki recommends for the goal, as steps marked recommended.
	 * <p>
	 * The suggestion list already holds a fight back until these are met, and
	 * says "Recommended 85 Ranged, you have 80" beside it. The plan knew nothing
	 * about them, so clicking that same suggestion answered "you already meet
	 * every requirement" - two parts of one panel disagreeing about one boss.
	 * <p>
	 * A recommended level picks up where a required one leaves off: 70 Ranged
	 * needed and 85 recommended is one stretch to 70 and a recommended one from
	 * 70 to 85, not the first stretch planned twice.
	 */
	private void planRecommended(Activity target, List<Requirement> required, PlayerState state,
		List<PathStep> steps, List<String> warnings, boolean allowTickManipulation)
	{
		for (Requirement rec : target.getRecommended())
		{
			if (RequirementEvaluator.isMet(rec, state))
			{
				continue;
			}
			List<PathStep> extra = new ArrayList<>();
			if (rec.getType() == Requirement.Type.SKILL_LEVEL)
			{
				int from = state.getSkillLevel(rec.getValue());
				for (Requirement hard : required)
				{
					if (hard.getType() == Requirement.Type.SKILL_LEVEL
						&& hard.getValue().equalsIgnoreCase(rec.getValue()))
					{
						from = Math.max(from, hard.getThreshold());
					}
				}
				if (from >= rec.getThreshold())
				{
					continue;
				}
				extra.addAll(skillPathPlanner.plan(rec.getValue(), from, rec.getThreshold(),
					trainingMethodDatabase.getMethodsFor(rec.getValue()), allowTickManipulation, warnings));
			}
			else
			{
				if (required.stream().anyMatch(hard -> sameRequirement(rec, hard)))
				{
					continue;
				}
				expandStandaloneRequirement(rec, state, extra, warnings, allowTickManipulation);
			}
			for (PathStep step : extra)
			{
				steps.add(step.asRecommended());
			}
		}
	}

	private void expandStandaloneRequirement(Requirement req, PlayerState state, List<PathStep> steps,
		List<String> warnings, boolean allowTickManipulation)
	{
		if (req.getType() == Requirement.Type.SKILL_LEVEL)
		{
			int current = state.getSkillLevel(req.getValue());
			if (current >= req.getThreshold())
			{
				return; // already met, nothing to plan
			}
			List<PathStep> skillSteps = skillPathPlanner.plan(req.getValue(), current, req.getThreshold(),
				trainingMethodDatabase.getMethodsFor(req.getValue()), allowTickManipulation, warnings);
			if (skillSteps.isEmpty() && req.getHint() != null)
			{
				// Fall back to the authored hint if we have no structured method data for this skill.
				steps.add(new PathStep(PathStep.Type.TRAIN_SKILL,
					req.getValue() + " to " + req.getThreshold(), req.getHint(), null));
			}
			else
			{
				steps.addAll(skillSteps);
			}
			return;
		}

		if (req.getType() == Requirement.Type.COMBINED_SKILL_LEVEL)
		{
			String[] skillNames = req.getValue().split(",");
			int combinedCurrent = 0;
			for (String s : skillNames)
			{
				combinedCurrent += state.getSkillLevel(s.trim());
			}
			if (combinedCurrent >= req.getThreshold())
			{
				return; // already met
			}
			// Deliberately not decomposed into per-skill training steps: raising
			// Attack vs Strength vs splitting between them are all valid ways to
			// close the gap, and there's no basis here to prefer one split over
			// another the way there is for a single-skill requirement - that
			// would need an explicit player preference this scaffold doesn't
			// collect yet, so it's surfaced as information instead of a plan.
			String detail = "Currently " + combinedCurrent + "/" + req.getThreshold() + " combined. Raise "
				+ String.join(" and/or ", skillNames) + " in whatever split suits you"
				+ (req.getHint() != null ? " \u2014 " + req.getHint() : "");
			steps.add(new PathStep(PathStep.Type.INFO, describeRequirement(req), detail, null));
			return;
		}

		if (req.getType() == Requirement.Type.ANY_OF)
		{
			// Not recursively expanded into full sub-chains per branch (that's
			// a meaningfully bigger undertaking - each branch could itself
			// need its own quest/skill chain resolved). Presented as an
			// explicit choice instead, same philosophy as multiple training
			// methods: don't silently collapse to one branch when the data
			// doesn't give a basis to prefer one over another.
			List<PathStep.Option> options = new ArrayList<>();
			for (Requirement child : req.getAnyOf())
			{
				options.add(new PathStep.Option(describeRequirement(child), child.getHint(), null));
			}
			if (!options.isEmpty())
			{
				steps.add(new PathStep(PathStep.Type.INFO, "Any ONE of the following", options));
			}
			return;
		}

		steps.add(new PathStep(PathStep.Type.INFO, describeRequirement(req), req.getHint(), null));
	}

	/**
	 * How many Combat Achievement points stand between the player and a tier,
	 * and what that means in tasks.
	 * <p>
	 * The task count is a floor, not a forecast: it assumes every point comes
	 * from the tier's own tasks. Lower-tier tasks still count toward the total,
	 * and they are usually the quicker points, which the detail says.
	 */
	static PathStep combatAchievementPointsStep(CombatAchievementTier tier, int points)
	{
		String where = "Find them in the Character Summary tab, then Combat Achievements, "
			+ "filtered to " + tier.getLabel() + " and Incomplete.";
		if (points < 0)
		{
			return new PathStep(PathStep.Type.DO_ACTIVITY,
				"Reach " + format(tier.getPointsToUnlock()) + " Combat Achievement points",
				tier.getLabel() + " tasks are worth " + tier.getPointsPerTask() + " points each, and "
					+ "tasks from any easier tier still count toward the total. "
					+ "Log in for your current total. " + where,
				tier.getTaskListUrl());
		}

		int missing = tier.getPointsToUnlock() - points;
		if (missing <= 0)
		{
			return new PathStep(PathStep.Type.DO_ACTIVITY,
				"Claim the " + tier.getLabel() + " tier rewards",
				"You have " + format(points) + " points, past the " + format(tier.getPointsToUnlock())
					+ " this tier needs. Speak to Ghommal at the Warriors' Guild for the rewards.",
				"https://oldschool.runescape.wiki/w/Combat_Achievements#Rewards");
		}

		int tasks = (missing + tier.getPointsPerTask() - 1) / tier.getPointsPerTask();
		return new PathStep(PathStep.Type.DO_ACTIVITY,
			"Earn " + format(missing) + " more Combat Achievement points",
			"You have " + format(points) + " of the " + format(tier.getPointsToUnlock()) + " needed. "
				+ "That is " + tasks + " " + tier.getLabel() + " task" + (tasks == 1 ? "" : "s")
				+ " at " + tier.getPointsPerTask() + " points each (the tier has " + tier.getTaskCount()
				+ "), or more tasks from easier tiers you skipped, which are often the faster points. "
				+ where,
			tier.getTaskListUrl());
	}

	/** True when {@code b} already covers {@code a}: same kind, same skill, at least as high. */
	/**
	 * Which fight an item drops from, as a key two pieces of the same kit share,
	 * or null for anything that is not a plain drop. Keyed on the drop's own
	 * "from" text as well as its boss page, so Hydras and the Alchemical Hydra
	 * - which share a gear page - stay separate trips.
	 */
	private String fightOf(String itemId)
	{
		ItemSource part = itemSourceDatabase.getSource(itemId);
		if (part == null || part.getType() != ItemSource.SourceType.MONSTER_DROP
			|| part.getDetail() == null)
		{
			return null;
		}
		return part.getDetail() + "|" + part.getPreparationFrom();
	}

	/**
	 * Several drops from the same fight, as one kill step: "Hydra's eye, Hydra's
	 * fang and Hydra's heart from Hydras". Each piece's requirement is planned
	 * once, however many pieces share it.
	 */
	private void planDropsTogether(List<ItemSource.Ingredient> parts, int quantity, PlayerState state,
		List<PathStep> steps, List<String> warnings, boolean allowTickManipulation)
	{
		List<ItemSource> sources = new ArrayList<>();
		List<Requirement> planned = new ArrayList<>();
		for (ItemSource.Ingredient ingredient : parts)
		{
			ItemSource part = itemSourceDatabase.getSource(ingredient.getItemId());
			sources.add(part);
			Requirement req = part.getSkillRequirement();
			if (req != null && planned.stream().noneMatch(done -> sameRequirement(req, done)))
			{
				expandStandaloneRequirement(req, state, steps, warnings, allowTickManipulation);
				planned.add(req);
			}
		}

		List<String> names = new ArrayList<>();
		for (ItemSource part : sources)
		{
			names.add(part.getDisplayName());
		}
		ItemSource first = sources.get(0);
		String title = joinNames(names) + " from " + first.getDetail();

		// Each piece's own average, rather than one total. The pieces roll
		// independently, so adding their averages together would overstate the
		// trip, and the honest figure for "all of them" depends on the drop
		// table in ways a single number would hide.
		String unit = first.getAttemptUnit();
		boolean sameRate = sources.stream().allMatch(s -> s.getEstimatedKc() != null
			&& s.getEstimatedKc().equals(first.getEstimatedKc()))
			&& parts.stream().allMatch(p -> p.getQuantity() == parts.get(0).getQuantity());
		String kcNote;
		if (sameRate)
		{
			kcNote = "~" + format(first.getEstimatedKc() * parts.get(0).getQuantity() * quantity)
				+ " " + unit + " on average for each piece \u2014 rough average, not a guaranteed rate";
		}
		else
		{
			List<String> each = new ArrayList<>();
			for (int i = 0; i < sources.size(); i++)
			{
				ItemSource part = sources.get(i);
				each.add(part.getEstimatedKc() == null
					? part.getDisplayName() + " rate unknown"
					: "~" + format(part.getEstimatedKc() * parts.get(i).getQuantity() * quantity)
						+ " " + unit + " for " + part.getDisplayName());
			}
			kcNote = String.join(", ", each) + " \u2014 rough averages, not guaranteed rates";
		}

		Activity fight = first.getPreparationFrom() == null
			? null
			: activitiesById.get(first.getPreparationFrom());
		steps.add(new PathStep(PathStep.Type.KILL_BOSS, title, withNote(kcNote, first),
			fight != null && fight.getWikiUrl() != null ? fight.getWikiUrl() : first.getWikiUrl()));
	}

	/**
	 * Removes a prerequisite the plan already asked for. A recipe is planned one
	 * ingredient at a time, and two ingredients behind the same quest or the
	 * same Slayer level each asked for it, so the plan said "train Slayer to
	 * 85" twice. Only prerequisites are folded: two "buy" or "kill" steps for
	 * different ingredients are different errands even when they read alike.
	 */
	static void dropRepeatedPrerequisites(List<PathStep> steps)
	{
		Set<String> seen = new java.util.HashSet<>();
		steps.removeIf(step ->
		{
			if (step.getType() == PathStep.Type.ACQUIRE_ITEM || step.getType() == PathStep.Type.KILL_BOSS)
			{
				return false;
			}
			String key = step.getType() + "|" + step.getTitle() + "|" + step.getDetail()
				+ "|" + step.getSkill() + "|" + step.getLevelFrom() + "|" + step.getLevelTo();
			return !seen.add(key);
		});
	}

	/**
	 * How many of an ingredient still have to be got, once what the player owns
	 * is taken off, with a line saying so whenever something was.
	 *
	 * @param spent what earlier ingredients have already claimed, per game item
	 *              id, so a part two recipes share is not counted as owned
	 *              twice; null to count nothing as owned
	 */
	private int stillNeeded(ItemSource.Ingredient ingredient, int wanted, PlayerState state,
		Map<Integer, Integer> spent, List<String> warnings)
	{
		ItemSource source = itemSourceDatabase.getSource(ingredient.getItemId());
		if (spent == null || source == null || source.getGameItemId() == null)
		{
			return wanted;
		}
		int id = source.getGameItemId();
		int use = Math.min(wanted, state.getOwnedCount(id) - spent.getOrDefault(id, 0));
		if (use <= 0)
		{
			return wanted;
		}
		spent.merge(id, use, Integer::sum);
		if (use == wanted)
		{
			warnings.add("You already have " + (wanted == 1 ? "the " : "the " + format(wanted) + " ")
				+ source.getDisplayName() + " this needs, so that is left out.");
		}
		else
		{
			warnings.add("You already have " + format(use) + " of the " + format(wanted) + " "
				+ source.getDisplayName() + " this needs \u2014 planning for the other "
				+ format(wanted - use) + ".");
		}
		return wanted - use;
	}

	/** The kill-count estimate, then how the drop works, where the data says. */
	private static String withNote(String kcNote, ItemSource source)
	{
		return source.getNote() == null ? kcNote : kcNote + ". " + source.getNote();
	}

	/** "a", "a and b", "a, b and c". */
	static String joinNames(List<String> names)
	{
		if (names.size() <= 1)
		{
			return names.isEmpty() ? "" : names.get(0);
		}
		return String.join(", ", names.subList(0, names.size() - 1))
			+ " and " + names.get(names.size() - 1);
	}

	private static boolean sameRequirement(Requirement a, Requirement b)
	{
		return b != null && a.getType() == b.getType()
			&& java.util.Objects.equals(a.getValue(), b.getValue())
			&& b.getThreshold() >= a.getThreshold();
	}

	private static String format(int n)
	{
		return String.format(java.util.Locale.ROOT, "%,d", n);
	}

	/** Shortfall human-readable label for a single requirement, used both standalone and inside ANY_OF choices. */
	private String describeRequirement(Requirement req)
	{
		switch (req.getType())
		{
			case SKILL_LEVEL:
				return req.getValue() + " level " + req.getThreshold();
			case BOSS_KC:
				return req.getValue() + ": " + req.getThreshold() + " kills";
			case QUEST_POINTS:
				return req.getThreshold() + " Quest Points";
			case COMBAT_LEVEL:
				return "Combat level " + req.getThreshold();
			case COMBAT_ACHIEVEMENT_TIER:
				return "Combat Achievements: " + req.getValue() + " tier";
			case QUEST_COMPLETE:
				return "Complete " + req.getValue();
			case DIARY_COMPLETE:
				return req.getValue() + " diary";
			case COMBINED_SKILL_LEVEL:
				return req.getThreshold() + " combined " + String.join("+", req.getValue().split(","));
			default:
				return req.getType() + " " + req.getValue() + " " + req.getThreshold();
		}
	}

	/**
	 * Recursively resolves how to obtain `quantity` of `itemId`, expanding
	 * CRAFT recipes into their ingredients (and any skill requirement the
	 * craft needs) until everything bottoms out in a GE_BUY / SHOP /
	 * MONSTER_DROP leaf, or we give up with a warning.
	 */
	private void planItem(String itemId, int quantity, PlayerState state, List<PathStep> steps,
		List<String> warnings, Set<String> visiting, boolean allowTickManipulation,
		Map<Integer, Integer> spent)
	{
		String key = itemId.toUpperCase();
		if (visiting.contains(key))
		{
			warnings.add("Circular crafting recipe detected involving " + itemId);
			return;
		}

		ItemSource source = itemSourceDatabase.getSource(itemId);
		if (source == null)
		{
			warnings.add("No source data for item: " + itemId + " \u2014 check the wiki manually.");
			return;
		}

		visiting.add(key);

		// Any source can gate on a requirement, not just a crafting recipe: you
		// cannot farm a raid drop without the stats to survive the raid. Expanded
		// before the acquisition step so the prerequisite reads first.
		if (source.getSkillRequirement() != null)
		{
			expandStandaloneRequirement(source.getSkillRequirement(), state, steps, warnings, allowTickManipulation);
		}

		switch (source.getType())
		{
			case GE_BUY:
				steps.add(new PathStep(PathStep.Type.ACQUIRE_ITEM,
					"Buy " + quantity + "x " + source.getDisplayName(),
					"Grand Exchange" + (source.getDetail() != null ? " \u2014 " + source.getDetail() : ""),
					source.getWikiUrl()));
				break;
			case SHOP:
			{
				// A points shop that only quotes its price is a dead end. "250
				// points" says nothing about where points come from, how long
				// they take or what to bring, and the player is left to go and
				// find out somewhere else - which is the whole thing this panel
				// is for. Where the currency has an activity behind it, that
				// activity becomes a step in its own right, ahead of the
				// purchase, carrying its own description and kit.
				String earns = source.getCurrencyFrom();
				Activity earner = earns == null ? null : activitiesById.get(earns);
				if (earner != null)
				{
					// The earner's own entry requirements come first. The herb
					// sack only asks for 58 Herblore, but its points come from
					// Tithe Farm, which asks for 34 Farming - and without this the
					// plan sent someone at 20 Farming to a minigame they could not
					// enter. One the item already asked for is not repeated.
					for (Requirement entry : earner.getRequirements())
					{
						if (!RequirementEvaluator.isMet(entry, state)
							&& !sameRequirement(entry, source.getSkillRequirement()))
						{
							expandStandaloneRequirement(entry, state, steps, warnings, allowTickManipulation);
						}
					}
					steps.add(new PathStep(stepTypeFor(earner.getCategory()), earner.getName(),
						earner.getCategory() + (earner.getDescription() != null
							? " \u2014 " + earner.getDescription()
							: ""),
						earner.getWikiUrl()));
				}
				else if (earns != null)
				{
					warnings.add("Unknown activity id: " + earns);
				}
				steps.add(new PathStep(PathStep.Type.ACQUIRE_ITEM,
					"Buy " + quantity + "x " + source.getDisplayName(),
					"Shop: " + source.getDetail(), source.getWikiUrl()));
				break;
			}
			case MONSTER_DROP:
			{
				String kcNote = source.getEstimatedKc() != null
					? ("~" + String.format(java.util.Locale.ROOT, "%,d", source.getEstimatedKc() * quantity)
					+ " " + source.getAttemptUnit() + " for " + quantity
					+ (quantity == 1 ? " drop" : " drops") + " \u2014 rough average, not a guaranteed rate")
					: "Drop rate unknown \u2014 check the wiki's droptable page";
				steps.add(new PathStep(PathStep.Type.KILL_BOSS,
					source.getDisplayName() + " from " + source.getDetail(),
					withNote(kcNote, source), source.getWikiUrl()));
				break;
			}
			case QUEST_REWARD:
				steps.add(new PathStep(PathStep.Type.DO_QUEST,
					"Complete quest for " + source.getDisplayName(),
					source.getDetail(), source.getWikiUrl()));
				break;
			case CRAFT:
			{
				// Pieces that drop from the same fight are one trip, not three. A
				// brimstone ring is the eye, fang and heart of the same hydra, and
				// planned one ingredient at a time it read as "kill hydras" three
				// times over, each with its own copy of the Slayer requirement.
				//
				// What is already owned comes off first. Only the finished item
				// used to be checked against the bank, so someone holding two of
				// a ring's three parts was sent to get all three again.
				List<ItemSource.Ingredient> toGet = new ArrayList<>();
				for (ItemSource.Ingredient ingredient : source.getIngredients())
				{
					int left = stillNeeded(ingredient, ingredient.getQuantity() * quantity, state, spent,
						warnings);
					if (left > 0)
					{
						toGet.add(new ItemSource.Ingredient(ingredient.getItemId(), left));
					}
				}
				Map<String, List<ItemSource.Ingredient>> byFight = new LinkedHashMap<>();
				for (ItemSource.Ingredient ingredient : toGet)
				{
					String fight = fightOf(ingredient.getItemId());
					if (fight != null)
					{
						byFight.computeIfAbsent(fight, f -> new ArrayList<>()).add(ingredient);
					}
				}
				Set<String> plannedFights = new LinkedHashSet<>();
				for (ItemSource.Ingredient ingredient : toGet)
				{
					String fight = fightOf(ingredient.getItemId());
					List<ItemSource.Ingredient> together = fight == null ? null : byFight.get(fight);
					if (together != null && together.size() > 1)
					{
						if (plannedFights.add(fight))
						{
							// The quantities in toGet are already totals.
							planDropsTogether(together, 1, state, steps, warnings,
								allowTickManipulation);
						}
						continue;
					}
					planItem(ingredient.getItemId(), ingredient.getQuantity(), state, steps,
						warnings, visiting, allowTickManipulation, spent);
				}
				steps.add(new PathStep(PathStep.Type.ACQUIRE_ITEM,
					"Craft " + quantity + "x " + source.getDisplayName(),
					source.getDetail(), source.getWikiUrl()));
				break;
			}
			default:
				warnings.add("Unknown source type for " + itemId);
		}

		visiting.remove(key);
	}
}

package com.nowwhat.engine;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.PrerequisiteChain;
import com.nowwhat.model.Requirement;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Answers "what do I need to do before I can do X" by walking the
 * requirement graph backwards from a target activity.
 * <p>
 * The key idea: an unmet QUEST_COMPLETE or DIARY_COMPLETE requirement is
 * itself just another Activity in the database (a quest is an Activity with
 * category QUEST, a diary tier is an Activity with category DIARY, and each
 * of THOSE can have its own requirements, including earlier quests or
 * diary tiers). So resolving "what unlocks Zulrah" means recursively
 * resolving "what unlocks Regicide", which might mean resolving "what
 * unlocks [some earlier quest]", and so on, until everything left is a
 * plain skill level / KC / combat level with nothing further to chain to.
 * <p>
 * This depends entirely on activities.json actually containing an entry for
 * every quest/diary tier referenced elsewhere as a requirement - if a quest
 * requirement points at a quest name with no matching Activity entry, that
 * reference is reported back as "unresolved" rather than silently dropped,
 * so gaps in the content database are visible instead of hidden.
 */
public class PrerequisiteResolver
{
	private final Map<String, Activity> questsByName = new HashMap<>();
	private final Map<String, Activity> diaryTiersById = new HashMap<>();
	private final Map<String, Activity> combatAchievementTiersById = new HashMap<>();

	public PrerequisiteResolver(List<Activity> allActivities)
	{
		for (Activity activity : allActivities)
		{
			if (activity.getCategory() == Activity.Category.QUEST)
			{
				questsByName.put(activity.getName(), activity);
			}
			else if (activity.getCategory() == Activity.Category.DIARY)
			{
				diaryTiersById.put(activity.getId().toUpperCase(), activity);
			}
			else if (activity.getCategory() == Activity.Category.COMBAT_ACHIEVEMENT)
			{
				combatAchievementTiersById.put(activity.getId().toUpperCase(), activity);
			}
		}
	}

	public PrerequisiteChain resolve(Activity target, PlayerState state)
	{
		if (RequirementEvaluator.isAlreadyDone(target, state))
		{
			return new PrerequisiteChain(target, true, new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
		}

		List<Activity> orderedSteps = new ArrayList<>();
		List<Requirement> standalone = new ArrayList<>();
		List<String> unresolved = new ArrayList<>();
		Set<String> visiting = new LinkedHashSet<>();
		Set<String> visited = new LinkedHashSet<>();

		walk(target, state, orderedSteps, standalone, unresolved, visiting, visited, true);

		return new PrerequisiteChain(target, false, orderedSteps, dedupeRequirements(standalone), unresolved);
	}

	/**
	 * @param isTarget true only on the initial call, so the target itself
	 *                 isn't duplicated into its own prerequisite list.
	 */
	private void walk(Activity activity, PlayerState state, List<Activity> orderedSteps,
		List<Requirement> standalone, List<String> unresolved, Set<String> visiting, Set<String> visited,
		boolean isTarget)
	{
		if (visited.contains(activity.getId()))
		{
			return;
		}
		if (visiting.contains(activity.getId()))
		{
			// Circular requirement in the content data - stop rather than
			// recurse forever. This should never legitimately happen; if it
			// does, activities.json has a data error worth fixing.
			unresolved.add("(circular reference detected involving " + activity.getName() + ")");
			return;
		}

		visiting.add(activity.getId());

		for (Requirement req : activity.getRequirements())
		{
			if (RequirementEvaluator.isMet(req, state))
			{
				continue;
			}

			switch (req.getType())
			{
				case QUEST_COMPLETE:
				{
					Activity questPrereq = questsByName.get(req.getValue());
					if (questPrereq != null)
					{
						walk(questPrereq, state, orderedSteps, standalone, unresolved, visiting, visited, false);
					}
					else
					{
						unresolved.add("Quest: " + req.getValue() + " (not in activity database)");
					}
					break;
				}
				case DIARY_COMPLETE:
				{
					Activity diaryPrereq = diaryTiersById.get(req.getValue().toUpperCase());
					if (diaryPrereq != null)
					{
						walk(diaryPrereq, state, orderedSteps, standalone, unresolved, visiting, visited, false);
					}
					else
					{
						unresolved.add("Diary tier: " + req.getValue() + " (not in activity database)");
					}
					break;
				}
				case COMBAT_ACHIEVEMENT_TIER:
				{
					// A tier is itself an activity, the same way a diary tier is,
					// so "Master needs Elite" plans Elite as a step rather than
					// printing the raw "CA_ELITE" key as a shortfall.
					Activity tierPrereq = combatAchievementTiersById.get(req.getValue().toUpperCase());
					if (tierPrereq != null)
					{
						walk(tierPrereq, state, orderedSteps, standalone, unresolved, visiting, visited, false);
					}
					else
					{
						unresolved.add("Combat Achievement tier: " + req.getValue() + " (not in activity database)");
					}
					break;
				}
				default:
					// SKILL_LEVEL, BOSS_KC, QUEST_POINTS, COMBAT_LEVEL,
					// ANY_OF: nothing further to chain
					// to here - PathPlanner expands each of these appropriately
					// (training steps, or a presented choice for ANY_OF).
					standalone.add(req);
			}
		}

		visiting.remove(activity.getId());
		visited.add(activity.getId());

		if (!isTarget)
		{
			orderedSteps.add(activity);
		}
	}

	private List<Requirement> dedupeRequirements(List<Requirement> requirements)
	{
		// One entry per skill/KC however many quests along the chain ask for it,
		// and that entry is the highest ask. Keeping the first one met instead
		// planned Agility to 10 for Desert Treasure II, because The Dig Site
		// wants 10 and is walked before Secrets of the North, which wants 69.
		// The entry stays where the first ask was, so the order still follows
		// the chain.
		List<Requirement> result = new ArrayList<>();
		Map<String, Integer> indexByKey = new HashMap<>();
		for (Requirement req : requirements)
		{
			if (req.getType() == Requirement.Type.ANY_OF)
			{
				// A choice has no value to key on, and two different choices
				// are two different gates - never folded into one.
				if (!result.contains(req))
				{
					result.add(req);
				}
				continue;
			}
			String key = req.getType() + ":" + req.getValue();
			Integer at = indexByKey.get(key);
			if (at == null)
			{
				indexByKey.put(key, result.size());
				result.add(req);
			}
			else if (req.getThreshold() > result.get(at).getThreshold())
			{
				result.set(at, req);
			}
		}
		return result;
	}
}

package com.nowwhat.engine;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.Requirement;

/**
 * Single source of truth for "is this requirement currently met". Used by
 * both SuggestionEngine (what can I do now) and PrerequisiteResolver
 * (what do I need to do to unlock X) so the two never disagree.
 */
public final class RequirementEvaluator
{
	private RequirementEvaluator()
	{
	}

	public static boolean isMet(Requirement req, PlayerState state)
	{
		switch (req.getType())
		{
			case SKILL_LEVEL:
				return state.getSkillLevel(req.getValue()) >= req.getThreshold();
			case QUEST_COMPLETE:
				return state.isQuestComplete(req.getValue());
			case DIARY_COMPLETE:
				return state.isDiaryTierComplete(req.getValue());
			case COMBAT_ACHIEVEMENT_TIER:
				return state.isCombatAchievementTierComplete(req.getValue());
			case BOSS_KC:
				return state.getBossKillCount(req.getValue()) >= req.getThreshold();
			case QUEST_POINTS:
				return state.getQuestPoints() >= req.getThreshold();
			case COMBAT_LEVEL:
				return state.getCombatLevel() >= req.getThreshold();
			case ITEM_OWNED:
				return state.getOwnedCount(parseItemId(req.getValue()))
					>= Math.max(1, req.getThreshold());
			case COMBINED_SKILL_LEVEL:
				return combinedLevel(req, state) >= req.getThreshold();
			case ANY_OF:
				for (Requirement child : req.getAnyOf())
				{
					if (isMet(child, state))
					{
						return true;
					}
				}
				return req.getAnyOf().isEmpty(); // an empty ANY_OF is vacuously met rather than an unsatisfiable gate
			default:
				return false;
		}
	}

	private static int parseItemId(String value)
	{
		try
		{
			return Integer.parseInt(value.trim());
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static int combinedLevel(Requirement req, PlayerState state)
	{
		int sum = 0;
		for (String skill : req.getValue().split(","))
		{
			sum += state.getSkillLevel(skill.trim());
		}
		return sum;
	}

	/**
	 * True if the activity itself is something with a clear "done" state
	 * that the player has already reached (a quest, a diary tier, a combat
	 * achievement tier, or a specific collection log unlock). Open-ended
	 * grinds (PVM/SKILLING/MINIGAME/CLUE_SCROLL) have no single "done" state
	 * here - that's left to user-set goals rather than static content data.
	 */
	public static boolean isAlreadyDone(Activity activity, PlayerState state)
	{
		switch (activity.getCategory())
		{
			case QUEST:
				return state.isQuestComplete(activity.getName());
			case DIARY:
				return state.isDiaryTierComplete(activity.getId());
			case COMBAT_ACHIEVEMENT:
				return state.isCombatAchievementTierComplete(activity.getId());
			case COLLECTION_LOG:
				return state.hasCollectionLogUnlock(activity.getName());
			default:
				return false;
		}
	}
}

package com.nowwhat.engine;

import com.nowwhat.model.PathStep;
import com.nowwhat.model.TrainingMethod;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.TreeSet;

/**
 * Given a skill's bundled TrainingMethods and a [fromLevel, toLevel) range,
 * produces an ordered list of TRAIN_SKILL steps.
 * <p>
 * Two design choices worth calling out:
 * <p>
 * <b>Multiple alternatives within one intensity.</b> A segment is never
 * collapsed to a single "best" method - Mining 45+ with normal methods
 * genuinely has several different valid options (Motherlode Mine, Blast
 * Mine, gem rocks, calcified rocks) at different xp/hr with different
 * trade-offs, and the planner has no basis to pick a winner among them. All
 * of them are surfaced as {@link PathStep.Option}s, sorted by xp/hr as a
 * hint but never pruned to one.
 * <p>
 * <b>Exclusive intensity selection, not additive.</b> `preferTickManipulation`
 * picks ONE intensity band per segment rather than showing both together -
 * mixing a tick-manip option into a list of normal ones is clutter for
 * someone who already said they don't want it, and vice versa. The only
 * fallback is one-directional: asking for tick-manipulation falls back to
 * normal methods where none is recorded (since intensity is a preference,
 * not a hard requirement), but asking for normal never falls back to
 * tick-manipulation - that would defeat the entire point of choosing it.
 */
public class SkillPathPlanner
{
	public List<PathStep> plan(String skill, int fromLevel, int toLevel, List<TrainingMethod> methods,
		boolean preferTickManipulation, List<String> warningsOut)
	{
		List<PathStep> steps = new ArrayList<>();
		if (fromLevel >= toLevel)
		{
			return steps;
		}

		if (methods.isEmpty())
		{
			warningsOut.add("No training method data for " + skill + " \u2014 check the wiki's training guide manually.");
			return steps;
		}

		// Breakpoints come from ALL methods regardless of intensity, so segment
		// boundaries are identical whichever preference is chosen - only which
		// methods populate each segment's options differs.
		TreeSet<Integer> breakpoints = new TreeSet<>();
		breakpoints.add(fromLevel);
		breakpoints.add(toLevel);
		for (TrainingMethod method : methods)
		{
			if (method.getMinLevel() > fromLevel && method.getMinLevel() < toLevel)
			{
				breakpoints.add(method.getMinLevel());
			}
			if (method.getMaxLevel() > fromLevel && method.getMaxLevel() < toLevel)
			{
				breakpoints.add(method.getMaxLevel());
			}
		}

		Integer[] points = breakpoints.toArray(new Integer[0]);

		// Two passes. The first resolves each raw segment to the methods that
		// survive the intensity preference; the second merges neighbours that
		// resolved to the *same* methods before emitting steps.
		//
		// The merge matters because breakpoints come from every method regardless
		// of intensity (so the boundaries don't shift when the preference does).
		// A method bracketed finely by level - 1.5-tick teaks, which run from 93k
		// at 35 to 222k at 90 - therefore splits the *normal* plan at 41, 50, 61,
		// 71, 80 and 90 too, where nothing about the normal options changes. That
		// produced consecutive steps reading "Teak trees" and then "Teak trees".
		List<Segment> segments = new ArrayList<>();
		for (int i = 0; i < points.length - 1; i++)
		{
			int segmentStart = points[i];
			int segmentEnd = points[i + 1];
			if (segmentStart >= segmentEnd)
			{
				continue;
			}

			List<TrainingMethod> tickCovering = new ArrayList<>();
			List<TrainingMethod> normalCovering = new ArrayList<>();
			for (TrainingMethod method : methods)
			{
				if (method.getMinLevel() <= segmentStart && method.getMaxLevel() >= segmentEnd)
				{
					(method.isTickManipulation() ? tickCovering : normalCovering).add(method);
				}
			}

			List<TrainingMethod> chosen;
			boolean fellBack = false;
			if (preferTickManipulation)
			{
				if (!tickCovering.isEmpty())
				{
					chosen = tickCovering;
				}
				else
				{
					chosen = normalCovering;
					fellBack = !normalCovering.isEmpty();
				}
			}
			else
			{
				// Normal preferred: never falls back to tick-manipulation, even
				// if that's the only thing covering this segment.
				chosen = normalCovering;
			}

			if (chosen.isEmpty())
			{
				String note = "No training method covers " + skill + " level " + segmentStart + "\u2013" + segmentEnd
					+ " \u2014 gap in the bundled data.";
				if (!preferTickManipulation && !tickCovering.isEmpty())
				{
					note += " (a tick-manipulation method exists here but is excluded by your preference)";
				}
				warningsOut.add(note);
				continue;
			}

			chosen = new ArrayList<>(chosen);
			// Plain xp/hr order, rate-less methods last. A quest route ranking
			// first would make it the headline for its whole range, which turns
			// "here is a shortcut" into "go and quest" - the panel keeps such an
			// option visible instead of promoting it (see renderStep).
			chosen.sort(Comparator.comparingInt(this::rate).reversed());

			Segment previous = segments.isEmpty() ? null : segments.get(segments.size() - 1);
			if (previous != null && previous.end == segmentStart
				&& previous.fellBack == fellBack && previous.methods.equals(chosen))
			{
				previous.end = segmentEnd;
			}
			else
			{
				segments.add(new Segment(segmentStart, segmentEnd, chosen, fellBack));
			}

			if (segments.size() > 200)
			{
				warningsOut.add("Aborted planning " + skill + " after 200 segments \u2014 check methods.json for overlapping/malformed ranges.");
				break;
			}
		}

		for (Segment segment : segments)
		{
			if (segment.fellBack)
			{
				warningsOut.add("No tick-manipulation method recorded for " + skill + " "
					+ segment.start + "\u2013" + segment.end + " \u2014 showing normal methods instead.");
			}

			long segmentXp = XpTable.xpBetween(segment.start, segment.end);

			List<PathStep.Option> options = new ArrayList<>();
			for (TrainingMethod method : segment.methods)
			{
				// Compact rather than fully separated: at sidebar width a label
				// like "137,000" gets wrapped after the comma, splitting the
				// number across two lines.
				// The name alone. Rate, time, intensity and Wilderness exposure all
				// travel beside it as data now, so the panel can lay them out rather
				// than hand the player one long wrapped sentence to read back.
				options.add(new PathStep.Option(
					method.getName(),
					method.getNotes(),
					timeEstimate(method, segmentXp),
					method.getWikiUrl(),
					method.getQuests(),
					method.isPvpRisk(),
					method.isTickManipulation(),
					method.getXpPerHour(),
					method.getGear(),
					method.getSupplies()
				).withAttention(method.getAttention())
					.withNeeded(shoppingList(method, segmentXp)));
			}

			// No "(choose one)" here: whether a choice is still open depends on
			// what the player has already picked, and only the panel knows that.
			// Baked into the title, a collapsed step went on saying "choose one"
			// after they had chosen.
			String title = capitalize(skill) + " " + segment.start + " \u2192 " + segment.end ;
			steps.add(new PathStep(PathStep.Type.TRAIN_SKILL, title, options)
				.withXpCost(segmentXp)
				.withLevels(skill, segment.start, segment.end));
		}

		return steps;
	}

	/** A level range that resolved to one particular set of methods. */
	private static final class Segment
	{
		private final int start;
		private int end;
		private final List<TrainingMethod> methods;
		private final boolean fellBack;

		private Segment(int start, int end, List<TrainingMethod> methods, boolean fellBack)
		{
			this.start = start;
			this.end = end;
			this.methods = methods;
			this.fellBack = fellBack;
		}
	}

	/**
	 * The wall-clock estimate for this method over this segment, as its own
	 * short line. How long a segment takes is what a player actually compares
	 * methods on, and it cannot be read off an xp/hr figure without doing the
	 * arithmetic - but buried at the end of a three-clause note it may as well
	 * not be there.
	 *
	 * @return null for a method with no hourly rate, such as a quest route.
	 */
	private String timeEstimate(TrainingMethod method, long segmentXp)
	{
		Integer xpPerHour = method.getXpPerHour();
		if (xpPerHour == null || xpPerHour <= 0 || segmentXp <= 0)
		{
			return null;
		}
		return "~" + XpTable.formatHours(segmentXp / (double) xpPerHour)
			+ " \u00b7 " + XpTable.formatXp(xpPerHour) + " xp/hr";
	}

	/**
	 * What this method's materials come to over this many xp.
	 * <p>
	 * Rounded up, per item, because a shopping list that is one bone short is
	 * not a shopping list. The count is deliberately exact arithmetic on the xp
	 * rather than an estimate: a player buying 44,048 dragon bones wants the
	 * number the xp implies, and if the figure behind it is approximate - as a
	 * 50% bone-save chance is - that belongs in the method's note, where the
	 * reason can be given.
	 *
	 * @return empty when the method records no countable actions
	 */
	private List<PathStep.Option.Needed> shoppingList(TrainingMethod method, long segmentXp)
	{
		if (!method.hasShoppingList() || segmentXp <= 0)
		{
			return java.util.Collections.emptyList();
		}
		// Rounded up to whole actions BEFORE the per-action quantity is applied.
		// A redwood shield takes two logs, and 8.3 actions' worth of xp needs 9
		// shields and therefore 18 logs - not the 17 that comes out of rounding
		// 16.6 at the end. Half a shield is not a shield.
		long actions = (long) Math.ceil(segmentXp / method.getXpPerAction());
		List<PathStep.Option.Needed> needed = new ArrayList<>();
		for (TrainingMethod.Consumed consumed : method.getConsumes())
		{
			long quantity = (long) Math.ceil(actions * consumed.getEach());
			if (quantity > 0)
			{
				needed.add(new PathStep.Option.Needed(consumed.getItem(), quantity));
			}
		}
		return needed;
	}

	private int rate(TrainingMethod method)
	{
		return method.getXpPerHour() != null ? method.getXpPerHour() : -1;
	}

	private String capitalize(String s)
	{
		if (s.isEmpty())
		{
			return s;
		}
		return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
	}
}

package com.nowwhat.engine;

import com.nowwhat.model.Activity;
import com.nowwhat.model.CombatAchievementTier;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.Requirement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Set;

/**
 * Filters and ranks activities for a given player.
 * <p>
 * Deliberately kept free of any RuneLite/Client dependency so it can be
 * unit tested with a hand-built PlayerState and doesn't need a running
 * game client.
 */
public class SuggestionEngine
{
	/**
	 * Returns activities the player is NOT yet done with, but for which every
	 * requirement is currently met (i.e. "you can do this right now"),
	 * sorted by priority descending.
	 */
	public List<Activity> getAvailableNow(List<Activity> allActivities, PlayerState state)
	{
		return getAvailableNow(allActivities, state, Collections.emptySet());
	}

	/**
	 * As {@link #getAvailableNow(List, PlayerState)}, but leaving out whole
	 * categories the player has switched off in settings.
	 * <p>
	 * A hidden category is dropped here rather than in the panel so that the
	 * "nothing is available" case stays honest: a player who has turned quests
	 * off should be told there is nothing left to do, not shown a count that
	 * includes the things being hidden from them.
	 *
	 * @param hiddenCategories categories to leave out; a category nobody has a
	 *                         switch for is simply never in this set
	 */
	public List<Activity> getAvailableNow(List<Activity> allActivities, PlayerState state,
		Set<Activity.Category> hiddenCategories)
	{
		return getAvailableNow(allActivities, state, hiddenCategories, false);
	}

	/**
	 * As above, optionally leaving out everything in the Wilderness, for the
	 * player who never wants to be sent where other players can attack them.
	 * <p>
	 * "Available" here means suggested: the game's requirements are met
	 * <em>and</em> so are the stats the wiki recommends. A fight with no
	 * requirement at all is not something to point a level 3 account at.
	 */
	public List<Activity> getAvailableNow(List<Activity> allActivities, PlayerState state,
		Set<Activity.Category> hiddenCategories, boolean hideWilderness)
	{
		List<Activity> result = new ArrayList<>();
		for (Activity activity : allActivities)
		{
			if (isHidden(activity, hiddenCategories, hideWilderness))
			{
				continue;
			}
			if (isAlreadyDone(activity, state))
			{
				continue;
			}
			if (meetsAllRequirements(activity, state) && unmetRecommended(activity, state).isEmpty())
			{
				result.add(activity);
			}
		}
		result.sort(Comparator.comparingInt(Activity::getPriority).reversed());
		return result;
	}

	/**
	 * Returns activities the player is close to unlocking - exactly one
	 * requirement away, and that one a short step (see {@link #CLOSE_LEVELS}) -
	 * so the panel can show "almost there" suggestions
	 * (e.g. "2 more Mining levels unlocks Diary tier X").
	 */
	public List<Activity> getAlmostAvailable(List<Activity> allActivities, PlayerState state)
	{
		return getAlmostAvailable(allActivities, state, Collections.emptySet());
	}

	/**
	 * As {@link #getAlmostAvailable(List, PlayerState)}, but leaving out whole
	 * categories the player has switched off in settings.
	 */
	public List<Activity> getAlmostAvailable(List<Activity> allActivities, PlayerState state,
		Set<Activity.Category> hiddenCategories)
	{
		return getAlmostAvailable(allActivities, state, hiddenCategories, false);
	}

	/** As above, optionally leaving out everything in the Wilderness. */
	public List<Activity> getAlmostAvailable(List<Activity> allActivities, PlayerState state,
		Set<Activity.Category> hiddenCategories, boolean hideWilderness)
	{
		List<Activity> result = new ArrayList<>();
		for (Activity activity : allActivities)
		{
			if (isHidden(activity, hiddenCategories, hideWilderness))
			{
				continue;
			}
			if (isAlreadyDone(activity, state))
			{
				continue;
			}
			if (isAlmost(activity, state))
			{
				result.add(activity);
			}
		}
		return result;
	}

	/**
	 * A short step away, one of two ways: one requirement short and that one
	 * close, with the recommended stats already there; or every requirement met
	 * and only a few levels of recommended stats to go. A fight that is a
	 * requirement away and also far below its recommended stats is not close,
	 * whatever the requirement says.
	 */
	private boolean isAlmost(Activity activity, PlayerState state)
	{
		List<Requirement> recommended = unmetRecommended(activity, state);
		if (meetsAllRequirements(activity, state))
		{
			if (recommended.isEmpty())
			{
				return false;
			}
			for (Requirement req : recommended)
			{
				if (!isClose(req, state))
				{
					return false;
				}
			}
			return true;
		}
		Requirement missing = theOneMissing(activity, state);
		return missing != null && isClose(missing, state) && recommended.isEmpty();
	}

	/** The recommended stats this player does not have yet, in the order the data lists them. */
	private List<Requirement> unmetRecommended(Activity activity, PlayerState state)
	{
		List<Requirement> unmet = new ArrayList<>();
		for (Requirement req : activity.getRecommended())
		{
			if (!isRequirementMet(req, state))
			{
				unmet.add(req);
			}
		}
		return unmet;
	}

	/**
	 * How many levels short still counts as "almost". One requirement away used
	 * to be the whole test, so 70 Slayer put Cerberus (91) on the list beside
	 * things two levels off, and on a high-level account the far-off ones were
	 * most of what was left.
	 */
	static final int CLOSE_LEVELS = 5;
	/** Quest points come a few at a time, so the margin is wider than for a level. */
	static final int CLOSE_QUEST_POINTS = 10;

	/** The single requirement standing in the way, or null when there are none or several. */
	private Requirement theOneMissing(Activity activity, PlayerState state)
	{
		Requirement missing = null;
		for (Requirement req : activity.getRequirements())
		{
			if (!isRequirementMet(req, state))
			{
				if (missing != null)
				{
					return null;
				}
				missing = req;
			}
		}
		return missing;
	}

	/**
	 * Whether a requirement is a short step away. A level is close within a
	 * few levels; a quest or a Combat Achievement tier is one thing to do, so
	 * it counts as close however long that thing takes - the plan says how long.
	 */
	private boolean isClose(Requirement req, PlayerState state)
	{
		switch (req.getType())
		{
			case SKILL_LEVEL:
				return req.getThreshold() - state.getSkillLevel(req.getValue()) <= CLOSE_LEVELS;
			case COMBAT_LEVEL:
				return req.getThreshold() - state.getCombatLevel() <= CLOSE_LEVELS;
			case COMBINED_SKILL_LEVEL:
				return req.getThreshold() - combinedLevel(req, state) <= CLOSE_LEVELS;
			case QUEST_POINTS:
				return req.getThreshold() - state.getQuestPoints() <= CLOSE_QUEST_POINTS;
			case ANY_OF:
				for (Requirement option : req.getAnyOf())
				{
					if (isClose(option, state))
					{
						return true;
					}
				}
				return false;
			default:
				return true;
		}
	}

	/**
	 * The line under an "Almost there" suggestion saying what is in the way,
	 * e.g. "Needs 91 Slayer, you have 87". Null when nothing is missing or more
	 * than one thing is.
	 */
	public String whatIsMissing(Activity activity, PlayerState state)
	{
		if (meetsAllRequirements(activity, state))
		{
			List<Requirement> recommended = unmetRecommended(activity, state);
			if (recommended.isEmpty())
			{
				return null;
			}
			// Said as a recommendation, not a need: nothing stops the player
			// going now, and the line should not claim otherwise.
			List<String> parts = new ArrayList<>();
			for (Requirement req : recommended)
			{
				parts.add(describe(req, state));
			}
			return "Recommended " + String.join(", and ", parts);
		}
		Requirement missing = theOneMissing(activity, state);
		return missing == null ? null : "Needs " + describe(missing, state);
	}

	private String describe(Requirement req, PlayerState state)
	{
		switch (req.getType())
		{
			case SKILL_LEVEL:
				return req.getThreshold() + " " + titleCase(req.getValue())
					+ ", you have " + state.getSkillLevel(req.getValue());
			case COMBAT_LEVEL:
				return "combat level " + req.getThreshold() + ", you are " + state.getCombatLevel();
			case COMBINED_SKILL_LEVEL:
			{
				List<String> names = new ArrayList<>();
				for (String skill : req.getValue().split(","))
				{
					names.add(titleCase(skill.trim()));
				}
				return req.getThreshold() + " " + String.join(" + ", names)
					+ " combined, you have " + combinedLevel(req, state);
			}
			case QUEST_POINTS:
				return req.getThreshold() + " Quest points, you have " + state.getQuestPoints();
			case QUEST_COMPLETE:
				return req.getValue() + " done first";
			case COMBAT_ACHIEVEMENT_TIER:
			{
				CombatAchievementTier tier = CombatAchievementTier.fromKey(req.getValue());
				return (tier != null ? "the " + tier.getLabel() : req.getValue())
					+ " Combat Achievement tier first";
			}
			case ANY_OF:
			{
				// Only the options that are close: the far ones are not what
				// put this on the list.
				List<String> close = new ArrayList<>();
				for (Requirement option : req.getAnyOf())
				{
					if (isClose(option, state))
					{
						close.add(describe(option, state));
					}
				}
				return String.join(", or ", close);
			}
			default:
				return req.getValue();
		}
	}

	private static int combinedLevel(Requirement req, PlayerState state)
	{
		int total = 0;
		for (String skill : req.getValue().split(","))
		{
			total += state.getSkillLevel(skill.trim());
		}
		return total;
	}

	private static String titleCase(String skill)
	{
		String lower = skill.toLowerCase(java.util.Locale.ROOT);
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	/** An activity with no category at all is never hidden: it has no switch. */
	private boolean isHidden(Activity activity, Set<Activity.Category> hiddenCategories,
		boolean hideWilderness)
	{
		if (hideWilderness && activity.isWilderness())
		{
			return true;
		}
		return activity.getCategory() != null && hiddenCategories.contains(activity.getCategory());
	}

	private boolean isAlreadyDone(Activity activity, PlayerState state)
	{
		return RequirementEvaluator.isAlreadyDone(activity, state);
	}

	private boolean meetsAllRequirements(Activity activity, PlayerState state)
	{
		for (Requirement req : activity.getRequirements())
		{
			if (!isRequirementMet(req, state))
			{
				return false;
			}
		}
		return true;
	}

	private boolean isRequirementMet(Requirement req, PlayerState state)
	{
		return RequirementEvaluator.isMet(req, state);
	}
}

package com.nowwhat.engine;

/**
 * The standard OSRS experience curve, plus the formatting helpers the planner
 * needs to say something useful about a training segment.
 *
 * <p>"Nightmare Zone, ~45,000 xp/hr" on its own doesn't answer the question a
 * player is actually asking, which is how long this is going to take. Knowing
 * that Attack 70 to 99 is 12.3M xp - roughly 273 hours at that rate - is the
 * difference between a plan and a restatement of the wiki.
 */
public final class XpTable
{
	/** Levels above 99 exist for the virtual-level/combat maths; 126 is the ceiling. */
	private static final int MAX_LEVEL = 126;

	private static final long[] XP_FOR_LEVEL = new long[MAX_LEVEL + 1];

	static
	{
		// xp(n) = floor( sum(k=1..n-1) floor(k + 300 * 2^(k/7)) / 4 )
		double points = 0;
		for (int level = 1; level < MAX_LEVEL; level++)
		{
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
			XP_FOR_LEVEL[level + 1] = (long) Math.floor(points / 4);
		}
	}

	private XpTable()
	{
	}

	public static long xpForLevel(int level)
	{
		if (level <= 1)
		{
			return 0;
		}
		return XP_FOR_LEVEL[Math.min(level, MAX_LEVEL)];
	}

	/** Experience needed to go from one level to another; never negative. */
	public static long xpBetween(int fromLevel, int toLevel)
	{
		return Math.max(0, xpForLevel(toLevel) - xpForLevel(fromLevel));
	}

	/** Compact xp for a UI that has ~200px to play with: 12.3M, 737k, 4,120. */
	public static String formatXp(long xp)
	{
		if (xp >= 1_000_000)
		{
			return trimZero(String.format(java.util.Locale.ROOT, "%.1f", xp / 1_000_000.0)) + "M";
		}
		if (xp >= 10_000)
		{
			return Math.round(xp / 1000.0) + "k";
		}
		return String.format(java.util.Locale.ROOT, "%,d", xp);
	}

	/**
	 * Rough wall-clock estimate. Deliberately coarse - these rates are
	 * averages from a bundled data file, not a measurement of the player, so
	 * presenting "272.6 hours" would imply a precision that isn't there.
	 */
	public static String formatHours(double hours)
	{
		if (hours < 1)
		{
			return Math.max(1, Math.round(hours * 60)) + " min";
		}
		if (hours < 10)
		{
			return trimZero(String.format(java.util.Locale.ROOT, "%.1f", hours)) + " hrs";
		}
		return Math.round(hours) + " hrs";
	}

	private static String trimZero(String s)
	{
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.nowwhat.model;

import java.util.Collections;
import java.util.List;

/**
 * One suggestable "thing to do" - a quest, a diary tier, a boss, a skilling
 * milestone, a collection log grind, etc. Loaded from activities.json.
 */
public class Activity
{
	public enum Category
	{
		QUEST,
		DIARY,
		PVM,
		SKILLING,
		MINIGAME,
		COLLECTION_LOG,
		COMBAT_ACHIEVEMENT,
		CLUE_SCROLL
	}

	private String id;
	private String name;
	private Category category;
	private String description;
	/** Short human-readable reason shown in the panel, e.g. "Unlocks Zulrah" or "83% done". */
	private String reasonTemplate;
	private String wikiUrl;
	private List<Requirement> requirements = Collections.emptyList();
	/** Higher = shown first when multiple suggestions are otherwise tied. */
	private int priority;
	/**
	 * The stats the wiki recommends before attempting this, as opposed to what
	 * the game enforces. They decide whether it is <em>suggested</em>, never
	 * whether it can be planned: plenty of fights have no requirement at all,
	 * and without this a level 3 account was being pointed at the Inferno.
	 */
	private List<Requirement> recommended = Collections.emptyList();
	/** Takes place in the Wilderness, where other players can attack you. */
	private boolean wilderness;

	/**
	 * What to wear and what to bring, for content you can now actually attempt.
	 * <p>
	 * A plan that ends at "you already meet every requirement" stops exactly
	 * where it became useful: the next question is always "so what do I take?",
	 * and answering it with a wiki link sends the player out of the sidebar to
	 * find out. These fields let the panel answer it in place.
	 */
	private List<GearSetup> setups = Collections.emptyList();
	/** Consumables and utility items to withdraw before going. */
	private List<String> supplies = Collections.emptyList();
	/** The wiki's full strategy page, for the depth the panel shouldn't try to hold. */
	private String strategyUrl;
	/**
	 * The RuneLite plugin that helps during the fight itself, by the name in its
	 * PluginDescriptor (e.g. "Zulrah Helper"). Looked up by name at runtime, so
	 * there is no build dependency on it and nothing breaks if it isn't installed.
	 */
	private String helperPlugin;
	/**
	 * That plugin's Plugin Hub id (e.g. "zulrah-helper"), used to link straight
	 * to its hub page rather than dropping the player on the hub's front door
	 * to go looking.
	 */
	private String helperPluginId;
	/**
	 * Another activity's id to take the preparation from, for an entry that is a
	 * reason to do a fight rather than a fight of its own.
	 * <p>
	 * A collection log slot is the clearest case: "Pet snakeling (Zulrah)" is
	 * Zulrah, over and over, so the answer to "what do I take?" is Zulrah's
	 * answer and duplicating four kits and seven supply lines per drop would
	 * mean two copies to keep right. Resolved once at load.
	 */
	private String preparationFrom;
	/**
	 * The name of the activity the preparation was borrowed from, set during
	 * resolution so the panel can say whose gear this is - a player who asked
	 * for a pet and got handed a blowpipe is owed the word "Zulrah".
	 */
	private String preparationSource;

	/** One named kit - "Ranged (budget)", "Magic (best in slot)" - and its items. */
	public static class GearSetup
	{
		private String name;
		private List<String> items = Collections.emptyList();

		public GearSetup()
		{
		}

		public GearSetup(String name, List<String> items)
		{
			this.name = name;
			this.items = items;
		}

		public String getName()
		{
			return name;
		}

		public List<String> getItems()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	public List<GearSetup> getSetups()
	{
		return setups == null ? Collections.emptyList() : setups;
	}

	public List<String> getSupplies()
	{
		return supplies == null ? Collections.emptyList() : supplies;
	}

	public String getStrategyUrl()
	{
		return strategyUrl;
	}

	public String getHelperPlugin()
	{
		return helperPlugin;
	}

	public String getHelperPluginId()
	{
		return helperPluginId;
	}

	public String getPreparationFrom()
	{
		return preparationFrom;
	}

	/** The activity this preparation belongs to, or null when it is this one's own. */
	public String getPreparationSource()
	{
		return preparationSource;
	}

	/**
	 * Takes another activity's gear, supplies, strategy page and in-fight helper.
	 * <p>
	 * Only ever fills gaps: an entry that says anything for itself keeps all of
	 * it, so adding a line of its own to a borrowing entry later does not
	 * silently mix the two.
	 */
	public void inheritPreparation(Activity source)
	{
		if (source == null || hasPreparation() || !source.hasPreparation())
		{
			return;
		}
		setups = source.getSetups();
		supplies = source.getSupplies();
		strategyUrl = source.getStrategyUrl();
		helperPlugin = source.getHelperPlugin();
		helperPluginId = source.getHelperPluginId();
		preparationSource = source.getName();
	}

	/** True when there is anything worth rendering in a preparation block. */
	public boolean hasPreparation()
	{
		return !getSetups().isEmpty() || !getSupplies().isEmpty()
			|| strategyUrl != null || helperPlugin != null;
	}

	/** No-arg constructor used by Gson when loading activities.json. */
	public Activity()
	{
	}

	/**
	 * Minimal constructor for programmatic construction (tests, and any
	 * future in-code activity registration) - everything beyond the
	 * essentials defaults to null/empty, matching how a bare JSON entry
	 * with only these fields would deserialize.
	 */
	public Activity(String id, String name, Category category, List<Requirement> requirements)
	{
		this.id = id;
		this.name = name;
		this.category = category;
		this.requirements = requirements;
	}

	/**
	 * Adds the description to a programmatically built activity.
	 * <p>
	 * Not decoration: a plan step built from an activity shows its description,
	 * so a test about what a step says has to be able to set one.
	 */
	public Activity withDescription(String description)
	{
		this.description = description;
		return this;
	}

	/** Adds recommended stats and the Wilderness flag to a programmatically built activity. */
	public Activity withRecommended(List<Requirement> recommended, boolean wilderness)
	{
		this.recommended = recommended;
		this.wilderness = wilderness;
		return this;
	}

	/** Same as above, with an explicit priority - used where ranking order matters (e.g. tests). */
	public Activity(String id, String name, Category category, List<Requirement> requirements, int priority)
	{
		this(id, name, category, requirements);
		this.priority = priority;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public Category getCategory()
	{
		return category;
	}

	/**
	 * The description as one line of prose, for the places that show it inline:
	 * a plan step, a rolled suggestion. See {@link #getHowTo()} for the laid-out
	 * version.
	 */
	public String getDescription()
	{
		return description == null ? null : flatten(description);
	}

	/**
	 * The description with its layout: paragraphs on their own lines, a short
	 * line ending in a colon as a heading, and lines starting "* " as a list
	 * under it. A birdhouse run is a route, a list of spots and a table of
	 * tiers, and written as one paragraph it could not be read in a sidebar.
	 */
	public String getHowTo()
	{
		return description;
	}

	/** Joins the laid-out form into one line, a heading's list joined with commas. */
	static String flatten(String text)
	{
		List<String> out = new java.util.ArrayList<>();
		List<String> list = new java.util.ArrayList<>();
		for (String raw : text.split("\n"))
		{
			String line = raw.trim();
			if (line.isEmpty())
			{
				continue;
			}
			if (line.startsWith("* "))
			{
				list.add(line.substring(2).trim());
				continue;
			}
			if (!list.isEmpty())
			{
				out.add(String.join(", ", list) + ".");
				list.clear();
			}
			out.add(line);
		}
		if (!list.isEmpty())
		{
			out.add(String.join(", ", list) + ".");
		}
		return String.join(" ", out);
	}

	public String getReasonTemplate()
	{
		return reasonTemplate;
	}

	public String getWikiUrl()
	{
		return wikiUrl;
	}

	public List<Requirement> getRequirements()
	{
		return requirements;
	}

	public int getPriority()
	{
		return priority;
	}

	/** Never null; Gson leaves the field null when the JSON has no such key. */
	public List<Requirement> getRecommended()
	{
		return recommended == null ? Collections.emptyList() : recommended;
	}

	public boolean isWilderness()
	{
		return wilderness;
	}
}

package com.nowwhat.model;

/**
 * The six Combat Achievement tiers, and the numbers that say how far away
 * each one is.
 * <p>
 * A tier is not a list you clear; it is a points total. Every task is worth
 * a fixed number of points by its own tier (an Easy task 1, a Master task 5),
 * and a tier's rewards unlock once your running total reaches its threshold,
 * whichever tasks the points came from. So "plan the Master tier" is really
 * "earn this many more points", and that is the number the plan leads with.
 * <p>
 * The thresholds move whenever Jagex adds tasks, so they are written down
 * here with the date they were taken from the wiki's Combat Achievements page
 * (2026-11-03) rather than presented as permanent. When the panel says a tier
 * needs a different number of points than the in-game interface does, this
 * table is what to update.
 */
public enum CombatAchievementTier
{
	EASY("Easy", 1, 41, 41),
	MEDIUM("Medium", 2, 169, 64),
	HARD("Hard", 3, 436, 89),
	ELITE("Elite", 4, 1100, 166),
	MASTER("Master", 5, 1965, 173),
	GRANDMASTER("Grandmaster", 6, 2697, 122);

	private final String label;
	private final int pointsPerTask;
	private final int pointsToUnlock;
	private final int taskCount;

	CombatAchievementTier(String label, int pointsPerTask, int pointsToUnlock, int taskCount)
	{
		this.label = label;
		this.pointsPerTask = pointsPerTask;
		this.pointsToUnlock = pointsToUnlock;
		this.taskCount = taskCount;
	}

	/** The key used by activity ids and requirements: {@code CA_MASTER}. */
	public String getKey()
	{
		return "CA_" + name();
	}

	public String getLabel()
	{
		return label;
	}

	public int getPointsPerTask()
	{
		return pointsPerTask;
	}

	/** The running points total at which this tier's rewards unlock. */
	public int getPointsToUnlock()
	{
		return pointsToUnlock;
	}

	public int getTaskCount()
	{
		return taskCount;
	}

	/** The wiki's list of this tier's tasks. */
	public String getTaskListUrl()
	{
		return "https://oldschool.runescape.wiki/w/Combat_Achievements/" + label;
	}

	/** The tier a {@code CA_<TIER>} key names, or null for anything else. */
	public static CombatAchievementTier fromKey(String key)
	{
		if (key == null)
		{
			return null;
		}
		for (CombatAchievementTier tier : values())
		{
			if (tier.getKey().equalsIgnoreCase(key))
			{
				return tier;
			}
		}
		return null;
	}
}

package com.nowwhat.model;

/**
 * A player-set target for the path planner to plan a route towards.
 * Deliberately a plain discriminated-union-style class rather than a class
 * hierarchy, to keep (de)serialization and Swing form-binding simple.
 */
public class Goal
{
	public enum Type
	{
		/** Reach a skill level. skillName + targetLevel. */
		SKILL_LEVEL,
		/** Own N of an item (bank + inventory + equipment). itemId + targetQuantity. */
		ITEM_QUANTITY,
		/** Unlock/complete something already in the Activity database. activityId. */
		ACTIVITY,
		/**
		 * Bring every skill up to targetLevel. targetLevel.
		 * <p>
		 * "I want 80+ in everything" is a different question from "I want 80
		 * Thieving", and answering it one skill at a time means working out
		 * which skills are short, in what order, by hand.
		 */
		BASE_STATS,
		/**
		 * Reach a total level. targetLevel holds the total, not a skill level.
		 * <p>
		 * Which levels to take is the whole question, and the answer is the
		 * cheapest next level each time - see PathPlanner.
		 */
		TOTAL_LEVEL
	}

	private final Type type;
	private final String skillName;
	private final int targetLevel;
	private final String itemId;
	private final int targetQuantity;
	private final String activityId;
	private final String label;
	private final boolean allowTickManipulation;
	/**
	 * Whether an ITEM_QUANTITY goal counts what the player already has towards
	 * the target.
	 * <p>
	 * It does by default, since asking for 3 of something you already have 2 of
	 * is a one-item job. But that makes "how do I get one of these" unanswerable
	 * for anyone who already owns one - the plan comes back "already done", and
	 * the only way to see the route is to ask for two and read a plan for the
	 * wrong quantity. So it is the player's call, not an assumption.
	 */
	private final boolean countOwned;

	private Goal(Type type, String skillName, int targetLevel, String itemId, int targetQuantity,
		String activityId, String label, boolean allowTickManipulation)
	{
		this(type, skillName, targetLevel, itemId, targetQuantity, activityId, label,
			allowTickManipulation, true);
	}

	private Goal(Type type, String skillName, int targetLevel, String itemId, int targetQuantity,
		String activityId, String label, boolean allowTickManipulation, boolean countOwned)
	{
		this.countOwned = countOwned;
		this.type = type;
		this.skillName = skillName;
		this.targetLevel = targetLevel;
		this.itemId = itemId;
		this.targetQuantity = targetQuantity;
		this.activityId = activityId;
		this.label = label;
		this.allowTickManipulation = allowTickManipulation;
	}

	public static Goal skillLevel(String skillName, int targetLevel, boolean allowTickManipulation)
	{
		return new Goal(Type.SKILL_LEVEL, skillName.toUpperCase(), targetLevel, null, 0, null,
			targetLevel + " " + capitalize(skillName), allowTickManipulation);
	}

	public static Goal itemQuantity(String itemId, int targetQuantity, String displayName, boolean allowTickManipulation)
	{
		return itemQuantity(itemId, targetQuantity, displayName, allowTickManipulation, true);
	}

	public static Goal itemQuantity(String itemId, int targetQuantity, String displayName,
		boolean allowTickManipulation, boolean countOwned)
	{
		return new Goal(Type.ITEM_QUANTITY, null, 0, itemId.toUpperCase(), targetQuantity, null,
			displayName + " x" + targetQuantity, allowTickManipulation, countOwned);
	}

	/** Every skill at {@code level} or better. */
	public static Goal baseStats(int level, boolean allowTickManipulation)
	{
		return new Goal(Type.BASE_STATS, null, level, null, 0, null,
			level + "+ in every skill", allowTickManipulation);
	}

	/** A total level target, not a single skill's level. */
	public static Goal totalLevel(int total, boolean allowTickManipulation)
	{
		return new Goal(Type.TOTAL_LEVEL, null, total, null, 0, null,
			total + " total level", allowTickManipulation);
	}

	public static Goal activity(String activityId, String displayName, boolean allowTickManipulation)
	{
		return new Goal(Type.ACTIVITY, null, 0, null, 0, activityId, displayName, allowTickManipulation);
	}

	private static String capitalize(String s)
	{
		if (s.isEmpty())
		{
			return s;
		}
		return s.substring(0, 1).toUpperCase() + s.substring(1).toLowerCase();
	}

	public Type getType()
	{
		return type;
	}

	public String getSkillName()
	{
		return skillName;
	}

	public int getTargetLevel()
	{
		return targetLevel;
	}

	public String getItemId()
	{
		return itemId;
	}

	public int getTargetQuantity()
	{
		return targetQuantity;
	}

	public String getActivityId()
	{
		return activityId;
	}

	public String getLabel()
	{
		return label;
	}

	/**
	 * Which training intensity the planner should show for skill segments -
	 * true prefers tick-manipulation methods (falling back to normal methods
	 * only where no tick-manip method is recorded), false shows only normal
	 * methods and never falls back to tick-manipulation. Exclusive, not
	 * additive: the plan shows one intensity band per segment, not both
	 * mixed together.
	 */
	public boolean isAllowTickManipulation()
	{
		return allowTickManipulation;
	}

	/** @see #countOwned */
	public boolean isCountOwned()
	{
		return countOwned;
	}

	/** The same goal again, planned as if the player owned none of it yet. */
	public Goal ignoringWhatIsOwned()
	{
		return new Goal(type, skillName, targetLevel, itemId, targetQuantity, activityId, label,
			allowTickManipulation, false);
	}
}

package com.nowwhat.model;

import java.util.Collections;
import java.util.List;

/**
 * How to obtain an item. Loaded from item-sources.json, keyed by item id.
 */
public class ItemSource
{
	public enum SourceType
	{
		GE_BUY,
		SHOP,
		MONSTER_DROP,
		CRAFT,
		QUEST_REWARD
	}

	/** A single ingredient line in a CRAFT recipe. */
	public static class Ingredient
	{
		private String itemId;
		private int quantity;

		public Ingredient()
		{
		}

		public Ingredient(String itemId, int quantity)
		{
			this.itemId = itemId;
			this.quantity = quantity;
		}

		public String getItemId()
		{
			return itemId;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}

	private String id;
	private String displayName;
	private SourceType type;
	/** RuneLite item id, so the planner can subtract what you already own. */
	private Integer gameItemId;
	/** Free-text detail: shop name, boss name, notes - meaning depends on type. */
	private String detail;
	/**
	 * How the drop actually works, where that takes more than a place name:
	 * "about 1 kill in 100 drops an unsired...". Kept apart from detail because
	 * a drop's detail is read as a place in "Bludgeon claw from <detail>", and
	 * a sentence there turns the step title into a paragraph.
	 */
	private String note;
	private String wikiUrl;
	/** MONSTER_DROP only: rough expected kills for one drop. Always an estimate. */
	private Integer estimatedKc;
	/**
	 * MONSTER_DROP only: what one of those attempts is called, when "attempts"
	 * is the wrong word. Barrows is counted in chests, not kills - one chest is
	 * six brothers - so "~728 attempts" left the player guessing what an
	 * attempt was. Null means "attempts".
	 */
	private String attemptUnit;
	/**
	 * The activity whose gear and supplies answer "so what do I take?" for this
	 * item - the id of the fight it drops from.
	 * <p>
	 * {@link #detail} already names that fight in prose ("Chambers of Xeric"),
	 * but prose is not a reference: "Smoke devils" is the Thermonuclear smoke
	 * devil and "Cyclopes in the Warriors' Guild" is not any activity's name, so
	 * matching on it would work for some items and silently fail for others.
	 */
	private String preparationFrom;
	/**
	 * SHOP only: the activity whose currency pays for this.
	 * <p>
	 * {@link #detail} names the shop and the price, and a price on its own is a
	 * dead end: "Tithe Farm reward shop, 250 points" tells a player nothing
	 * about where points come from, how long 250 of them take, or what to bring
	 * to earn them. Naming the activity lets the plan put a step in front of the
	 * purchase instead of quoting a number and stopping.
	 */
	private String currencyFrom;
	/** CRAFT only: skill level needed to perform the craft. */
	private Requirement skillRequirement;
	/** CRAFT only. */
	private List<Ingredient> ingredients = Collections.emptyList();

	public String getPreparationFrom()
	{
		// You are going to the activity that mints the currency either way, so
		// its kit answers "what do I take?" for the shop item too. Derived
		// rather than authored twice, so the two cannot drift apart.
		return preparationFrom != null ? preparationFrom : currencyFrom;
	}

	/** For programmatic construction; the shipped data comes from JSON. */
	public ItemSource withCurrencyFrom(String currencyFrom)
	{
		this.currencyFrom = currencyFrom;
		return this;
	}

	/** For programmatic construction; the shipped data comes from JSON. */
	public ItemSource withGameItemId(int gameItemId)
	{
		this.gameItemId = gameItemId;
		return this;
	}

	/** @see #currencyFrom */
	public String getCurrencyFrom()
	{
		return currencyFrom;
	}

	/** No-arg constructor used by Gson when loading item-sources.json. */
	public ItemSource()
	{
	}

	/** Full constructor for programmatic construction (tests). */
	public ItemSource(String id, String displayName, SourceType type, String detail, String wikiUrl,
		Integer estimatedKc, Requirement skillRequirement, List<Ingredient> ingredients)
	{
		this.id = id;
		this.displayName = displayName;
		this.type = type;
		this.detail = detail;
		this.wikiUrl = wikiUrl;
		this.estimatedKc = estimatedKc;
		this.skillRequirement = skillRequirement;
		this.ingredients = ingredients;
	}

	public String getId()
	{
		return id;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public SourceType getType()
	{
		return type;
	}

	/** @see #note */
	public String getNote()
	{
		return note;
	}

	public String getDetail()
	{
		return detail;
	}

	public String getWikiUrl()
	{
		return wikiUrl;
	}

	public Integer getEstimatedKc()
	{
		return estimatedKc;
	}

	/** What one attempt is called in the plan: "attempts" unless the data says otherwise. */
	public String getAttemptUnit()
	{
		return attemptUnit == null ? "attempts" : attemptUnit;
	}

	public Requirement getSkillRequirement()
	{
		return skillRequirement;
	}

	public List<Ingredient> getIngredients()
	{
		return ingredients;
	}

	public Integer getGameItemId()
	{
		return gameItemId;
	}
}

package com.nowwhat.model;

import java.util.List;

/**
 * The result of planning a route to a Goal: an ordered sequence of concrete
 * steps, plus anything the planner couldn't resolve (missing training
 * method data, missing item source data, circular crafting recipes, etc).
 */
public class Path
{
	private final Goal goal;
	private final boolean alreadyComplete;
	private final List<PathStep> steps;
	private final List<String> warnings;
	private final boolean requirementsAlreadyMet;

	public Path(Goal goal, boolean alreadyComplete, List<PathStep> steps, List<String> warnings)
	{
		this(goal, alreadyComplete, steps, warnings, false);
	}

	public Path(Goal goal, boolean alreadyComplete, List<PathStep> steps, List<String> warnings,
		boolean requirementsAlreadyMet)
	{
		this.goal = goal;
		this.alreadyComplete = alreadyComplete;
		this.steps = steps;
		this.warnings = warnings;
		this.requirementsAlreadyMet = requirementsAlreadyMet;
	}

	public Goal getGoal()
	{
		return goal;
	}

	public boolean isAlreadyComplete()
	{
		return alreadyComplete;
	}

	public List<PathStep> getSteps()
	{
		return steps;
	}

	public List<String> getWarnings()
	{
		return warnings;
	}

	/**
	 * True when nothing stands in the way: every requirement is already
	 * satisfied, but the activity itself isn't something you "complete" (a
	 * boss, a minigame), so it can't be reported as already done either.
	 * Without this the panel shows a one-item plan that reads like a bug.
	 */
	public boolean isRequirementsAlreadyMet()
	{
		return requirementsAlreadyMet;
	}
}

package com.nowwhat.model;

import java.util.Collections;
import java.util.List;

/**
 * One concrete, actionable step in a Path. Unlike a Requirement (which just
 * states a gate that must be met), a PathStep says what to actually go do.
 * <p>
 * A TRAIN_SKILL step covers a level range and may carry more than one
 * {@link Option} - e.g. when tick manipulation is disallowed, a level
 * bracket often has several genuinely different non-tick-manip methods
 * (Motherlode Mine, Blast Mine, gem rocks, calcified rocks...) rather than
 * one clear winner, and the planner presents all of them instead of
 * arbitrarily picking one. Every other step type carries exactly one
 * Option, kept in `alternatives` for a single consistent shape.
 */
public class PathStep
{
	public enum Type
	{
		/** Train a skill from one level to another - see `alternatives` for the method(s). */
		TRAIN_SKILL,
		/** Acquire N of an item via buying, a shop, or a crafting action. */
		ACQUIRE_ITEM,
		/** Kill a boss/monster some number of times for a drop. */
		KILL_BOSS,
		/** Complete a quest/diary tier/other Activity as a prerequisite. */
		DO_ACTIVITY,
		/**
		 * Complete a quest. Split out from DO_ACTIVITY so the panel can gather a
		 * run of them into one list and hand the actual walkthrough to Quest
		 * Helper, rather than spending a screen of the plan restating what a far
		 * better plugin already does.
		 */
		DO_QUEST,
		/** Complete an Achievement Diary tier. Handed off the same way as DO_QUEST. */
		DO_DIARY,
		/** The planner couldn't find data to expand this further - informational only. */
		INFO
	}

	/** One concrete way to accomplish a step - a named method, a place to buy from, etc. */
	public static class Option
	{
		private final String title;
		private final String detail;
		private final String wikiUrl;
		private final List<String> quests;
		/**
		 * Flags rather than text in the title. They used to be appended as
		 * "[Wilderness - PvP risk]" and "[Tick manipulation]", which made an
		 * already-wrapping name longer and left the panel no way to render them
		 * as anything but more prose.
		 */
		private final boolean pvpRisk;
		private final boolean tickManipulation;
		/** Null means no judgement was recorded; see {@link TrainingMethod.Attention}. */
		private final TrainingMethod.Attention attention;
		/** How much of what this option's range will use up; empty when unknown. */
		private final List<Needed> needed;
		/**
		 * The scannable fact - "~3 hrs - 160k xp/hr". Kept apart from the note
		 * because welding it on the end made every note a five-line paragraph
		 * whose last clause was the only part most players were looking for.
		 */
		private final String meta;
		/**
		 * The hourly rate behind {@link #getMeta()}, kept as a number as well as
		 * a formatted string. The panel merges consecutive level brackets that
		 * resolve to the same method into one step, and a merged step's estimate
		 * has to be recomputed over the whole range - which cannot be done by
		 * reading "~3 hrs" back out of a label.
		 */
		private final Integer xpPerHour;
		/**
		 * What to wear and what to bring for this method, in the same loose
		 * prose the activity gear lines use, so the panel turns both into the
		 * same pictures.
		 * <p>
		 * A training step used to answer "where" and stop. "Maniacal monkeys"
		 * is a fine answer to where, and no answer at all to the question the
		 * player actually has standing in a bank: what do I take.
		 */
		private final List<String> gear;
		private final List<String> supplies;

		public Option(String title, String detail, String wikiUrl)
		{
			this(title, detail, wikiUrl, Collections.emptyList(), false, false);
		}

		public Option(String title, String detail, String wikiUrl, List<String> quests)
		{
			this(title, detail, wikiUrl, quests, false, false);
		}

		public Option(String title, String detail, String wikiUrl, List<String> quests,
			boolean pvpRisk, boolean tickManipulation)
		{
			this(title, detail, null, wikiUrl, quests, pvpRisk, tickManipulation);
		}

		public Option(String title, String detail, String meta, String wikiUrl,
			List<String> quests, boolean pvpRisk, boolean tickManipulation)
		{
			this(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation, null);
		}

		public Option(String title, String detail, String meta, String wikiUrl,
			List<String> quests, boolean pvpRisk, boolean tickManipulation, Integer xpPerHour)
		{
			this(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation, xpPerHour,
				Collections.emptyList(), Collections.emptyList());
		}

		public Option(String title, String detail, String meta, String wikiUrl,
			List<String> quests, boolean pvpRisk, boolean tickManipulation, Integer xpPerHour,
			List<String> gear, List<String> supplies)
		{
			this(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation, xpPerHour,
				gear, supplies, null, Collections.emptyList());
		}

		private Option(String title, String detail, String meta, String wikiUrl,
			List<String> quests, boolean pvpRisk, boolean tickManipulation, Integer xpPerHour,
			List<String> gear, List<String> supplies, TrainingMethod.Attention attention,
			List<Needed> needed)
		{
			this.needed = needed == null ? Collections.emptyList() : needed;
			this.attention = attention;
			this.gear = gear == null ? Collections.emptyList() : gear;
			this.supplies = supplies == null ? Collections.emptyList() : supplies;
			this.xpPerHour = xpPerHour;
			this.meta = meta;
			this.title = title;
			this.detail = detail;
			this.wikiUrl = wikiUrl;
			this.quests = quests == null ? Collections.emptyList() : quests;
			this.pvpRisk = pvpRisk;
			this.tickManipulation = tickManipulation;
		}

		public List<String> getGear()
		{
			return gear;
		}

		public List<String> getSupplies()
		{
			return supplies;
		}

		/** True when there is anything to show about what to take. */
		public boolean hasPreparation()
		{
			return !gear.isEmpty() || !supplies.isEmpty();
		}

		/** One line of a shopping list: an item and how many of it. */
		public static final class Needed
		{
			private final String item;
			private final long quantity;

			public Needed(String item, long quantity)
			{
				this.item = item;
				this.quantity = quantity;
			}

			public String getItem()
			{
				return item;
			}

			public long getQuantity()
			{
				return quantity;
			}
		}

		/** This option with gear and supplies attached - everything else unchanged. */
		public Option withPreparation(List<String> gear, List<String> supplies)
		{
			return new Option(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation,
				xpPerHour, gear, supplies, attention, needed);
		}

		/**
		 * This option with its shopping list attached. Computed per level range
		 * rather than stored on the method, because the answer <em>is</em> the
		 * range: the same method costs 44,000 bones over one stretch and 3,000
		 * over another.
		 */
		public Option withNeeded(List<Needed> needed)
		{
			return new Option(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation,
				xpPerHour, gear, supplies, attention, needed);
		}

		/** Empty when the method does not consume anything countable. */
		public List<Needed> getNeeded()
		{
			return needed;
		}

		/**
		 * This option with an attention judgement attached - everything else
		 * unchanged. A wither rather than another constructor parameter: the
		 * constructor chain is already five deep, and every existing caller
		 * means "no judgement recorded" anyway.
		 */
		public Option withAttention(TrainingMethod.Attention attention)
		{
			return new Option(title, detail, meta, wikiUrl, quests, pvpRisk, tickManipulation,
				xpPerHour, gear, supplies, attention, needed);
		}

		/**
		 * Null when the method behind this option carries no attention
		 * judgement, which is not the same as judging it ordinary.
		 */
		public TrainingMethod.Attention getAttention()
		{
			return attention;
		}

		/** Null when the method has no hourly rate, e.g. a quest route. */
		public String getMeta()
		{
			return meta;
		}

		/** Null when the method has no hourly rate, e.g. a quest route. */
		public Integer getXpPerHour()
		{
			return xpPerHour;
		}

		public boolean isPvpRisk()
		{
			return pvpRisk;
		}

		public boolean isTickManipulation()
		{
			return tickManipulation;
		}

		/** Quests that complete this option outright; empty for an ordinary method. */
		public List<String> getQuests()
		{
			return quests;
		}

		public String getTitle()
		{
			return title;
		}

		public String getDetail()
		{
			return detail;
		}

		public String getWikiUrl()
		{
			return wikiUrl;
		}
	}

	private final Type type;
	private final String title;
	private final String detail;
	private final String wikiUrl;
	private final List<Option> alternatives;
	/**
	 * True for the one step that <em>is</em> the goal, as opposed to something
	 * needed on the way to it. The panel groups runs of prerequisite quests and
	 * diaries into a single "needed first" list, and the destination must not
	 * be swept into that list alongside them.
	 */
	private final boolean target;
	/**
	 * Experience this step costs, or 0 where the notion doesn't apply. Carried
	 * as a number so the panel can place it where its layout wants it, instead
	 * of having it welded into the title.
	 */
	private long xpCost;
	/**
	 * The level range a TRAIN_SKILL step covers, and the skill it covers it in.
	 * Null/0 for every other step type. Carried as numbers because the panel
	 * has to be able to restate a run of brackets as one range - recovering
	 * "76" and "99" by parsing the title back apart is not a thing to build on.
	 */
	private String skill;
	private int levelFrom;
	private int levelTo;

	/** Single-option convenience constructor - used by every step type except TRAIN_SKILL. */
	public PathStep(Type type, String title, String detail, String wikiUrl)
	{
		this(type, title, detail, wikiUrl, false);
	}

	/** As above, for the step that is the goal itself. */
	public PathStep(Type type, String title, String detail, String wikiUrl, boolean target)
	{
		this.target = target;
		this.type = type;
		this.title = title;
		this.detail = detail;
		this.wikiUrl = wikiUrl;
		this.alternatives = Collections.singletonList(new Option(title, detail, wikiUrl));
	}

	/** Multi-option constructor - used by TRAIN_SKILL when a level range has several viable methods. */
	public PathStep(Type type, String title, List<Option> alternatives)
	{
		this.target = false;
		this.type = type;
		this.title = title;
		this.alternatives = alternatives;
		// detail/wikiUrl mirror the first (highest-priority) alternative for
		// any rendering path that only looks at the single-option fields.
		Option first = alternatives.isEmpty() ? null : alternatives.get(0);
		this.detail = first != null ? first.getDetail() : null;
		this.wikiUrl = first != null ? first.getWikiUrl() : null;
	}

	public boolean isTarget()
	{
		return target;
	}

	/**
	 * True for a step nothing forces: it closes the gap to the stats the wiki
	 * recommends for the goal, not to anything the game checks. The panel says
	 * so, because "train Ranged to 85" beside steps the game does insist on
	 * reads as one more thing standing in the way.
	 */
	private boolean recommended;

	public boolean isRecommended()
	{
		return recommended;
	}

	public PathStep asRecommended()
	{
		this.recommended = true;
		return this;
	}

	public long getXpCost()
	{
		return xpCost;
	}

	public PathStep withXpCost(long xp)
	{
		this.xpCost = xp;
		return this;
	}

	public PathStep withLevels(String skill, int levelFrom, int levelTo)
	{
		this.skill = skill;
		this.levelFrom = levelFrom;
		this.levelTo = levelTo;
		return this;
	}

	/** True when this step carries a real level range, i.e. it trains a skill. */
	public boolean hasLevels()
	{
		return skill != null && levelTo > levelFrom;
	}

	public String getSkill()
	{
		return skill;
	}

	public int getLevelFrom()
	{
		return levelFrom;
	}

	public int getLevelTo()
	{
		return levelTo;
	}

	public Type getType()
	{
		return type;
	}

	public String getTitle()
	{
		return title;
	}

	public String getDetail()
	{
		return detail;
	}

	public String getWikiUrl()
	{
		return wikiUrl;
	}

	/** Always has at least one entry when the step has any content at all. */
	public List<Option> getAlternatives()
	{
		return alternatives;
	}

	public boolean hasChoice()
	{
		return alternatives.size() > 1;
	}
}

package com.nowwhat.model;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * A plain-data snapshot of the logged-in player's progress, rebuilt on every
 * refresh cycle (e.g. on GameTick or every N minutes) by NowWhatPlugin.
 * The SuggestionEngine only ever reads from this - it never talks to the
 * RuneLite Client directly, which keeps the engine unit-testable.
 */
public class PlayerState
{
	private final Map<String, Integer> skillLevels = new HashMap<>();
	private final Map<String, Long> skillXp = new java.util.HashMap<>();
	private final Set<String> completedQuests = new HashSet<>();
	private int questPoints;
	private int combatLevel;
	/** Key format "REGION_TIER", e.g. "ARDOUGNE_HARD" */
	private final Set<String> completedDiaryTiers = new HashSet<>();
	private final Map<String, Integer> bossKillCounts = new HashMap<>();
	private final Set<String> completedCombatAchievementTiers = new HashSet<>();
	/** Running Combat Achievement points total, or -1 while it has not been read. */
	private int combatAchievementPoints = -1;
	/** Collection log slots the player owns, by item name. Only reliable once the log has been opened once. */
	private final Set<String> collectionLogUnlocks = new HashSet<>();
	private int collectionLogSlotsTotal;
	private int collectionLogSlotsObtained;

	// What the player owns, keyed by RuneLite item id, summed across bank,
	// inventory and worn equipment. See ItemTracker for why the bank half of
	// this is a snapshot rather than live.
	private Map<Integer, Integer> ownedItems = new HashMap<>();
	private Set<Integer> equippedItems = new HashSet<>();
	private boolean bankSnapshotAvailable;

	public void setSkillLevel(String skill, int level)
	{
		skillLevels.put(skill.toUpperCase(), level);
	}

	/**
	 * Current experience in a skill, or 0 when it is not known.
	 * <p>
	 * Levels alone were enough while every goal named one skill: you are 76
	 * Thieving, you want 99, the xp between those is the plan. A total level
	 * goal has to compare the <em>next</em> level in 23 skills against each
	 * other, and "level 62" could be one xp short of 63 or the whole bracket
	 * away. Without the xp the cheapest-first ordering is guesswork dressed as
	 * arithmetic.
	 */
	public long getSkillXp(String skill)
	{
		Long xp = skillXp.get(skill.toUpperCase());
		return xp == null ? 0 : xp;
	}

	public void setSkillXp(String skill, long xp)
	{
		skillXp.put(skill.toUpperCase(), xp);
	}

	/** Every level read from the client, for the panel to mark finished steps. */
	public Map<String, Integer> getSkillLevels()
	{
		return java.util.Collections.unmodifiableMap(skillLevels);
	}

	public int getSkillLevel(String skill)
	{
		return skillLevels.getOrDefault(skill.toUpperCase(), 1);
	}

	public void addCompletedQuest(String questName)
	{
		completedQuests.add(questName);
	}

	public boolean isQuestComplete(String questName)
	{
		return completedQuests.contains(questName);
	}

	public void setQuestPoints(int qp)
	{
		this.questPoints = qp;
	}

	public int getQuestPoints()
	{
		return questPoints;
	}

	public void setCombatLevel(int level)
	{
		this.combatLevel = level;
	}

	public int getCombatLevel()
	{
		return combatLevel;
	}

	public void addCompletedDiaryTier(String regionTierKey)
	{
		completedDiaryTiers.add(regionTierKey.toUpperCase());
	}

	public boolean isDiaryTierComplete(String regionTierKey)
	{
		return completedDiaryTiers.contains(regionTierKey.toUpperCase());
	}

	public void setBossKillCount(String bossName, int kc)
	{
		bossKillCounts.put(bossName.toUpperCase(), kc);
	}

	public int getBossKillCount(String bossName)
	{
		return bossKillCounts.getOrDefault(bossName.toUpperCase(), 0);
	}

	public void addCompletedCombatAchievementTier(String tier)
	{
		completedCombatAchievementTiers.add(tier.toUpperCase());
	}

	public boolean isCombatAchievementTierComplete(String tier)
	{
		return completedCombatAchievementTiers.contains(tier.toUpperCase());
	}

	public void setCombatAchievementPoints(int points)
	{
		combatAchievementPoints = points;
	}

	/** -1 when unknown, which is not the same as having none. */
	public int getCombatAchievementPoints()
	{
		return combatAchievementPoints;
	}

	public void addCollectionLogUnlock(String itemName)
	{
		collectionLogUnlocks.add(itemName);
	}

	public boolean hasCollectionLogUnlock(String itemName)
	{
		return collectionLogUnlocks.contains(itemName);
	}

	public void setCollectionLogProgress(int obtained, int total)
	{
		this.collectionLogSlotsObtained = obtained;
		this.collectionLogSlotsTotal = total;
	}

	public int getCollectionLogSlotsObtained()
	{
		return collectionLogSlotsObtained;
	}

	public int getCollectionLogSlotsTotal()
	{
		return collectionLogSlotsTotal;
	}

	public void setOwnedItems(Map<Integer, Integer> items)
	{
		this.ownedItems = items;
	}

	/** How many of this item the player has across bank, inventory and equipment. */
	public int getOwnedCount(int itemId)
	{
		return ownedItems.getOrDefault(itemId, 0);
	}

	public void setEquippedItems(Set<Integer> items)
	{
		this.equippedItems = items;
	}

	public boolean isEquipped(int itemId)
	{
		return equippedItems.contains(itemId);
	}

	public Set<Integer> getEquippedItems()
	{
		return equippedItems;
	}

	/**
	 * False until the player has opened their bank at least once. A plan built
	 * without this should say so rather than assume an empty bank.
	 */
	public boolean isBankSnapshotAvailable()
	{
		return bankSnapshotAvailable;
	}

	public void setBankSnapshotAvailable(boolean available)
	{
		this.bankSnapshotAvailable = available;
	}
}

package com.nowwhat.model;

import java.util.List;

/**
 * Result of resolving "what do I need to do to unlock X".
 */
public class PrerequisiteChain
{
	private final Activity target;
	private final boolean alreadyUnlocked;
	/** Other activities (quests/diary tiers) you must complete first, in the order to do them. */
	private final List<Activity> requiredActivitiesInOrder;
	/** Requirements that aren't themselves a trackable activity (skill levels, KC, QP, combat level). */
	private final List<Requirement> standaloneRequirements;
	/** Requirement values referenced (e.g. a quest name) that weren't found in the activity database - can't be chained further. */
	private final List<String> unresolvedReferences;

	public PrerequisiteChain(Activity target, boolean alreadyUnlocked, List<Activity> requiredActivitiesInOrder,
		List<Requirement> standaloneRequirements, List<String> unresolvedReferences)
	{
		this.target = target;
		this.alreadyUnlocked = alreadyUnlocked;
		this.requiredActivitiesInOrder = requiredActivitiesInOrder;
		this.standaloneRequirements = standaloneRequirements;
		this.unresolvedReferences = unresolvedReferences;
	}

	public Activity getTarget()
	{
		return target;
	}

	public boolean isAlreadyUnlocked()
	{
		return alreadyUnlocked;
	}

	public List<Activity> getRequiredActivitiesInOrder()
	{
		return requiredActivitiesInOrder;
	}

	public List<Requirement> getStandaloneRequirements()
	{
		return standaloneRequirements;
	}

	public List<String> getUnresolvedReferences()
	{
		return unresolvedReferences;
	}
}

package com.nowwhat.model;

import java.util.List;

/**
 * A single prerequisite gate for an {@link Activity}.
 * <p>
 * Every activity in activities.json carries zero or more of these. The
 * {@link com.nowwhat.engine.SuggestionEngine} evaluates each one against
 * live {@link PlayerState} and only surfaces activities where every
 * requirement is satisfied.
 */
public class Requirement
{
	public enum Type
	{
		/** value = OSRS skill name (e.g. "AGILITY"), threshold = level */
		SKILL_LEVEL,
		/** value = quest name exactly as it appears in the RuneLite Quest enum */
		QUEST_COMPLETE,
		/** value = "REGION_TIER" e.g. "ARDOUGNE_MEDIUM" */
		DIARY_COMPLETE,
		/** value = combat achievement tier key, e.g. "CA_GRANDMASTER" (matches the activity id) */
		COMBAT_ACHIEVEMENT_TIER,
		/** value = boss/activity name as tracked in hiscores, threshold = kill count */
		BOSS_KC,
		/** value = quest point total, threshold = minimum QP */
		QUEST_POINTS,
		/** value = combat level, threshold = minimum combat level */
		COMBAT_LEVEL,
		/**
		 * value = comma-separated skill names (e.g. "ATTACK,STRENGTH"),
		 * threshold = minimum sum of those skills' levels. Real gates like
		 * this exist in OSRS (Warriors' Guild's 130 combined Attack+Strength
		 * alternative being the canonical example).
		 */
		COMBINED_SKILL_LEVEL,
		/**
		 * Satisfied if ANY ONE of `anyOf` is satisfied - mirrors the OR-groups
		 * the OSRS Wiki's `achievement_requirement` bucket already models
		 * (e.g. Warriors' Guild-style "99 Attack OR 99 Strength" gates).
		 * value/threshold are unused for this type; only `anyOf` matters.
		 * Only one level of OR-nesting is supported for now - an ANY_OF
		 * whose children are themselves ANY_OF isn't handled specially, since
		 * nothing in the bundled sample data needed it yet. Worth revisiting
		 * once real Bucket-derived data shows how deep the nesting actually
		 * gets in practice.
		 */
		ANY_OF,
		/**
		 * value = RuneLite item id, threshold = how many are needed (0/1 means
		 * "own one"). Gear gates are real - a boss recommendation that assumes
		 * a blowpipe is wrong for someone who doesn't have one - and this is
		 * how the content data expresses them.
		 */
		ITEM_OWNED
	}

	private Type type;
	private String value;
	private int threshold;
	/** ANY_OF only: the alternatives, any one of which satisfies this requirement. */
	private List<Requirement> anyOf;
	/**
	 * Optional: a short, concrete suggestion for how to actually satisfy this
	 * requirement - a training method, a course, a shop, etc. This is the
	 * piece existing tools (Goal Planner, QuestPath) don't provide: they'll
	 * tell you that you need 47 Agility, but not the fastest reasonable way
	 * to get there from where you are. Null is fine for requirements where
	 * "just go do the thing" is self-explanatory (e.g. QUEST_COMPLETE).
	 */
	private String hint;

	public Requirement()
	{
	}

	public Requirement(Type type, String value, int threshold)
	{
		this.type = type;
		this.value = value;
		this.threshold = threshold;
	}

	/** Builds an ANY_OF requirement from its alternatives - used by both production data loading callers and tests. */
	public static Requirement anyOf(Requirement... children)
	{
		Requirement req = new Requirement();
		req.type = Type.ANY_OF;
		req.anyOf = java.util.Arrays.asList(children);
		return req;
	}

	public Type getType()
	{
		return type;
	}

	public String getValue()
	{
		return value;
	}

	public int getThreshold()
	{
		return threshold;
	}

	public String getHint()
	{
		return hint;
	}

	public List<Requirement> getAnyOf()
	{
		return anyOf == null ? java.util.Collections.emptyList() : anyOf;
	}
}

package com.nowwhat.model;

/**
 * One way to train a skill, valid over [minLevel, maxLevel). Loaded from
 * methods.json. The path planner walks a skill's methods to build a
 * sequence of TRAIN_SKILL steps covering a level range.
 * <p>
 * Ranges for the same skill are allowed to overlap - a tick-manipulation
 * method and its calmer fallback commonly cover the exact same level
 * bracket at very different xp/hr and very different click intensity.
 * SkillPathPlanner picks between overlapping candidates based on the
 * caller's tick-manipulation preference rather than always taking the
 * highest xp/hr option.
 * <p>
 * {@link Risk} is the same idea applied to danger rather than click rate:
 * a method that can only be trained in the Wilderness is not interchangeable
 * with an equally fast safe one, and a plan that quotes an xp/hr figure
 * without saying where it's earned is hiding the part a player would most
 * want to weigh.
 */
public class TrainingMethod
{
	public enum Intensity
	{
		/** Ordinary play speed - the default assumption if a method omits this field. */
		NORMAL,
		/**
		 * Requires precise, repeated timing against the game's tick rate
		 * (dropping/reclicking, 3-ticking, etc.) to reach the stated xp/hr.
		 * Legitimate and wiki-documented, but far more click-intensive than
		 * a NORMAL method - many players deliberately avoid it.
		 */
		TICK_MANIPULATION
	}

	/**
	 * How much of the player's attention a method actually costs, which is a
	 * separate question from how fast it is and from whether it is tick
	 * manipulation.
	 * <p>
	 * Bloodwood is why this field exists. The wiki classes it as the fastest
	 * Woodcutting method that is not tick manipulation, so it is correctly
	 * {@link Intensity#NORMAL} - but its 130k/hr assumes an efficient two-tick
	 * cycle filling sap buckets across three trees at once, and the panel was
	 * presenting that beside an ironwood tree you click once every four minutes
	 * as though the only difference between them were the xp. That is the same
	 * kind of hidden cost as {@link Risk#PVP}: real, decision-changing, and
	 * invisible in an xp/hr figure, so it is recorded as data and labelled
	 * rather than left for the player to already know.
	 * <p>
	 * Unset is not {@link #ORDINARY}. A method with no value here has not been
	 * judged yet and gets no label, because printing "ordinary" over a method
	 * nobody has assessed would be inventing a fact. Tick-manipulation methods
	 * are deliberately left unset too - they already carry their own label and
	 * do not need a second one saying the same thing.
	 */
	public enum Attention
	{
		/** Little input: one tree every few minutes, or no banking to do. */
		AFK,
		/** Ordinary clicking - assessed and unremarkable. Carries no label. */
		ORDINARY,
		/** Near-continuous input to reach the stated rate, without being tick manipulation. */
		DEMANDING
	}

	/**
	 * One counted thing an action of this method uses up, and how many of it per
	 * action.
	 * <p>
	 * Recorded so the panel can answer the question a player actually goes to a
	 * bank screen with. "Gilded altar with dragon bones, 643k xp/hr, ~17 hours"
	 * tells you the time but not the shopping list, and the arithmetic to get
	 * from one to the other - 11.1M xp divided by 252 xp a bone - is exactly the
	 * sort of thing people leave the client to do in a calculator.
	 */
	public static class Consumed
	{
		private String item;
		private double each = 1;

		public Consumed()
		{
		}

		public Consumed(String item, double each)
		{
			this.item = item;
			this.each = each;
		}

		public String getItem()
		{
			return item;
		}

		/** How many per action; fractional for something used across several actions. */
		public double getEach()
		{
			return each <= 0 ? 1 : each;
		}
	}

	public enum Risk
	{
		/** No PvP exposure - the default assumption if a method omits this field. */
		SAFE,
		/**
		 * Trained in the Wilderness, where other players can attack you and
		 * your gear and caught stock are lost on death. This is a cost that
		 * doesn't show up anywhere in an xp/hr figure, so it's recorded as
		 * data and labelled in the plan rather than left for the player to
		 * already know.
		 */
		PVP
	}

	private String skill;
	private int minLevel;
	private int maxLevel;
	private String name;
	private Integer xpPerHour;
	private String notes;
	private String wikiUrl;
	/** Defaults to NORMAL when absent from methods.json (see getIntensity()). */
	private Intensity intensity;
	/** Defaults to SAFE when absent from methods.json (see getRisk()). */
	private Risk risk;
	/** Null when absent from methods.json, meaning "not judged" - see {@link Attention}. */
	private Attention attention;
	/**
	 * The xp one action of this method gives - one bone offered, one bow strung,
	 * one gem cut. Null for a method whose xp does not come in countable units,
	 * such as a minigame or a stretch of combat.
	 */
	private Double xpPerAction;
	/** What one action uses up. Empty for a method that consumes nothing. */
	private java.util.List<Consumed> consumes;
	/**
	 * Quests that cover this level range outright, for a method that is "do
	 * these quests" rather than an hourly grind. Named here rather than buried
	 * in prose so the panel can list them and hand them to Quest Helper the
	 * same way it hands over a quest prerequisite.
	 */
	private java.util.List<String> quests;
	/**
	 * What to wear for this method, and what to bring, written the same way the
	 * activity gear lines are so the panel can picture both. Recorded on the
	 * lowest bracket of a method and shared up the rest at load, exactly as the
	 * note is.
	 */
	private java.util.List<String> gear;
	private java.util.List<String> supplies;
	/**
	 * An activity id to take the kit from, for a method that <i>is</i> an
	 * activity the database already describes.
	 * <p>
	 * Wintertodt is the case this exists for. It is a Firemaking method and a
	 * minigame with four warm-clothing slots and a hammer, and the minigame
	 * entry already says so - so planning 99 Firemaking used to name Wintertodt
	 * and then say nothing at all about what to wear, while clicking the same
	 * minigame in the suggestion list pictured the whole kit. Two copies of one
	 * answer was the wrong fix; this borrows it, exactly as
	 * {@code Activity.preparationFrom} does for a collection log slot that is
	 * really a boss.
	 */
	private String activity;

	/** No-arg constructor used by Gson when loading methods.json. */
	public TrainingMethod()
	{
	}

	/** Convenience constructor for safe methods - equivalent to passing {@link Risk#SAFE}. */
	public TrainingMethod(String skill, int minLevel, int maxLevel, String name, Integer xpPerHour,
		String notes, String wikiUrl, Intensity intensity)
	{
		this(skill, minLevel, maxLevel, name, xpPerHour, notes, wikiUrl, intensity, Risk.SAFE);
	}

	/** Full constructor for programmatic construction (tests). */
	public TrainingMethod(String skill, int minLevel, int maxLevel, String name, Integer xpPerHour,
		String notes, String wikiUrl, Intensity intensity, Risk risk)
	{
		this.risk = risk;
		this.skill = skill;
		this.minLevel = minLevel;
		this.maxLevel = maxLevel;
		this.name = name;
		this.xpPerHour = xpPerHour;
		this.notes = notes;
		this.wikiUrl = wikiUrl;
		this.intensity = intensity;
	}

	public String getSkill()
	{
		return skill;
	}

	public int getMinLevel()
	{
		return minLevel;
	}

	public int getMaxLevel()
	{
		return maxLevel;
	}

	public String getName()
	{
		return name;
	}

	public Integer getXpPerHour()
	{
		return xpPerHour;
	}

	public String getNotes()
	{
		return notes;
	}

	/**
	 * Fills in a note this row left blank, from a sibling bracket of the same
	 * method.
	 * <p>
	 * A method split into level brackets records its note once, on the lowest
	 * bracket, so the panel does not print the same paragraph under nine
	 * headings. But a plan that starts above that bracket - Thieving from 76,
	 * where the Knights of Ardougne note lives on the 55-60 row - would then
	 * never see the note at all, which is exactly where it is most wanted. The
	 * database copies it down the brackets at load time and the panel's own
	 * repeat check stops it printing twice.
	 */
	public void inheritNotes(String inherited)
	{
		if (notes == null || notes.isEmpty())
		{
			notes = inherited;
		}
	}

	public String getWikiUrl()
	{
		return wikiUrl;
	}

	public Intensity getIntensity()
	{
		return intensity == null ? Intensity.NORMAL : intensity;
	}

	public boolean isTickManipulation()
	{
		return getIntensity() == Intensity.TICK_MANIPULATION;
	}

	/** Never null - a method with no quest route returns an empty list. */
	public java.util.List<String> getGear()
	{
		return gear == null ? java.util.Collections.emptyList() : gear;
	}

	public java.util.List<String> getSupplies()
	{
		return supplies == null ? java.util.Collections.emptyList() : supplies;
	}

	/** Takes the gear recorded on the lowest bracket of the same method. */
	public void inheritPreparation(java.util.List<String> inheritedGear,
		java.util.List<String> inheritedSupplies)
	{
		if (getGear().isEmpty() && inheritedGear != null)
		{
			gear = inheritedGear;
		}
		if (getSupplies().isEmpty() && inheritedSupplies != null)
		{
			supplies = inheritedSupplies;
		}
	}

	/**
	 * Null unless this method's xp arrives in countable actions. Paired with
	 * {@link #getConsumes()}: together they are what turns a level range into a
	 * shopping list.
	 */
	public Double getXpPerAction()
	{
		return xpPerAction;
	}

	/** Never null - a method that consumes nothing returns an empty list. */
	public java.util.List<Consumed> getConsumes()
	{
		return consumes == null ? java.util.Collections.emptyList() : consumes;
	}

	/** True when this method can say how much of what a level range will cost. */
	public boolean hasShoppingList()
	{
		return xpPerAction != null && xpPerAction > 0 && !getConsumes().isEmpty();
	}

	/** Null for an ordinary method; an activity id for one that borrows its kit. */
	public String getActivity()
	{
		return activity;
	}

	public java.util.List<String> getQuests()
	{
		return quests == null ? java.util.Collections.emptyList() : quests;
	}

	public Risk getRisk()
	{
		return risk == null ? Risk.SAFE : risk;
	}

	/**
	 * Null when the method carries no attention judgement at all, which is
	 * deliberately distinct from {@link Attention#ORDINARY}.
	 */
	public Attention getAttention()
	{
		return attention;
	}

	/**
	 * Sets the attention judgement, for programmatic construction - tests and
	 * the diagnostic harnesses, which build methods rather than loading JSON.
	 */
	public TrainingMethod withAttention(Attention attention)
	{
		this.attention = attention;
		return this;
	}

	/**
	 * Sets the countable-action fields, for programmatic construction - tests
	 * and the diagnostic harnesses, which build methods rather than loading
	 * JSON.
	 */
	public TrainingMethod withConsumption(double xpPerAction, Consumed... consumes)
	{
		this.xpPerAction = xpPerAction;
		this.consumes = java.util.Arrays.asList(consumes);
		return this;
	}

	/** Takes the attention judgement recorded on the lowest bracket of the same method. */
	public void inheritAttention(Attention inherited)
	{
		if (attention == null)
		{
			attention = inherited;
		}
	}

	public boolean isPvpRisk()
	{
		return getRisk() == Risk.PVP;
	}
}

package com.nowwhat;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.PlayerState;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JSpinner;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A rendered plan folds away the steps the player has since finished.
 * <p>
 * The plan used to be rendered once and then left alone while the player went
 * and did it, so a step they had completed stayed on the list and the only way
 * to reach the step they were on was to scroll past the ones they were not.
 */
public class FinishedStepsTest
{
	private static final List<String> ALL_SKILLS = Arrays.asList(
		"ATTACK", "DEFENCE", "STRENGTH", "HITPOINTS", "RANGED", "PRAYER", "MAGIC",
		"COOKING", "WOODCUTTING", "FLETCHING", "FISHING", "FIREMAKING", "CRAFTING",
		"SMITHING", "MINING", "HERBLORE", "AGILITY", "THIEVING", "SLAYER", "FARMING",
		"RUNECRAFT", "HUNTER", "CONSTRUCTION");

	@Test
	public void aStepThePlayerHasSinceFinishedFoldsAway() throws Exception
	{
		// Planned at 70 everywhere, so every skill is a step towards 80.
		PlayerState planning = new PlayerState();
		for (String skill : ALL_SKILLS)
		{
			planning.setSkillLevel(skill, 70);
		}

		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			built[0] = panel(planning);
			planBaseStats(built[0], 80);
		});

		List<String> before = text(built[0]);
		assertTrue("expected a Prayer step in the plan: " + before,
			before.stream().anyMatch(line -> line.contains("Prayer 70")));
		assertFalse("nothing is finished yet, so nothing should offer to unfold: " + before,
			before.stream().anyMatch(line -> line.contains("done already")));

		// Now the player has Prayer 80 and nothing else has moved.
		java.util.Map<String, Integer> now = new java.util.HashMap<>();
		for (String skill : ALL_SKILLS)
		{
			now.put(skill, 70);
		}
		now.put("PRAYER", 80);
		SwingUtilities.invokeAndWait(() -> built[0].setProgress(now));

		List<String> after = text(built[0]);
		assertTrue("expected an offer to unfold the finished step: " + after,
			after.stream().anyMatch(line -> line.contains("done already")));
		assertFalse("the finished Prayer step should be folded away: " + after,
			after.stream().anyMatch(line -> line.contains("Prayer 70")));
		assertTrue("the unfinished steps should still be there: " + after,
			after.stream().anyMatch(line -> line.contains("Agility 70")));
	}

	/** Unfolding brings them back, marked as done rather than as work left. */
	@Test
	public void unfoldingShowsTheFinishedStepMarkedDone() throws Exception
	{
		PlayerState planning = new PlayerState();
		for (String skill : ALL_SKILLS)
		{
			planning.setSkillLevel(skill, 70);
		}

		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			built[0] = panel(planning);
			planBaseStats(built[0], 80);
			java.util.Map<String, Integer> now = new java.util.HashMap<>();
			for (String skill : ALL_SKILLS)
			{
				now.put(skill, 70);
			}
			now.put("PRAYER", 80);
			built[0].setProgress(now);
			click(built[0], "done already");
		});

		List<String> after = text(built[0]);
		// The caption and the title are separate labels, and the caption is
		// drawn upper-case, so what the player reads is "STEP 8 . 1.2M XP . DONE"
		// above "Prayer 70 -> 80".
		assertTrue("expected a step captioned done: " + after,
			after.stream().anyMatch(line ->
				line.toLowerCase(java.util.Locale.ROOT).contains(" done")));
		assertTrue("expected the finished step back: " + after,
			after.stream().anyMatch(line -> line.contains("Prayer 70")));
	}

	/**
	 * A quest on the way to the goal folds away once the game says it is done.
	 * The plan is not planned again while it is open, so a quest finished since
	 * used to stay listed as still to do.
	 */
	@Test
	public void aQuestFinishedSinceThePlanWasMadeFoldsAway() throws Exception
	{
		Gson gson = new Gson();
		ActivityDatabase ad = new ActivityDatabase(gson);
		ad.load();
		com.nowwhat.model.Activity goal = ad.getAllActivities().stream()
			.filter(a -> "Desert Treasure I".equals(a.getName()))
			.findFirst().orElseThrow(AssertionError::new);

		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			built[0] = panel(new PlayerState());
			built[0].planFor(goal);
		});

		List<String> before = text(built[0]);
		assertTrue("expected The Dig Site among the quests needed first: " + before,
			before.stream().anyMatch(line -> line.contains("The Dig Site")));

		SwingUtilities.invokeAndWait(() -> built[0].setProgress(
			new java.util.HashMap<>(), java.util.Collections.singleton("The Dig Site")));

		List<String> after = text(built[0]);
		assertTrue("expected an offer to unfold the finished quest: " + after,
			after.stream().anyMatch(line -> line.contains("done already")));
		assertFalse("the finished quest should be folded away: " + after,
			after.stream().anyMatch(line -> line.contains("The Dig Site")));
		assertTrue("the goal itself must stay: " + after,
			after.stream().anyMatch(line -> line.contains("Desert Treasure I")));
	}

	/**
	 * A level gained part-way through a step does not finish it, but it does
	 * change the step: the plan is made again from the new level.
	 */
	@Test
	public void aLevelGainedMidStepPlansAgainFromThere() throws Exception
	{
		PlayerState state = new PlayerState();
		for (String skill : ALL_SKILLS)
		{
			state.setSkillLevel(skill, 70);
		}

		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			built[0] = panel(state);
			planBaseStats(built[0], 80);
			built[0].setProgress(new java.util.HashMap<>(state.getSkillLevels()));
		});
		assertTrue(text(built[0]).stream().anyMatch(line -> line.contains("Prayer 70")));

		state.setSkillLevel("PRAYER", 75);
		SwingUtilities.invokeAndWait(() ->
			built[0].setProgress(new java.util.HashMap<>(state.getSkillLevels())));

		List<String> after = text(built[0]);
		assertTrue("expected the Prayer step to start from 75 now: " + after,
			after.stream().anyMatch(line -> line.contains("Prayer 75")));
		assertFalse("the old starting level should be gone: " + after,
			after.stream().anyMatch(line -> line.contains("Prayer 70")));

		// Finishing the step folds it away as done; it does not just vanish.
		state.setSkillLevel("PRAYER", 80);
		SwingUtilities.invokeAndWait(() ->
			built[0].setProgress(new java.util.HashMap<>(state.getSkillLevels())));
		List<String> finished = text(built[0]);
		assertTrue("expected the finished step to be offered back: " + finished,
			finished.stream().anyMatch(line -> line.contains("done already")));
	}

	private static void planBaseStats(NowWhatPanel panel, int level)
	{
		List<JSpinner> spinners = new ArrayList<>();
		findAll(panel, JSpinner.class, spinners);
		List<JButton> buttons = new ArrayList<>();
		findAll(panel, JButton.class, buttons);
		buttons.removeIf(b -> !"Plan path".equals(b.getText()));
		spinners.get(2).setValue(level);
		buttons.get(3).doClick();
	}

	/** Clicks the first label whose text contains {@code fragment}. */
	private static void click(NowWhatPanel panel, String fragment)
	{
		List<JLabel> labels = new ArrayList<>();
		findAll(panel, JLabel.class, labels);
		for (JLabel label : labels)
		{
			if (label.getText() != null && strip(label.getText()).contains(fragment))
			{
				for (java.awt.event.MouseListener listener : label.getMouseListeners())
				{
					listener.mouseClicked(new java.awt.event.MouseEvent(label,
						java.awt.event.MouseEvent.MOUSE_CLICKED, 0, 0, 1, 1, 1, false));
				}
				return;
			}
		}
		throw new AssertionError("no clickable label containing " + fragment);
	}

	private static List<String> text(NowWhatPanel panel)
	{
		List<JLabel> labels = new ArrayList<>();
		findAll(panel, JLabel.class, labels);
		List<String> lines = new ArrayList<>();
		for (JLabel label : labels)
		{
			if (label.getText() != null)
			{
				lines.add(strip(label.getText()));
			}
		}
		return lines;
	}

	/** Labels are HTML-wrapped for width, so the tags come back off to read them. */
	private static String strip(String html)
	{
		return html.replaceAll("<[^>]*>", " ").replaceAll("\\s+", " ").trim();
	}

	@SuppressWarnings("unchecked")
	private static <T> void findAll(Container root, Class<T> type, List<T> acc)
	{
		for (Component child : root.getComponents())
		{
			if (type.isInstance(child))
			{
				acc.add((T) child);
			}
			if (child instanceof Container)
			{
				findAll((Container) child, type, acc);
			}
		}
	}

	private static NowWhatPanel panel(PlayerState state)
	{
		try
		{
			Gson gson = new Gson();
			ActivityDatabase ad = new ActivityDatabase(gson);
			ad.load();
			TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
			tm.load(ad.getAllActivities());
			ItemSourceDatabase is = new ItemSourceDatabase(gson);
			is.load();
			PathPlanner planner = new PathPlanner(ad.getAllActivities(),
				new PrerequisiteResolver(ad.getAllActivities()), tm, is);
			NowWhatConfig config = new NowWhatConfig()
			{
			};
			return new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				goal -> planner.plan(goal, state));
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.nowwhat;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
