package com.nowwhat;

import com.nowwhat.data.ItemNameIndex;
import com.nowwhat.data.ItemTextParser;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * RuneLite's item search only knows tradeable items, so for an untradeable one
 * it offers a tradeable relative: the avernic defender's hilt, the dragon
 * defender's ornament kit, the uncharged scythe. Those are what the panel used
 * to picture. The bundled table, which knows the real item, now decides.
 */
public class IconPickTest
{
	private static int pick(String text)
	{
		ItemTextParser.Phrase phrase = ItemTextParser.phrases(text).get(0);
		Integer id = ItemTextParser.pick(phrase, ItemNameIndex.search(ItemTextParser.searchTerm(phrase)));
		return id == null ? -1 : id;
	}

	@Test
	public void untradeableGearIsTheItemItselfNotItsTradeableRelative()
	{
		assertEquals("Avernic defender, not the hilt", 22322, pick("Avernic defender"));
		assertEquals("Dragon defender, not the ornament kit", 12954, pick("Dragon defender"));
		assertEquals("charged Scythe of vitur", 22325, pick("Scythe of vitur"));
		assertEquals("Rune pouch, not its note", 12791, pick("Rune pouch"));
		assertEquals("Book of darkness, not the page set", 12612, pick("Book of darkness"));
	}

	/** Every item a line pictures, in order. */
	private static List<Integer> pickAll(String text)
	{
		List<Integer> ids = new java.util.ArrayList<>();
		for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(text))
		{
			Integer id = ItemTextParser.pick(phrase,
				ItemNameIndex.search(ItemTextParser.searchTerm(phrase)));
			ids.add(id == null ? -1 : id);
		}
		return ids;
	}

	@Test
	public void aSetNameForBodyAndLegsIsTheArmourAGuideMeans()
	{
		// Shortest name used to win: the Bandos robe top and Bandos chaps.
		assertEquals(java.util.Arrays.asList(11832, 11834), pickAll("Body/legs: Bandos"));
	}

	@Test
	public void theLegsOfARobeSetAreNotItsTop()
	{
		// "robe" is a legs word too, and "ancestral robe top" used to fill both boxes.
		assertEquals(java.util.Arrays.asList(21018, 21021, 21024),
			pickAll("Head/body/legs: ancestral"));
	}

	@Test
	public void aNameWrittenOutIsNotSwappedForAKnownItem()
	{
		assertEquals(1387, pick("Staff of fire"));
	}

	@Test
	public void tooltipsUseTheGamesSpellingWhereItIsKnown()
	{
		List<ItemTextParser.Candidate> table = Collections.singletonList(
			new ItemTextParser.Candidate("tumekens shadow", 27275));
		List<ItemTextParser.Candidate> tradeable = Arrays.asList(
			new ItemTextParser.Candidate("Tumeken's shadow (uncharged)", 27277),
			new ItemTextParser.Candidate("Tumeken's shadow", 99999));
		assertEquals("Tumeken's shadow", GearView.displayName(27275, table, tradeable));
		assertEquals("Tumekens shadow",
			GearView.displayName(27275, table, Collections.emptyList()));
	}

	/** The words each option of a line is looked up by. */
	private static List<String> lookups(String text)
	{
		List<String> out = new java.util.ArrayList<>();
		for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(text))
		{
			out.add(String.join(" ", phrase.getWords()));
		}
		return out;
	}

	@Test
	public void aSetNameCarriesThroughAListButNotPastAnOr()
	{
		assertEquals(java.util.Arrays.asList("super attack", "super strength", "super defence"),
			lookups("Super attack, strength and defence"));
		assertEquals(java.util.Arrays.asList("oathplate helm", "oathplate chest", "oathplate legs",
			"torva"), lookups("Oathplate helm, chest and legs or Torva"));
		assertEquals(java.util.Arrays.asList("ultor ring", "lightbearer"),
			lookups("Ultor ring or lightbearer"));
	}

	@Test
	public void aListCanShareItsLastWord()
	{
		assertEquals(java.util.Arrays.asList("dust runes", "chaos runes", "law runes"),
			lookups("dust, chaos and law runes"));
		// Fish are not a kind of thing a list shares: these stay three fish.
		assertEquals(java.util.Arrays.asList("anglerfish", "sharks", "manta rays"),
			lookups("anglerfish, sharks or manta rays"));
	}
}

package com.nowwhat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import net.runelite.api.EquipmentInventorySlot;
import org.junit.Test;

public class LoadoutTest
{
	private static final int HEAD = EquipmentInventorySlot.HEAD.getSlotIdx();
	private static final int BODY = EquipmentInventorySlot.BODY.getSlotIdx();
	private static final int WEAPON = EquipmentInventorySlot.WEAPON.getSlotIdx();
	private static final int SHIELD = EquipmentInventorySlot.SHIELD.getSlotIdx();
	private static final int RING = EquipmentInventorySlot.RING.getSlotIdx();

	@Test
	public void firstStepWearsTheFirstOptionInEverySlot()
	{
		Loadout loadout = new Loadout();
		loadout.add(1, HEAD, false);
		loadout.add(2, HEAD, false);
		loadout.add(3, HEAD, false);
		loadout.add(10, BODY, false);
		loadout.add(11, BODY, false);

		assertEquals(3, loadout.steps());
		assertEquals(2, loadout.slotCount());
		assertEquals(Integer.valueOf(1), loadout.worn(HEAD, 0));
		assertEquals(Integer.valueOf(10), loadout.worn(BODY, 0));
	}

	@Test
	public void aSlotThatRunsOutOfOptionsKeepsItsLastOne()
	{
		Loadout loadout = new Loadout();
		loadout.add(1, HEAD, false);
		loadout.add(2, HEAD, false);
		loadout.add(3, HEAD, false);
		loadout.add(20, RING, false);

		assertEquals(Integer.valueOf(3), loadout.worn(HEAD, 2));
		assertEquals(Integer.valueOf(20), loadout.worn(RING, 2));
	}

	@Test
	public void anEmptySlotWearsNothing()
	{
		Loadout loadout = new Loadout();
		loadout.add(1, HEAD, false);

		assertNull(loadout.worn(BODY, 0));
		assertTrue(loadout.options(BODY).isEmpty());
	}

	@Test
	public void repeatsAreListedOnce()
	{
		Loadout loadout = new Loadout();
		loadout.add(1, HEAD, false);
		loadout.add(1, HEAD, false);
		loadout.add(2, HEAD, false);

		assertEquals(Arrays.asList(1, 2), loadout.options(HEAD));
	}

	@Test
	public void aTwoHandedWeaponLeavesTheShieldSlotEmpty()
	{
		// Twisted bow, then a crossbow that does leave a hand free.
		Loadout loadout = new Loadout();
		loadout.add(100, WEAPON, true);
		loadout.add(101, WEAPON, false);
		loadout.add(200, SHIELD, false);
		loadout.add(201, SHIELD, false);

		assertTrue(loadout.isBlockedByTwoHander(0));
		assertNull(loadout.worn(SHIELD, 0));
		assertEquals(Integer.valueOf(201), loadout.worn(SHIELD, 1));
		// The shield is still listed for hovering, just not drawn as worn.
		assertEquals(Arrays.asList(200, 201), loadout.options(SHIELD));
	}
}

package com.nowwhat;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.PlayerState;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Getting back out of a screen.
 * <p>
 * The goal form had no way back to the opening fork, so picking "Plan a path"
 * once removed the random suggestion for the rest of the session - the half of
 * the panel for a player with nothing particular in mind became unreachable by
 * using the other half.
 */
public class NavigationTest
{
	@Test
	public void theGoalFormOffersTheRollAndTheWayBack() throws Exception
	{
		final List<String> onScreen = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = panel();
			click(panel, "Plan a path");
			onScreen.addAll(visibleText(panel));
		});

		assertTrue("expected the goal form to offer a roll: " + onScreen,
			onScreen.stream().anyMatch(line -> line.contains("Surprise me")));
		assertTrue("expected the goal form to offer a way back: " + onScreen,
			onScreen.stream().anyMatch(line -> line.contains("Back")));
	}

	@Test
	public void theRollIsReachableFromTheGoalForm() throws Exception
	{
		final List<String> rolled = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = panel();
			click(panel, "Plan a path");
			click(panel, "Surprise me");
			rolled.addAll(visibleText(panel));
		});

		// Logged out, the roll draws from the whole catalogue and says so.
		assertTrue("expected a rolled suggestion: " + rolled,
			rolled.stream().anyMatch(line -> line.contains("Roll again")));
	}

	private static void click(Container root, String fragment)
	{
		for (JLabel label : labels(root, true))
		{
			if (strip(label.getText()).contains(fragment) && label.getMouseListeners().length > 0)
			{
				for (java.awt.event.MouseListener listener : label.getMouseListeners())
				{
					listener.mouseClicked(new java.awt.event.MouseEvent(label,
						java.awt.event.MouseEvent.MOUSE_CLICKED, 0, 0, 1, 1, 1, false));
				}
				return;
			}
		}
		throw new AssertionError("nothing clickable reading " + fragment
			+ " on screen; found " + visibleText(root));
	}

	private static List<String> visibleText(Container root)
	{
		List<String> lines = new ArrayList<>();
		for (JLabel label : labels(root, true))
		{
			lines.add(strip(label.getText()));
		}
		return lines;
	}

	/**
	 * Labels under containers that are actually showing. {@code isVisible} is
	 * what the panel switches between screens, and a test that reads hidden
	 * containers would pass whatever screen was on.
	 */
	private static List<JLabel> labels(Container root, boolean visibleOnly)
	{
		List<JLabel> found = new ArrayList<>();
		collect(root, visibleOnly, found);
		return found;
	}

	private static void collect(Container container, boolean visibleOnly, List<JLabel> found)
	{
		for (Component child : container.getComponents())
		{
			if (visibleOnly && !child.isVisible())
			{
				continue;
			}
			if (child instanceof JLabel && ((JLabel) child).getText() != null)
			{
				found.add((JLabel) child);
			}
			if (child instanceof Container)
			{
				collect((Container) child, visibleOnly, found);
			}
		}
	}

	private static String strip(String html)
	{
		return html == null ? "" : html.replaceAll("<[^>]*>", " ").replaceAll("\\s+", " ").trim();
	}

	private static NowWhatPanel panel()
	{
		try
		{
			Gson gson = new Gson();
			ActivityDatabase ad = new ActivityDatabase(gson);
			ad.load();
			TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
			tm.load(ad.getAllActivities());
			ItemSourceDatabase is = new ItemSourceDatabase(gson);
			is.load();
			PathPlanner planner = new PathPlanner(ad.getAllActivities(),
				new PrerequisiteResolver(ad.getAllActivities()), tm, is);
			PlayerState state = new PlayerState();
			NowWhatConfig config = new NowWhatConfig()
			{
			};
			return new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				goal -> planner.plan(goal, state));
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

