package com.nowwhat;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.PlayerState;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.JViewport;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Everything the panel scrolls has {@link PluginPanel#PANEL_WIDTH} to live in
 * and never gets more. Horizontal scrolling is switched off, so a component
 * that asks for more does not get a scrollbar to reach it - it overflows the
 * viewport and whatever sits past the right edge is cut off, silently.
 * <p>
 * The check runs inside the scroll pane's viewport, not on the panel itself:
 * PluginPanel is deliberately PANEL_WIDTH + SCROLLBAR_WIDTH wide on the
 * outside, so the panel reporting 242px is correct and the viewport is the
 * 225px that content actually gets.
 * <p>
 * Swing reports a preferred width from content, so any new label, row or button
 * can reintroduce the overflow. This is the guard, not a one-time fix.
 */
public class PanelWidthTest
{
	@Test
	public void nothingInThePanelAsksToBeWiderThanTheSidebar() throws Exception
	{
		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() -> built[0] = panel());
		NowWhatPanel panel = built[0];

		JViewport viewport = viewportOf(panel);
		assertNotNull("expected the panel's content to live in a scroll pane", viewport);

		List<String> offenders = new ArrayList<>();
		// Only the deepest offender is reported: a parent is wide because its
		// child is, and naming the parent sends you looking in the wrong file.
		collect(viewport.getView(), describe(viewport.getView()), offenders);

		assertTrue("these components ask to be wider than the " + PluginPanel.PANEL_WIDTH
			+ "px sidebar:\n  " + String.join("\n  ", offenders), offenders.isEmpty());
	}

	/**
	 * The same check over a rendered plan, which is where the panel's widest
	 * content lives - step cards, option rows, shopping-list quantities and
	 * warning text. The empty state passing says nothing about those.
	 */
	@Test
	public void nothingInARenderedPlanAsksToBeWiderThanTheSidebar() throws Exception
	{
		final List<String> offenders = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = panel();
			plan(panel, "WOODCUTTING", 99);
			Component view = viewportOf(panel).getView();
			// Without this the test passes by rendering nothing at all, which is
			// the one way a width check can be green and worthless.
			assertTrue("expected the click to render a plan", rendersAStep(view));
			collect(view, describe(view), offenders);
		});

		assertTrue("these components ask to be wider than the " + PluginPanel.PANEL_WIDTH
			+ "px sidebar:\n  " + String.join("\n  ", offenders), offenders.isEmpty());
	}

	private static boolean rendersAStep(Component component)
	{
		if (component instanceof JLabel)
		{
			String text = ((JLabel) component).getText();
			if (text != null && text.contains("STEP"))
			{
				return true;
			}
		}
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				if (rendersAStep(child))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Drives the skill goal row the way a player would, then plans it. */
	private static void plan(NowWhatPanel panel, String skill, int level)
	{
		List<JComboBox> combos = new ArrayList<>();
		findAll(panel, JComboBox.class, combos);
		List<JSpinner> spinners = new ArrayList<>();
		findAll(panel, JSpinner.class, spinners);
		List<JButton> planButtons = new ArrayList<>();
		findAll(panel, JButton.class, planButtons);
		planButtons.removeIf(b -> !"Plan path".equals(b.getText()));

		combos.get(1).setSelectedItem(skill);
		spinners.get(0).setValue(level);
		planButtons.get(1).doClick();
	}

	@SuppressWarnings("unchecked")
	private static <T> void findAll(Container root, Class<T> type, List<T> acc)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				acc.add((T) c);
			}
			if (c instanceof Container)
			{
				findAll((Container) c, type, acc);
			}
		}
	}

	private static JViewport viewportOf(Container container)
	{
		for (Component child : container.getComponents())
		{
			if (child instanceof JScrollPane)
			{
				return ((JScrollPane) child).getViewport();
			}
			if (child instanceof Container)
			{
				JViewport found = viewportOf((Container) child);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void collect(Component component, String path, List<String> offenders)
	{
		int width = component.getPreferredSize().width;
		boolean blamedAChild = false;
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				int before = offenders.size();
				collect(child, path + " > " + describe(child), offenders);
				blamedAChild |= offenders.size() > before;
			}
		}
		if (width > PluginPanel.PANEL_WIDTH && !blamedAChild)
		{
			offenders.add(width + "px: " + path);
		}
	}

	private static String describe(Component component)
	{
		String name = component.getClass().getSimpleName();
		if (name.isEmpty())
		{
			name = component.getClass().getName();
		}
		if (component instanceof JLabel)
		{
			String text = ((JLabel) component).getText();
			if (text != null && !text.isEmpty())
			{
				name += "(\"" + (text.length() > 60 ? text.substring(0, 60) + "..." : text) + "\")";
			}
		}
		return name;
	}

	private static NowWhatPanel panel()
	{
		try
		{
			Gson gson = new Gson();
			ActivityDatabase ad = new ActivityDatabase(gson);
			ad.load();
			TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
			tm.load(ad.getAllActivities());
			ItemSourceDatabase is = new ItemSourceDatabase(gson);
			is.load();
			PathPlanner planner = new PathPlanner(ad.getAllActivities(),
				new PrerequisiteResolver(ad.getAllActivities()), tm, is);
			PlayerState state = new PlayerState();
			NowWhatConfig config = new NowWhatConfig()
			{
			};
			return new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				goal -> planner.plan(goal, state));
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.nowwhat;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.PlayerState;
import java.awt.Component;
import java.awt.Container;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The item search's matches have to be on screen in the real panel, not just
 * in a picker tested on its own.
 * <p>
 * The picker grows when its list opens, but the block it sits in had its
 * height fixed when the panel was built - with the list closed - so typing
 * produced a list zero pixels tall: the field worked, and nothing showed
 * underneath it to say what it had found. SearchPickerTest measured the
 * picker by itself and could not see this.
 */
public class SearchListVisibleTest
{
	@Test
	public void typingShowsTheMatchesInsideThePanel() throws Exception
	{
		final int[] listHeight = {-1};
		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = panel();
			SearchPicker<?> picker = find(panel, SearchPicker.class);
			assertNotNull("expected an item search in the panel", picker);

			// Show the "choose a goal" screen the picker lives on.
			for (Container c = picker.getParent(); c != null && c != panel; c = c.getParent())
			{
				c.setVisible(true);
			}
			panel.setSize(242, 3000);
			layOut(panel);

			find(picker, JTextField.class).setText("rune");
			layOut(panel);

			JScrollPane results = find(picker, JScrollPane.class);
			listHeight[0] = results.isVisible() ? results.getHeight() : 0;
		});

		assertTrue("the matches list is " + listHeight[0] + "px tall after typing",
			listHeight[0] >= 40);
	}

	/**
	 * What a real frame does after a revalidate: every level re-measures. A
	 * panel with no window around it gets no such pass, and BoxLayout keeps
	 * the sizes it measured before the typing.
	 */
	private static void layOut(Container root)
	{
		invalidateAll(root);
		doLayoutAll(root);
	}

	/** Top down, so each container lays out with its parent's final size. */
	private static void doLayoutAll(Container root)
	{
		root.doLayout();
		for (Component c : root.getComponents())
		{
			if (c instanceof Container)
			{
				doLayoutAll((Container) c);
			}
		}
	}

	private static void invalidateAll(Container root)
	{
		root.invalidate();
		for (Component c : root.getComponents())
		{
			if (c instanceof Container)
			{
				invalidateAll((Container) c);
			}
		}
	}

	@SuppressWarnings("unchecked")
	private static <T> T find(Container root, Class<T> type)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				return (T) c;
			}
			if (c instanceof Container)
			{
				T found = find((Container) c, type);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static NowWhatPanel panel()
	{
		try
		{
			Gson gson = new Gson();
			ActivityDatabase ad = new ActivityDatabase(gson);
			ad.load();
			TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
			tm.load(ad.getAllActivities());
			ItemSourceDatabase is = new ItemSourceDatabase(gson);
			is.load();
			PathPlanner planner = new PathPlanner(ad.getAllActivities(),
				new PrerequisiteResolver(ad.getAllActivities()), tm, is);
			PlayerState state = new PlayerState();
			NowWhatConfig config = new NowWhatConfig()
			{
			};
			return new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				goal -> planner.plan(goal, state));
		}
		catch (RuntimeException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.nowwhat;

import java.awt.Component;
import java.awt.Container;
import java.util.Arrays;
import java.util.List;
import javax.swing.JList;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SearchPickerTest
{
	private static final List<String> ITEMS = Arrays.asList(
		"Abyssal bludgeon", "Abyssal whip", "Dragon claws", "Seers' ring");

	/**
	 * Nothing is chosen until the player chooses it, so the field is empty and
	 * the placeholder is what they see. The dropdown this replaced opened on its
	 * first entry; a search box doing that would be both a choice nobody made
	 * and the reason the box looks like a dropdown.
	 */
	@Test
	public void startsWithNothingChosen() throws Exception
	{
		SearchPicker<String>[] picker = newPicker();
		assertNull(picker[0].getSelected());
		assertEquals("", field(picker[0]).getText());
	}

	@Test
	public void typingAndPickingCommitsTheMatch() throws Exception
	{
		SearchPicker<String>[] picker = newPicker();
		SwingUtilities.invokeAndWait(() -> field(picker[0]).setText("bludg"));
		SwingUtilities.invokeAndWait(() -> list(picker[0]).setSelectedIndex(0));
		picker[0].select(list(picker[0]).getSelectedValue());

		assertEquals("Abyssal bludgeon", picker[0].getSelected());
	}

	/**
	 * A result row has to be tall enough to show its own text. The height was
	 * guessed at as the field's height minus 4, and a guess is wrong as soon as
	 * the row is taller than the guess: the list is then capped below the height
	 * of its own rows and the match shows sliced in half along the bottom edge.
	 * <p>
	 * The row is forced taller than any guess here on purpose. The default look
	 * and feel in a test JVM is not the client's, and under this one the old
	 * arithmetic happened to come out large enough - so a test that just typed a
	 * query passed either way and guarded nothing.
	 */
	@Test
	public void aResultRowIsNotClippedByTheListItSitsIn() throws Exception
	{
		SearchPicker<String>[] picker = newPicker();
		SwingUtilities.invokeAndWait(() ->
		{
			JList<String> tall = list(picker[0]);
			tall.setFont(tall.getFont().deriveFont(28f));
			field(picker[0]).setText("Abyssal bludgeon");
		});

		JList<String> list = list(picker[0]);
		assertEquals(1, list.getModel().getSize());
		int rowHeight = list.getCellRenderer()
			.getListCellRendererComponent(list, list.getModel().getElementAt(0), 0, false, false)
			.getPreferredSize().height;
		int available = scroller(picker[0]).getPreferredSize().height;

		assertTrue("one row wants " + rowHeight + "px but the list is only " + available
			+ "px tall, so its text is cut off", available >= rowHeight);
	}

	@SuppressWarnings("unchecked")
	private static SearchPicker<String>[] newPicker() throws Exception
	{
		final SearchPicker<String>[] built = new SearchPicker[1];
		SwingUtilities.invokeAndWait(() -> built[0] = new SearchPicker<>(ITEMS, name -> name,
			"Search for an item", "Type to search, or pick from the list"));
		return built;
	}

	private static JTextField field(Container root)
	{
		return find(root, JTextField.class);
	}

	@SuppressWarnings("unchecked")
	private static JList<String> list(Container root)
	{
		return find(root, JList.class);
	}

	private static JScrollPane scroller(Container root)
	{
		return find(root, JScrollPane.class);
	}

	private static <T> T find(Container root, Class<T> type)
	{
		for (Component child : root.getComponents())
		{
			if (type.isInstance(child))
			{
				return type.cast(child);
			}
			if (child instanceof Container)
			{
				T found = find((Container) child, type);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}
}

package com.nowwhat;

