import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Integrity checks on the bundled content database.
 *
 * <p>These exist because the failure mode they catch is invisible: a
 * requirement naming a quest that isn't in the file doesn't crash anything,
 * it just quietly degrades into an "unresolved reference" warning in the
 * panel, and a chain that should have been eight steps long silently becomes
 * three. Content is edited far more often than code here, so the build should
 * be what notices.
 */
public class ContentDatabaseTest
{
	private static final Set<String> VALID_SKILLS = new HashSet<>(java.util.Arrays.asList(
		"ATTACK", "DEFENCE", "STRENGTH", "HITPOINTS", "RANGED", "PRAYER", "MAGIC", "COOKING",
		"WOODCUTTING", "FLETCHING", "FISHING", "FIREMAKING", "CRAFTING", "SMITHING", "MINING",
		"HERBLORE", "AGILITY", "THIEVING", "SLAYER", "FARMING", "RUNECRAFT", "HUNTER",
		"CONSTRUCTION", "SAILING"));

	private List<Activity> activities;
	private List<ItemSource> items;
	private List<TrainingMethod> methods;

	@Before
	public void setUp()
	{
		Gson gson = new Gson();
		ActivityDatabase activityDatabase = new ActivityDatabase(gson);
		activityDatabase.load();
		activities = activityDatabase.getAllActivities();

		ItemSourceDatabase itemDatabase = new ItemSourceDatabase(gson);
		itemDatabase.load();
		items = itemDatabase.getAllSources();

		// Loaded through the database rather than read straight from JSON, so
		// these see the file exactly as the panel does - notes, gear and
		// attention already shared down each method's level brackets.
		TrainingMethodDatabase methodDatabase = new TrainingMethodDatabase(gson);
		methodDatabase.load(activities);
		methods = methodDatabase.getAllMethods();
	}

	/**
	 * A method split into brackets records its attention judgement once, and the
	 * database copies it down. If that copy ever stops happening, the panel
	 * silently drops the label from every bracket but the lowest - and a missing
	 * label does not look like a bug, it looks like an unjudged method.
	 */
	@Test
	public void everyBracketOfAJudgedMethodCarriesTheJudgement()
	{
		Set<String> judged = new HashSet<>();
		for (TrainingMethod method : methods)
		{
			if (method.getAttention() != null)
			{
				judged.add(method.getSkill() + "/" + method.getName());
			}
		}

		List<String> missing = new ArrayList<>();
		for (TrainingMethod method : methods)
		{
			String key = method.getSkill() + "/" + method.getName();
			if (judged.contains(key) && method.getAttention() == null)
			{
				missing.add(key + " " + method.getMinLevel() + "-" + method.getMaxLevel());
			}
		}

		assertEquals("brackets missing the attention judgement their siblings carry: " + missing,
			0, missing.size());
	}

	/**
	 * Tick manipulation already gets its own label in the panel. A method
	 * carrying both would print two tags that say the same thing, so the
	 * generator refuses the combination and this is the check on the shipped
	 * file.
	 */
	@Test
	public void noTickManipulationMethodAlsoClaimsAnAttentionJudgement()
	{
		List<String> both = new ArrayList<>();
		for (TrainingMethod method : methods)
		{
			if (method.isTickManipulation() && method.getAttention() != null)
			{
				both.add(method.getSkill() + "/" + method.getName());
			}
		}

		assertEquals("tick-manipulation methods should carry no attention judgement: " + both,
			0, both.size());
	}

	/**
	 * An item that borrows a fight's kit has to name a fight that exists.
	 * <p>
	 * Nothing throws if it does not - {@code NowWhatPanel} looks the id up,
	 * gets null, and shows the drop with no answer to "what do I take?", which
	 * looks exactly like an item nobody wrote a kit for.
	 */
	@Test
	public void everyItemBorrowingKitNamesAKnownActivity()
	{
		Set<String> ids = new HashSet<>();
		for (Activity activity : activities)
		{
			ids.add(activity.getId());
		}

		List<String> dangling = new ArrayList<>();
		int borrowing = 0;
		for (ItemSource item : items)
		{
			if (item.getPreparationFrom() == null)
			{
				continue;
			}
			borrowing++;
			if (!ids.contains(item.getPreparationFrom()))
			{
				dangling.add(item.getDisplayName() + " -> " + item.getPreparationFrom());
			}
		}

		assertEquals("items borrowing kit from no such activity: " + dangling,
			0, dangling.size());
		assertTrue("no item borrows kit any more - did the link get dropped?", borrowing > 0);
	}

	/**
	 * A shop price quoted in a currency you earn has to say where you earn it.
	 * <p>
	 * "Tithe Farm reward shop, 250 points" was the complaint that produced this:
	 * the panel named a shop and a number and stopped, with nothing about what
	 * Tithe Farm is, how points accrue or how long 250 of them take. The ones
	 * still missing a link are listed here by name, so adding a new points shop
	 * fails this test until it either gets its activity or is admitted to the
	 * list - a dead end has to be a decision, not an oversight.
	 */
	@Test
	public void everyShopPricedInEarnedCurrencyNamesWhereItIsEarned()
	{
		// A points shop that cannot name where its currency is earned is admitted
		// here by name. Each of these is a shop whose currency comes from an
		// activity activities.json does not have yet - Mahogany Homes, Giants'
		// Foundry, Mastering Mixology, the Hallowed Sepulchre and Soul Wars. The
		// detail says in words where the currency comes from; adding the activity
		// and a currencyFrom is the fix, and takes the id off this list.
		Set<String> knownGaps = new HashSet<>(java.util.Arrays.asList(
			"CARPENTERS_HELMET", "CARPENTERS_SHIRT", "CARPENTERS_TROUSERS", "CARPENTERS_BOOTS",
			"PLANK_SACK",
			"SMITHS_TUNIC", "SMITHS_TROUSERS", "SMITHS_BOOTS", "SMITHS_GLOVES", "COLOSSAL_BLADE",
			"REAGENT_POUCH", "PRESCRIPTION_GOGGLES",
			"HALLOWED_RING",
			"ECTOPLASMATOR"));

		List<String> deadEnds = new ArrayList<>();
		for (ItemSource item : items)
		{
			if (item.getType() != ItemSource.SourceType.SHOP || item.getDetail() == null)
			{
				continue;
			}
			String detail = item.getDetail().toLowerCase(java.util.Locale.ROOT);
			boolean earned = detail.contains("point") || detail.contains("mark")
				|| detail.contains("token") || detail.contains("reward");
			if (earned && item.getCurrencyFrom() == null && !knownGaps.contains(item.getId()))
			{
				deadEnds.add(item.getId() + " (" + item.getDetail() + ")");
			}
		}

		assertEquals("shop items quoting an earned price with nowhere to earn it: " + deadEnds,
			0, deadEnds.size());
	}

	/**
	 * Every {@code gameItemId} has to be a real item, and has to be the item it
	 * claims to be.
	 * <p>
	 * This is the check the first pass did not have, and two ids typed from
	 * memory back then were wrong. A wrong id is silent: nothing throws, the
	 * panel simply shows a picture of a different item, and the only way to
	 * notice is to recognise the sprite. The name a constant reads back as is
	 * approximate - {@code MASORI_BODY_F} comes back as "masori body (f)" - so
	 * the match is deliberately loose: the first word of the display name has
	 * to appear in the constant. That is enough to catch an id pointing at
	 * something else entirely, which is the failure that matters.
	 */
	@Test
	public void everyGameItemIdNamesTheItemItClaimsTo()
	{
		Map<Integer, List<String>> byId = new HashMap<>();
		for (ItemTextParser.Candidate candidate : ItemIdConstants.all())
		{
			byId.computeIfAbsent(candidate.getId(), k -> new ArrayList<>())
				.add(candidate.getName());
		}
		assertTrue("no ItemID constants on the classpath - this test proves nothing",
			byId.size() > 1000);

		List<String> wrong = new ArrayList<>();
		for (ItemSource item : items)
		{
			List<String> names = byId.get(item.getGameItemId());
			if (names == null)
			{
				wrong.add(item.getDisplayName() + " -> " + item.getGameItemId()
					+ " is not an item id at all");
				continue;
			}
			String first = flattenFirstWord(item.getDisplayName());
			boolean ok = false;
			for (String name : names)
			{
				if (flatten(name).contains(first))
				{
					ok = true;
					break;
				}
			}
			if (!ok)
			{
				wrong.add(item.getDisplayName() + " -> " + item.getGameItemId()
					+ " which is " + names);
			}
		}

		assertEquals("item ids naming the wrong item: " + wrong, 0, wrong.size());
	}

	private static String flattenFirstWord(String text)
	{
		String[] words = flatten(text).split(" ");
		return words.length == 0 ? "" : words[0];
	}

	private static String flatten(String text)
	{
		return text.toLowerCase(java.util.Locale.ROOT)
			.replace("'", "")
			.replace("-", "")
			.replace("(", "")
			.replace(")", "");
	}

	/**
	 * A method may borrow its kit from an activity, and a borrow that names an
	 * id nothing answers to is the same silent failure as a dangling quest
	 * reference: the plan renders, the gear is just missing.
	 */
	@Test
	public void everyBorrowedKitNamesAKnownActivity()
	{
		Set<String> ids = new HashSet<>();
		for (Activity activity : activities)
		{
			ids.add(activity.getId());
		}

		List<String> dangling = new ArrayList<>();
		for (TrainingMethod method : methods)
		{
			if (method.getActivity() != null && !ids.contains(method.getActivity()))
			{
				dangling.add(method.getName() + " -> " + method.getActivity());
			}
		}

		assertEquals("methods borrowing kit from no such activity: " + dangling,
			0, dangling.size());
	}

	/**
	 * And the borrow has to actually land. Wintertodt is the regression this
	 * guards: it is a Firemaking method whose four warm-clothing slots live in
	 * the minigame entry, and for a while the skill path named it and then said
	 * nothing about what to wear.
	 */
	@Test
	public void aMethodThatBorrowsKitEndsUpWithIt()
	{
		int checked = 0;
		for (TrainingMethod method : methods)
		{
			if (method.getActivity() == null)
			{
				continue;
			}
			checked++;
			assertTrue(method.getName() + " borrows from " + method.getActivity()
					+ " but came out with no gear and no supplies",
				!method.getGear().isEmpty() || !method.getSupplies().isEmpty());
		}
		assertTrue("no method borrows kit any more - did the link get dropped?", checked > 0);
	}

	/**
	 * A shopping list needs both halves: the xp of one action and what that
	 * action uses up. Half of it recorded is a count that silently never
	 * appears, which is the hardest kind of data bug to notice.
	 */
	@Test
	public void everyCountableMethodRecordsBothHalvesOfItsShoppingList()
	{
		List<String> broken = new ArrayList<>();
		for (TrainingMethod method : methods)
		{
			boolean hasRate = method.getXpPerAction() != null && method.getXpPerAction() > 0;
			boolean hasItems = !method.getConsumes().isEmpty();
			if (hasRate != hasItems)
			{
				broken.add(method.getSkill() + "/" + method.getName()
					+ " xpPerAction=" + method.getXpPerAction()
					+ " consumes=" + method.getConsumes().size());
			}
			for (TrainingMethod.Consumed consumed : method.getConsumes())
			{
				if (consumed.getItem() == null || consumed.getItem().trim().isEmpty())
				{
					broken.add(method.getName() + " consumes a nameless item");
				}
			}
		}

		assertEquals("methods with a half-recorded shopping list: " + broken, 0, broken.size());
	}

	/**
	 * Woodcutting is judged end to end, and should stay that way. The axis is
	 * populated skill by skill, so a partially judged skill is the dangerous
	 * state: an unlabelled method next to labelled ones reads as "ordinary"
	 * when it actually means "nobody has looked". Add the judgement when you
	 * add the method, or add the skill to the exemption below with a reason.
	 */
	@Test
	public void everyWoodcuttingMethodIsJudgedForAttention()
	{
		List<String> unjudged = new ArrayList<>();
		for (TrainingMethod method : methods)
		{
			if (!"WOODCUTTING".equals(method.getSkill()) || method.isTickManipulation())
			{
				continue;
			}
			if (method.getAttention() == null)
			{
				unjudged.add(method.getName() + " " + method.getMinLevel()
					+ "-" + method.getMaxLevel());
			}
		}

		assertEquals("Woodcutting methods with no attention judgement: " + unjudged,
			0, unjudged.size());
	}

	@Test
	public void activitiesLoad()
	{
		assertTrue("activities.json should not be empty", activities.size() > 50);
	}

	@Test
	public void activityIdsAreUnique()
	{
		Set<String> seen = new HashSet<>();
		List<String> duplicates = new ArrayList<>();
		for (Activity activity : activities)
		{
			if (!seen.add(activity.getId()))
			{
				duplicates.add(activity.getId());
			}
		}
		assertEquals("duplicate activity ids: " + duplicates, 0, duplicates.size());
	}

	@Test
	public void everyQuestRequirementNamesAKnownQuest()
	{
		Set<String> questNames = new HashSet<>();
		for (Activity activity : activities)
		{
			if (activity.getCategory() == Activity.Category.QUEST)
			{
				questNames.add(activity.getName());
			}
		}

		List<String> dangling = new ArrayList<>();
		forEachRequirement((activity, req) ->
		{
			if (req.getType() == Requirement.Type.QUEST_COMPLETE && !questNames.contains(req.getValue()))
			{
				dangling.add(activity.getId() + " -> \"" + req.getValue() + "\"");
			}
		});
		assertEquals("quest requirements with no matching QUEST activity: " + dangling,
			0, dangling.size());
	}

	@Test
	public void everyDiaryRequirementNamesAKnownDiaryTier()
	{
		Set<String> diaryIds = new HashSet<>();
		for (Activity activity : activities)
		{
			if (activity.getCategory() == Activity.Category.DIARY)
			{
				diaryIds.add(activity.getId().toUpperCase());
			}
		}

		List<String> dangling = new ArrayList<>();
		forEachRequirement((activity, req) ->
		{
			if (req.getType() == Requirement.Type.DIARY_COMPLETE
				&& !diaryIds.contains(req.getValue().toUpperCase()))
			{
				dangling.add(activity.getId() + " -> \"" + req.getValue() + "\"");
			}
		});
		assertEquals("diary requirements with no matching DIARY activity: " + dangling,
			0, dangling.size());
	}

	@Test
	public void everySkillRequirementNamesARealSkill()
	{
		List<String> bad = new ArrayList<>();
		forEachRequirement((activity, req) ->
		{
			if (req.getType() == Requirement.Type.SKILL_LEVEL && !VALID_SKILLS.contains(req.getValue()))
			{
				bad.add(activity.getId() + " -> \"" + req.getValue() + "\"");
			}
			if (req.getType() == Requirement.Type.SKILL_LEVEL
				&& (req.getThreshold() < 1 || req.getThreshold() > 99))
			{
				bad.add(activity.getId() + " -> " + req.getValue() + " level " + req.getThreshold());
			}
		});
		assertEquals("invalid skill requirements: " + bad, 0, bad.size());
	}

	@Test
	public void itemsLoadAndCarryGameIds()
	{
		assertTrue("item-sources.json should not be empty", items.size() > 10);

		List<String> missing = new ArrayList<>();
		for (ItemSource item : items)
		{
			// Without a game item id the planner cannot subtract what the
			// player already owns, which is the whole point of bank tracking.
			if (item.getGameItemId() == null || item.getGameItemId() <= 0)
			{
				missing.add(item.getId());
			}
		}
		assertEquals("item sources with no usable gameItemId: " + missing, 0, missing.size());
	}

	@Test
	public void everyCraftIngredientResolves()
	{
		Set<String> itemIds = new HashSet<>();
		for (ItemSource item : items)
		{
			itemIds.add(item.getId().toUpperCase());
		}

		List<String> dangling = new ArrayList<>();
		for (ItemSource item : items)
		{
			if (item.getIngredients() == null)
			{
				continue;
			}
			for (ItemSource.Ingredient ingredient : item.getIngredients())
			{
				if (!itemIds.contains(ingredient.getItemId().toUpperCase()))
				{
					dangling.add(item.getId() + " -> " + ingredient.getItemId());
				}
			}
		}
		assertEquals("craft ingredients with no matching item source: " + dangling,
			0, dangling.size());
	}

	private interface RequirementVisitor
	{
		void visit(Activity activity, Requirement requirement);
	}

	/** Walks every requirement, including the children of ANY_OF groups. */
	private void forEachRequirement(RequirementVisitor visitor)
	{
		for (Activity activity : activities)
		{
			for (Requirement req : activity.getRequirements())
			{
				visitor.visit(activity, req);
				if (req.getAnyOf() != null)
				{
					for (Requirement child : req.getAnyOf())
					{
						visitor.visit(activity, child);
					}
				}
			}
		}
	}
}

package com.nowwhat.data;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * A name-to-id index for every item in the game, built from RuneLite's
 * {@code ItemID} constants. <b>Test and build-time only.</b>
 * <p>
 * The plugin itself ships {@link ItemNameIndex}, a table generated from this by
 * {@link ItemNamesTable}: reading these constants by reflection at runtime is
 * something Plugin Hub plugins may not do. Here it checks that item ids in the
 * data name the items they claim to, and builds that table.
 * <p>
 * This exists because {@code ItemManager.search} only covers <b>tradeable</b>
 * items: it walks the Grand Exchange price map, so nothing untradeable is in
 * it. Half the gear a boss guide names is untradeable - void, barrows gloves,
 * an infernal cape, a slayer helmet - and a charged weapon is the sharpest
 * case of all, because the charged scythe of vitur cannot be traded and only
 * "Scythe of vitur (uncharged)" appears in the price list. A player looking at
 * a best-in-slot setup with no scythe in it reasonably concludes the pictures
 * are broken.
 * <p>
 * The constants are read by reflection, once, with no client and no network, so
 * this also works in tests and in the offline diagnostics. The cost is that a
 * constant name is not a display name: it has lost apostrophes, hyphens and
 * brackets ({@code MASORI_BODY_F}, {@code PRAYER_POTION4}). Those are put back
 * where the pattern is unambiguous, and {@link ItemTextParser} matches
 * leniently enough to absorb the rest. Because of that, this is the
 * <em>fallback</em>: a real display name from the item index is always
 * preferred when there is one.
 */
public final class ItemIdConstants
{
	private static final String ITEM_ID_CLASS = "net.runelite.api.ItemID";

	private static List<ItemTextParser.Candidate> index;

	private ItemIdConstants()
	{
	}

	/**
	 * Every item constant, name and id. Used to check that the ids written into
	 * item-sources.json point at the items they say they do.
	 */
	public static List<ItemTextParser.Candidate> all()
	{
		return Collections.unmodifiableList(index());
	}

	/**
	 * Every item whose name contains {@code term}, compared without the
	 * punctuation these names cannot carry.
	 */
	public static List<ItemTextParser.Candidate> search(String term)
	{
		List<ItemTextParser.Candidate> all = index();
		List<ItemTextParser.Candidate> hits = new ArrayList<>();
		if (term == null || term.isEmpty())
		{
			return hits;
		}
		String needle = flatten(term);
		for (ItemTextParser.Candidate candidate : all)
		{
			if (flatten(candidate.getName()).contains(needle))
			{
				hits.add(candidate);
			}
		}
		return hits;
	}

	/** Apostrophes and hyphens are absent from constant names; ignore them on both sides. */
	private static String flatten(String text)
	{
		return text.toLowerCase(Locale.ROOT)
			.replace("'", "")
			.replace("\u2019", "")
			.replace("-", "")
			.replace("+", "");
	}

	private static synchronized List<ItemTextParser.Candidate> index()
	{
		if (index != null)
		{
			return index;
		}

		List<ItemTextParser.Candidate> built = new ArrayList<>();
		try
		{
			Class<?> itemId = Class.forName(ITEM_ID_CLASS);
			for (Field field : itemId.getFields())
			{
				if (field.getType() != int.class || !Modifier.isStatic(field.getModifiers()))
				{
					continue;
				}
				built.add(new ItemTextParser.Candidate(displayName(field.getName()),
					field.getInt(null)));
			}
		}
		catch (ReflectiveOperationException | LinkageError noItemIdOnTheClasspath)
		{
			// Leaves the index empty: every lookup then simply falls through to
			// whatever the real item index offered, which is where it started.
			built = Collections.emptyList();
		}
		index = built;
		return index;
	}

	/**
	 * A constant name read back as something like the item's name.
	 * <p>
	 * {@code MASORI_BODY_F} is "masori body (f)" and {@code PRAYER_POTION4} is
	 * "prayer potion(4)": a trailing one or two letter segment is a variant
	 * marker in every real item name that has one, and a digit run glued to the
	 * last word is a dose.
	 */
	static String displayName(String constant)
	{
		// Two constants glue their variant onto the word: the salve amulet (i)
		// and (ei) are SALVE_AMULETI and SALVE_AMULETEI, which no rule below
		// can tell apart from a word that ends in "ei".
		if (constant.equals("SALVE_AMULETI"))
		{
			return "salve amulet (i)";
		}
		if (constant.equals("SALVE_AMULETEI"))
		{
			return "salve amulet (ei)";
		}
		String[] parts = constant.toLowerCase(Locale.ROOT).split("_");
		StringBuilder name = new StringBuilder();
		for (int i = 0; i < parts.length; i++)
		{
			if (name.length() > 0)
			{
				name.append(' ');
			}
			// "max" as well: AVERNIC_TREADS_MAX is "Avernic treads (max)", and
			// without the bracket a setup naming them never matched at all.
			if (i > 0 && i == parts.length - 1 && (parts[i].length() <= 2 || parts[i].equals("max"))
				&& !parts[i].isEmpty() && !Character.isDigit(parts[i].charAt(0)))
			{
				name.append('(').append(parts[i]).append(')');
			}
			else
			{
				name.append(parts[i]);
			}
		}

		// "potion4" -> "potion(4)"
		String built = name.toString();
		int at = built.length();
		while (at > 0 && Character.isDigit(built.charAt(at - 1)))
		{
			at--;
		}
		if (at > 0 && at < built.length() && Character.isLetter(built.charAt(at - 1)))
		{
			built = built.substring(0, at) + "(" + built.substring(at) + ")";
		}
		return built;
	}
}

package com.nowwhat.data;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The fallback index exists for the items RuneLite's own search cannot see -
 * everything untradeable - so what matters is that the names it rebuilds from
 * constants are close enough to match against.
 */
public class ItemIdConstantsTest
{
	@Test
	public void variantMarkersComeBackAsBrackets()
	{
		assertEquals("masori body (f)", ItemIdConstants.displayName("MASORI_BODY_F"));
		assertEquals("slayer helmet (i)", ItemIdConstants.displayName("SLAYER_HELMET_I"));
	}

	@Test
	public void aDoseGluedToTheWordIsSeparated()
	{
		assertEquals("prayer potion(4)", ItemIdConstants.displayName("PRAYER_POTION4"));
		assertEquals("super restore(1)", ItemIdConstants.displayName("SUPER_RESTORE1"));
	}

	@Test
	public void plainNamesAreLeftAlone()
	{
		assertEquals("scythe of vitur", ItemIdConstants.displayName("SCYTHE_OF_VITUR"));
		assertEquals("twisted bow", ItemIdConstants.displayName("TWISTED_BOW"));
	}

	@Test
	public void theUntradeablesRuneLiteCannotSearchAreInHere()
	{
		// Each of these is absent from the Grand Exchange price list, which is
		// the whole reason this index exists.
		for (String name : new String[]{"scythe of vitur", "barrows gloves", "infernal cape",
			"void ranger helm"})
		{
			assertTrue(name + " should be findable", holdsSomethingNamed(name));
		}
	}

	@Test
	public void aNameNoItemHasFindsNothing()
	{
		assertFalse(holdsSomethingNamed("sword of definitely not a real item"));
		assertTrue(ItemIdConstants.search("").isEmpty());
	}

	private boolean holdsSomethingNamed(String name)
	{
		List<ItemTextParser.Candidate> hits = ItemIdConstants.search(name);
		for (ItemTextParser.Candidate hit : hits)
		{
			if (hit.getName().contains(name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.nowwhat.data;

import com.google.gson.Gson;
import com.nowwhat.model.Activity;
import com.nowwhat.model.ItemSource;
import com.nowwhat.model.TrainingMethod;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Builds {@code item-names.txt}, the table {@link ItemNameIndex} ships with.
 * <p>
 * Every gear, supply and shopping-list line in the bundled data is parsed the
 * way the panel parses it, and each phrase is resolved against the full set of
 * RuneLite's item constants ({@link ItemIdConstants}). The items those phrases
 * resolve to are the table - the only names the panel's fallback can ever be
 * asked for. Reflection is fine here: this runs at build time, in test code,
 * and never ships.
 * <p>
 * Run {@code ./gradlew itemnames} after changing the gear or supply text.
 */
public final class ItemNamesTable
{
	static final String SOURCE_PATH = "src/main/resources/com/nowwhat/item-names.txt";

	private ItemNamesTable()
	{
	}

	public static void main(String[] args) throws IOException
	{
		String body = render(required(), checkedIds().keySet());
		Files.write(Paths.get(SOURCE_PATH), body.getBytes(StandardCharsets.UTF_8));
		System.out.println("wrote " + required().size() + " items to " + SOURCE_PATH);
	}

	/**
	 * The id the game actually uses for a picked item.
	 * <p>
	 * RuneLite keeps some names on an id the game never used: ULTOR_RING is
	 * 25485, and the ring players wear is ULTOR_RING_28307. The parser takes
	 * the plain constant, so where item-sources.json - whose ids were checked
	 * against the wiki - gives the same name with a number on the end, that id
	 * wins. A different form of the item does not: the data lists the Eye of
	 * Ayak by its uncharged id because that is how it drops, but the gear
	 * picture should be the charged staff a player actually holds.
	 */
	static int realId(int picked, String name, Map<String, Integer> checked)
	{
		Integer real = checked.get(ItemNameIndex.flatten(name));
		if (real == null || real == picked)
		{
			return picked;
		}
		String realName = constantNames().get(real);
		String prefix = name + " ";
		if (realName == null || !realName.startsWith(prefix)
			|| realName.length() == prefix.length())
		{
			return picked;
		}
		for (char c : realName.substring(prefix.length()).toCharArray())
		{
			if (!Character.isDigit(c))
			{
				return picked;
			}
		}
		return real;
	}

	private static Map<Integer, String> constantNames;

	private static synchronized Map<Integer, String> constantNames()
	{
		if (constantNames == null)
		{
			constantNames = new HashMap<>();
			for (ItemTextParser.Candidate candidate : ItemIdConstants.all())
			{
				constantNames.putIfAbsent(candidate.getId(), candidate.getName());
			}
		}
		return constantNames;
	}

	/** Wiki-checked item ids from item-sources.json, by flattened display name. */
	static Map<String, Integer> checkedIds()
	{
		ItemSourceDatabase sources = new ItemSourceDatabase(new Gson());
		try
		{
			sources.load();
		}
		catch (Exception e)
		{
			throw new IllegalStateException("could not load item-sources.json", e);
		}
		Map<String, Integer> ids = new HashMap<>();
		for (ItemSource source : sources.getAllSources())
		{
			if (source.getGameItemId() != null && source.getDisplayName() != null)
			{
				ids.put(ItemNameIndex.flatten(source.getDisplayName()), source.getGameItemId());
			}
		}
		return ids;
	}

	/** Every line of text the panel turns into item pictures. */
	static List<String> kitLines()
	{
		Gson gson = new Gson();
		ActivityDatabase activities = new ActivityDatabase(gson);
		TrainingMethodDatabase methods = new TrainingMethodDatabase(gson);
		try
		{
			activities.load();
			methods.load(activities.getAllActivities());
		}
		catch (Exception e)
		{
			throw new IllegalStateException("could not load the bundled data", e);
		}

		List<String> lines = new ArrayList<>();
		for (Activity activity : activities.getAllActivities())
		{
			for (Activity.GearSetup setup : activity.getSetups())
			{
				lines.addAll(setup.getItems());
			}
			lines.addAll(activity.getSupplies());
		}
		for (TrainingMethod method : methods.getAllMethods())
		{
			lines.addAll(method.getGear());
			lines.addAll(method.getSupplies());
			for (TrainingMethod.Consumed consumed : method.getConsumes())
			{
				lines.add(consumed.getItem());
			}
		}
		return lines;
	}

	/** What the panel's fallback can be asked for, by id, resolved against every item constant. */
	static Map<Integer, String> required()
	{
		Map<String, Integer> checked = checkedIds();
		Map<Integer, String> needed = new TreeMap<>();
		for (String line : kitLines())
		{
			for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(line))
			{
				List<ItemTextParser.Candidate> candidates =
					ItemIdConstants.search(ItemTextParser.searchTerm(phrase));
				Integer id = ItemTextParser.pick(phrase, candidates, checked.keySet());
				if (id == null)
				{
					continue;
				}
				for (ItemTextParser.Candidate candidate : candidates)
				{
					if (candidate.getId() == id)
					{
						needed.putIfAbsent(realId(id, candidate.getName(), checked), candidate.getName());
						break;
					}
				}
			}
		}
		return needed;
	}

	/** One item per line, "id TAB name", in id order so a regenerated table diffs cleanly. */
	static String render(Map<Integer, String> items, java.util.Set<String> known)
	{
		StringBuilder out = new StringBuilder();
		for (Map.Entry<Integer, String> item : items.entrySet())
		{
			out.append(item.getKey()).append('\t').append(item.getValue());
			if (known.contains(ItemNameIndex.flatten(item.getValue())))
			{
				out.append('\t').append(ItemNameIndex.KNOWN);
			}
			out.append('\n');
		}
		return out.toString();
	}
}

package com.nowwhat.data;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The item table the plugin ships has to answer every gear line exactly the way
 * the full set of item constants would. It replaced a runtime reflection read of
 * those constants, and a table that quietly fell behind the gear text would turn
 * pictures back into words with nothing to say why.
 */
public class ItemNamesTableTest
{
	private static final String REGENERATE = " - run ./gradlew itemnames and commit the result";

	@Test
	public void theShippedTableIsUpToDate()
	{
		Map<Integer, String> shipped = new TreeMap<>();
		for (ItemTextParser.Candidate candidate : ItemNameIndex.all())
		{
			shipped.put(candidate.getId(), candidate.getName());
		}
		assertEquals("item-names.txt is out of step with the gear and supply text" + REGENERATE,
			ItemNamesTable.required(), shipped);
	}

	/**
	 * The table is a cut-down candidate list, so the same phrase now chooses
	 * among fewer items. It has to choose the same one.
	 */
	@Test
	public void everyPhrasePicksWhatTheFullIndexPicks()
	{
		List<String> differ = new ArrayList<>();
		Map<String, Integer> checked = ItemNamesTable.checkedIds();
		for (String line : ItemNamesTable.kitLines())
		{
			for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(line))
			{
				String term = ItemTextParser.searchTerm(phrase);
				List<ItemTextParser.Candidate> all = ItemIdConstants.search(term);
				Integer full = ItemTextParser.pick(phrase, all, checked.keySet());
				// Through the same correction the table was built with: the full
				// index still picks ULTOR_RING's unused id, the table the real one.
				for (ItemTextParser.Candidate candidate : all)
				{
					if (full != null && candidate.getId() == full)
					{
						full = ItemNamesTable.realId(full, candidate.getName(), checked);
						break;
					}
				}
				Integer shipped = ItemTextParser.pick(phrase, ItemNameIndex.search(term));
				if (!Objects.equals(full, shipped))
				{
					differ.add("\"" + phrase.getText() + "\" in \"" + line + "\": " + full + " vs " + shipped);
				}
			}
		}
		assertTrue("the shipped table picks differently for:\n  " + String.join("\n  ", differ)
			+ "\n" + REGENERATE, differ.isEmpty());
	}

	/** The untradeables RuneLite's own search cannot find, which is why the table exists. */
	@Test
	public void theUntradeablesTheGearListsNameAreInIt()
	{
		for (String name : new String[]{"scythe of vitur", "barrows gloves", "infernal cape",
			"void ranger helm"})
		{
			assertTrue(name + " should be findable", holdsSomethingNamed(name));
		}
	}

	@Test
	public void aNameNoItemHasFindsNothing()
	{
		assertFalse(holdsSomethingNamed("sword of definitely not a real item"));
		assertTrue(ItemNameIndex.search("").isEmpty());
	}

	private static boolean holdsSomethingNamed(String name)
	{
		for (ItemTextParser.Candidate hit : ItemNameIndex.search(name))
		{
			if (hit.getName().contains(name))
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void anUnusedPlainIdGivesWayToTheIdTheGameUses()
	{
		java.util.Map<String, Integer> checked = new java.util.HashMap<>();
		checked.put("ultor ring", 28307);
		checked.put("eye of ayak", 31115);

		// ULTOR_RING (25485) was never used; ULTOR_RING_28307 is the ring.
		org.junit.Assert.assertEquals(28307, ItemNamesTable.realId(25485, "ultor ring", checked));
		// EYE_OF_AYAK_UNCHARGED is a real item, just not the one worn.
		org.junit.Assert.assertEquals(31113, ItemNamesTable.realId(31113, "eye of ayak", checked));
	}
}

package com.nowwhat.data;

import com.nowwhat.data.ItemTextParser.Candidate;
import com.nowwhat.data.ItemTextParser.Phrase;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The gear lines in activities.json are prose, and turning prose into item ids
 * is guesswork. These tests are where the guessing is held to account: a wrong
 * icon beside a boss setup is worse than no icon, so the cases that must come
 * back empty matter as much as the ones that must resolve.
 */
public class ItemTextParserTest
{
	/**
	 * Stands in for RuneLite's item index. Substring matching on the longest
	 * word, which is what ItemManager.search does, so the filtering under test
	 * sees the same shape of input it will see in a client.
	 */
	private static final List<Candidate> ITEMS = Arrays.asList(
		new Candidate("Occult necklace", 19553),
		new Candidate("Amulet of fury", 6585),
		new Candidate("Amulet of blood fury", 24780),
		new Candidate("Amulet of torture", 19553),
		new Candidate("Amulet of rancour", 29801),
		new Candidate("Masori mask", 27226),
		new Candidate("Masori mask (f)", 27235),
		new Candidate("Masori body", 27229),
		new Candidate("Masori body (f)", 27238),
		new Candidate("Masori chaps", 27232),
		new Candidate("Masori chaps (f)", 27241),
		new Candidate("Crystal key", 989),
		new Candidate("Crystal pickaxe", 23863),
		new Candidate("Crystal boots", 23644),
		new Candidate("Twisted bow", 20997),
		new Candidate("Toxic blowpipe", 12926),
		new Candidate("Toxic blowpipe (empty)", 12922),
		new Candidate("Prayer potion(4)", 2434),
		new Candidate("Prayer potion(3)", 139),
		new Candidate("Berserker ring", 6737),
		new Candidate("Berserker ring (i)", 11773),
		new Candidate("Ultor ring", 28307),
		new Candidate("Dizana's quiver", 28947),
		new Candidate("Dizana's quiver (uncharged)", 28902),
		new Candidate("Elidinis' ward (f)", 25988),
		new Candidate("Elidinis' ward", 25985),
		new Candidate("Zaryte vambraces", 26235),
		new Candidate("Barrows gloves", 7462),
		new Candidate("Twisted buckler", 21000),
		new Candidate("Bandos chestplate", 11832),
		new Candidate("Bandos tassets", 11834),
		new Candidate("Void ranger helm", 11664),
		new Candidate("Magic shortbow (i)", 12788),
		new Candidate("Torag's platebody", 4749),
		new Candidate("Torag's platelegs", 4751),
		new Candidate("Facemask", 4166),
		new Candidate("Shark", 385),
		new Candidate("Ava's accumulator", 10499));

	/** The id a whole written line resolves to, phrase by phrase. */
	private List<Integer> resolve(String entry)
	{
		List<Integer> ids = new ArrayList<>();
		for (Phrase phrase : ItemTextParser.phrases(entry))
		{
			Integer id = ItemTextParser.pick(phrase, search(phrase));
			if (id != null && !ids.contains(id))
			{
				ids.add(id);
			}
		}
		return ids;
	}

	/** Substring search on the term the parser asks for, as the real index does. */
	private List<Candidate> search(Phrase phrase)
	{
		String longest = ItemTextParser.searchTerm(phrase);
		List<Candidate> hits = new ArrayList<>();
		for (Candidate candidate : ITEMS)
		{
			if (candidate.getName().toLowerCase(Locale.ROOT).contains(longest))
			{
				hits.add(candidate);
			}
		}
		return hits;
	}

	private String nameOf(int id)
	{
		for (Candidate candidate : ITEMS)
		{
			if (candidate.getId() == id)
			{
				return candidate.getName();
			}
		}
		return "?" + id;
	}

	private List<String> names(String entry)
	{
		List<String> names = new ArrayList<>();
		for (Integer id : resolve(entry))
		{
			names.add(nameOf(id));
		}
		return names;
	}

	@Test
	public void plainItemNameResolves()
	{
		assertEquals(Arrays.asList("Twisted bow"), names("twisted bow"));
	}

	@Test
	public void alternativesEachResolve()
	{
		assertEquals(Arrays.asList("Twisted bow", "Toxic blowpipe"),
			names("twisted bow or toxic blowpipe"));
	}

	@Test
	public void shortestNameWinsOverItsVariants()
	{
		// "Toxic blowpipe (empty)" also contains every word of the phrase.
		assertEquals(Arrays.asList("Toxic blowpipe"), names("toxic blowpipe"));
	}

	@Test
	public void slotPinsDownAOneWordOption()
	{
		assertEquals(Arrays.asList("Occult necklace", "Amulet of fury"),
			names("Neck: occult then fury"));
	}

	@Test
	public void oneWordOptionWithoutASlotResolvesToNothing()
	{
		// This is the whole reason the slot prefix is read: bare "crystal" is a
		// key, a pickaxe and a pair of boots, and guessing is worse than silence.
		assertTrue(names("Best pickaxe you can wield - crystal, dragon or infernal").isEmpty());
	}

	@Test
	public void slotKeepsAOneWordOptionOffTheWrongItem()
	{
		assertEquals(Arrays.asList("Crystal boots"), names("Boots: crystal"));
	}

	@Test
	public void aSetExpandsOverEverySlotItNames()
	{
		assertEquals(Arrays.asList("Masori mask (f)", "Masori body (f)", "Masori chaps (f)"),
			names("Head/body/legs: Masori (f)"));
	}

	@Test
	public void severalSetsAcrossSeveralSlots()
	{
		assertEquals(Arrays.asList("Masori mask (f)", "Masori body (f)", "Masori chaps (f)",
			"Masori mask", "Masori body", "Masori chaps"),
			names("Head/body/legs: Masori (f), Masori"));
	}

	@Test
	public void commaSeparatedSetInOneOption()
	{
		// Only the first piece says "Bandos"; the second is named on its own.
		assertEquals(Arrays.asList("Bandos chestplate", "Bandos tassets"),
			names("Bandos chestplate and tassets"));
	}

	@Test
	public void quantityPrefixAndPluralSupplyStillResolve()
	{
		assertEquals(Arrays.asList("Prayer potion(4)"), names("8-10 prayer potions (4)"));
	}

	@Test
	public void trailingExplanationIsNotTreatedAsAnItem()
	{
		assertEquals(Arrays.asList("Twisted bow"),
			names("twisted bow - borrow one if you have to"));
	}

	@Test
	public void imbuedVariantIsMatchedWhenAskedFor()
	{
		assertEquals(Arrays.asList("Berserker ring (i)"), names("Ring: berserker (i)"));
	}

	@Test
	public void prosePhraseResolvesToNothing()
	{
		assertTrue(names("40 Prayer for Protect from Magic").isEmpty());
		assertTrue(names("An active gargoyle Slayer task").isEmpty());
	}

	@Test
	public void armourWrittenByItsShortNameStillResolves()
	{
		// "Torag's body" is Torag's platebody; only the slot groups know that.
		assertEquals(Arrays.asList("Torag's platebody", "Torag's platelegs"),
			names("Torag's body and legs"));
	}

	@Test
	public void aWordThatIsAWholeItemNameNeedsNoSlot()
	{
		assertEquals(Arrays.asList("Facemask"), names("Facemask or slayer helmet").subList(0, 1));
		assertEquals(Arrays.asList("Shark"), names("Sharks to fill the rest"));
	}

	@Test
	public void apostrophesAreNotLoadBearing()
	{
		assertEquals(Arrays.asList("Ava's accumulator"), names("Avas accumulator"));
	}

	@Test
	public void anUnchargedVariantStandsInWhenItIsAllThereIs()
	{
		// The charged scythe is untradeable, so an index built from Grand
		// Exchange prices only has the uncharged one. A picture of it is still
		// a picture of the right weapon.
		List<Candidate> onlyUncharged = Arrays.asList(
			new Candidate("Scythe of vitur (uncharged)", 22486));
		Phrase phrase = ItemTextParser.phrases("scythe of vitur").get(0);
		assertEquals(Integer.valueOf(22486), ItemTextParser.pick(phrase, onlyUncharged));
	}

	@Test
	public void theChargedItemWinsWhenBothExist()
	{
		List<Candidate> both = Arrays.asList(
			new Candidate("Scythe of vitur (uncharged)", 22486),
			new Candidate("Scythe of vitur", 22325));
		Phrase phrase = ItemTextParser.phrases("scythe of vitur").get(0);
		assertEquals(Integer.valueOf(22325), ItemTextParser.pick(phrase, both));
	}

	@Test
	public void noCandidatesIsNull()
	{
		Phrase phrase = ItemTextParser.phrases("twisted bow").get(0);
		assertNull(ItemTextParser.pick(phrase, new ArrayList<>()));
	}

	@Test
	public void explanationIsWhatFollowsTheItems()
	{
		assertEquals("not optional here",
			ItemTextParser.explanation("Extended anti-venom+ (4) - not optional here"));
		assertNull(ItemTextParser.explanation("twisted bow or toxic blowpipe"));
	}
}

package com.nowwhat.data;

import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The goal pickers are only better than the dropdowns they replaced if what the
 * player types lands on what they meant. These are the cases that decide that.
 */
public class NameSearchTest
{
	private static final Function<String, String> SELF = s -> s;

	private static final List<String> ITEMS = Arrays.asList(
		"Abyssal whip",
		"Dragon boots",
		"Dragon claws",
		"Dragon hunter lance",
		"Dragon warhammer",
		"Seers' ring",
		"Toxic blowpipe",
		"Twisted bow",
		"Zamorak brew (4)");

	private static List<String> search(String query)
	{
		return NameSearch.rank(query, ITEMS, SELF, 0);
	}

	/**
	 * An untouched box is the whole list being browsed, not a search being
	 * ranked, so it keeps the order it was handed - alphabetical here. Ranking
	 * it by length instead opened the picker on whichever name was shortest,
	 * which reads as a bug.
	 */
	@Test
	public void aBlankQueryKeepsTheGivenOrder()
	{
		assertEquals(ITEMS, search(""));
		assertEquals(ITEMS, search("   "));
		assertEquals(ITEMS, NameSearch.rank(null, ITEMS, SELF, 0));
	}

	/**
	 * The three ranks, in order: the query prefixes the whole name, the query
	 * starts one of its words, the query is merely in there somewhere. A
	 * purpose-built list, because the real one has no name with "bow" buried
	 * mid-word to be outranked.
	 */
	@Test
	public void prefixBeatsWordStartBeatsAnywhere()
	{
		List<String> names = Arrays.asList("Elbow guard", "Twisted bow", "Bow string");
		assertEquals(Arrays.asList("Bow string", "Twisted bow", "Elbow guard"),
			NameSearch.rank("bow", names, SELF, 0));
	}

	@Test
	public void shorterNamesWinWithinTheSameRank()
	{
		assertEquals(
			Arrays.asList("Dragon boots", "Dragon claws", "Dragon warhammer",
				"Dragon hunter lance"),
			search("dragon"));
	}

	/** Every term has to land somewhere, which is what makes "drag cl" precise. */
	@Test
	public void everyTermMustMatch()
	{
		assertEquals(Arrays.asList("Dragon claws"), search("drag cl"));
		assertEquals(Arrays.asList("Dragon hunter lance"), search("dragon lance"));
		assertTrue(search("dragon scythe").isEmpty());
	}

	/** Nobody types the apostrophe, and several of these names have lost theirs. */
	@Test
	public void punctuationIsIgnoredOnBothSides()
	{
		assertEquals(Arrays.asList("Seers' ring"), search("seers ring"));
		assertEquals(Arrays.asList("Seers' ring"), search("seers' ring"));
		assertEquals(Arrays.asList("Zamorak brew (4)"), search("zamorak brew 4"));
	}

	@Test
	public void theLimitCaps()
	{
		assertEquals(2, NameSearch.rank("dragon", ITEMS, SELF, 2).size());
		assertEquals(4, NameSearch.rank("dragon", ITEMS, SELF, 0).size());
	}

	@Test
	public void nothingMatchingComesBackEmpty()
	{
		assertTrue(search("elysian").isEmpty());
	}

	/** A null name must be skipped rather than thrown over. */
	@Test
	public void entriesWithNoNameAreIgnored()
	{
		List<String> withNull = Arrays.asList("Dragon claws", null, "Dragon boots");
		assertEquals(2, NameSearch.rank("dragon", withNull, SELF, 0).size());
		assertEquals(2, NameSearch.rank("", withNull, SELF, 0).size());
	}
}

package com.nowwhat.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * The lookup that decides whether to say "Quest Helper has the walkthrough" or
 * "install it from the Plugin Hub". Getting it wrong is invisible until someone
 * notices the panel claiming a plugin they have never installed.
 */
public class PluginLookupTest
{
	private static final List<String> NAMES = Arrays.asList(
		"Ground Items", "Quest Helper", null, "Zulrah Helper", "Menu Entry Swapper");
	private static final List<String> CLASSES = Arrays.asList(
		"net.runelite.client.plugins.grounditems.GroundItemsPlugin",
		"com.questhelper.QuestHelperPlugin",
		"com.github.someone.zulrahhelper.ZulrahHelperPlugin",
		"com.example.forked.ZulrahPlugin",
		"net.runelite.client.plugins.menuentryswapper.MenuEntrySwapperPlugin");

	@Test
	public void findsAPluginByItsDescriptorName()
	{
		assertEquals(1, PluginLookup.match("Quest Helper", NAMES, CLASSES));
	}

	@Test
	public void exactNameBeatsAnEarlierLooseMatch()
	{
		// Index 2 has no descriptor name but a class name containing
		// "zulrahhelper"; index 3 is the real thing and must win.
		assertEquals(3, PluginLookup.match("Zulrah Helper", NAMES, CLASSES));
	}

	@Test
	public void aRenamedForkIsStillFoundByItsClassName()
	{
		List<String> names = Arrays.asList("Quest Helper Deluxe");
		List<String> classes = Arrays.asList("com.questhelper.QuestHelperPlugin");
		assertEquals(0, PluginLookup.match("Quest Helper", names, classes));
	}

	@Test
	public void askingForOnePluginNeverAnswersWithAnother()
	{
		// The bug this test exists for: a hardcoded com.questhelper check in the
		// fallback made every lookup succeed as long as Quest Helper was
		// installed, so the panel told players Zulrah Helper was ready when it
		// was not installed at all.
		List<String> names = Arrays.asList("Quest Helper");
		List<String> classes = Arrays.asList("com.questhelper.QuestHelperPlugin");
		assertEquals(-1, PluginLookup.match("Zulrah Helper", names, classes));
		assertEquals(-1, PluginLookup.match("Tombs of Amascut", names, classes));
	}

	@Test
	public void nothingInstalledIsNotAMatch()
	{
		assertEquals(-1, PluginLookup.match("Quest Helper",
			Collections.emptyList(), Collections.emptyList()));
	}

	@Test
	public void missingNamesAndClassesAreSurvivable()
	{
		assertEquals(-1, PluginLookup.match(null, NAMES, CLASSES));
		assertEquals(-1, PluginLookup.match("Quest Helper", null, null));
		assertEquals(-1, PluginLookup.match("", NAMES, CLASSES));
	}
}

package com.nowwhat.diag;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemIdConstants;
import com.nowwhat.data.ItemTextParser;
import com.nowwhat.model.Activity;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.ItemID;

/**
 * How much of the bundled "what to bring" text turns into item pictures.
 * <p>
 * The icons themselves only exist in a running client, which makes this feature
 * awkward to judge from outside one: the question "does the gear show up" cannot
 * be answered by a screenshot of an offline panel, because offline there is no
 * item index at all. So this stands a proxy index in its place - RuneLite's
 * ItemID constants, which ship in the api jar - and reports, line by line, what
 * the parser would resolve.
 * <p>
 * The proxy is coarser than the real index: constant names lose the brackets
 * around variants ("MASORI_BODY_F" against "Masori body (f)") and dose numbers
 * run into the word ("PRAYER_POTION4"), so some of the misses listed here do
 * resolve in a client. It is a floor, not a measurement.
 */
public class IconCoverage
{
	public static void main(String[] args) throws Exception
	{
		List<ItemTextParser.Candidate> index = java.util.Collections.emptyList();
		System.out.println("fallback item index: " + ItemIdConstants.search("scythe").size()
			+ " names matching \"scythe\"");

		Gson gson = new Gson();
		ActivityDatabase ad = new ActivityDatabase(gson);
		ad.load();
		com.nowwhat.data.TrainingMethodDatabase tm = new com.nowwhat.data.TrainingMethodDatabase(gson);
		tm.load(ad.getAllActivities());

		int lines = 0;
		int resolved = 0;
		int picturesOnly = 0;
		List<String> misses = new ArrayList<>();

		// Activities first, then the training methods that carry a kit of their
		// own - both end up in the same box in the panel, so both are measured.
		Map<String, List<String>> sources = new LinkedHashMap<>();
		for (Activity activity : ad.getAllActivities())
		{
			List<String> entries = new ArrayList<>();
			for (Activity.GearSetup setup : activity.getSetups())
			{
				entries.addAll(setup.getItems());
			}
			entries.addAll(activity.getSupplies());
			if (!entries.isEmpty())
			{
				sources.put(activity.getName(), entries);
			}
		}
		for (com.nowwhat.model.TrainingMethod method : tm.getAllMethods())
		{
			List<String> entries = new ArrayList<>();
			entries.addAll(method.getGear());
			entries.addAll(method.getSupplies());
			// The shopping list goes through the same parser and the same icon
			// row, so a consumable that resolves to nothing would quietly print
			// as words where the count was meant to sit under a picture.
			for (com.nowwhat.model.TrainingMethod.Consumed consumed : method.getConsumes())
			{
				entries.add(consumed.getItem());
			}
			if (!entries.isEmpty())
			{
				sources.put(method.getSkill() + " - " + method.getName(), entries);
			}
		}

		for (Map.Entry<String, List<String>> source : sources.entrySet())
		{
			List<String> entries = source.getValue();
			if (entries.isEmpty())
			{
				continue;
			}

			System.out.println();
			System.out.println("== " + source.getKey());
			for (String entry : entries)
			{
				lines++;
				Map<Integer, String> found = new LinkedHashMap<>();
				Map<String, Boolean> optionMatched = new LinkedHashMap<>();
				for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(entry))
				{
					List<ItemTextParser.Candidate> candidates = search(index,
						ItemTextParser.searchTerm(phrase));
					Integer id = ItemTextParser.pick(phrase, candidates);
					optionMatched.merge(phrase.getText(), id != null, (a, b) -> a || b);
					if (id == null)
					{
						continue;
					}
					for (ItemTextParser.Candidate candidate : candidates)
					{
						if (candidate.getId() == id)
						{
							found.putIfAbsent(id, candidate.getName());
							break;
						}
					}
				}
				if (found.isEmpty())
				{
					misses.add(source.getKey() + ": " + entry);
					System.out.println("   --  " + entry);
				}
				else
				{
					resolved++;
					// Whether the panel will drop the words for this line, which
					// is the same test GearView applies.
					boolean complete = !optionMatched.containsValue(Boolean.FALSE);
					if (complete)
					{
						picturesOnly++;
					}
					System.out.println("   " + found.size() + (complete ? "x! " : "x  ") + entry
						+ "   ->  " + String.join(", ", found.values()));
				}
			}
		}

		System.out.println();
		System.out.println("lines with at least one icon: " + resolved + "/" + lines
			+ " (" + Math.round(100.0 * resolved / lines) + "%)");
		System.out.println("lines the pictures replace outright: " + picturesOnly
			+ "/" + lines + " (" + Math.round(100.0 * picturesOnly / lines) + "%)");
		System.out.println("lines with none: " + misses.size());
	}

	/**
	 * The same fallback index the panel uses when RuneLite's tradeable-only
	 * search comes up empty, so this measures the real thing rather than a
	 * stand-in. In a client the tradeable half additionally resolves against
	 * proper display names, so these numbers are a floor.
	 */
	private static List<ItemTextParser.Candidate> search(List<ItemTextParser.Candidate> unused,
		String term)
	{
		return ItemIdConstants.search(term);
	}
}

package com.nowwhat.diag;

import com.nowwhat.data.ItemIdConstants;
import com.nowwhat.data.ItemTextParser;
import java.util.List;

/**
 * Looks an item id up by name, out of RuneLite's own {@code ItemID} constants.
 * <p>
 * Every {@code gameItemId} in item-sources.json is supposed to have been read
 * out of {@code ItemID} rather than recalled, because two that were typed from
 * memory during the first pass were wrong and a wrong id is invisible until a
 * player sees the wrong picture. This is the reading. Adding an item to
 * {@code tools/gen_data.py} starts here:
 *
 * <pre>
 * ./gradlew itemid --args="osmumtens fang|elidinis ward|lightbearer"
 * </pre>
 *
 * Terms are separated by {@code |} because item names have spaces in them.
 * Each one prints every constant containing it, closest first, so an ambiguous
 * name ("masori body" against its (f) variant) is a choice you make looking at
 * the list rather than a guess.
 */
public final class ItemIdLookup
{
	private ItemIdLookup()
	{
	}

	public static void main(String[] args)
	{
		if (args.length == 0)
		{
			System.out.println("usage: --args=\"name|another name\"");
			return;
		}

		for (String term : String.join(" ", args).split("\\|"))
		{
			String needle = term.trim();
			if (needle.isEmpty())
			{
				continue;
			}
			System.out.println();
			System.out.println("== " + needle);
			List<ItemTextParser.Candidate> hits = ItemIdConstants.search(needle);
			if (hits.isEmpty())
			{
				System.out.println("   (nothing)");
				continue;
			}
			// Shortest first: the plain item before every charged, ornamented
			// and broken variant of it, which is nearly always the one wanted.
			hits.sort((a, b) -> a.getName().length() != b.getName().length()
				? Integer.compare(a.getName().length(), b.getName().length())
				: a.getName().compareTo(b.getName()));
			int shown = 0;
			for (ItemTextParser.Candidate hit : hits)
			{
				System.out.printf("   %-44s %d%n", hit.getName(), hit.getId());
				if (++shown >= 12)
				{
					System.out.println("   ... and " + (hits.size() - shown) + " more");
					break;
				}
			}
		}
	}
}

package com.nowwhat.diag;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemNameIndex;
import com.nowwhat.data.ItemTextParser;
import com.nowwhat.model.Activity;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Which slots each gear setup leaves empty, and which of its words never became
 * an item - the two reasons a loadout looks unfinished in the panel.
 * <p>
 * Slots come from RuneLite's own item stats, the file the client downloads at
 * startup. It is not bundled, so pass a saved copy:
 * {@code ./gradlew loadoutaudit -Pstats=path/to/stats.ids.min.json}
 * (from https://static.runelite.net/item/stats.ids.min.json).
 * <p>
 * Only the bundled name table is used to match words, which is what the panel
 * has for untradeable items; it also tries RuneLite's tradeable search, so a
 * tradeable item reported unmatched here can still be pictured in the client.
 */
public final class LoadoutAudit
{
	private static final Map<Integer, String> SLOTS = new LinkedHashMap<>();

	static
	{
		SLOTS.put(0, "head");
		SLOTS.put(1, "cape");
		SLOTS.put(2, "neck");
		SLOTS.put(3, "weapon");
		SLOTS.put(4, "body");
		SLOTS.put(5, "shield");
		SLOTS.put(7, "legs");
		SLOTS.put(9, "hands");
		SLOTS.put(10, "feet");
		SLOTS.put(12, "ring");
		SLOTS.put(13, "ammo");
	}

	private LoadoutAudit()
	{
	}

	public static void main(String[] args) throws IOException
	{
		if (args.length < 1)
		{
			throw new IllegalArgumentException("pass the path of a saved stats.ids.min.json");
		}
		Map<Integer, Integer> slotOf = new TreeMap<>();
		Set<Integer> twoHanded = new LinkedHashSet<>();
		try (Reader reader = Files.newBufferedReader(Paths.get(args[0]), StandardCharsets.UTF_8))
		{
			JsonObject stats = new Gson().fromJson(reader, JsonObject.class);
			for (Map.Entry<String, JsonElement> entry : stats.entrySet())
			{
				JsonObject item = entry.getValue().getAsJsonObject();
				if (item.has("equipment"))
				{
					JsonObject equipment = item.getAsJsonObject("equipment");
					int id = Integer.parseInt(entry.getKey());
					// The minified file drops zero fields, and head is slot 0.
					slotOf.put(id, equipment.has("slot") ? equipment.get("slot").getAsInt() : 0);
					if (equipment.has("is2h") && equipment.get("is2h").getAsBoolean())
					{
						twoHanded.add(id);
					}
				}
			}
		}

		ActivityDatabase activities = new ActivityDatabase(new Gson());
		activities.load();
		String only = args.length > 1 ? args[1] : null;

		for (Activity activity : activities.getAllActivities())
		{
			if (only != null && !activity.getId().contains(only))
			{
				continue;
			}
			for (Activity.GearSetup setup : activity.getSetups())
			{
				Set<Integer> filled = new LinkedHashSet<>();
				boolean twoHander = false;
				List<String> unmatched = new ArrayList<>();
				for (String line : setup.getItems())
				{
					for (ItemTextParser.Phrase phrase : ItemTextParser.phrases(line))
					{
						String term = ItemTextParser.searchTerm(phrase);
						Integer id = ItemTextParser.pick(phrase, ItemNameIndex.search(term));
						if (id == null)
						{
							unmatched.add(phrase.getText());
							continue;
						}
						Integer slot = slotOf.get(id);
						if (only != null)
						{
							// Asked about one fight: say what every phrase became.
							System.out.println("    \"" + phrase + "\" -> " + id + " "
								+ ItemNameIndex.search(term).stream().filter(c -> c.getId() == id)
									.map(ItemTextParser.Candidate::getName).findFirst().orElse("?")
								+ " -> " + (slot == null ? "not worn" : SLOTS.get(slot)));
						}
						if (slot == null)
						{
							continue;
						}
						filled.add(slot);
						twoHander |= slot == 3 && twoHanded.contains(id);
					}
				}
				List<String> empty = new ArrayList<>();
				for (Map.Entry<Integer, String> slot : SLOTS.entrySet())
				{
					boolean shieldTaken = slot.getKey() == 5 && twoHander;
					if (!filled.contains(slot.getKey()) && !shieldTaken)
					{
						empty.add(slot.getValue());
					}
				}
				System.out.println(activity.getId() + " | " + setup.getName()
					+ " | empty: " + String.join(",", empty)
					+ (unmatched.isEmpty() ? "" : " | unmatched: " + String.join("; ", unmatched)));
			}
		}
	}
}

package com.nowwhat.diag;

import com.google.gson.Gson;
import com.nowwhat.NowWhatConfig;
import com.nowwhat.NowWhatPanel;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.Activity;
import com.nowwhat.model.ItemSource;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

/**
 * Renders NowWhatPanel offline at real sidebar width so the layout can be
 * eyeballed without launching a client and logging in.
 */
public class PanelShot
{
	static final com.nowwhat.model.PlayerState STATE = new com.nowwhat.model.PlayerState();

	public static void main(String[] args) throws Exception
	{
		Gson gson = new Gson();
		ActivityDatabase ad = new ActivityDatabase(gson);
		ad.load();
		TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
		tm.load(ad.getAllActivities());
		ItemSourceDatabase is = new ItemSourceDatabase(gson);
		is.load();
		PathPlanner planner = new PathPlanner(ad.getAllActivities(),
			new PrerequisiteResolver(ad.getAllActivities()), tm, is);

		NowWhatConfig config = new NowWhatConfig()
		{
		};

		// An account that already meets most things, so the render exercises the
		// same code paths a logged-in player hits rather than the empty-state one.
		STATE.setSkillLevel("ATTACK", 75);
		STATE.setSkillLevel("RANGED", 78);
		STATE.setSkillLevel("MAGIC", 80);
		STATE.setSkillLevel("AGILITY", 60);
		STATE.addCompletedQuest("Regicide");

		final int width = Integer.parseInt(args[0]);
		final String out = args[1];
		final String pickActivity = args.length > 2 ? args[2] : null;
		// A long skill plan is taller than a sidebar ever is, and anything past
		// the frame height is simply not painted - so the height has to be
		// settable or the shot silently truncates the thing being checked.
		// After the mode: a height, and/or the account to plan for, written the
		// way paneltext takes it ("all=70", "quest=Bone+Voyage").
		int tall = 900;
		for (int i = 3; i < args.length; i++)
		{
			if (args[i].matches("[0-9]+"))
			{
				tall = Integer.parseInt(args[i]);
			}
			else if (args[i].startsWith("all="))
			{
				int level = Integer.parseInt(args[i].substring(4));
				for (net.runelite.api.Skill skill : net.runelite.api.Skill.values())
				{
					STATE.setSkillLevel(skill.name(), level);
				}
			}
			else if (args[i].startsWith("quest="))
			{
				STATE.addCompletedQuest(args[i].substring(6).replace('+', ' '));
			}
		}
		final int height = tall;

		// Built and clicked in one pass, captured in a second, with the event
		// queue drained in between. Anything the panel schedules for itself -
		// a resize listener, an invokeLater - only runs once this thread lets
		// the queue turn over, and a shot taken inside the first pass is a shot
		// of a layout that has not finished happening.
		final JFrame[] window = new JFrame[1];
		final NowWhatPanel[] built = new NowWhatPanel[1];
		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				goal -> planner.plan(goal, STATE));
			built[0] = panel;

			// Populate the suggestion lists the way a refresh would.
			List<Activity> some = ad.getAllActivities();
			panel.update(some.subList(0, Math.min(2, some.size())));

			// pack() makes the frame displayable (so Swing will lay out and
			// paint) without ever putting a window on screen.
			JFrame f = new JFrame();
			f.setUndecorated(true);
			f.getContentPane().add(panel);
			f.pack();
			f.setSize(width, height);
			f.validate();

			if ("choose".equals(pickActivity) || "roll".equals(pickActivity))
			{
				// The opening fork: click through to the screen being checked,
				// the way a player reaches it.
				panel.update(ad.getAllActivities(), ad.getAllActivities().subList(0, 4));
				clickLabel(panel, "choose".equals(pickActivity) ? "Plan a path" : "Surprise me");
			}
			else if (pickActivity != null)
			{
				// mode is "activity:<id>", "skill:<SKILL>:<level>" or "item:<ID>"
				String[] parts = pickActivity.split(":");
				List<JComboBox> combos = new ArrayList<>();
				findAll(panel, JComboBox.class, combos);
				List<javax.swing.JSpinner> spinners = new ArrayList<>();
				findAll(panel, javax.swing.JSpinner.class, spinners);
				// NB: a JComboBox contains its own arrow JButton, so filter by label.
				List<JButton> all = new ArrayList<>();
				findAll(panel, JButton.class, all);
				List<JButton> planButtons = new ArrayList<>();
				for (JButton b : all)
				{
					if ("Plan path".equals(b.getText()))
					{
						planButtons.add(b);
					}
				}

				int row;
				if ("skill".equals(parts[0]))
				{
					row = 1;
					combos.get(1).setSelectedItem(parts[1]);
					spinners.get(0).setValue(Integer.parseInt(parts[2]));
				}
				else if ("item".equals(parts[0]))
				{
					row = 2;
					// The item goal is a SearchPicker now, not a dropdown.
					List<com.nowwhat.SearchPicker> pickers = new ArrayList<>();
					findAll(panel, com.nowwhat.SearchPicker.class, pickers);
					selectIn(pickers.get(0), parts[1]);
				}
				else
				{
					row = 0;
					select(combos.get(0), parts[1]);
				}
				planButtons.get(row).doClick();
			}
			window[0] = f;
		});

		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = built[0];
			JFrame f = window[0];
			panel.doLayout();
			panel.validate();

			// What actually happened inside the results container?
			List<java.awt.Container> results = new ArrayList<>();
			dumpResults(panel, results);

			// PluginPanel is PANEL_WIDTH + SCROLLBAR_WIDTH wide on the outside by
			// design - 225 of viewport and 17 for the scrollbar - so comparing
			// its preferred width against the frame width reported an overflow
			// on every single run. It cried wolf for long enough to be believed
			// once and chased as a bug. What actually matters is whether
			// anything inside the viewport is too wide for it, and that is
			// PanelWidthTest's job, component by component.
			Dimension pref = panel.getPreferredSize();
			int sidebar = PluginPanel.PANEL_WIDTH + PluginPanel.SCROLLBAR_WIDTH;
			System.out.println("panel preferred size = " + pref.width + "x" + pref.height
				+ "  (frame width " + width + ", a real sidebar is " + sidebar + " outside)");
			System.out.println(pref.width > sidebar
				? "!! wider than a sidebar -> run PanelWidthTest to find what overflows"
				: "ok: fits a sidebar");

			BufferedImage img = new BufferedImage(panel.getWidth(), panel.getHeight(),
				BufferedImage.TYPE_INT_RGB);
			panel.printAll(img.getGraphics());
			try
			{
				ImageIO.write(img, "png", new File(out));
			}
			catch (Exception ex)
			{
				throw new RuntimeException(ex);
			}
			f.dispose();
		});
		System.exit(0);
	}

	/** Fires the first clickable label containing this text, as a mouse click would. */
	static boolean clickLabel(Container c, String needle)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof javax.swing.JLabel)
			{
				String text = ((javax.swing.JLabel) child).getText()
					.replaceAll("<[^>]*>", "").replace("&nbsp;", " ").trim();
				if (text.contains(needle) && child.getMouseListeners().length > 0)
				{
					java.awt.event.MouseEvent event = new java.awt.event.MouseEvent(child,
						java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
						0, 1, 1, 1, false);
					for (java.awt.event.MouseListener listener : child.getMouseListeners())
					{
						listener.mouseClicked(event);
					}
					return true;
				}
			}
			else if (child instanceof Container && clickLabel((Container) child, needle))
			{
				return true;
			}
		}
		return false;
	}

	/** Finds the results container by identity and reports what Swing did with it. */
	static void dumpResults(Container root, List<Container> acc)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof javax.swing.JPanel && c.getName() == null
				&& ((Container) c).getComponentCount() > 0
				&& ((Container) c).getComponent(0) instanceof javax.swing.JLabel)
			{
				javax.swing.JLabel first = (javax.swing.JLabel) ((Container) c).getComponent(0);
				if (first.getForeground().equals(java.awt.Color.CYAN))
				{
					System.out.println("RESULTS container: children=" + ((Container) c).getComponentCount()
						+ " bounds=" + c.getBounds()
						+ " pref=" + c.getPreferredSize()
						+ " max=" + ((javax.swing.JComponent) c).getMaximumSize()
						+ " visible=" + c.isVisible());
					for (Component k : ((Container) c).getComponents())
					{
						System.out.println("    child " + k.getClass().getSimpleName()
							+ " bounds=" + k.getBounds() + " pref=" + k.getPreferredSize());
					}
					return;
				}
			}
			if (c instanceof Container)
			{
				dumpResults((Container) c, acc);
			}
		}
	}

	/**
	 * Picks an entry out of a {@link com.nowwhat.SearchPicker} by id, which is
	 * what the harness means by "item:TWISTED_BOW". The picker is a text field
	 * and a filtered list, so there is no index to set - the entry is looked up
	 * and handed back to it.
	 */
	@SuppressWarnings("unchecked")
	private static void selectIn(com.nowwhat.SearchPicker picker, String id)
	{
		for (Object o : picker.getEntries())
		{
			String key = o instanceof Activity ? ((Activity) o).getId()
				: o instanceof ItemSource ? ((ItemSource) o).getId()
				: String.valueOf(o);
			if (key.equalsIgnoreCase(id))
			{
				picker.select(o);
				return;
			}
		}
		throw new IllegalArgumentException("no picker entry for " + id);
	}

	static void select(JComboBox combo, String id)
	{
		for (int i = 0; i < combo.getItemCount(); i++)
		{
			Object o = combo.getItemAt(i);
			String key = o instanceof Activity ? ((Activity) o).getId()
				: o instanceof com.nowwhat.model.ItemSource ? ((com.nowwhat.model.ItemSource) o).getId()
				: String.valueOf(o);
			if (key.equalsIgnoreCase(id))
			{
				combo.setSelectedIndex(i);
				return;
			}
		}
		throw new IllegalArgumentException("no combo entry for " + id);
	}

	@SuppressWarnings("unchecked")
	static <T> void findAll(Container root, Class<T> type, List<T> into)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				into.add((T) c);
			}
			if (c instanceof Container)
			{
				findAll((Container) c, type, into);
			}
		}
	}
}

package com.nowwhat.diag;

import com.google.gson.Gson;
import com.nowwhat.NowWhatConfig;
import com.nowwhat.NowWhatPanel;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.Activity;
import com.nowwhat.model.ItemSource;
import com.nowwhat.model.PlayerState;
import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SwingUtilities;

/**
 * Prints what the panel actually renders for a goal, as text, in order.
 * <p>
 * A PNG is the right check for spacing and a wrong one for structure: working
 * out from pixels whether eight level brackets collapsed into one step means
 * counting headings in an image. This dumps the rendered labels instead, so a
 * change to how steps are grouped can be read, diffed and checked in a second.
 * <p>
 * Usage: paneltext --args="skill:THIEVING:99 THIEVING=76 pick=Pyramid+Plunder"
 * <br>A pick= argument spells spaces as +, since the args arrive split on space.
 * <br>Later arguments set starting levels; the goal is the first.
 */
public class PanelText
{
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception
	{
		Gson gson = new Gson();
		ActivityDatabase ad = new ActivityDatabase(gson);
		ad.load();
		TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
		tm.load(ad.getAllActivities());
		ItemSourceDatabase is = new ItemSourceDatabase(gson);
		is.load();
		PathPlanner planner = new PathPlanner(ad.getAllActivities(),
			new PrerequisiteResolver(ad.getAllActivities()), tm, is);

		PlayerState state = new PlayerState();
		for (int i = 1; i < args.length; i++)
		{
			if (args[i].startsWith("pick=") || args[i].startsWith("click="))
			{
				continue;
			}
			if (args[i].startsWith("all="))
			{
				// Every skill at once, for reaching the "you already meet every
				// requirement" branch without listing twenty-three of them.
				int level = Integer.parseInt(args[i].substring(4));
				for (String skill : new String[]{"ATTACK", "DEFENCE", "STRENGTH", "HITPOINTS",
					"RANGED", "PRAYER", "MAGIC", "COOKING", "WOODCUTTING", "FLETCHING",
					"FISHING", "FIREMAKING", "CRAFTING", "SMITHING", "MINING", "HERBLORE",
					"AGILITY", "THIEVING", "SLAYER", "FARMING", "RUNECRAFT", "HUNTER",
					"CONSTRUCTION"})
				{
					state.setSkillLevel(skill, level);
				}
				continue;
			}
			if (args[i].startsWith("quest="))
			{
				state.addCompletedQuest(args[i].substring(6).replace('+', ' '));
				continue;
			}
			if (args[i].startsWith("own="))
			{
				// own=<gameItemId>x<count>, plus the bank snapshot flag the
				// planner checks before trusting any of it.
				String[] owned = args[i].substring(4).split("x");
				java.util.Map<Integer, Integer> items = new java.util.HashMap<>();
				items.put(Integer.parseInt(owned[0]), Integer.parseInt(owned[1]));
				state.setOwnedItems(items);
				state.setBankSnapshotAvailable(true);
				continue;
			}
			String[] kv = args[i].split("=");
			state.setSkillLevel(kv[0].toUpperCase(), Integer.parseInt(kv[1]));
		}

		String goal = args[0];
		NowWhatConfig config = new NowWhatConfig()
		{
		};

		SwingUtilities.invokeAndWait(() ->
		{
			NowWhatPanel panel = new NowWhatPanel(config, ad.getAllActivities(), is.getAllSources(),
				g -> planner.plan(g, state));

			JFrame f = new JFrame();
			f.setUndecorated(true);
			f.getContentPane().add(panel);
			f.pack();
			f.setSize(240, 900);
			f.validate();

			// The pool a roll draws from, as a live refresh would supply it.
			panel.update(ad.getAllActivities(), ad.getAllActivities().subList(0, 4));

			String[] parts = goal.split(":");
			if ("start".equals(parts[0]) || "roll".equals(parts[0]))
			{
				if ("roll".equals(parts[0]))
				{
					clickIn(panel, "Surprise me");
					for (int i = 1; i < args.length; i++)
					{
						if (args[i].startsWith("click="))
						{
							clickIn(panel, args[i].substring(6).replace('+', ' '));
						}
					}
				}
				print(panel, 0);
				f.dispose();
				return;
			}
			List<JComboBox> combos = new ArrayList<>();
			findAll(panel, JComboBox.class, combos);
			List<JSpinner> spinners = new ArrayList<>();
			findAll(panel, JSpinner.class, spinners);
			List<JButton> buttons = new ArrayList<>();
			findAll(panel, JButton.class, buttons);
			List<JButton> planButtons = new ArrayList<>();
			for (JButton b : buttons)
			{
				if ("Plan path".equals(b.getText()))
				{
					planButtons.add(b);
				}
			}

			int row;
			if ("skill".equals(parts[0]))
			{
				row = 1;
				combos.get(1).setSelectedItem(parts[1]);
				spinners.get(0).setValue(Integer.parseInt(parts[2]));
			}
			else if ("item".equals(parts[0]))
			{
				row = 2;
				// The item goal is a SearchPicker now, not a dropdown.
				List<com.nowwhat.SearchPicker> pickers = new ArrayList<>();
				findAll(panel, com.nowwhat.SearchPicker.class, pickers);
				selectIn(pickers.get(0), parts[1]);
				if (parts.length > 2)
				{
					spinners.get(1).setValue(Integer.parseInt(parts[2]));
				}
			}
			else if ("base".equals(parts[0]))
			{
				row = 3;
				spinners.get(2).setValue(Integer.parseInt(parts[1]));
			}
			else if ("total".equals(parts[0]))
			{
				row = 4;
				spinners.get(3).setValue(Integer.parseInt(parts[1]));
			}
			else
			{
				row = 0;
				select(combos.get(0), parts[1]);
			}
			planButtons.get(row).doClick();

			// Pre-chosen methods, so the collapsed-and-merged view a player sees
			// after clicking a method can be dumped too, not just the first one.
			List<String> picks = new ArrayList<>();
			for (int i = 1; i < args.length; i++)
			{
				if (args[i].startsWith("pick="))
				{
					picks.add(args[i].substring(5).replace('+', ' '));
				}
			}
			if (!picks.isEmpty())
			{
				try
				{
					Object plan = planOf(panel);
					Field chosen = plan.getClass().getDeclaredField("chosenOptions");
					chosen.setAccessible(true);
					((java.util.Set<String>) chosen.get(plan)).addAll(picks);
				}
				catch (ReflectiveOperationException ex)
				{
					throw new RuntimeException(ex);
				}
				planButtons.get(row).doClick();
			}

			try
			{
				Object plan = planOf(panel);
				Field field = plan.getClass().getDeclaredField("pathResultContainer");
				field.setAccessible(true);
				Container results = (Container) field.get(plan);

				// A click= argument drives the links in the rendered plan, so the
				// expanded views can be dumped too - which is where the grouping
				// code is easiest to get wrong and hardest to see.
				for (int i = 1; i < args.length; i++)
				{
					if (!args[i].startsWith("click="))
					{
						continue;
					}
					String needle = args[i].substring(6).replace('+', ' ');
					if (!click(results, needle))
					{
						System.out.println("!! no clickable label containing: " + needle);
					}
					results = (Container) field.get(panel);
				}
				print(results, 0);
			}
			catch (ReflectiveOperationException ex)
			{
				throw new RuntimeException(ex);
			}
			f.dispose();
		});
		System.exit(0);
	}

	private static void print(Container c, int depth)
	{
		for (Component child : c.getComponents())
		{
			if (!child.isVisible())
			{
				continue;
			}
			if (child instanceof JLabel)
			{
				String text = plain((JLabel) child);
				if (!text.isEmpty())
				{
					System.out.println(indent(depth) + text);
				}
			}
			else if (child instanceof JPanel && ((JPanel) child).getComponentCount() == 0)
			{
				System.out.println(indent(depth) + "---------------");
			}
			else if (child instanceof Container)
			{
				print((Container) child, depth);
			}
		}
	}

	private static void clickIn(Container root, String needle)
	{
		if (!click(root, needle))
		{
			System.out.println("!! nothing clickable containing: " + needle);
		}
	}

	/** Fires the first label whose text contains `needle`, as a mouse click would. */
	private static boolean click(Container c, String needle)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JLabel)
			{
				String text = plain((JLabel) child);
				if (text.contains(needle) && ((JLabel) child).getMouseListeners().length > 0)
				{
					java.awt.event.MouseEvent event = new java.awt.event.MouseEvent(child,
						java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
						0, 1, 1, 1, false);
					for (java.awt.event.MouseListener listener : child.getMouseListeners())
					{
						listener.mouseClicked(event);
					}
					return true;
				}
			}
			else if (child instanceof Container && click((Container) child, needle))
			{
				return true;
			}
		}
		return false;
	}

	private static String plain(JLabel label)
	{
		return label.getText().replaceAll("<[^>]*>", "").replace("&nbsp;", " ").trim();
	}

	private static String indent(int depth)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < depth; i++)
		{
			sb.append("  ");
		}
		return sb.toString();
	}

	/**
	 * Picks an entry out of a {@link com.nowwhat.SearchPicker} by id, which is
	 * what the harness means by "item:TWISTED_BOW". The picker is a text field
	 * and a filtered list, so there is no index to set - the entry is looked up
	 * and handed back to it.
	 */
	@SuppressWarnings("unchecked")
	private static void selectIn(com.nowwhat.SearchPicker picker, String id)
	{
		for (Object o : picker.getEntries())
		{
			String key = o instanceof Activity ? ((Activity) o).getId()
				: o instanceof ItemSource ? ((ItemSource) o).getId()
				: String.valueOf(o);
			if (key.equalsIgnoreCase(id))
			{
				picker.select(o);
				return;
			}
		}
		throw new IllegalArgumentException("no picker entry for " + id);
	}

	/** The panel's plan view, which holds the rendered plan and the choices made in it. */
	private static Object planOf(NowWhatPanel panel) throws ReflectiveOperationException
	{
		Field plan = NowWhatPanel.class.getDeclaredField("plan");
		plan.setAccessible(true);
		return plan.get(panel);
	}

	private static void select(JComboBox combo, String id)
	{
		for (int i = 0; i < combo.getItemCount(); i++)
		{
			Object o = combo.getItemAt(i);
			String key = o instanceof Activity ? ((Activity) o).getId()
				: o instanceof ItemSource ? ((ItemSource) o).getId()
				: String.valueOf(o);
			if (key.equalsIgnoreCase(id))
			{
				combo.setSelectedIndex(i);
				return;
			}
		}
		throw new IllegalArgumentException("no combo entry for " + id);
	}

	@SuppressWarnings("unchecked")
	private static <T> void findAll(Container root, Class<T> type, List<T> acc)
	{
		for (Component c : root.getComponents())
		{
			if (type.isInstance(c))
			{
				acc.add((T) c);
			}
			if (c instanceof Container)
			{
				findAll((Container) c, type, acc);
			}
		}
	}
}

package com.nowwhat.diag;

import com.google.gson.Gson;
import com.nowwhat.data.ActivityDatabase;
import com.nowwhat.data.ItemSourceDatabase;
import com.nowwhat.data.TrainingMethodDatabase;
import com.nowwhat.engine.PathPlanner;
import com.nowwhat.engine.PrerequisiteResolver;
import com.nowwhat.model.Activity;
import com.nowwhat.model.Goal;
import com.nowwhat.model.Path;
import com.nowwhat.model.PathStep;
import com.nowwhat.model.PlayerState;

public class PlanDiag
{
	public static void main(String[] args)
	{
		Gson gson = new Gson();
		ActivityDatabase ad = new ActivityDatabase(gson);
		ad.load();
		TrainingMethodDatabase tm = new TrainingMethodDatabase(gson);
		tm.load(ad.getAllActivities());
		ItemSourceDatabase is = new ItemSourceDatabase(gson);
		is.load();

		PrerequisiteResolver pr = new PrerequisiteResolver(ad.getAllActivities());
		PathPlanner planner = new PathPlanner(ad.getAllActivities(), pr, tm, is);

		// Empty state = what latestState holds before any refresh has run.
		PlayerState empty = new PlayerState();

		for (Activity a : ad.getAllActivities())
		{
			Path p = planner.plan(Goal.activity(a.getId(), a.getName(), false), empty);
			System.out.println("ACTIVITY " + a.getId()
				+ " | complete=" + p.isAlreadyComplete()
				+ " | steps=" + p.getSteps().size()
				+ " | warnings=" + p.getWarnings().size());
			for (PathStep s : p.getSteps())
			{
				System.out.println("    step: " + s.getType() + " :: " + s.getTitle()
					+ " :: alts=" + s.getAlternatives().size());
			}
			for (String w : p.getWarnings())
			{
				System.out.println("    warn: " + w);
			}
		}

		Path sk = planner.plan(Goal.skillLevel("MINING", 70, false), empty);
		System.out.println("SKILL MINING->70 | complete=" + sk.isAlreadyComplete()
			+ " | steps=" + sk.getSteps().size() + " | warnings=" + sk.getWarnings().size());
		for (PathStep s : sk.getSteps())
		{
			System.out.println("    step: " + s.getType() + " :: " + s.getTitle()
				+ " :: alts=" + s.getAlternatives().size());
		}
	}
}

