		ItemSource a = new ItemSource("A", "Part A", ItemSource.SourceType.GE_BUY,
			null, null, null, quest, Collections.emptyList());
		ItemSource b = new ItemSource("B", "Part B", ItemSource.SourceType.GE_BUY,
			null, null, null, quest, Collections.emptyList());
		ItemSource whole = new ItemSource("WHOLE", "Whole", ItemSource.SourceType.CRAFT,
			"Put together", null, null, null, Arrays.asList(
				new ItemSource.Ingredient("A", 1),
				new ItemSource.Ingredient("B", 1)));

		PathPlanner planner = new PathPlanner(Collections.emptyList(),
			new PrerequisiteResolver(Collections.emptyList()),
			TrainingMethodDatabase.of(Collections.emptyList()),
			ItemSourceDatabase.of(Arrays.asList(a, b, whole)));

		Path path = planner.plan(Goal.itemQuantity("WHOLE", 1, "Whole", false), new PlayerState());

		long questSteps = path.getSteps().stream()
			.filter(s -> s.getType() != PathStep.Type.ACQUIRE_ITEM)
			.count();
		assertTrue(path.getSteps().toString(), questSteps <= 1);
		assertEquals(path.getSteps().toString(), 3,
			path.getSteps().stream().filter(s -> s.getType() == PathStep.Type.ACQUIRE_ITEM).count());
	}

	/**
	 * Levels come before the quests that ask for them: a plan that opens with
	 * quests the player cannot start yet has its steps in the wrong order.
	 */
	@Test
	public void activityGoalListsTrainingBeforeTheQuestsThatNeedIt()
	{
		Activity quest = new Activity("q1", "Gate Quest", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 30)));
		Activity boss = new Activity("boss", "Some Boss", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Gate Quest", 0)));
		TrainingMethod method = new TrainingMethod("AGILITY", 1, 99, "Some course", 20000, null, null,
			Intensity.NORMAL);
		PathPlanner planner = new PathPlanner(Arrays.asList(quest, boss),
			new PrerequisiteResolver(Arrays.asList(quest, boss)),
			TrainingMethodDatabase.of(Arrays.asList(method)),
			ItemSourceDatabase.of(Collections.emptyList()));

		Path path = planner.plan(Goal.activity("boss", "Some Boss", false), new PlayerState());

		assertEquals(path.getSteps().toString(), 3, path.getSteps().size());
		assertEquals(PathStep.Type.TRAIN_SKILL, path.getSteps().get(0).getType());
		assertEquals(PathStep.Type.DO_QUEST, path.getSteps().get(1).getType());
		assertTrue(path.getSteps().get(2).isTarget());
	}

	/**
	 * The suggestion list holds a fight back for its recommended stats, so the
	 * plan has to know about them too - as steps marked recommended, picking up
	 * where the required level leaves off.
	 */
	@Test
	public void recommendedStatsBecomeRecommendedStepsAfterTheRequiredOnes()
	{
		Activity boss = new Activity("boss", "Some Boss", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "RANGED", 70)))
			.withRecommended(Arrays.asList(
				new Requirement(Requirement.Type.SKILL_LEVEL, "RANGED", 85)), false);
		TrainingMethod method = new TrainingMethod("RANGED", 1, 99, "Some monster", 50000, null, null,
			Intensity.NORMAL);
		PathPlanner planner = new PathPlanner(Arrays.asList(boss),
			new PrerequisiteResolver(Arrays.asList(boss)),
			TrainingMethodDatabase.of(Arrays.asList(method)),
			ItemSourceDatabase.of(Collections.emptyList()));

		PlayerState state = new PlayerState();
		state.setSkillLevel("RANGED", 60);
		Path path = planner.plan(Goal.activity("boss", "Some Boss", false), state);

		assertEquals(path.getSteps().toString(), 3, path.getSteps().size());
		PathStep required = path.getSteps().get(0);
		assertEquals(60, required.getLevelFrom());
		assertEquals(70, required.getLevelTo());
		assertEquals(false, required.isRecommended());
		PathStep recommended = path.getSteps().get(1);
		assertEquals(70, recommended.getLevelFrom());
		assertEquals(85, recommended.getLevelTo());
		assertTrue(recommended.isRecommended());
		assertEquals(false, path.isRequirementsAlreadyMet());

		// With the recommended stats met as well, nothing is left to say.
		state.setSkillLevel("RANGED", 85);
		assertTrue(planner.plan(Goal.activity("boss", "Some Boss", false), state)
			.isRequirementsAlreadyMet());
	}

	/**
	 * Only the finished item used to be checked against what the player owns,
	 * so holding two of three parts still meant being sent for all three.
	 */
	@Test
	public void ingredientsAlreadyOwnedAreLeftOutOfAnItemPlan()
	{
		ItemSource a = new ItemSource("A", "Part A", ItemSource.SourceType.GE_BUY,
			null, null, null, null, Collections.emptyList()).withGameItemId(101);
		ItemSource b = new ItemSource("B", "Part B", ItemSource.SourceType.GE_BUY,
			null, null, null, null, Collections.emptyList()).withGameItemId(102);
		ItemSource whole = new ItemSource("WHOLE", "Whole", ItemSource.SourceType.CRAFT,
			"Put together", null, null, null, Arrays.asList(
				new ItemSource.Ingredient("A", 1),
				new ItemSource.Ingredient("B", 5))).withGameItemId(100);
		PathPlanner planner = new PathPlanner(Collections.emptyList(),
			new PrerequisiteResolver(Collections.emptyList()),
			TrainingMethodDatabase.of(Collections.emptyList()),
			ItemSourceDatabase.of(Arrays.asList(a, b, whole)));

		PlayerState state = new PlayerState();
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		owned.put(101, 1);
		owned.put(102, 2);
		state.setOwnedItems(owned);
		state.setBankSnapshotAvailable(true);

		Path path = planner.plan(Goal.itemQuantity("WHOLE", 1, "Whole", false), state);

		// Part A is covered outright; Part B is three short; then the craft.
		assertEquals(path.getSteps().toString(), 2, path.getSteps().size());
		assertEquals("Buy 3x Part B", path.getSteps().get(0).getTitle());
		assertEquals("Craft 1x Whole", path.getSteps().get(1).getTitle());
		assertTrue(path.getWarnings().toString(),
			path.getWarnings().stream().anyMatch(w -> w.contains("Part A")));

		// Asked for as if nothing were owned, everything is planned.
		Path fromNothing = planner.plan(
			Goal.itemQuantity("WHOLE", 1, "Whole", false).ignoringWhatIsOwned(), state);
		assertEquals(fromNothing.getSteps().toString(), 3, fromNothing.getSteps().size());
	}
}

package com.nowwhat.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.PrerequisiteChain;
import com.nowwhat.model.Requirement;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class PrerequisiteResolverTest
{
	@Test
	public void alreadyUnlockedActivityReturnsEmptyChain()
	{
		Activity quest = new Activity("q1", "Simple Quest", Activity.Category.QUEST, Arrays.asList());
		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(quest));

		PlayerState state = new PlayerState();
		state.addCompletedQuest("Simple Quest");

		PrerequisiteChain chain = resolver.resolve(quest, state);

		assertTrue(chain.isAlreadyUnlocked());
		assertTrue(chain.getRequiredActivitiesInOrder().isEmpty());
	}

	@Test
	public void transitiveQuestChainIsResolvedInPrerequisiteFirstOrder()
	{
		Activity questOne = new Activity("q1", "Quest One", Activity.Category.QUEST, Arrays.asList());
		Activity questTwo = new Activity("q2", "Quest Two", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Quest One", 0)
		));
		Activity targetBoss = new Activity("boss", "Some Boss", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Quest Two", 0)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(questOne, questTwo, targetBoss));
		PlayerState state = new PlayerState(); // nothing completed

		PrerequisiteChain chain = resolver.resolve(targetBoss, state);

		List<Activity> steps = chain.getRequiredActivitiesInOrder();
		assertEquals(2, steps.size());
		assertEquals("Quest One", steps.get(0).getName()); // deepest prerequisite first
		assertEquals("Quest Two", steps.get(1).getName());
		assertTrue(chain.getUnresolvedReferences().isEmpty());
	}

	@Test
	public void alreadyMetLinksInTheChainAreSkipped()
	{
		Activity questOne = new Activity("q1", "Quest One", Activity.Category.QUEST, Arrays.asList());
		Activity questTwo = new Activity("q2", "Quest Two", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Quest One", 0)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(questOne, questTwo));
		PlayerState state = new PlayerState();
		state.addCompletedQuest("Quest One"); // already done - shouldn't appear in the chain

		PrerequisiteChain chain = resolver.resolve(questTwo, state);

		assertTrue(chain.getRequiredActivitiesInOrder().isEmpty());
	}

	@Test
	public void unknownQuestReferenceIsReportedNotSilentlyDropped()
	{
		Activity target = new Activity("q1", "Quest With Gap", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Nonexistent Quest", 0)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(target));
		PrerequisiteChain chain = resolver.resolve(target, new PlayerState());

		assertEquals(1, chain.getUnresolvedReferences().size());
		assertTrue(chain.getUnresolvedReferences().get(0).contains("Nonexistent Quest"));
	}

	@Test
	public void circularQuestReferenceDoesNotInfiniteLoop()
	{
		// A -> requires B, B -> requires A. Must terminate, not hang.
		Activity questA = new Activity("qa", "Quest A", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Quest B", 0)
		));
		Activity questB = new Activity("qb", "Quest B", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Quest A", 0)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(questA, questB));

		// The assertion here is really "this call returns at all" - a hang
		// would time out the test run rather than fail an assertion.
		PrerequisiteChain chain = resolver.resolve(questA, new PlayerState());

		assertTrue(chain.getUnresolvedReferences().stream().anyMatch(s -> s.contains("circular")));
	}

	@Test
	public void theSameSkillAskedTwiceKeepsTheHigherLevel()
	{
		// The low ask is walked first, as The Dig Site's 10 Agility is on the
		// way to Desert Treasure II's 69.
		Activity early = new Activity("q1", "Early Quest", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 10)
		));
		Activity late = new Activity("q2", "Late Quest", Activity.Category.QUEST, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Early Quest", 0),
			new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 69)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(early, late));
		PrerequisiteChain chain = resolver.resolve(late, new PlayerState());

		assertEquals(1, chain.getStandaloneRequirements().size());
		assertEquals(69, chain.getStandaloneRequirements().get(0).getThreshold());
	}

	@Test
	public void twoDifferentChoicesAreBothKept()
	{
		Activity target = new Activity("boss", "Some Boss", Activity.Category.PVM, Arrays.asList(
			Requirement.anyOf(
				new Requirement(Requirement.Type.SKILL_LEVEL, "ATTACK", 99),
				new Requirement(Requirement.Type.SKILL_LEVEL, "STRENGTH", 99)),
			Requirement.anyOf(
				new Requirement(Requirement.Type.SKILL_LEVEL, "RANGED", 99),
				new Requirement(Requirement.Type.SKILL_LEVEL, "MAGIC", 99))
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(target));
		PrerequisiteChain chain = resolver.resolve(target, new PlayerState());

		assertEquals(2, chain.getStandaloneRequirements().size());
	}

	@Test
	public void diaryTierChainResolvesThroughLowerTierFirst()
	{
		Activity easyTier = new Activity("ARDOUGNE_EASY", "Ardougne Easy", Activity.Category.DIARY, Arrays.asList());
		Activity mediumTier = new Activity("ARDOUGNE_MEDIUM", "Ardougne Medium", Activity.Category.DIARY, Arrays.asList(
			new Requirement(Requirement.Type.DIARY_COMPLETE, "ARDOUGNE_EASY", 0)
		));

		PrerequisiteResolver resolver = new PrerequisiteResolver(Arrays.asList(easyTier, mediumTier));
		PrerequisiteChain chain = resolver.resolve(mediumTier, new PlayerState());

		assertEquals(1, chain.getRequiredActivitiesInOrder().size());
		assertEquals("Ardougne Easy", chain.getRequiredActivitiesInOrder().get(0).getName());
	}
}

package com.nowwhat.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.Requirement;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * Plenty of fights have no requirement at all, and with only requirements to
 * go on a fresh account was told to do the Inferno. The wiki's recommended
 * stats decide what is suggested; they never decide what can be planned.
 */
public class RecommendedStatsTest
{
	private final SuggestionEngine engine = new SuggestionEngine();
	private PlayerState state;

	@Before
	public void setUp()
	{
		state = new PlayerState();
	}

	private static Activity fight(boolean wilderness, Requirement... recommended)
	{
		return new Activity("pvm_x", "Test fight", Activity.Category.PVM, Collections.emptyList())
			.withRecommended(Arrays.asList(recommended), wilderness);
	}

	private static Requirement level(String skill, int level)
	{
		return new Requirement(Requirement.Type.SKILL_LEVEL, skill, level);
	}

	@Test
	public void aFightWithNoRequirementsIsNotSuggestedBelowItsRecommendedStats()
	{
		state.setSkillLevel("RANGED", 40);
		List<Activity> all = Collections.singletonList(fight(false, level("RANGED", 90)));

		assertTrue(engine.getAvailableNow(all, state).isEmpty());
		assertTrue("50 levels short is not almost", engine.getAlmostAvailable(all, state).isEmpty());
	}

	@Test
	public void aFewLevelsShortOfTheRecommendationIsAlmostThere()
	{
		state.setSkillLevel("RANGED", 87);
		state.setSkillLevel("DEFENCE", 70);
		Activity fight = fight(false, level("RANGED", 90), level("DEFENCE", 70));
		List<Activity> all = Collections.singletonList(fight);

		assertTrue(engine.getAvailableNow(all, state).isEmpty());
		assertEquals(all, engine.getAlmostAvailable(all, state));
		assertEquals("Recommended 90 Ranged, you have 87", engine.whatIsMissing(fight, state));
	}

	@Test
	public void meetingTheRecommendationMakesItAvailable()
	{
		state.setSkillLevel("RANGED", 90);
		List<Activity> all = Collections.singletonList(fight(false, level("RANGED", 90)));

		assertEquals(all, engine.getAvailableNow(all, state));
	}

	@Test
	public void anyCombatStyleTheWikiOffersIsEnough()
	{
		state.setSkillLevel("ATTACK", 85);
		state.setSkillLevel("STRENGTH", 85);
		Requirement meleeOrRanged = Requirement.anyOf(
			new Requirement(Requirement.Type.COMBINED_SKILL_LEVEL, "ATTACK,STRENGTH", 170),
			level("RANGED", 90));
		List<Activity> all = Collections.singletonList(fight(false, meleeOrRanged));

		assertEquals(all, engine.getAvailableNow(all, state));
	}

	@Test
	public void theWildernessSwitchHidesWildernessFightsOnly()
	{
		Activity wild = fight(true);
		Activity safe = new Activity("pvm_y", "Safe fight", Activity.Category.PVM, Collections.emptyList());
		List<Activity> all = Arrays.asList(wild, safe);

		assertEquals(2, engine.getAvailableNow(all, state).size());
		assertEquals(Collections.singletonList(safe),
			engine.getAvailableNow(all, state, EnumSet.noneOf(Activity.Category.class), true));
	}
}

package com.nowwhat.engine;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.Requirement;
import java.util.Collections;
import org.junit.Test;

public class RequirementEvaluatorTest
{
	@Test
	public void skillLevelMetAndUnmet()
	{
		PlayerState state = new PlayerState();
		state.setSkillLevel("AGILITY", 50);

		assertTrue(RequirementEvaluator.isMet(new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 47), state));
		assertTrue(RequirementEvaluator.isMet(new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 50), state));
		assertFalse(RequirementEvaluator.isMet(new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 51), state));
	}

	@Test
	public void questCompleteChecksExactName()
	{
		PlayerState state = new PlayerState();
		state.addCompletedQuest("Dragon Slayer I");

		assertTrue(RequirementEvaluator.isMet(new Requirement(Requirement.Type.QUEST_COMPLETE, "Dragon Slayer I", 0), state));
		assertFalse(RequirementEvaluator.isMet(new Requirement(Requirement.Type.QUEST_COMPLETE, "Dragon Slayer II", 0), state));
	}

	@Test
	public void anyOfIsMetWhenAnySingleChildIsMet()
	{
		PlayerState state = new PlayerState();
		state.setSkillLevel("ATTACK", 60);
		state.setSkillLevel("STRENGTH", 99);

		Requirement anyOf = Requirement.anyOf(
			new Requirement(Requirement.Type.SKILL_LEVEL, "ATTACK", 99),
			new Requirement(Requirement.Type.SKILL_LEVEL, "STRENGTH", 99)
		);

		assertTrue(RequirementEvaluator.isMet(anyOf, state));
	}

	@Test
	public void anyOfIsUnmetWhenNoChildIsMet()
	{
		PlayerState state = new PlayerState();
		state.setSkillLevel("ATTACK", 60);
		state.setSkillLevel("STRENGTH", 60);

		Requirement anyOf = Requirement.anyOf(
			new Requirement(Requirement.Type.SKILL_LEVEL, "ATTACK", 99),
			new Requirement(Requirement.Type.SKILL_LEVEL, "STRENGTH", 99)
		);

		assertFalse(RequirementEvaluator.isMet(anyOf, state));
	}

	@Test
	public void combinedSkillLevelSumsAllListedSkills()
	{
		PlayerState state = new PlayerState();
		state.setSkillLevel("ATTACK", 65);
		state.setSkillLevel("STRENGTH", 65); // combined 130

		assertTrue(RequirementEvaluator.isMet(
			new Requirement(Requirement.Type.COMBINED_SKILL_LEVEL, "ATTACK,STRENGTH", 130), state));
		assertFalse(RequirementEvaluator.isMet(
			new Requirement(Requirement.Type.COMBINED_SKILL_LEVEL, "ATTACK,STRENGTH", 131), state));
	}

	@Test
	public void warriorsGuildStyleGateIsMetByTheCombinedBranchAlone()
	{
		// Regression guard for the exact real-game shape: neither single skill
		// at 99, but the combined branch of the ANY_OF still satisfies it.
		PlayerState state = new PlayerState();
		state.setSkillLevel("ATTACK", 65);
		state.setSkillLevel("STRENGTH", 65);

		Requirement anyOf = Requirement.anyOf(
			new Requirement(Requirement.Type.SKILL_LEVEL, "ATTACK", 99),
			new Requirement(Requirement.Type.SKILL_LEVEL, "STRENGTH", 99),
			new Requirement(Requirement.Type.COMBINED_SKILL_LEVEL, "ATTACK,STRENGTH", 130)
		);

		assertTrue(RequirementEvaluator.isMet(anyOf, state));
	}

	@Test
	public void isAlreadyDoneDelegatesToCategorySpecificState()
	{
		PlayerState state = new PlayerState();
		state.addCompletedQuest("Cook's Assistant");

		Activity quest = new Activity("quest_x", "Cook's Assistant", Activity.Category.QUEST, Collections.emptyList());
		assertTrue(RequirementEvaluator.isAlreadyDone(quest, state));

		Activity unrelatedQuest = new Activity("quest_y", "Some Other Quest", Activity.Category.QUEST, Collections.emptyList());
		assertFalse(RequirementEvaluator.isAlreadyDone(unrelatedQuest, state));
	}

	@Test
	public void isAlreadyDoneIsFalseForOpenEndedCategories()
	{
		// PVM/SKILLING/MINIGAME/CLUE_SCROLL have no single "done" state.
		PlayerState state = new PlayerState();
		Activity pvm = new Activity("pvm_x", "Some Boss", Activity.Category.PVM, Collections.emptyList());
		assertFalse(RequirementEvaluator.isAlreadyDone(pvm, state));
	}
}

package com.nowwhat.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.nowwhat.model.PathStep;
import com.nowwhat.model.TrainingMethod;
import com.nowwhat.model.TrainingMethod.Intensity;
import com.nowwhat.model.TrainingMethod.Risk;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class SkillPathPlannerTest
{
	private final SkillPathPlanner planner = new SkillPathPlanner();

	private static TrainingMethod normal(int min, int max, String name, Integer xpHr)
	{
		return new TrainingMethod("MINING", min, max, name, xpHr, null, null, Intensity.NORMAL);
	}

	private static TrainingMethod tick(int min, int max, String name, Integer xpHr)
	{
		return new TrainingMethod("MINING", min, max, name, xpHr, null, null, Intensity.TICK_MANIPULATION);
	}

	private static TrainingMethod wilderness(int min, int max, String name, Integer xpHr)
	{
		return new TrainingMethod("MINING", min, max, name, xpHr, null, null, Intensity.NORMAL, Risk.PVP);
	}

	@Test
	public void noDataProducesNoStepsAndAWarning()
	{
		List<String> warnings = new ArrayList<>();
		List<PathStep> steps = planner.plan("MINING", 1, 50, new ArrayList<>(), false, warnings);

		assertTrue(steps.isEmpty());
		assertEquals(1, warnings.size());
	}

	@Test
	public void alreadyAtOrAboveTargetProducesNoSteps()
	{
		List<String> warnings = new ArrayList<>();
		List<PathStep> steps = planner.plan("MINING", 50, 40,
			Arrays.asList(normal(1, 99, "Iron ore", 20000)), false, warnings);

		assertTrue(steps.isEmpty());
		assertTrue(warnings.isEmpty());
	}

	@Test
	public void segmentsSplitAtMethodBoundaries()
	{
		// Two non-overlapping methods covering the full range: expect exactly
		// two segments, split precisely at the boundary between them.
		List<TrainingMethod> methods = Arrays.asList(
			normal(1, 15, "Copper/Tin", 8000),
			normal(15, 40, "Iron ore", 20000)
		);
		List<String> warnings = new ArrayList<>();

		List<PathStep> steps = planner.plan("MINING", 1, 40, methods, false, warnings);

		assertEquals(2, steps.size());
		assertTrue(steps.get(0).getTitle().contains("1"));
		assertTrue(steps.get(0).getTitle().contains("15"));
		assertTrue(steps.get(1).getTitle().contains("15"));
		assertTrue(steps.get(1).getTitle().contains("40"));
		assertTrue(warnings.isEmpty());
	}

	@Test
	public void overlappingNormalMethodsAreAllOfferedAsAlternatives()
	{
		// The exact scenario from the conversation: several normal methods,
		// none pruned, all offered together with the widest-agreement range
		// grouped as one step.
		List<TrainingMethod> methods = Arrays.asList(
			normal(40, 99, "Motherlode Mine", 45000),
			normal(43, 99, "Blast Mine", 50000),
			normal(40, 99, "Gem rocks", 35000),
			normal(45, 99, "Calcified rocks", 40000)
		);
		List<String> warnings = new ArrayList<>();

		List<PathStep> steps = planner.plan("MINING", 40, 99, methods, false, warnings);

		// Breakpoints at 40, 43, 45, 99 -> three segments.
		assertEquals(3, steps.size());

		// Segment [40,43): only Motherlode + Gem rocks cover it.
		assertEquals(2, steps.get(0).getAlternatives().size());
		// Segment [43,45): Motherlode + Gem rocks + Blast Mine.
		assertEquals(3, steps.get(1).getAlternatives().size());
		// Segment [45,99): all four.
		assertEquals(4, steps.get(2).getAlternatives().size());

		// Every step should offer a choice given more than one alternative.
		assertTrue(steps.get(2).hasChoice());
	}

	@Test
	public void alternativesAreSortedByXpPerHourDescending()
	{
		List<TrainingMethod> methods = Arrays.asList(
			normal(1, 99, "Slow method", 10000),
			normal(1, 99, "Fast method", 50000),
			normal(1, 99, "Medium method", 25000)
		);
		List<String> warnings = new ArrayList<>();

		List<PathStep> steps = planner.plan("MINING", 1, 99, methods, false, warnings);

		assertEquals(1, steps.size());
		List<PathStep.Option> options = steps.get(0).getAlternatives();
		assertEquals(3, options.size());
		// Titles are the bare method name now, so these compare exactly.
		assertEquals("Fast method", options.get(0).getTitle());
		assertEquals("Medium method", options.get(1).getTitle());
		assertEquals("Slow method", options.get(2).getTitle());
	}

	@Test
	public void wildernessMethodsAreFlaggedAndShownAlongsideSafeOnes()
	{
		// The reason risk is recorded at all: a rate alone can't tell you that
		// one of these two options can get you killed by another player.
		List<TrainingMethod> methods = Arrays.asList(
			wilderness(1, 99, "Wilderness rocks", 90000),
			normal(1, 99, "Safe rocks", 80000)
		);
		List<String> riskWarnings = new ArrayList<>();

		List<PathStep> riskSteps = planner.plan("MINING", 1, 40, methods, false, riskWarnings);

		assertEquals(1, riskSteps.size());
		List<PathStep.Option> riskOptions = riskSteps.get(0).getAlternatives();
		// Risk is flagged, not filtered - the safe option stays on the list.
		assertEquals(2, riskOptions.size());
		// The flag travels as data rather than as text welded into the name, so
		// the panel can render it as a tag instead of a longer sentence.
		assertTrue(riskOptions.get(0).isPvpRisk());
		assertEquals("Wilderness rocks", riskOptions.get(0).getTitle());
		assertTrue(!riskOptions.get(1).isPvpRisk());
	}

	@Test
	public void safeMethodsCarryNoRiskLabel()
	{
		List<String> warnings = new ArrayList<>();
		List<PathStep> steps = planner.plan("MINING", 1, 40,
			Arrays.asList(normal(1, 99, "Iron ore", 20000)), false, warnings);

		assertTrue(!steps.get(0).getAlternatives().get(0).isPvpRisk());
	}

	@Test
	public void adjacentSegmentsResolvingToTheSameMethodsAreMerged()
	{
		// A finely level-bracketed tick method (as 1.5-tick teaks are, running
		// 93k at 35 to 222k at 90) adds breakpoints the normal plan has no use
		// for. Without merging, a normal-pace player got consecutive steps
		// listing the identical single method.
		List<TrainingMethod> methods = Arrays.asList(
			normal(1, 99, "Steady rocks", 30000),
			tick(1, 25, "Tick rocks A", 90000),
			tick(25, 50, "Tick rocks B", 120000),
			tick(50, 99, "Tick rocks C", 150000)
		);
		List<String> warnings = new ArrayList<>();

		List<PathStep> normalPlan = planner.plan("MINING", 1, 70, methods, false, warnings);

		// One unbroken step, not three slices of the same method.
		assertEquals(1, normalPlan.size());
		assertEquals(1, normalPlan.get(0).getAlternatives().size());
		assertTrue(normalPlan.get(0).getTitle().contains("1"));
		assertTrue(normalPlan.get(0).getTitle().contains("70"));

		// The tick plan still gets every bracket, because each one is a
		// genuinely different method with a different rate.
		List<PathStep> tickPlan = planner.plan("MINING", 1, 70, methods, true, new ArrayList<>());
		assertEquals(3, tickPlan.size());
	}

	@Test
	public void mergingStopsWhereTheMethodSetActuallyChanges()
	{
		List<TrainingMethod> methods = Arrays.asList(
			normal(1, 99, "Steady rocks", 30000),
			normal(40, 99, "Better rocks", 50000)
		);
		List<String> warnings = new ArrayList<>();

		List<PathStep> steps = planner.plan("MINING", 1, 60, methods, false, warnings);

		assertEquals(2, steps.size());
		assertEquals(1, steps.get(0).getAlternatives().size());
		assertEquals(2, steps.get(1).getAlternatives().size());
	}

	@Test
	public void questRouteMethodsCarryTheirQuestsIntoTheOption()
	{
		// A rate-less "do these quests" method has to reach the panel with its
		// quest names attached, or the panel has nothing to hand to Quest Helper.
		TrainingMethod quests = new TrainingMethod("MINING", 1, 40, "Quests", null,
			"These cover the early levels", null, Intensity.NORMAL);
		TrainingMethod grind = normal(1, 40, "Copper ore", 20000);
		List<String> warnings = new ArrayList<>();

		List<PathStep> steps = planner.plan("MINING", 1, 30,
			Arrays.asList(quests, grind), false, warnings);

		assertEquals(1, steps.size());
		// Training leads - the quest route is an alternative the panel keeps
		// visible, not the headline for the whole bracket.
		assertTrue(steps.get(0).getAlternatives().get(0).getTitle().contains("Copper ore"));
		assertEquals("Quests", steps.get(0).getAlternatives().get(1).getTitle());
	}

	/**
	 * The judgement has to survive the trip from methods.json to the card, or
	 * the data is recorded and never seen.
	 */
	@Test
	public void attentionTravelsFromTheMethodToTheOption()
	{
		TrainingMethod hard = normal(1, 99, "Two-tick sap cycle", 130000)
			.withAttention(TrainingMethod.Attention.DEMANDING);
		TrainingMethod easy = normal(1, 99, "One tree every four minutes", 66000)
			.withAttention(TrainingMethod.Attention.AFK);

		List<PathStep> steps = new SkillPathPlanner().plan("MINING", 1, 99,
			java.util.Arrays.asList(hard, easy), false, new ArrayList<>());

		assertEquals(1, steps.size());
		java.util.Map<String, TrainingMethod.Attention> byName = new java.util.HashMap<>();
		for (PathStep.Option option : steps.get(0).getAlternatives())
		{
			byName.put(option.getTitle(), option.getAttention());
		}
		assertEquals(TrainingMethod.Attention.DEMANDING, byName.get("Two-tick sap cycle"));
		assertEquals(TrainingMethod.Attention.AFK, byName.get("One tree every four minutes"));
	}

	/**
	 * An unjudged method must come through as null, not ORDINARY. The panel
	 * prints nothing either way, but conflating the two would turn "nobody has
	 * assessed this" into a claim that it is unremarkable.
	 */
	@Test
	public void anUnjudgedMethodReachesTheOptionWithNoJudgement()
	{
		List<PathStep> steps = new SkillPathPlanner().plan("MINING", 1, 99,
			java.util.Collections.singletonList(normal(1, 99, "Motherlode Mine", 40000)),
			false, new ArrayList<>());

		assertEquals(1, steps.size());
		assertNull(steps.get(0).getAlternatives().get(0).getAttention());
	}

	/**
	 * The shopping list is the range's xp divided by one action's xp. This is
	 * the arithmetic a player was leaving the client to do in a wiki tab, so it
	 * had better be right.
	 */
	@Test
	public void aShoppingListIsTheRangeXpOverTheActionXp()
	{
		// 1 -> 2 Mining is 83 xp; at 10 xp an action that is 9 actions, rounded up.
		TrainingMethod method = normal(1, 99, "Offering bones", 50000)
			.withConsumption(10, new TrainingMethod.Consumed("Dragon bones", 1));

		List<PathStep> steps = new SkillPathPlanner().plan("MINING", 1, 2,
			java.util.Collections.singletonList(method), false, new ArrayList<>());

		List<PathStep.Option.Needed> needed = steps.get(0).getAlternatives().get(0).getNeeded();
		assertEquals(1, needed.size());
		assertEquals("Dragon bones", needed.get(0).getItem());
		assertEquals(9, needed.get(0).getQuantity());
	}

	/** Two logs a shield means twice the logs, not twice the actions. */
	@Test
	public void aConsumedQuantityPerActionMultiplies()
	{
		TrainingMethod method = normal(1, 99, "Redwood shields", 50000)
			.withConsumption(10, new TrainingMethod.Consumed("Redwood logs", 2));

		List<PathStep> steps = new SkillPathPlanner().plan("MINING", 1, 2,
			java.util.Collections.singletonList(method), false, new ArrayList<>());

		List<PathStep.Option.Needed> needed = steps.get(0).getAlternatives().get(0).getNeeded();
		assertEquals(18, needed.get(0).getQuantity());
	}

	/**
	 * Most methods do not consume anything countable - a minigame, a stretch of
	 * combat - and must come through with no list rather than an empty-looking
	 * one the panel would still head "Buy".
	 */
	@Test
	public void aMethodWithNoCountableActionHasNoShoppingList()
	{
		List<PathStep> steps = new SkillPathPlanner().plan("MINING", 1, 99,
			java.util.Collections.singletonList(normal(1, 99, "Motherlode Mine", 40000)),
			false, new ArrayList<>());

		assertTrue(steps.get(0).getAlternatives().get(0).getNeeded().isEmpty());
	}
}

package com.nowwhat.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.nowwhat.model.Activity;
import com.nowwhat.model.PlayerState;
import com.nowwhat.model.Requirement;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class SuggestionEngineTest
{
	private final SuggestionEngine engine = new SuggestionEngine();
	private PlayerState state;

	@Before
	public void setUp()
	{
		state = new PlayerState();
	}

	private Activity questRequiringAgility(int requiredLevel)
	{
		return new Activity("q1", "Test Quest", Activity.Category.QUEST,
			Arrays.asList(new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", requiredLevel)));
	}

	@Test
	public void availableNowExcludesActivitiesWithUnmetRequirements()
	{
		state.setSkillLevel("AGILITY", 40);
		List<Activity> all = Arrays.asList(questRequiringAgility(50));

		assertTrue(engine.getAvailableNow(all, state).isEmpty());
	}

	@Test
	public void availableNowIncludesActivitiesWithMetRequirements()
	{
		state.setSkillLevel("AGILITY", 50);
		Activity quest = questRequiringAgility(50);
		List<Activity> all = Arrays.asList(quest);

		List<Activity> result = engine.getAvailableNow(all, state);
		assertEquals(1, result.size());
		assertEquals(quest, result.get(0));
	}

	@Test
	public void availableNowExcludesAlreadyCompletedQuests()
	{
		state.setSkillLevel("AGILITY", 50);
		state.addCompletedQuest("Test Quest");
		List<Activity> all = Arrays.asList(questRequiringAgility(50));

		assertTrue(engine.getAvailableNow(all, state).isEmpty());
	}

	@Test
	public void availableNowIsSortedByPriorityDescending()
	{
		Activity low = new Activity("low", "Low priority", Activity.Category.SKILLING, Arrays.asList(), 1);
		Activity high = new Activity("high", "High priority", Activity.Category.SKILLING, Arrays.asList(), 9);

		List<Activity> result = engine.getAvailableNow(Arrays.asList(low, high), state);

		assertEquals(2, result.size());
		assertEquals("high", result.get(0).getId());
		assertEquals("low", result.get(1).getId());
	}

	@Test
	public void almostAvailableRequiresExactlyOneUnmetRequirement()
	{
		state.setSkillLevel("AGILITY", 43); // 4 short: within CLOSE_LEVELS
		state.setSkillLevel("THIEVING", 32); // met
		Activity twoReqsOneUnmet = new Activity("a", "Two reqs", Activity.Category.DIARY, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 47),
			new Requirement(Requirement.Type.SKILL_LEVEL, "THIEVING", 32)
		));
		Activity twoReqsBothUnmet = new Activity("b", "Two unmet", Activity.Category.DIARY, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 47),
			new Requirement(Requirement.Type.SKILL_LEVEL, "MAGIC", 70)
		));

		List<Activity> result = engine.getAlmostAvailable(Arrays.asList(twoReqsOneUnmet, twoReqsBothUnmet), state);

		assertEquals(1, result.size());
		assertEquals("a", result.get(0).getId());
	}

	@Test
	public void almostAvailableExcludesAlreadyDoneActivities()
	{
		state.setSkillLevel("AGILITY", 40);
		state.addCompletedQuest("Test Quest");
		Activity quest = questRequiringAgility(47); // one unmet req, but already done

		assertFalse(engine.getAlmostAvailable(Arrays.asList(quest), state).contains(quest));
	}

	private Activity available(String id, Activity.Category category)
	{
		return new Activity(id, id, category,
			Arrays.asList(new Requirement(Requirement.Type.SKILL_LEVEL, "AGILITY", 10)));
	}

	@Test
	public void availableNowDropsCategoriesThePlayerSwitchedOff()
	{
		state.setSkillLevel("AGILITY", 50);
		List<Activity> all = Arrays.asList(
			available("quest", Activity.Category.QUEST),
			available("boss", Activity.Category.PVM));

		List<Activity> result = engine.getAvailableNow(all, state,
			EnumSet.of(Activity.Category.QUEST));

		assertEquals(1, result.size());
		assertEquals("boss", result.get(0).getId());
	}

	@Test
	public void availableNowKeepsCategoriesThatHaveNoSwitch()
	{
		// Only four categories have a setting. A minigame cannot be hidden,
		// so it must survive a filter that hides everything that can be.
		state.setSkillLevel("AGILITY", 50);
		List<Activity> all = Arrays.asList(available("pc", Activity.Category.MINIGAME));

		List<Activity> result = engine.getAvailableNow(all, state,
			EnumSet.of(Activity.Category.QUEST, Activity.Category.DIARY,
				Activity.Category.PVM, Activity.Category.COLLECTION_LOG));

		assertEquals(1, result.size());
	}

	@Test
	public void almostAvailableDropsCategoriesThePlayerSwitchedOff()
	{
		state.setSkillLevel("AGILITY", 43); // close enough to list
		Activity quest = questRequiringAgility(47);

		assertTrue(engine.getAlmostAvailable(Arrays.asList(quest), state,
			EnumSet.of(Activity.Category.QUEST)).isEmpty());
		assertEquals(1, engine.getAlmostAvailable(Arrays.asList(quest), state,
			EnumSet.of(Activity.Category.PVM)).size());
	}

	@Test
	public void noHiddenCategoriesMeansTheOldBehaviour()
	{
		state.setSkillLevel("AGILITY", 50);
		List<Activity> all = Arrays.asList(
			available("quest", Activity.Category.QUEST),
			available("boss", Activity.Category.PVM));

		assertEquals(engine.getAvailableNow(all, state).size(),
			engine.getAvailableNow(all, state, EnumSet.noneOf(Activity.Category.class)).size());
	}

	/**
	 * 70 Slayer used to put Cerberus (91) on the list, because one requirement
	 * away was the only test. Far-off levels are not "almost".
	 */
	@Test
	public void almostAvailableLeavesOutRequirementsThatAreFarOff()
	{
		state.setSkillLevel("SLAYER", 87);
		Activity kraken = new Activity("kraken", "Kraken", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "SLAYER", 87 + 1)));
		Activity cerberus = new Activity("cerb", "Cerberus", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "SLAYER", 87 + SuggestionEngine.CLOSE_LEVELS + 1)));

		List<Activity> result = engine.getAlmostAvailable(Arrays.asList(kraken, cerberus), state);

		assertEquals(1, result.size());
		assertEquals("kraken", result.get(0).getId());
	}

	/** A quest is one thing to do, so it stays close however far the levels inside it are. */
	@Test
	public void aMissingQuestStillCountsAsAlmost()
	{
		Activity zulrah = new Activity("zulrah", "Zulrah", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.QUEST_COMPLETE, "Regicide", 0)));

		assertEquals(1, engine.getAlmostAvailable(Arrays.asList(zulrah), state).size());
		assertEquals("Needs Regicide done first", engine.whatIsMissing(zulrah, state));
	}

	@Test
	public void whatIsMissingNamesTheLevelAndWhereYouAre()
	{
		state.setSkillLevel("SLAYER", 87);
		Activity cerberus = new Activity("cerb", "Cerberus", Activity.Category.PVM, Arrays.asList(
			new Requirement(Requirement.Type.SKILL_LEVEL, "SLAYER", 91)));

		assertEquals("Needs 91 Slayer, you have 87", engine.whatIsMissing(cerberus, state));
	}
}

import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/**
 * Pixel-art generator for the Now What icons. Drawn by hand at 16x16 rather
 * than rendered with Graphics2D, because antialiasing at this size turns
 * everything to mush on RuneLite's dark sidebar.
 * <p>
 * Usage: {@code java tools/MakeIcon.java <out.png> [scale]}
 * <ul>
 * <li>scale 1 (the default) is the sidebar nav button,
 *     {@code src/main/resources/com/nowwhat/icon.png}.
 * <li>scale 3 is the plugin hub's listing icon, {@code icon.png} in the
 *     repository root, which the hub allows up to 48x72.
 * </ul>
 * The larger one is the same art scaled by whole pixels, not a redraw: the hub
 * listing and the sidebar button should be recognisably one icon, and
 * nearest-neighbour keeps the pixel edges hard instead of smearing them.
 */
public class MakeIcon
{
	// Ascending staircase = progression, "the next step up".
	static final int STEP = 0xFFE4E4E4;   // near-white, reads on dark gray
	static final int ARROW = 0xFFFF981F;  // RuneLite brand orange

	public static void main(String[] a) throws Exception
	{
		int scale = a.length > 1 ? Integer.parseInt(a[1]) : 1;
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);

		// Three solid treads, each 4 wide, rising 3px per step, sharing a baseline.
		fill(img, 1, 4, 12, 14, STEP);
		fill(img, 5, 8, 9, 14, STEP);
		fill(img, 9, 12, 6, 14, STEP);

		// Up-and-right arrow above the top tread.
		int[][] shaft = {{9,5},{10,4},{11,3},{12,2},{13,1},{10,5},{11,4},{12,3},{13,2}};
		for (int[] p : shaft)
		{
			img.setRGB(p[0], p[1], ARROW);
		}
		// Arrowhead: corner bracket at the top right.
		for (int x = 11; x <= 14; x++)
		{
			img.setRGB(x, 0, ARROW);
		}
		for (int y = 0; y <= 3; y++)
		{
			img.setRGB(14, y, ARROW);
		}

		if (scale > 1)
		{
			img = upscale(img, scale);
		}

		ImageIO.write(img, "png", new File(a[0]));
		System.out.println("wrote " + a[0] + " at " + img.getWidth() + "x" + img.getHeight());
	}

	/** Nearest-neighbour, so one source pixel becomes a hard scale x scale block. */
	static BufferedImage upscale(BufferedImage src, int scale)
	{
		BufferedImage out = new BufferedImage(
			src.getWidth() * scale, src.getHeight() * scale, BufferedImage.TYPE_INT_ARGB);
		for (int x = 0; x < out.getWidth(); x++)
		{
			for (int y = 0; y < out.getHeight(); y++)
			{
				out.setRGB(x, y, src.getRGB(x / scale, y / scale));
			}
		}
		return out;
	}

	static void fill(BufferedImage img, int x0, int x1, int y0, int y1, int rgb)
	{
		for (int x = x0; x <= x1; x++)
		{
			for (int y = y0; y <= y1; y++)
			{
				img.setRGB(x, y, rgb);
			}
		}
	}
}
